INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0016', 'c81c-ce60-c6d0', '{"id":"person-0016","name":"Je Yun","title":"Sinjeong Base Toll Recorder","position":"Sinjeong Base Toll Recorder","rank":"Clerk","commonTier":"T5","occupation":"Toll Recording","gender":"Male","stage":"S2","state":"S01","stateName":"Free City","detailRoute":"/people/person-0016","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0016","name":"제윤","title":"신정기지 통행세 기록관","position":"신정기지 통행세 기록관","rank":"주사","commonTier":"T5","occupation":"통행세 기록","gender":"남성","stage":"S2","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0016","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0017', 'bcc0-c6d0-c8fc-908a', '{"id":"person-0017","name":"Byeon Goun","title":"Yeongdeungpo Waiting Hall Stationmaster","position":"Yeongdeungpo Waiting Hall Stationmaster","characterId":"K017","rank":"Duty Chief","commonTier":"T4","occupation":"Waiting Hall Duty","gender":"Female","stage":"S2","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#Person-Byeon Goun","detailRoute":"/people/person-0017","birthDate":"2090-09-06","birthday":"09-06","age":36,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":9,"effective":9},"stewardship":{"base":13,"effective":13},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k017-public-announcements","name":"Station announcements","rating":60},{"id":"k017-queue-administration","name":"Queue administration","rating":65}],"traits":[{"id":"k017-open-counter","name":"Use the public counter","description":"Redirects private requests to the public counter.","behavior":"Redirects private requests to the public counter.","stress":"Takes the microphone personally after blackout warnings.","relationship":"Posts Im Bada’s neighborhood queue lists at the station.","effects":[]},{"id":"k017-water-before-military","name":"People first","description":"Couples freight cars only after the food carts and the medical queue have boarded.","behavior":"Couples freight cars only after the food carts and the medical queue have boarded.","stress":"Takes orders to put ration queues behind military freight as insulting.","relationship":"Implements Yu Sejin’s dispatch order on the platform.","effects":[]}],"narrative":"Redirects favors to the public counter and administers food and medical queues. Waiting-hall management competence is supported; adjusting freight order is not counted as combat command.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:yeongdeungpo-concourse","name":{"ko":"Yeongdeungpo Waiting Hall"},"holderPersonId":"K017","directLiegePersonId":"K001","stateId":"S01","facilityRef":{"sourcePath":"lore/regions/station-interiors.json","stationName":"Yeongdeungpo","stationId":"Yeongdeungpo","stationIdentity":{"district":"Yeongdeungpo District","lat":37.51536,"lon":126.90693},"siteSourcePath":"lore/regions/content/11560.json","siteAnchor":"osm:node:5835544502","layerId":"concourse","layerName":"Station Waiting Hall"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"bcc0-c6d0-c8fc-908a","name":"Wonju Byeon Clan","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-5,"Force":15,"Material":20,"Communal":30,"Principle":10,"Public":20,"Eligibility":10,"Dispersed":-50,"Transformative":-25},"desire":{"Longing":40,"Monopoly":5,"Risk":-5,"Display":-25,"Sustained":-10,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Affiliation":"Free City","Livelihood":"Waiting Hall Duty","Rank":"Duty Chief","Title":"Yeongdeungpo Waiting Hall Stationmaster","Work Location":"Yeongdeungpo-bondong. At the Yeongdeungpo-bondong Waiting Hall, Byeon Goun broadcasts the suspension of Jin Hagyeom''s medical care and copies Yu Sejin''s train order and Im Bada''s ration tickets onto the public blackboard.","Values":"Authority 55 | Openness −5 | Force 15 | Material 20 | Communal 30 | Principle 10 | Publicity 20 | Credentials 10 | Dispersion −50 | Transformation −25","Desires":"Craving 40 | Monopoly 5 | Risk −5 | Display −25 | Persistence −10 | Orientation Bisexual | Union Non-exclusive"},"sections":{"Life":"Born to the 2126 generation. Grew up on waiting hall duty. The post of Yeongdeungpo Waiting Hall Stationmaster opened up through a substitute duty shift after an unexcused absence.\n- Work location: Yeongdeungpo-bondong. At the Yeongdeungpo-bondong Waiting Hall, Byeon Goun broadcasts the suspension of Jin Hagyeom''s medical care and copies Yu Sejin''s train order and Im Bada''s ration tickets onto the public blackboard.","Offices":"Rank: Duty Chief. Title: Yeongdeungpo Waiting Hall Stationmaster. Publishes the food-sharing counter and the medical queue tickets daily, and couples freight cars to the platform only after the food carts and medical patients have boarded.","Anecdote":"In 2125 she turned away a private solicitation and sent it to the public counter. Because of this, her signature for the post of Yeongdeungpo Waiting Hall Stationmaster was entered in the ledger.","Relationships":"An ally who announces Jin Hagyeom''s infirmary blockade over the waiting hall broadcast, enforces Yu Sejin''s dispatch order on the platform, and copies Im Bada''s alley queue tickets onto the station blackboard.","Ambition":"To make the Yeongdeungpo waiting hall the face-to-face counter of the free city''s west, where food, medical care and passage requests are handled under one roof.","Fear":"That the waiting hall will be shut on a mere cold-snap rumor, and people will scatter into dark surface passages and be exposed to outside machines.","Intervention":"Can block the order to seal the waiting hall and defend the counter, or expose the manipulation of queue tickets and have the stationmaster demoted."},"biography":"Gauges the crowd by the humidity on the platform, and takes an order to push the food queue behind the freight as an insult. Gentle by nature, but takes over the broadcast herself once a cold-snap warning goes up.\n\n- Affiliation: Free City\n- Occupation: Waiting Hall Duty\n- Rank: Duty Chief\n- Title: Yeongdeungpo Waiting Hall Stationmaster\n**Life.** Born to the 2126 generation. Grew up on waiting hall duty. The post of Yeongdeungpo Waiting Hall Stationmaster opened up through a substitute duty shift after an unexcused absence.\n- Work location: Yeongdeungpo-bondong. At the Yeongdeungpo-bondong Waiting Hall, Byeon Goun broadcasts the suspension of Jin Hagyeom''s medical care and copies Yu Sejin''s train order and Im Bada''s ration tickets onto the public blackboard.\n\n**Office.** Rank: Duty Chief. Title: Yeongdeungpo Waiting Hall Stationmaster. Publishes the food-sharing counter and the medical queue tickets daily, and couples freight cars to the platform only after the food carts and medical patients have boarded.\n\n**Anecdote.** In 2125 she turned away a private solicitation and sent it to the public counter. Because of this, her signature for the post of Yeongdeungpo Waiting Hall Stationmaster was entered in the ledger.\n\n**Relations.** An ally who announces Jin Hagyeom''s infirmary blockade over the waiting hall broadcast, enforces Yu Sejin''s dispatch order on the platform, and copies Im Bada''s alley queue tickets onto the station blackboard.\n\n**Ambition.** To make the Yeongdeungpo waiting hall the face-to-face counter of the free city''s west, where food, medical care and passage requests are handled under one roof.\n\n**Fear.** That the waiting hall will be shut on a mere cold-snap rumor, and people will scatter into dark surface passages and be exposed to outside machines.\n\n**Intervention.** Can block the order to seal the waiting hall and defend the counter, or expose the manipulation of queue tickets and have the stationmaster demoted.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −5 | Force 15 | Material 20 | Communal 30 | Principle 10 | Publicity 20 | Credentials 10 | Dispersion −50 | Transformation −25\n- Desires: Craving 40 | Monopoly 5 | Risk −5 | Display −25 | Persistence −10 | Orientation Bisexual | Union Non-exclusive\n:::","directLiege":{"personId":"K001","name":"Han Jae-mok","relationKind":"direct-liege","ownerTerm":"Direct Superior","effectiveYear":2126},"court":{"id":"court:K017","members":[{"personId":"K600","name":"Song Haji"}]},"relations":{"outgoing":[{"from":"Byeon Goun","type":"Command","to":"Yu Sejin","basis":"Enforcing Yu Sejin''s dispatch order on the platform"},{"from":"Byeon Goun","type":"Contract","to":"Jin Hagyeom","basis":"An alliance that announces Jin Hagyeom''s infirmary lockdown through waiting-room broadcasts, and"}],"incoming":[{"from":"Song Haji","type":"Command","to":"Byeon Goun","basis":"Handles waiting hall shifts and tunnel patrols under Byeon Goun''s command"}]}}', '{"id":"person-0017","name":"변고운","title":"영등포 대합실 역장","position":"영등포 대합실 역장","characterId":"K017","rank":"당직장","commonTier":"T4","occupation":"대합실 당직","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-변고운","detailRoute":"/people/person-0017","birthDate":"2090-09-06","birthday":"09-06","age":36,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":9,"effective":9},"stewardship":{"base":13,"effective":13},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k017-public-announcements","name":"대합실 방송","rating":60},{"id":"k017-queue-administration","name":"대기표 관리","rating":65}],"traits":[{"id":"k017-open-counter","name":"공개 창구로","description":"사적 청탁을 공개 창구로 돌려보낸다.","behavior":"사적 청탁을 공개 창구로 돌려보낸다.","stress":"정전 예고가 뜨면 직접 방송을 잡는다.","relationship":"임바다의 골목 대기표를 역 칠판에 옮긴다.","effects":[]},{"id":"k017-water-before-military","name":"사람 먼저","description":"식량 수레와 진료 대기열이 오른 뒤에 짐 화차를 붙인다.","behavior":"식량 수레와 진료 대기열이 오른 뒤에 짐 화차를 붙인다.","stress":"배급열을 군수 뒤로 미루라는 명령을 모욕으로 듣는다.","relationship":"유세진의 배차 순서를 현장에서 집행한다.","effects":[]}],"narrative":"청탁을 공개 창구로 돌리고 식량·진료 대기열을 운영한다. 대합실 운영의 숙련은 인정하되 짐 순서 조정을 전투 지휘 실적으로 계산하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:yeongdeungpo-concourse","name":{"ko":"영등포 대합실"},"holderPersonId":"K017","directLiegePersonId":"K001","stateId":"S01","facilityRef":{"sourcePath":"lore/regions/station-interiors.json","stationName":"영등포","stationId":"Yeongdeungpo","stationIdentity":{"district":"영등포구","lat":37.51536,"lon":126.90693},"siteSourcePath":"lore/regions/content/11560.json","siteAnchor":"osm:node:5835544502","layerId":"concourse","layerName":"역사 대합실"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"bcc0-c6d0-c8fc-908a","name":"원주 변씨","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-5,"무력":15,"물질":20,"공동":30,"원칙":10,"공개":20,"자격":10,"분산":-50,"변혁":-25},"desire":{"갈망":40,"독점":5,"위험":-5,"과시":-25,"지속":-10,"지향":"양성","결합":"비독점"},"fields":{"소속":"자유도시","생업":"대합실 당직","품계":"당직장","직함":"영등포 대합실 역장","업무 위치":"영등포본동. 영등포본동 대합실에서 변고운은 진하겸의 진료 중단을 방송하고 유세진의 열차 순서와 임바다의 배급 대기표를 공개 칠판에 옮긴다.","가치관":"권위 55 | 개방 −5 | 무력 15 | 물질 20 | 공동 30 | 원칙 10 | 공개 20 | 자격 10 | 분산 −50 | 변혁 −25","욕망":"갈망 40 | 독점 5 | 위험 −5 | 과시 −25 | 지속 −10 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 대합실 당직에서 자랐다. 영등포 대합실 역장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 영등포본동. 영등포본동 대합실에서 변고운은 진하겸의 진료 중단을 방송하고 유세진의 열차 순서와 임바다의 배급 대기표를 공개 칠판에 옮긴다.","관직":"품계 당직장. 직함은 영등포 대합실 역장. 식량 나눔 창구와 진료 대기표를 매일 공개하고, 짐 화차는 식량 수레와 진료 환자가 먼저 오른 뒤에만 승강장에 붙인다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 영등포 대합실 역장 자리의 서명이 장부에 올랐다.","관계":"진하겸의 의무소 봉쇄를 대합실 방송으로 알리는 동맹이고, 유세진의 배차 순서를 승강장에서 집행하며, 임바다의 골목 대기표를 역 칠판에 옮겨 적는다.","야망":"영등포 대합실을 식량·진료·통행 신청이 한 지붕 아래 처리되는 자유도시 서쪽의 대면 창구로 만든다.","공포":"한파 소문만으로 대합실이 닫히고 사람들이 어두운 지상 통로로 흩어져 바깥 기계에 노출되는 것.","개입":"대합실 봉쇄 명령을 막아 창구를 지키거나, 대기표 조작을 밝혀 역장을 강등시킬 수 있다."},"biography":"승강장 습기로 인파를 가늠하고, 식량 대기열을 짐 뒤로 미루라는 명령을 모욕으로 듣는다. 온화하나 한파 경보가 뜨면 방송을 직접 잡는다.\n\n- 소속: 자유도시\n- 생업: 대합실 당직\n- 품계: 당직장\n- 직함: 영등포 대합실 역장\n**생애.** 2126년 세대. 대합실 당직에서 자랐다. 영등포 대합실 역장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 영등포본동. 영등포본동 대합실에서 변고운은 진하겸의 진료 중단을 방송하고 유세진의 열차 순서와 임바다의 배급 대기표를 공개 칠판에 옮긴다.\n\n**관직.** 품계 당직장. 직함은 영등포 대합실 역장. 식량 나눔 창구와 진료 대기표를 매일 공개하고, 짐 화차는 식량 수레와 진료 환자가 먼저 오른 뒤에만 승강장에 붙인다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 영등포 대합실 역장 자리의 서명이 장부에 올랐다.\n\n**관계.** 진하겸의 의무소 봉쇄를 대합실 방송으로 알리는 동맹이고, 유세진의 배차 순서를 승강장에서 집행하며, 임바다의 골목 대기표를 역 칠판에 옮겨 적는다.\n\n**야망.** 영등포 대합실을 식량·진료·통행 신청이 한 지붕 아래 처리되는 자유도시 서쪽의 대면 창구로 만든다.\n\n**공포.** 한파 소문만으로 대합실이 닫히고 사람들이 어두운 지상 통로로 흩어져 바깥 기계에 노출되는 것.\n\n**개입.** 대합실 봉쇄 명령을 막아 창구를 지키거나, 대기표 조작을 밝혀 역장을 강등시킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −5 | 무력 15 | 물질 20 | 공동 30 | 원칙 10 | 공개 20 | 자격 10 | 분산 −50 | 변혁 −25\n- 욕망: 갈망 40 | 독점 5 | 위험 −5 | 과시 −25 | 지속 −10 | 지향 양성 | 결합 비독점\n:::","directLiege":{"personId":"K001","name":"한재목","relationKind":"direct-liege","ownerTerm":"직속 상관","effectiveYear":2126},"court":{"id":"court:K017","members":[{"personId":"K600","name":"송하지"}]},"relations":{"outgoing":[{"from":"변고운","type":"지휘","to":"유세진","basis":"유세진의 배차 순서를 승강장에서 집행하며"},{"from":"변고운","type":"계약","to":"진하겸","basis":"진하겸의 의무소 봉쇄를 대합실 방송으로 알리는 동맹이고"}],"incoming":[{"from":"송하지","type":"지휘","to":"변고운","basis":"변고운의 지휘 아래 대합실 교대와 터널 순찰을 맡음"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0018', 'd5c8-d0dc-c778-8a31', '{"id":"person-0018","name":"Heo Eunchan","title":"Sinjeong Base Siding Power Supervisor","position":"Sinjeong Base Siding Power Supervisor","characterId":"K018","rank":"Duty Chief","commonTier":"T4","occupation":"Power Equipment Operation","gender":"Male","stage":"S2","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-Heo-Eunchan","detailRoute":"/people/person-0018","birthDate":"2076-04-13","birthday":"04-13","age":50,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":10,"effective":10},"stewardship":{"base":13,"effective":13},"intrigue":{"base":13,"effective":13},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k018-power-allocation","name":"Power allocation","rating":65},{"id":"k018-component-rejection","name":"Rejecting defective parts","rating":55}],"traits":[{"id":"k018-pump-load-first","name":"Pump load first","description":"Powers heating and food storage first and pushes repair charging back.","behavior":"Powers heating and food storage first and pushes repair charging back.","stress":"Guards against overdischarge stopping the emergency heating.","relationship":"Carries a debt from rejecting O Haerin’s refrigeration charging request.","effects":[]},{"id":"k018-unaltered-shift-log","name":"Preserve shift logs","description":"Keeps public power allocations and shift logs.","behavior":"Keeps public power allocations and shift logs.","stress":"Burns notes demanding the wrong priority.","relationship":"Adds power consumption to Je Yun’s ledger.","effects":[]}],"narrative":"Reads overload signs and enforces public power allocation and charging limits. Returning defective parts is recorded; invention and armed performance are not.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d0dc-c778-8a31","name":"Taein Heo Clan","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":50,"Openness":-5,"Force":0,"Material":35,"Communal":10,"Principle":25,"Public":5,"Eligibility":-5,"Dispersed":-55,"Transformative":-20},"desire":{"Longing":10,"Monopoly":-20,"Risk":30,"Display":-20,"Sustained":30,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Power Equipment Operation","Rank":"Duty Chief","Title":"Sinjeong Base Siding Power Supervisor","Work Location":"Sinjeong 3-dong. At the Sinjeong 3-dong stabling line, Heo Eunchan cross-checks the fuel level against the power gauges and allocates power first to dwelling heating and food storage.","Values":"Authority 50 | Openness −5 | Force 0 | Material 35 | Communal 10 | Principle 25 | Publicity 5 | Credentials −5 | Dispersion −55 | Transformation −20","Desires":"Craving 10 | Monopoly −20 | Risk 30 | Display −20 | Persistence 30 | Orientation None | Union Contract Cohabitation"},"sections":{"Life":"Born to the 2126 generation. Grew up at the Sinjeong rail depot. The post of Power Supervisor of the Sinjeong Depot Stabling Line opened up through a defect report made just before a derailment.\n- Work location: Sinjeong 3-dong. At the Sinjeong 3-dong stabling line, Heo Eunchan cross-checks the fuel level against the power gauges and allocates power first to dwelling heating and food storage.","Offices":"Rank: Duty Chief. Title: Sinjeong Base Siding Power Supervisor. Records the power distribution on a public gauge board, and permits repair charging only when power for dwelling heating and food storage is above the minimum line.","Anecdote":"In 2125 he sent a box of defective parts back just before shipment. Because of this, his signature for the post of Power Supervisor of the Sinjeong Depot Stabling Line was entered in the ledger.","Relationships":"Takes orders from Choe Hangyeol to supply power for maintenance train departures, attaches power usage to the transit ledger by contract, and owes a debt for refusing O Haerin''s request for refrigeration charging.","Ambition":"To lock the emergency power of the Sinjeong stabling line exclusively for heating and repair work, and so become the midnight artery of the winter nights.","Fear":"That a single over-discharge will shut off the emergency heating, or that the heat of the generators will instead draw outside machines.","Intervention":"Can find replacement batteries and open a dual supply, or expose the tampering with the gauges and have the supervisor replaced."},"biography":"Reads overload from the vibration of the transformer, and burns the note telling him to put repair charging ahead of heating. Taciturn, and never trims the shift log.\n\n- Affiliation: Free City\n- Occupation: Power Equipment Operation\n- Rank: Duty Chief\n- Title: Sinjeong Base Siding Power Supervisor\n**Life.** Born to the 2126 generation. Grew up at the Sinjeong rail depot. The post of Power Supervisor of the Sinjeong Depot Stabling Line opened up through a defect report made just before a derailment.\n- Work location: Sinjeong 3-dong. At the Sinjeong 3-dong stabling line, Heo Eunchan cross-checks the fuel level against the power gauges and allocates power first to dwelling heating and food storage.\n\n**Office.** Rank: Duty Chief. Title: Sinjeong Base Siding Power Supervisor. Records the power distribution on a public gauge board, and permits repair charging only when power for dwelling heating and food storage is above the minimum line.\n\n**Anecdote.** In 2125 he sent a box of defective parts back just before shipment. Because of this, his signature for the post of Power Supervisor of the Sinjeong Depot Stabling Line was entered in the ledger.\n\n**Relations.** Takes orders from Choe Hangyeol to supply power for maintenance train departures, attaches power usage to the transit ledger by contract, and owes a debt for refusing O Haerin''s request for refrigeration charging.\n\n**Ambition.** To lock the emergency power of the Sinjeong stabling line exclusively for heating and repair work, and so become the midnight artery of the winter nights.\n\n**Fear.** That a single over-discharge will shut off the emergency heating, or that the heat of the generators will instead draw outside machines.\n\n**Intervention.** Can find replacement batteries and open a dual supply, or expose the tampering with the gauges and have the supervisor replaced.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 50 | Openness −5 | Force 0 | Material 35 | Communal 10 | Principle 25 | Publicity 5 | Credentials −5 | Dispersion −55 | Transformation −20\n- Desires: Craving 10 | Monopoly −20 | Risk 30 | Display −20 | Persistence 30 | Orientation None | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Heo Eunchan","type":"Command","to":"Choe Han-gyeol","basis":"takes orders to supply power for the dispatch of Choe Hangyeol''s repair trains,"}],"incoming":[{"from":"Chae Hansol","type":"Contract","to":"Heo Eunchan","basis":"Supports Heo Eunchan''s stabling-line power distribution from the generation side"}]}}', '{"id":"person-0018","name":"허은찬","title":"신정기지 유치선 전력감독","position":"신정기지 유치선 전력감독","characterId":"K018","rank":"당직장","commonTier":"T4","occupation":"전력 설비 운전","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-허은찬","detailRoute":"/people/person-0018","birthDate":"2076-04-13","birthday":"04-13","age":50,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":10,"effective":10},"stewardship":{"base":13,"effective":13},"intrigue":{"base":13,"effective":13},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k018-power-allocation","name":"전력 배분","rating":65},{"id":"k018-component-rejection","name":"불량 부품 확인","rating":55}],"traits":[{"id":"k018-pump-load-first","name":"펌프 부하 먼저","description":"난방과 식량 보관 전력을 먼저 대고 정비 충전은 뒤로 미룬다.","behavior":"난방과 식량 보관 전력을 먼저 대고 정비 충전은 뒤로 미룬다.","stress":"과방전으로 비상 난방이 멈출 것을 경계한다.","relationship":"오해린의 냉동 충전 청을 거절한 빚을 안고 있다.","effects":[]},{"id":"k018-unaltered-shift-log","name":"교대 일지 보존","description":"전력 배분과 교대 일지를 공개 기록으로 남긴다.","behavior":"전력 배분과 교대 일지를 공개 기록으로 남긴다.","stress":"우선순위를 바꾸라는 쪽지를 태운다.","relationship":"제윤의 원장에 전력 사용량을 붙인다.","effects":[]}],"narrative":"과부하 징후를 읽고 공개 배분과 충전 제한을 수행한다. 불량품 반환은 확인되지만 발전 설비 발명이나 무장 수행은 근거가 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d0dc-c778-8a31","name":"태인 허씨","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":50,"개방":-5,"무력":0,"물질":35,"공동":10,"원칙":25,"공개":5,"자격":-5,"분산":-55,"변혁":-20},"desire":{"갈망":10,"독점":-20,"위험":30,"과시":-20,"지속":30,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"전력 설비 운전","품계":"당직장","직함":"신정기지 유치선 전력감독","업무 위치":"신정3동. 신정3동 유치선에서 허은찬은 연료 잔량과 전력 계기판을 대조하고 거처 난방과 식량 보관 전력을 먼저 배분한다.","가치관":"권위 50 | 개방 −5 | 무력 0 | 물질 35 | 공동 10 | 원칙 25 | 공개 5 | 자격 −5 | 분산 −55 | 변혁 −20","욕망":"갈망 10 | 독점 −20 | 위험 30 | 과시 −20 | 지속 30 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 신정 차량기지에서 자랐다. 신정기지 유치선 전력감독 자리는 탈선 직전 결함 보고로 열렸다.\n- 업무 위치: 신정3동. 신정3동 유치선에서 허은찬은 연료 잔량과 전력 계기판을 대조하고 거처 난방과 식량 보관 전력을 먼저 배분한다.","관직":"품계 당직장. 직함은 신정기지 유치선 전력감독. 전력 배분을 공개 계기판에 남기고, 정비용 충전은 거처 난방과 식량 보관 전력이 최저선을 넘을 때만 허용한다.","일화":"2125년 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 신정기지 유치선 전력감독 자리의 서명이 장부에 올랐다.","관계":"최한결의 보수열차 출고에 전력을 대는 지휘를 받고, 통행 원장에 전력 사용량을 계약으로 붙이며, 오해린의 냉동 충전 요청을 거절한 빚이 있다.","야망":"신정 유치선의 비상 전력을 난방·보수 작업 전용으로 고정해 겨울밤의 심야 동맥이 된다.","공포":"한 번의 과방전으로 비상 난방이 꺼지거나, 반대로 발전기 열기가 바깥 기계를 끌어들이는 것.","개입":"대체 축전지를 구해 이중 공급을 열거나, 계기판 조작을 폭로해 감독을 교체할 수 있다."},"biography":"변압기 진동으로 과부하를 읽고, 난방보다 정비 충전을 앞세우라는 쪽지를 태운다. 과묵하고 교대 일지를 깎지 않는다.\n\n- 소속: 자유도시\n- 생업: 전력 설비 운전\n- 품계: 당직장\n- 직함: 신정기지 유치선 전력감독\n**생애.** 2126년 세대. 신정 차량기지에서 자랐다. 신정기지 유치선 전력감독 자리는 탈선 직전 결함 보고로 열렸다.\n- 업무 위치: 신정3동. 신정3동 유치선에서 허은찬은 연료 잔량과 전력 계기판을 대조하고 거처 난방과 식량 보관 전력을 먼저 배분한다.\n\n**관직.** 품계 당직장. 직함은 신정기지 유치선 전력감독. 전력 배분을 공개 계기판에 남기고, 정비용 충전은 거처 난방과 식량 보관 전력이 최저선을 넘을 때만 허용한다.\n\n**일화.** 2125년 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 신정기지 유치선 전력감독 자리의 서명이 장부에 올랐다.\n\n**관계.** 최한결의 보수열차 출고에 전력을 대는 지휘를 받고, 통행 원장에 전력 사용량을 계약으로 붙이며, 오해린의 냉동 충전 요청을 거절한 빚이 있다.\n\n**야망.** 신정 유치선의 비상 전력을 난방·보수 작업 전용으로 고정해 겨울밤의 심야 동맥이 된다.\n\n**공포.** 한 번의 과방전으로 비상 난방이 꺼지거나, 반대로 발전기 열기가 바깥 기계를 끌어들이는 것.\n\n**개입.** 대체 축전지를 구해 이중 공급을 열거나, 계기판 조작을 폭로해 감독을 교체할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 50 | 개방 −5 | 무력 0 | 물질 35 | 공동 10 | 원칙 25 | 공개 5 | 자격 −5 | 분산 −55 | 변혁 −20\n- 욕망: 갈망 10 | 독점 −20 | 위험 30 | 과시 −20 | 지속 30 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"허은찬","type":"지휘","to":"최한결","basis":"최한결의 보수열차 출고에 전력을 대는 지휘를 받고"}],"incoming":[{"from":"채한솔","type":"계약","to":"허은찬","basis":"허은찬의 유치선 전력 배분을 발전 쪽에서 받치고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0019', 'ad6c-b2a5-c131', '{"id":"person-0019","name":"Gu Haon","title":"Yeouido Wharf Market Auctioneer","position":"Yeouido Wharf Market Auctioneer","characterId":"K019","rank":"Clerk","commonTier":"T5","occupation":"Wharf Auction","gender":"Female","stage":"S2","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-Gu-Haon","detailRoute":"/people/person-0019","birthDate":"2077-10-24","birthday":"10-24","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":12,"effective":12},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k019-dock-auction","name":"Dock auction","rating":65},{"id":"k019-loss-accounting","name":"Loss accounting","rating":55}],"traits":[{"id":"k019-price-restraint","name":"Restrain cold-snap prices","description":"Does not raise prices in heatless lanes.","behavior":"Does not raise prices in heatless lanes.","stress":"That another big market''s price ledger would swallow the Yeouido market and western food would sell at inflated prices.","relationship":"Splits loads with the market hands who run the auction in lottery order, and sends back as a grudge any offer to raise winter emergency prices.","effects":[]},{"id":"k019-standard-before-sale","name":"Standards before sale","description":"Keeps sold food from shipping out if it has spoiled.","behavior":"Keeps sold food from shipping out if it has spoiled.","stress":"That another big market''s price ledger would swallow the Yeouido market and western food would sell at inflated prices.","relationship":"Splits loads with the market hands who run the auction in lottery order, and sends back as a grudge any offer to raise winter emergency prices.","effects":[]}],"narrative":"Auction administration and loss disclosure are actual evidence. Rejects emergency pricing, but an expanded permit system remains a goal.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-5,"Force":20,"Material":50,"Communal":20,"Principle":20,"Public":15,"Eligibility":-10,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":-10,"Monopoly":-5,"Risk":35,"Display":10,"Sustained":5,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Wharf Auction","Rank":"Clerk","Title":"Yeouido Wharf Market Auctioneer","Work Location":"Yeouidong. Before an auction at the Yeouidong wharf, Gu Haon checks the condition tags on the grain sacks and the scale seals, and puts up the winning lots in line with the lottery order.","Values":"Authority 55 | Openness −5 | Force 20 | Material 50 | Communal 20 | Principle 20 | Publicity 15 | Qualification −10 | Dispersion −40 | Transformation −25","Desires":"Craving −10 | Monopoly −5 | Risk 35 | Display 10 | Persistence 5 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Born in the 2126 generation. Grew up at Noryangjin Wharf. The post of Yeouido Wharf Market Auctioneer opened to her through the public disclosure of a scale recheck.\n- Workplace: Yeouidong. Before an auction at the Yeouidong wharf, Gu Haon checks the condition tags on the grain sacks and the scale seals, and puts up the winning lots in line with the lottery order.","Offices":"Rank: Clerk. Title: Yeouido Wharf Market Auctioneer. Before an auction begins, she checks the condition tags, and food that has spoiled is not shipped out even if it has won the bid.","Anecdote":"In 2125, she first distributed grain that had begun to rot and made the loss ledger public. Because of this, her signature for the post of Yeouido Wharf Market Auctioneer was entered in the ledger.","Relationships":"Shares the load with the market hands who run auctions in lottery order, and sends back with resentment any proposal to raise winter emergency prices.","Ambition":"Opens food auctions only together with the seal of the market representative, so that prices become a public ledger everyone can see.","Fear":"That another market''s price ledger swallows even the Yeouido wharf, so that western food is sold at winter prices.","Intervention":"She can expose the smuggler-boat winning-bid ledger, or escort the sealed samples to protect her public auction."},"biography":"She reads grain prices faster than the river wind, and instantly pulls merchants who cheat the scale from the morning lottery. She haggles like singing, but never raises prices in the alleys where children and elders live.\n\n- Affiliation: Free City\n- Livelihood: Wharf Auction\n- Rank: Clerk\n- Title: Yeouido Wharf Market Auctioneer\n**Life.** Born in the 2126 generation. Grew up at Noryangjin Wharf. The post of Yeouido Wharf Market Auctioneer opened to her through the public disclosure of a scale recheck.\n- Workplace: Yeouidong. Before an auction at the Yeouidong wharf, Gu Haon checks the condition tags on the grain sacks and the scale seals, and puts up the winning lots in line with the lottery order.\n\n**Office.** Rank: Clerk. Title: Yeouido Wharf Market Auctioneer. Before an auction begins, she checks the condition tags, and food that has spoiled is not shipped out even if it has won the bid.\n\n**Anecdote.** In 2125, she first distributed grain that had begun to rot and made the loss ledger public. Because of this, her signature for the post of Yeouido Wharf Market Auctioneer was entered in the ledger.\n\n**Relationships.** Shares the load with the market hands who run auctions in lottery order, and sends back with resentment any proposal to raise winter emergency prices.\n\n**Ambition.** Opens food auctions only together with the seal of the market representative, so that prices become a public ledger everyone can see.\n\n**Fear.** That another market''s price ledger swallows even the Yeouido wharf, so that western food is sold at winter prices.\n\n**Intervention.** She can expose the smuggler-boat winning-bid ledger, or escort the sealed samples to protect her public auction.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 55 | Openness −5 | Force 20 | Material 50 | Communal 20 | Principle 20 | Publicity 15 | Qualification −10 | Dispersion −40 | Transformation −25\n- Desires: Craving −10 | Monopoly −5 | Risk 35 | Display 10 | Persistence 5 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Gu Haon","type":"Command","to":"Jeong Mo-ran","basis":"A contract that carries out Jeong Moran''s berth lottery as an auction, and"},{"from":"Gu Haon","type":"Contract","to":"Gu Taeyun","basis":"Dividing Yangcheon grain sack turns and cart turns with Gu Taeyun"}],"incoming":[]}}', '{"id":"person-0019","name":"구하온","title":"여의도 선창시장 경매사","position":"여의도 선창시장 경매사","characterId":"K019","rank":"주사","commonTier":"T5","occupation":"선창 경매","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-구하온","detailRoute":"/people/person-0019","birthDate":"2077-10-24","birthday":"10-24","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":12,"effective":12},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k019-dock-auction","name":"선창 경매","rating":65},{"id":"k019-loss-accounting","name":"손실 기록","rating":55}],"traits":[{"id":"k019-price-restraint","name":"혹한 가격 억제","description":"난방 끊긴 골목의 가격을 올리지 않는다.","behavior":"난방 끊긴 골목의 가격을 올리지 않는다.","stress":"다른 시장의 가격 장부가 여의도 선창까지 삼켜, 서쪽 식량이 겨울 시세로 팔리는 것.","relationship":"추첨 순서대로 경매를 집행하는 장터 일꾼들과 짐을 나누고, 겨울 비상 시세를 올리자는 제안은 원한으로 돌려보낸다.","effects":[]},{"id":"k019-standard-before-sale","name":"낙찰보다 기준","description":"낙찰된 식량도 상했으면 출고시키지 않는다.","behavior":"낙찰된 식량도 상했으면 출고시키지 않는다.","stress":"다른 시장의 가격 장부가 여의도 선창까지 삼켜, 서쪽 식량이 겨울 시세로 팔리는 것.","relationship":"추첨 순서대로 경매를 집행하는 장터 일꾼들과 짐을 나누고, 겨울 비상 시세를 올리자는 제안은 원한으로 돌려보낸다.","effects":[]}],"narrative":"경매 집행과 손실 공개가 실제 근거다. 비상 시세를 거절하지만 허가제의 성립은 아직 목표다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-5,"무력":20,"물질":50,"공동":20,"원칙":20,"공개":15,"자격":-10,"분산":-40,"변혁":-25},"desire":{"갈망":-10,"독점":-5,"위험":35,"과시":10,"지속":5,"지향":"유동","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"선창 경매","품계":"주사","직함":"여의도 선창시장 경매사","업무 위치":"여의동. 여의동 선창 경매에 앞서 구하온은 곡물 포대의 상태 표식과 저울 봉인을 확인하고 추첨 순서에 맞춰 낙찰품을 올린다.","가치관":"권위 55 | 개방 −5 | 무력 20 | 물질 50 | 공동 20 | 원칙 20 | 공개 15 | 자격 −10 | 분산 −40 | 변혁 −25","욕망":"갈망 −10 | 독점 −5 | 위험 35 | 과시 10 | 지속 5 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 노량진 선창에서 자랐다. 여의도 선창시장 경매사 자리는 저울 재점검 공개로 열렸다.\n- 업무 위치: 여의동. 여의동 선창 경매에 앞서 구하온은 곡물 포대의 상태 표식과 저울 봉인을 확인하고 추첨 순서에 맞춰 낙찰품을 올린다.","관직":"품계 주사. 직함은 여의도 선창시장 경매사. 경매 시작 전 상태 표식을 확인하고, 상한 식량은 낙찰이 되어도 내보내지 않는다.","일화":"2125년 썩기 시작한 곡물을 먼저 나눠 주고 손실 장부를 공개했다. 이 일로 여의도 선창시장 경매사 자리의 서명이 장부에 올랐다.","관계":"추첨 순서대로 경매를 집행하는 장터 일꾼들과 짐을 나누고, 겨울 비상 시세를 올리자는 제안은 원한으로 돌려보낸다.","야망":"식량 경매를 장터 대표의 봉인과 함께만 열어 시세가 모두에게 보이는 공개 장부가 되게 한다.","공포":"다른 시장의 가격 장부가 여의도 선창까지 삼켜, 서쪽 식량이 겨울 시세로 팔리는 것.","개입":"밀선 낙찰 장부를 폭로하거나, 봉인 표본을 호송해 그의 공개 경매를 지킬 수 있다."},"biography":"강바람보다 곡물 시세를 빨리 읽고, 저울을 속이는 상인을 아침 추첨에서 즉시 뺀다. 흥정을 노래처럼 하지만 아이와 노인이 사는 골목의 가격은 올리지 않는다.\n\n- 소속: 자유도시\n- 생업: 선창 경매\n- 품계: 주사\n- 직함: 여의도 선창시장 경매사\n**생애.** 2126년 세대. 노량진 선창에서 자랐다. 여의도 선창시장 경매사 자리는 저울 재점검 공개로 열렸다.\n- 업무 위치: 여의동. 여의동 선창 경매에 앞서 구하온은 곡물 포대의 상태 표식과 저울 봉인을 확인하고 추첨 순서에 맞춰 낙찰품을 올린다.\n\n**관직.** 품계 주사. 직함은 여의도 선창시장 경매사. 경매 시작 전 상태 표식을 확인하고, 상한 식량은 낙찰이 되어도 내보내지 않는다.\n\n**일화.** 2125년 썩기 시작한 곡물을 먼저 나눠 주고 손실 장부를 공개했다. 이 일로 여의도 선창시장 경매사 자리의 서명이 장부에 올랐다.\n\n**관계.** 추첨 순서대로 경매를 집행하는 장터 일꾼들과 짐을 나누고, 겨울 비상 시세를 올리자는 제안은 원한으로 돌려보낸다.\n\n**야망.** 식량 경매를 장터 대표의 봉인과 함께만 열어 시세가 모두에게 보이는 공개 장부가 되게 한다.\n\n**공포.** 다른 시장의 가격 장부가 여의도 선창까지 삼켜, 서쪽 식량이 겨울 시세로 팔리는 것.\n\n**개입.** 밀선 낙찰 장부를 폭로하거나, 봉인 표본을 호송해 그의 공개 경매를 지킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −5 | 무력 20 | 물질 50 | 공동 20 | 원칙 20 | 공개 15 | 자격 −10 | 분산 −40 | 변혁 −25\n- 욕망: 갈망 −10 | 독점 −5 | 위험 35 | 과시 10 | 지속 5 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"구하온","type":"지휘","to":"정모란","basis":"정모란의 선석 추첨을 경매로 집행하는 계약이고"},{"from":"구하온","type":"계약","to":"구태윤","basis":"구태윤과 양천 곡물 포대 순번과 짐수레 순번을 나누며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0020', 'c9c4-d48d-ae30', '{"id":"person-0020","name":"Jin Sebin","title":"Yangcheon Mobile Medical Vehicle Team Leader","position":"Yangcheon Mobile Medical Vehicle Team Leader","rank":"Clerk","commonTier":"T5","occupation":"Mobile Medical Care","gender":"Male","stage":"S2","state":"S01","stateName":"Free City","detailRoute":"/people/person-0020","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0020","name":"진세빈","title":"양천 이동의무차 반장","position":"양천 이동의무차 반장","rank":"주사","commonTier":"T5","occupation":"이동 진료","gender":"남성","stage":"S2","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0020","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0021', 'cc44-d3c9-ac15', '{"id":"person-0021","name":"Chae Hansol","title":"Sinjeong Base Emergency Generator Chief Operator","position":"Sinjeong Base Emergency Generator Chief Operator","characterId":"K021","rank":"Duty Chief","commonTier":"T4","occupation":"Emergency Generator Operation","gender":"Female","stage":"S2","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-chae-hansol","detailRoute":"/people/person-0021","birthDate":"2093-01-24","birthday":"01-24","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":10,"effective":10},"stewardship":{"base":12,"effective":12},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k021-generator-output-matching","name":"Generator output matching","rating":65},{"id":"k021-brake-repair","name":"Brake repair","rating":60},{"id":"k021-fuel-output-log","name":"Fuel and output logging","rating":60}],"traits":[{"id":"k021-documented-distribution","name":"Documented distribution","description":"Uses output logs rather than oral distribution orders.","behavior":"Uses output logs rather than oral distribution orders.","stress":"Resents pressure to divert heating power as a favor.","relationship":"Supports Heo Eunchan’s allocation from the generator side.","effects":[]},{"id":"k021-finish-the-shift","name":"Through the next shift","description":"Repairs brakes overnight to maintain the next shift.","behavior":"Repairs brakes overnight to maintain the next shift.","stress":"Fears emergency heating stopping on a fuel-starved night.","relationship":"Obeys supply instructions but refuses concealed power distribution.","effects":[]}],"narrative":"Overnight brake repair and pump-test output adjustment support separate practical strengths. Fuel and output management are confirmed; machine invention is not granted.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc44-d3c9-ac15","name":"Pyeonggang Chae Clan","crest":"clan-crests/cc44-d3c9-ac15.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":40,"Openness":-5,"Force":5,"Material":30,"Communal":20,"Principle":25,"Public":0,"Eligibility":-10,"Dispersed":-50,"Transformative":-25},"desire":{"Longing":30,"Monopoly":0,"Risk":35,"Display":-25,"Sustained":40,"Orientation":"Reason","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Emergency Generator Operation","Rank":"Duty Chief","Title":"Sinjeong Base Emergency Generator Chief Operator","Work Location":"Sinjeong 3-dong. At the Sinjeong 3-dong depot, Chae Hansol seals the remaining fuel and the output log and sends them to Heo Eunchan, and allocates emergency generation output to match Heo Dodam''s pump trial run.","Values":"Authority 40 | Openness −5 | Force 5 | Material 30 | Communal 20 | Principle 25 | Publicity 0 | Qualification −10 | Dispersion −50 | Transformation −25","Desires":"Craving 30 | Monopoly 0 | Risk 35 | Display −25 | Persistence 40 | Orientation Opposite Sex | Union Contract Cohabitation"},"sections":{"Life":"Born in the 2126 generation. Grew up at the Sinjeong rail depot. The post of Sinjeong Depot Emergency Generation Operations Chief opened to her through a defect report made just before a derailment.\n- Workplace: Sinjeong 3-dong. At the Sinjeong 3-dong depot, Chae Hansol seals the remaining fuel and the output log and sends them to Heo Eunchan, and allocates emergency generation output to match Heo Dodam''s pump trial run.","Offices":"Rank: Duty Chief. Title: Sinjeong Base Emergency Generator Chief Operator. Each shift she seals the remaining fuel and the output log and posts them on the public gauge board, and if output is at or below the minimum, she cuts repair power distribution whatever favor is asked.","Anecdote":"In 2125, she repaired a broken brake overnight and kept the next shift''s train dispatch on schedule. Because of this, her signature for the post of Sinjeong Depot Emergency Generation Operations Chief was entered in the ledger.","Relationships":"She has backed Heo Eunchan''s power distribution to the stabling tracks from the generation side, matched output to Heo Dodam''s pump trial runs, and obeyed Han Jaemok''s orders to maintain supply, but has refused concealed power distribution.","Ambition":"Binds Sinjeong emergency generation and Yeongdeungpo heating power into a single public distribution grid, protecting the warmth of the winter dwellings.","Fear":"That on a night when the fuel runs out, heating runs only on hand-fed stoves, and the glow of the embers draws outside machines.","Intervention":"She can secure substitute fuel to open a dual distribution grid, or expose the tampering with the output logs so that the operations chief is replaced."},"biography":"Sensitive to the smell of fuel and hates verbal power allocations. Takes the pressure to divert power from dwelling heating to the wharf lighting as an insult.\n\n- Affiliation: Free City\n- Livelihood: Emergency Generator Operation\n- Rank: Duty Chief\n- Title: Sinjeong Base Emergency Generator Chief Operator\n**Life.** Born in the 2126 generation. Grew up at the Sinjeong rail depot. The post of Sinjeong Depot Emergency Generation Operations Chief opened to her through a defect report made just before a derailment.\n- Workplace: Sinjeong 3-dong. At the Sinjeong 3-dong depot, Chae Hansol seals the remaining fuel and the output log and sends them to Heo Eunchan, and allocates emergency generation output to match Heo Dodam''s pump trial run.\n\n**Office.** Rank: Duty Chief. Title: Sinjeong Base Emergency Generator Chief Operator. Each shift she seals the remaining fuel and the output log and posts them on the public gauge board, and if output is at or below the minimum, she cuts repair power distribution whatever favor is asked.\n\n**Anecdote.** In 2125, she repaired a broken brake overnight and kept the next shift''s train dispatch on schedule. Because of this, her signature for the post of Sinjeong Depot Emergency Generation Operations Chief was entered in the ledger.\n\n**Relations.** She has backed Heo Eunchan''s power distribution to the stabling tracks from the generation side, matched output to Heo Dodam''s pump trial runs, and obeyed Han Jaemok''s orders to maintain supply, but has refused concealed power distribution.\n\n**Ambition.** Binds Sinjeong emergency generation and Yeongdeungpo heating power into a single public distribution grid, protecting the warmth of the winter dwellings.\n\n**Fear.** That on a night when the fuel runs out, heating runs only on hand-fed stoves, and the glow of the embers draws outside machines.\n\n**Intervention.** She can secure substitute fuel to open a dual distribution grid, or expose the tampering with the output logs so that the operations chief is replaced.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 40 | Openness −5 | Force 5 | Material 30 | Communal 20 | Principle 25 | Publicity 0 | Credentials −10 | Dispersal −50 | Transformation −25\n- Desires: Craving 30 | Possessiveness 0 | Risk 35 | Display −25 | Endurance 40 | Orientation: Opposite Sex | Union: Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Chae Hansol","type":"Contract","to":"Han Jae-mok","basis":"Obeys Han Jaemok''s order to maintain supply but refuses concealed distribution"},{"from":"Chae Hansol","type":"Contract","to":"Heo Eunchan","basis":"Supports Heo Eunchan''s stabling-line power distribution from the generation side"}],"incoming":[]}}', '{"id":"person-0021","name":"채한솔","title":"신정기지 비상발전 운전장","position":"신정기지 비상발전 운전장","characterId":"K021","rank":"당직장","commonTier":"T4","occupation":"비상 발전 운전","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-채한솔","detailRoute":"/people/person-0021","birthDate":"2093-01-24","birthday":"01-24","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":10,"effective":10},"stewardship":{"base":12,"effective":12},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k021-generator-output-matching","name":"발전 출력 조정","rating":65},{"id":"k021-brake-repair","name":"제동 수리","rating":60},{"id":"k021-fuel-output-log","name":"연료·출력 기록","rating":60}],"traits":[{"id":"k021-documented-distribution","name":"기록된 배전","description":"구두 배전보다 출력 일지를 남긴다.","behavior":"구두 배전보다 출력 일지를 남긴다.","stress":"사정을 봐 달라는 압박으로 난방 전력을 빼는 일을 모욕으로 느낀다.","relationship":"허은찬의 배분을 발전 쪽에서 받친다.","effects":[]},{"id":"k021-finish-the-shift","name":"다음 교대까지","description":"제동 고장을 밤새 고쳐 교대를 이어 간다.","behavior":"제동 고장을 밤새 고쳐 교대를 이어 간다.","stress":"연료 고갈의 밤에 비상 난방이 멈출 것을 두려워한다.","relationship":"공급 지시에는 따르되 은폐 배전은 거부한다.","effects":[]}],"narrative":"제동 수리의 밤샘과 펌프 시운전 출력 조정을 별도로 반영했다. 연료·출력 관리는 확인되며 새로운 기계 발명은 발급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc44-d3c9-ac15","name":"평강 채씨","crest":"clan-crests/cc44-d3c9-ac15.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":40,"개방":-5,"무력":5,"물질":30,"공동":20,"원칙":25,"공개":0,"자격":-10,"분산":-50,"변혁":-25},"desire":{"갈망":30,"독점":0,"위험":35,"과시":-25,"지속":40,"지향":"이성","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"비상 발전 운전","품계":"당직장","직함":"신정기지 비상발전 운전장","업무 위치":"신정3동. 신정3동 기지에서 채한솔은 연료 잔량과 출력 일지를 봉인해 허은찬에게 보내고 허도담의 펌프 시운전에 맞춰 비상발전 출력을 배분한다.","가치관":"권위 40 | 개방 −5 | 무력 5 | 물질 30 | 공동 20 | 원칙 25 | 공개 0 | 자격 −10 | 분산 −50 | 변혁 −25","욕망":"갈망 30 | 독점 0 | 위험 35 | 과시 −25 | 지속 40 | 지향 이성 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 신정 차량기지에서 자랐다. 신정기지 비상발전 운전장 자리는 탈선 직전 결함 보고로 열렸다.\n- 업무 위치: 신정3동. 신정3동 기지에서 채한솔은 연료 잔량과 출력 일지를 봉인해 허은찬에게 보내고 허도담의 펌프 시운전에 맞춰 비상발전 출력을 배분한다.","관직":"품계 당직장. 직함은 신정기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 공개 계기판에 올리고, 최저 출력 이하면 어떤 부탁이 와도 정비용 배전을 끊는다.","일화":"2125년 고장 난 제동을 밤새 고쳐 다음 교대 배차를 지켰다. 이 일로 신정기지 비상발전 운전장 자리의 서명이 장부에 올랐다.","관계":"허은찬의 유치선 전력 배분을 발전 쪽에서 받치고, 허도담의 펌프 시운전에 출력을 맞추며, 한재목의 공급 유지 지시에는 복종해 왔지만 은폐 배전은 거부해 왔다.","야망":"신정 비상 발전과 영등포 난방 전력을 하나의 공개 배전망으로 묶어 겨울 거처의 온기를 지킨다.","공포":"연료가 바닥난 밤에 난방이 사람 손의 난로로만 돌아가고, 그 불씨가 바깥 기계를 끌어들이는 것.","개입":"대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다."},"biography":"연료 냄새에 예민하고 구두 배전을 싫어한다. 거처 난방보다 선창 조명에 전력을 돌리라는 압박을 모욕으로 여긴다.\n\n- 소속: 자유도시\n- 생업: 비상 발전 운전\n- 품계: 당직장\n- 직함: 신정기지 비상발전 운전장\n**생애.** 2126년 세대. 신정 차량기지에서 자랐다. 신정기지 비상발전 운전장 자리는 탈선 직전 결함 보고로 열렸다.\n- 업무 위치: 신정3동. 신정3동 기지에서 채한솔은 연료 잔량과 출력 일지를 봉인해 허은찬에게 보내고 허도담의 펌프 시운전에 맞춰 비상발전 출력을 배분한다.\n\n**관직.** 품계 당직장. 직함은 신정기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 공개 계기판에 올리고, 최저 출력 이하면 어떤 부탁이 와도 정비용 배전을 끊는다.\n\n**일화.** 2125년 고장 난 제동을 밤새 고쳐 다음 교대 배차를 지켰다. 이 일로 신정기지 비상발전 운전장 자리의 서명이 장부에 올랐다.\n\n**관계.** 허은찬의 유치선 전력 배분을 발전 쪽에서 받치고, 허도담의 펌프 시운전에 출력을 맞추며, 한재목의 공급 유지 지시에는 복종해 왔지만 은폐 배전은 거부해 왔다.\n\n**야망.** 신정 비상 발전과 영등포 난방 전력을 하나의 공개 배전망으로 묶어 겨울 거처의 온기를 지킨다.\n\n**공포.** 연료가 바닥난 밤에 난방이 사람 손의 난로로만 돌아가고, 그 불씨가 바깥 기계를 끌어들이는 것.\n\n**개입.** 대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 40 | 개방 −5 | 무력 5 | 물질 30 | 공동 20 | 원칙 25 | 공개 0 | 자격 −10 | 분산 −50 | 변혁 −25\n- 욕망: 갈망 30 | 독점 0 | 위험 35 | 과시 −25 | 지속 40 | 지향 이성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"채한솔","type":"계약","to":"한재목","basis":"한재목의 공급 유지 지시에는 복종하되 은폐 배전은 거부한다"},{"from":"채한솔","type":"계약","to":"허은찬","basis":"허은찬의 유치선 전력 배분을 발전 쪽에서 받치고"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0022', 'ace0-d55c-c591', '{"id":"person-0022","name":"Go Neulgyeol","title":"Sinjeong–Ttukseom Food Convoy Train Crew Member","position":"Sinjeong–Ttukseom Food Convoy Train Crew Member","rank":"Clerk","commonTier":"T5","occupation":"Convoy Train Crew Duty","gender":"Male","stage":"S3","state":"S01","stateName":"Free City","detailRoute":"/people/person-0022","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0022","name":"고늘결","title":"신정-뚝섬 식량 호송 열차 승무원","position":"신정-뚝섬 식량 호송 열차 승무원","rank":"주사","commonTier":"T5","occupation":"호송열차 승무","gender":"남성","stage":"S3","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0022","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0023', 'bc30-acbd-c8fc-88f5', '{"id":"person-0023","name":"Bae Chodam","title":"Dwelling Assignment Registry Clerk","position":"Dwelling Assignment Registry Clerk","rank":"Clerk","commonTier":"T5","occupation":"Contract Recording","gender":"Female","stage":"S3","state":"S01","stateName":"Free City","detailRoute":"/people/person-0023","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0023","name":"배초담","title":"거처 배정 명부 서기","position":"거처 배정 명부 서기","rank":"주사","commonTier":"T5","occupation":"계약 기록","gender":"여성","stage":"S3","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0023","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0024', 'b958-bb38-d654-67f3', '{"id":"person-0024","name":"Ryu Hanmoe","title":"Witness to the Will Copy","position":"Witness to the Will Copy","characterId":"K024","rank":"Clerk","commonTier":"T5","occupation":"Document Witnessing and Verification","gender":"Male","stage":"S3","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-ryuhanmoe","detailRoute":"/people/person-0024","birthDate":"2093-06-08","birthday":"06-08","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k024-copy-comparison","name":"Copy comparison","rating":60},{"id":"k024-public-confrontation","name":"Public confrontation","rating":55}],"traits":[{"id":"k024-joint-inspection","name":"Jointly opened copies","description":"Returns an empty envelope when only one side attends.","behavior":"Returns an empty envelope when only one side attends.","stress":"That the handover records he attended would be bundled with a doctored list, and the whole exchange of detained people would be branded a forgery.","relationship":"Wary of Jang Pilgyu''s margin readings, and matching page counts with Go Eunha, the Ttukseom workshop clerk.","effects":[]},{"id":"k024-physical-document-trust","name":"Seals and page counts","description":"Checks seal engravings and page counts before trusting words.","behavior":"Checks seal engravings and page counts before trusting words.","stress":"That the handover records he attended would be bundled with a doctored list, and the whole exchange of detained people would be branded a forgery.","relationship":"Wary of Jang Pilgyu''s margin readings, and matching page counts with Go Eunha, the Ttukseom workshop clerk.","effects":[]}],"narrative":"Confrontation and witnessed copy inspection are confirmed. Page and ink comparison is documentary work, without a measured forensic success rate or diplomatic argumentation.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":45,"Openness":-5,"Force":5,"Material":25,"Communal":25,"Principle":15,"Public":5,"Eligibility":0,"Dispersed":-40,"Transformative":-15},"desire":{"Longing":0,"Monopoly":15,"Risk":30,"Display":5,"Sustained":-10,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Affiliation":"Free City","Livelihood":"Document Witnessing and Verification","Rank":"Clerk","Title":"Witness to the Will Copy","Work Location":"Yangpyeong 1-dong. At the Yangpyeong 1-dong viewing handover, Ryu Hanmoe checks the page numbers and ink of the will copy against the records of Yun Seorin, Jang Pilgyu, and Go Eunha, and opens the envelope only after the ration representative and the auditor are both present.","Values":"Authority 45 | Openness −5 | Force 5 | Material 25 | Communal 25 | Principle 15 | Publicity 5 | Credentials 0 | Dispersal −40 | Transformation −15","Desires":"Craving 0 | Possessiveness 15 | Risk 30 | Display 5 | Endurance −10 | Orientation: Fluid | Union: Monogamy"},"sections":{"Life":"Born in the 2126 generation. Grew up on waiting-hall duty. The post of Witness to the Will Copy Attendance opened through a substitute shift after an unexcused absence.\n- Workplace: Yangpyeong 1-dong. At the Yangpyeong 1-dong viewing handover, Ryu Hanmoe checks the page numbers and ink of the will copy against the records of Yun Seorin, Jang Pilgyu, and Go Eunha, and opens the envelope only after the ration representative and the auditor are both present.","Offices":"Rank: Clerk. Title: Witness to the Will Copy. He opens a handover registry only when representatives of both the handing-over and receiving sides are watching at the same time, and a viewing attended by only one side is returned with an empty envelope.","Anecdote":"In 2125, when the accounts of two witnesses diverged, he opened a public confrontation. For this, his signature for the post of Witness to the Will Copy Attendance went into the ledger.","Relationships":"He stays wary of Jang Pilgyu''s marginal interpretations, and matches page numbers with Go Eunha, clerk of the Ttukseom workshop.","Ambition":"To line up the page numbers and ink of the handover registries that have drifted into the city with the original ledger, so that no one can choose the authentic copy at will.","Fear":"That a registry he attended will be bundled with a fabricated list and the entire handover record branded a forgery.","Intervention":"You can appraise the ink date of the copy to establish his testimony, or find traces of the envelope having been opened beforehand and strip him of his attendance qualification."},"biography":"At the sight of a paper with a broken seal his voice cracks first, and when three sheets overlap he counts page numbers instead of sighing. He trusts the impression of the confirmation seal over people.\n\n- Affiliation: Free City\n- Occupation: Document Witnessing and Verification\n- Rank: Clerk\n- Title: Witness to the Will Copy\n**Life.** Born in the 2126 generation. Grew up on waiting-hall duty. The post of Witness to the Will Copy Attendance opened through a substitute shift after an unexcused absence.\n- Workplace: Yangpyeong 1-dong. At the Yangpyeong 1-dong viewing handover, Ryu Hanmoe checks the page numbers and ink of the will copy against the records of Yun Seorin, Jang Pilgyu, and Go Eunha, and opens the envelope only after the ration representative and the auditor are both present.\n\n**Office.** Rank: Clerk. Title: Witness to the Will Copy. He opens a handover registry only when representatives of both the handing-over and receiving sides are watching at the same time, and a viewing attended by only one side is returned with an empty envelope.\n\n**Anecdote.** In 2125, when the accounts of two witnesses diverged, he opened a public confrontation. For this, his signature for the post of Witness to the Will Copy Attendance went into the ledger.\n\n**Relations.** He stays wary of Jang Pilgyu''s marginal interpretations, and matches page numbers with Go Eunha, clerk of the Ttukseom workshop.\n\n**Ambition.** To line up the page numbers and ink of the handover registries that have drifted into the city with the original ledger, so that no one can choose the authentic copy at will.\n\n**Fear.** That a registry he attended will be bundled with a fabricated list and the entire handover record branded a forgery.\n\n**Intervention.** You can appraise the ink date of the copy to establish his testimony, or find traces of the envelope having been opened beforehand and strip him of his attendance qualification.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 45 | Openness −5 | Force 5 | Material 25 | Communal 25 | Principle 15 | Publicity 5 | Credentials 0 | Dispersal −40 | Transformation −15\n- Desires: Craving 0 | Possessiveness 15 | Risk 30 | Display 5 | Endurance −10 | Orientation: Fluid | Union: Monogamy\n:::","relations":{"outgoing":[{"from":"Ryu Hanmoe","type":"Oath","to":"Yun Seo-rin","basis":""},{"from":"Ryu Hanmoe","type":"Oath","to":"Go Eun-ha","basis":"He matches page numbers with Go Eunha, clerk of the Ttukseom workshop"}],"incoming":[{"from":"Go Eun-ha","type":"Contract","to":"Ryu Hanmoe","basis":""}]}}', '{"id":"person-0024","name":"류한뫼","title":"유언 사본 입회 증인","position":"유언 사본 입회 증인","characterId":"K024","rank":"주사","commonTier":"T5","occupation":"문서 입회·대조","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-류한뫼","detailRoute":"/people/person-0024","birthDate":"2093-06-08","birthday":"06-08","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k024-copy-comparison","name":"사본 대조","rating":60},{"id":"k024-public-confrontation","name":"공개 대질","rating":55}],"traits":[{"id":"k024-joint-inspection","name":"함께 펼친 사본","description":"한쪽만 온 열람은 빈 봉투로 돌려보낸다.","behavior":"한쪽만 온 열람은 빈 봉투로 돌려보낸다.","stress":"자신이 입회한 인계 기록이 조작된 명단과 묶여 억류 인원 교환 전체가 위조로 몰리는 것.","relationship":"장필규의 난외 해석을 경계하며, 뚝섬 공방 서기 고은하와 쪽수를 맞춘다.","effects":[]},{"id":"k024-physical-document-trust","name":"도장과 쪽수","description":"사람 말보다 도장 각인과 쪽수를 확인한다.","behavior":"사람 말보다 도장 각인과 쪽수를 확인한다.","stress":"자신이 입회한 인계 기록이 조작된 명단과 묶여 억류 인원 교환 전체가 위조로 몰리는 것.","relationship":"장필규의 난외 해석을 경계하며, 뚝섬 공방 서기 고은하와 쪽수를 맞춘다.","effects":[]}],"narrative":"대질과 사본 입회가 확인된다. 잉크·쪽수의 대조는 문서 업무이며 전문 감정의 성공률이나 외교 논변은 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":45,"개방":-5,"무력":5,"물질":25,"공동":25,"원칙":15,"공개":5,"자격":0,"분산":-40,"변혁":-15},"desire":{"갈망":0,"독점":15,"위험":30,"과시":5,"지속":-10,"지향":"유동","결합":"단혼"},"fields":{"소속":"자유도시","생업":"문서 입회·대조","품계":"주사","직함":"유언 사본 입회 증인","업무 위치":"양평1동. 양평1동 열람 인계에서 류한뫼는 유언 사본의 쪽수와 잉크를 윤서린·장필규·고은하의 기록과 맞대고 배급 대표와 감사관이 함께 입회한 뒤 봉투를 연다.","가치관":"권위 45 | 개방 −5 | 무력 5 | 물질 25 | 공동 25 | 원칙 15 | 공개 5 | 자격 0 | 분산 −40 | 변혁 −15","욕망":"갈망 0 | 독점 15 | 위험 30 | 과시 5 | 지속 −10 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2126년 세대. 대합실 당직에서 자랐다. 유언 사본 입회 증인 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 양평1동. 양평1동 열람 인계에서 류한뫼는 유언 사본의 쪽수와 잉크를 윤서린·장필규·고은하의 기록과 맞대고 배급 대표와 감사관이 함께 입회한 뒤 봉투를 연다.","관직":"품계 주사. 직함은 유언 사본 입회 증인. 인계 명부는 맡기는 쪽과 받는 쪽 대표가 동시에 볼 때만 펼치고, 한쪽만 온 열람은 빈 봉투로 돌려보낸다.","일화":"2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 유언 사본 입회 증인 자리의 서명이 장부에 올랐다.","관계":"장필규의 난외 해석을 경계하며, 뚝섬 공방 서기 고은하와 쪽수를 맞춘다.","야망":"시내로 흘러든 인계 명부의 쪽수와 잉크를 원본 장부와 한 줄로 맞춰, 누구도 마음대로 진본을 고르지 못하게 한다.","공포":"자신이 입회한 인계 기록이 조작된 명단과 묶여 억류 인원 교환 전체가 위조로 몰리는 것.","개입":"사본의 잉크 일자를 감정해 그의 증언을 세우거나, 봉투를 미리 연 흔적을 찾아 입회 자격을 박탈할 수 있다."},"biography":"봉함 풀린 종이를 보면 목소리가 먼저 갈라지고, 세 장이 겹치면 한숨 대신 쪽수를 센다. 사람보다 인준 도장의 각인을 믿는다.\n\n- 소속: 자유도시\n- 생업: 문서 입회·대조\n- 품계: 주사\n- 직함: 유언 사본 입회 증인\n**생애.** 2126년 세대. 대합실 당직에서 자랐다. 유언 사본 입회 증인 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 양평1동. 양평1동 열람 인계에서 류한뫼는 유언 사본의 쪽수와 잉크를 윤서린·장필규·고은하의 기록과 맞대고 배급 대표와 감사관이 함께 입회한 뒤 봉투를 연다.\n\n**관직.** 품계 주사. 직함은 유언 사본 입회 증인. 인계 명부는 맡기는 쪽과 받는 쪽 대표가 동시에 볼 때만 펼치고, 한쪽만 온 열람은 빈 봉투로 돌려보낸다.\n\n**일화.** 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 유언 사본 입회 증인 자리의 서명이 장부에 올랐다.\n\n**관계.** 장필규의 난외 해석을 경계하며, 뚝섬 공방 서기 고은하와 쪽수를 맞춘다.\n\n**야망.** 시내로 흘러든 인계 명부의 쪽수와 잉크를 원본 장부와 한 줄로 맞춰, 누구도 마음대로 진본을 고르지 못하게 한다.\n\n**공포.** 자신이 입회한 인계 기록이 조작된 명단과 묶여 억류 인원 교환 전체가 위조로 몰리는 것.\n\n**개입.** 사본의 잉크 일자를 감정해 그의 증언을 세우거나, 봉투를 미리 연 흔적을 찾아 입회 자격을 박탈할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 45 | 개방 −5 | 무력 5 | 물질 25 | 공동 25 | 원칙 15 | 공개 5 | 자격 0 | 분산 −40 | 변혁 −15\n- 욕망: 갈망 0 | 독점 15 | 위험 30 | 과시 5 | 지속 −10 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"류한뫼","type":"맹세","to":"윤서린","basis":""},{"from":"류한뫼","type":"맹세","to":"고은하","basis":"뚝섬 공방 서기 고은하와 쪽수를 맞춘다"}],"incoming":[{"from":"고은하","type":"계약","to":"류한뫼","basis":""}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0025', 'c5c4-c601-c6d4', '{"id":"person-0025","name":"Eom Saeul","title":"Yeongdeungpo-dong Cold-Damage Dwelling Representative","position":"Yeongdeungpo-dong Cold-Damage Dwelling Representative","characterId":"K025","rank":"District Chief","commonTier":"T3","occupation":"Waiting Hall Duty","gender":"Female","stage":"S3","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-eomsaeul","detailRoute":"/people/person-0025","birthDate":"2098-09-07","birthday":"09-07","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k025-sealed-water-notes","name":"Sealing inspection notes","rating":60},{"id":"k025-register-recovery","name":"Recovering life registers","rating":50}],"traits":[{"id":"k025-neighborhood-first","name":"Check neighborhoods first","description":"Visits the alleys before consulting ledgers when light leaks through the shutters.","behavior":"Visits the alleys before consulting ledgers when light leaks through the shutters.","stress":"Keeps requesting an audience with the food officer when children''s food containers are empty.","relationship":"","effects":[]},{"id":"k025-no-cover-for-turbidity","name":"Distrust of cold-damage excuses","description":"Prioritizes victim registers and sealed samples.","behavior":"Prioritizes victim registers and sealed samples.","stress":"Withdraws seals when inspection concealment threatens to spread.","relationship":"Clashes with Han Jaemok over continued supply.","effects":[]}],"narrative":"Saved a life register during a fire and sends daily inspection notes. Damage records and local observation are strengths, without granting professional rescue or nursing experience.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c5c4-c601-c6d4","name":"Yeongwol Eom Clan","crest":"clan-crests/c5c4-c601-c6d4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":30,"Openness":-5,"Force":15,"Material":25,"Communal":15,"Principle":20,"Public":5,"Eligibility":0,"Dispersed":-45,"Transformative":-25},"desire":{"Longing":45,"Monopoly":25,"Risk":10,"Display":-10,"Sustained":0,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Affiliation":"Free City","Livelihood":"Waiting Hall Duty","Rank":"District Chief","Title":"Yeongdeungpo-dong Cold-Damage Dwelling Representative","Work Location":"Yeongdeungpo-dong. Eom Saeul, who makes her rounds of the Yeongdeungpo-dong alleys, seals the cold-damage inspection notes and sends them to the clinic, and withdraws her food-sharing ticket stamp in response to pressure to cut food sharing.","Values":"Authority 30 | Openness −5 | Force 15 | Material 25 | Communal 15 | Principle 20 | Publicity 5 | Credentials 0 | Decentralization −45 | Transformation −25","Desires":"Craving 45 | Monopoly 25 | Risk 10 | Display −10 | Persistence 0 | Orientation bisexual | Bonding non-exclusive"},"sections":{"Life":"Generation of 2126. Raised on concourse duty. The post of Yeongdeungpo-dong Cold-Damage Dwelling Representative opened after she stood a substitute duty for an absent colleague on a cold night.\n- Work location: Yeongdeungpo-dong. Eom Saeul, who makes her rounds of the Yeongdeungpo-dong alleys, seals the cold-damage inspection notes and sends them to the clinic, and withdraws her food-sharing ticket stamp in response to pressure to cut food sharing.","Offices":"Rank: District Chief. Title: Yeongdeungpo-dong Cold-Damage Dwelling Representative. Seals the dwelling inspection notes every day and sends them to the clinic; if heating fuel falls below the minimum line, she files the relocation requests of those dwellings all at once.","Anecdote":"During the 2125 station fire, she carried out the ledger of lives first. Because of this, her signature for the post of Yeongdeungpo-dong Cold-Damage Dwelling Representative was entered in the ledger.","Relationships":"Hands inspection notes to the clinic doctors, clashes with those who want to cut food sharing, and passes frostbite cases to the dwellings of Magok.","Ambition":"To make fuel and food top-ups for cold-damaged households open automatically according to the damage register, so that recognition of damage is never used as a bargaining chip.","Fear":"That after a cold snap, a danger of death by freezing hidden for even one day will spread to neighboring dwellings, and that kidnapping gangs will exploit the gap.","Intervention":"You can escort the sealed samples to Magok to justify her refusal, or expose the inflating of the register to shake her post as representative."},"biography":"When cold wind and light leak through the shutters, she walks the alleys before consulting the ledger, and she does not trust officials who cover cold damage with explanations. If the children''s food containers run empty, she does not cut off her appeals for an audience with the food officer.\n\n- Affiliation: Free City\n- Livelihood: Waiting Hall Duty\n- Rank: District Chief\n- Title: Yeongdeungpo-dong Cold-Damage Dwelling Representative\n**Life.** Generation of 2126. Raised on concourse duty. The post of Yeongdeungpo-dong Cold-Damage Dwelling Representative opened after she stood a substitute duty for an absent colleague on a cold night.\n- Work location: Yeongdeungpo-dong. Eom Saeul, who makes her rounds of the Yeongdeungpo-dong alleys, seals the cold-damage inspection notes and sends them to the clinic, and withdraws her food-sharing ticket stamp in response to pressure to cut food sharing.\n\n**Office.** Rank: District Chief. Title: Yeongdeungpo-dong Cold-Damage Dwelling Representative. Seals the dwelling inspection notes every day and sends them to the clinic; if heating fuel falls below the minimum line, she files the relocation requests of those dwellings all at once.\n\n**Anecdote.** During the 2125 station fire, she carried out the ledger of lives first. Because of this, her signature for the post of Yeongdeungpo-dong Cold-Damage Dwelling Representative was entered in the ledger.\n\n**Relationships.** Hands inspection notes to the clinic doctors, clashes with those who want to cut food sharing, and passes frostbite cases to the dwellings of Magok.\n\n**Ambition.** To make fuel and food top-ups for cold-damaged households open automatically according to the damage register, so that recognition of damage is never used as a bargaining chip.\n\n**Fear.** That after a cold snap, a danger of death by freezing hidden for even one day will spread to neighboring dwellings, and that kidnapping gangs will exploit the gap.\n\n**Intervention.** You can escort the sealed samples to Magok to justify her refusal, or expose the inflating of the register to shake her post as representative.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 30 | Openness −5 | Force 15 | Material 25 | Communal 15 | Principle 20 | Publicity 5 | Credentials 0 | Decentralization −45 | Transformation −25\n- Desires: Craving 45 | Monopoly 25 | Risk 10 | Display −10 | Persistence 0 | Orientation bisexual | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Eom Saeul","type":"Contract","to":"Bak Nu-ri","basis":""}],"incoming":[{"from":"Go Choyun","type":"Oath","to":"Eom Saeul","basis":"Return the copy of the sealed check slip to Eom Saeul of Yeongdeungpo-dong."}]}}', '{"id":"person-0025","name":"엄새울","title":"영등포동 한파 피해 거처 대표","position":"영등포동 한파 피해 거처 대표","characterId":"K025","rank":"구역장","commonTier":"T3","occupation":"대합실 당직","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-엄새울","detailRoute":"/people/person-0025","birthDate":"2098-09-07","birthday":"09-07","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k025-sealed-water-notes","name":"거처 점검 쪽지 봉인","rating":60},{"id":"k025-register-recovery","name":"인명 장부 회수","rating":50}],"traits":[{"id":"k025-neighborhood-first","name":"골목부터 확인","description":"덧문 틈으로 불빛이 새면 장부보다 골목을 먼저 돈다.","behavior":"덧문 틈으로 불빛이 새면 장부보다 골목을 먼저 돈다.","stress":"아이들 식량통이 비면 식량 담당자 면담을 계속 요구한다.","relationship":"","effects":[]},{"id":"k025-no-cover-for-turbidity","name":"한파 해명 불신","description":"피해 명부와 봉인 표본을 우선한다.","behavior":"피해 명부와 봉인 표본을 우선한다.","stress":"검사 은폐가 번질 상황에 날인을 거둔다.","relationship":"공급 유지를 주장하는 한재목과 충돌한다.","effects":[]}],"narrative":"화재에서 인명 장부를 구했고 매일 점검 쪽지를 보낸다. 피해 기록과 현장 관찰이 강점이며, 구조나 간호의 전문 경력까지 발급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c5c4-c601-c6d4","name":"영월 엄씨","crest":"clan-crests/c5c4-c601-c6d4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":30,"개방":-5,"무력":15,"물질":25,"공동":15,"원칙":20,"공개":5,"자격":0,"분산":-45,"변혁":-25},"desire":{"갈망":45,"독점":25,"위험":10,"과시":-10,"지속":0,"지향":"양성","결합":"비독점"},"fields":{"소속":"자유도시","생업":"대합실 당직","품계":"구역장","직함":"영등포동 한파 피해 거처 대표","업무 위치":"영등포동. 영등포동 골목을 도는 엄새울은 한파 피해 점검 쪽지를 봉인해 진료소로 보내고, 식량 나눔을 줄이라는 압박에는 나눔표 날인을 거둔다.","가치관":"권위 30 | 개방 −5 | 무력 15 | 물질 25 | 공동 15 | 원칙 20 | 공개 5 | 자격 0 | 분산 −45 | 변혁 −25","욕망":"갈망 45 | 독점 25 | 위험 10 | 과시 −10 | 지속 0 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 대합실 당직에서 자랐다. 영등포동 한파 피해 거처 대표 자리는 한파 밤 결근자의 당직을 대신 선 일로 열렸다.\n- 업무 위치: 영등포동. 영등포동 골목을 도는 엄새울은 한파 피해 점검 쪽지를 봉인해 진료소로 보내고, 식량 나눔을 줄이라는 압박에는 나눔표 날인을 거둔다.","관직":"품계 구역장. 직함은 영등포동 한파 피해 거처 대표. 거처 점검 쪽지를 매일 봉인해 진료소에 보내고, 난방 연료가 최저선 아래면 해당 거처의 이주 요청을 일제히 올린다.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 영등포동 한파 피해 거처 대표 자리의 서명이 장부에 올랐다.","관계":"진료소 의사들에게 점검 쪽지를 넘기고, 식량 나눔을 줄이자는 쪽과 충돌하며, 마곡 거처에는 동상 사례를 알린다.","야망":"한파 피해 가구의 연료와 식량 보충이 피해 명부에 따라 자동으로 열리게 해, 피해 인정이 흥정거리로 쓰이지 않게 한다.","공포":"한파 뒤 동사 위험이 하루만 숨겨져도 이웃 거처까지 번지고, 그 틈을 납치 일당이 노리는 것.","개입":"봉인 표본을 마곡까지 호송해 그의 거부를 정당화하거나, 명부 부풀리기를 밝혀 대표 직을 흔들 수 있다."},"biography":"덧문 틈으로 찬 바람과 불빛이 새면 장부보다 먼저 골목을 돌고, 한파 피해를 해명으로 덮는 관리를 믿지 않는다. 아이들 식량통이 비면 담당자 면담을 끊지 않는다.\n\n- 소속: 자유도시\n- 생업: 대합실 당직\n- 품계: 구역장\n- 직함: 영등포동 한파 피해 거처 대표\n**생애.** 2126년 세대. 대합실 당직에서 자랐다. 영등포동 한파 피해 거처 대표 자리는 한파 밤 결근자의 당직을 대신 선 일로 열렸다.\n- 업무 위치: 영등포동. 영등포동 골목을 도는 엄새울은 한파 피해 점검 쪽지를 봉인해 진료소로 보내고, 식량 나눔을 줄이라는 압박에는 나눔표 날인을 거둔다.\n\n**관직.** 품계 구역장. 직함은 영등포동 한파 피해 거처 대표. 거처 점검 쪽지를 매일 봉인해 진료소에 보내고, 난방 연료가 최저선 아래면 해당 거처의 이주 요청을 일제히 올린다.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 영등포동 한파 피해 거처 대표 자리의 서명이 장부에 올랐다.\n\n**관계.** 진료소 의사들에게 점검 쪽지를 넘기고, 식량 나눔을 줄이자는 쪽과 충돌하며, 마곡 거처에는 동상 사례를 알린다.\n\n**야망.** 한파 피해 가구의 연료와 식량 보충이 피해 명부에 따라 자동으로 열리게 해, 피해 인정이 흥정거리로 쓰이지 않게 한다.\n\n**공포.** 한파 뒤 동사 위험이 하루만 숨겨져도 이웃 거처까지 번지고, 그 틈을 납치 일당이 노리는 것.\n\n**개입.** 봉인 표본을 마곡까지 호송해 그의 거부를 정당화하거나, 명부 부풀리기를 밝혀 대표 직을 흔들 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 30 | 개방 −5 | 무력 15 | 물질 25 | 공동 15 | 원칙 20 | 공개 5 | 자격 0 | 분산 −45 | 변혁 −25\n- 욕망: 갈망 45 | 독점 25 | 위험 10 | 과시 −10 | 지속 0 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"엄새울","type":"계약","to":"박누리","basis":""}],"incoming":[{"from":"고초윤","type":"맹세","to":"엄새울","basis":"영등포동의 엄새울에게 봉인한 점검 쪽지의 사본을 돌려준다"}]}}');
