INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0076', 'c9c4-b0a8-c6d0-664b', '{"id":"person-0076","name":"Jin Maru","title":"Disaster Response Medical Escort Sergeant","position":"Disaster Response Medical Escort Sergeant","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Patient Escort","gender":"Male","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0076","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0076","name":"진마루","title":"방재 의무호송 반장","position":"방재 의무호송 반장","rank":"일반 시민","commonTier":"T5","occupation":"환자 호송","gender":"남성","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0076","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0077', 'cc44-d3c9-ac15', '{"id":"person-0077","name":"Chae Mujin","title":"Seed Vault Server Room Emergency Power Operator","position":"Seed Vault Server Room Emergency Power Operator","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Emergency Generator Operation","gender":"Female","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0077","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0077","name":"채무진","title":"원종 보존고 전산실 비상발전 운전장","position":"원종 보존고 전산실 비상발전 운전장","rank":"일반 시민","commonTier":"T5","occupation":"비상 발전 운전","gender":"여성","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0077","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0078', 'c6b0-b2e8-c591', '{"id":"person-0078","name":"U Daon","title":"Original Audio Recording Escort","position":"Original Audio Recording Escort","characterId":"K078","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Original Audio Escort","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#person-u-daon","detailRoute":"/people/person-0078","birthDate":"2066-03-10","birthday":"03-10","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audio","name":"Sealed audio-original transport","rating":60},{"id":"accounts","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"double-sealed-transport","name":"Double-Sealed Transport","description":"U Daon treats separate safety-review and transmission-verification locks as necessary for moving original reels.","behavior":"U Daon dispatches reel boxes only after both locks are secured and refuses solo transport even at the disaster-response unit''s request.","stress":"Concern about reels being swapped during transport may strengthen U Daon''s insistence on dual locks and no solo journeys.","relationship":"In working with Jeong Hojun, U Daon may retain safety review as a transport condition rather than waive it for convenience.","effects":[]},{"id":"no-reading-before-verification","name":"No Reading Before Verification","description":"U Daon withholds personal narration from broadcast wording that has not been verified.","behavior":"U Daon refuses to read broadcast wording before verification and passes originals to Choi Jiu for checking editing traces.","stress":"If a manipulated voice risks certification as an authentic testament, U Daon may prioritize completed verification over narration.","relationship":"U Daon may rely on Choi Jiu''s verification while resisting delays in opening originals for political scheduling.","effects":[]}],"narrative":"He moves reels only after dual locks and refuses solo delivery. Preservation and ledger checks are supported, not professional audio analysis.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":15,"Force":-40,"Material":0,"Communal":5,"Principle":70,"Public":45,"Eligibility":45,"Dispersed":20,"Transformative":5},"desire":{"Longing":5,"Monopoly":25,"Risk":-5,"Display":-30,"Sustained":10,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Affiliation":"Arc","Livelihood":"Original Audio Escort","Rank":"Ordinary Citizen","Title":"Original Audio Recording Escort","Duty":"Yangjae 1-dong. U Daon checks each of the safety review and transmission verification locks on the original audio reel and does not set out without an accompanying escort.","Values":"Authority −15 | Openness 15 | Force −40 | Materialism 0 | Communal 5 | Principle 70 | Publicity 45 | Qualification 45 | Decentralization 20 | Transformation 5","Desires":"Craving 5 | Monopoly 25 | Risk −5 | Display −30 | Persistence 10 | Orientation Heterosexual | Union Monogamous"},"sections":{"Life":"2126 generation. Grew up at the Seoul Station Registry Office. U Daon checks each of the safety review and transmission verification locks on the original audio reel and does not set out without an accompanying escort.\n- Duty: Yangjae 1-dong.","Offices":"Rank: Ordinary Citizen. Title: Original Audio Recording Escort. The reel box departs only after the safety review and the transmission verification have each placed their lock, and a solo escort is refused even when the disaster response unit requests it.","Anecdote":"In 2125, cross-checked the double-payment ledger, struck out one line, and left a signature.","Relationships":"Hands the original over to Choe Jiu''s edit-trace verification, makes Jeong Hojun''s safety review a condition of the escort, and partly borrows Pyo Jian''s Technical Ledger courier route.","Ambition":"Builds a double-sealed escort route that no negotiator can halt midway, so that the audio record is not cut into pieces of a winner''s propaganda.","Fear":"That the reel is swapped during the escort, that a fabricated voice is ratified as the authentic will, and that the researcher becomes a hostage witness.","Intervention":"Can open a severed escort route so the reel arrives on time, or expose a substitution in which the box weight differs and disqualify the escort."},"biography":"Hears editing noise before human speech, and regards a request to open the original reel late to suit the political schedule as an insult. Does not read broadcast text until it has been verified.\n\n- Affiliation: Arc\n- Livelihood: Original Audio Escort\n- Rank: Ordinary Citizen\n- Title: Original Audio Recording Escort\n**Life.** 2126 generation. Grew up at the Seoul Station Registry Office. U Daon checks each of the safety review and transmission verification locks on the original audio reel and does not set out without an accompanying escort.\n- Duty: Yangjae 1-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Original Audio Recording Escort. The reel box departs only after the safety review and the transmission verification have each placed their lock, and a solo escort is refused even when the disaster response unit requests it.\n\n**Anecdote.** In 2125, cross-checked the double-payment ledger, struck out one line, and left a signature.\n\n**Relations.** Hands the original over to Choe Jiu''s edit-trace verification, makes Jeong Hojun''s safety review a condition of the escort, and partly borrows Pyo Jian''s Technical Ledger courier route.\n\n**Ambition.** Builds a double-sealed escort route that no negotiator can halt midway, so that the audio record is not cut into pieces of a winner''s propaganda.\n\n**Fear.** That the reel is swapped during the escort, that a fabricated voice is ratified as the authentic will, and that the researcher becomes a hostage witness.\n\n**Intervention.** Can open a severed escort route so the reel arrives on time, or expose a substitution in which the box weight differs and disqualify the escort.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −15 | Openness 15 | Force −40 | Materialism 0 | Communal 5 | Principle 70 | Publicity 45 | Qualification 45 | Decentralization 20 | Transformation 5\n- Desires: Craving 5 | Monopoly 25 | Risk −5 | Display −30 | Persistence 10 | Orientation Heterosexual | Union Monogamous\n:::","relations":{"outgoing":[{"from":"U Daon","type":"Contract","to":"Choe Ji-u","basis":"Hands the original over to Choe Jiu''s edit-trace verification"},{"from":"U Daon","type":"Contract","to":"Jeong Hojun","basis":"Making Jeong Hojun''s safety review a condition of the convoy"}],"incoming":[]}}', '{"id":"person-0078","name":"우다온","title":"음성기록 원본 호송원","position":"음성기록 원본 호송원","characterId":"K078","rank":"일반 시민","commonTier":"T5","occupation":"음성 원본 호송","gender":"남성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-우다온","detailRoute":"/people/person-0078","birthDate":"2066-03-10","birthday":"03-10","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audio","name":"음성 원본 봉인 호송","rating":60},{"id":"accounts","name":"지급 장부 대조","rating":50}],"traits":[{"id":"double-sealed-transport","name":"이중 봉인 호송","description":"우다온은 원본 릴의 이동에 안전심사와 송신 검증의 독립된 잠금이 필요하다고 여긴다.","behavior":"두 자물쇠가 채워진 뒤에만 릴 상자를 출발시키고 방재대가 요청해도 단독 호송을 거절한다.","stress":"호송 중 릴 교체가 우려되면 이중 잠금과 단독 이동 금지를 더욱 고수할 수 있다.","relationship":"정호준과 협력할 때 안전심사를 편의상 생략할 절차가 아니라 호송의 조건으로 유지하려 할 수 있다.","effects":[]},{"id":"no-reading-before-verification","name":"검증 전 낭독 거부","description":"우다온은 검증되지 않은 방송 문구에 자신의 낭독을 보태지 않는다.","behavior":"검증 전에는 방송 문구를 읽지 않고 편집 흔적 검증을 위해 최지우에게 원본을 넘긴다.","stress":"조작된 목소리가 유언 진본으로 인준될 우려가 있으면 낭독보다 검증 완료를 우선할 수 있다.","relationship":"최지우와의 협력에서는 검증을 맡기되 정치 일정에 따른 원본 개봉 지연에는 동의하기 어려울 수 있다.","effects":[]}],"narrative":"이중 잠금 뒤에만 릴을 호송하고 단독 이동을 거부한다. 원본 보존과 장부 대조가 근거이며 전문 음향 분석을 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":15,"무력":-40,"물질":0,"공동":5,"원칙":70,"공개":45,"자격":45,"분산":20,"변혁":5},"desire":{"갈망":5,"독점":25,"위험":-5,"과시":-30,"지속":10,"지향":"이성","결합":"단혼"},"fields":{"소속":"Arc","생업":"음성 원본 호송","품계":"일반 시민","직함":"음성기록 원본 호송원","업무":"양재1동. 우다온은 음성 원본 릴의 안전심사와 송신 검증 잠금을 각각 확인하고 동행 호송 없이 출발하지 않는다.","가치관":"권위 −15 | 개방 15 | 무력 −40 | 물질 0 | 공동 5 | 원칙 70 | 공개 45 | 자격 45 | 분산 20 | 변혁 5","욕망":"갈망 5 | 독점 25 | 위험 −5 | 과시 −30 | 지속 10 | 지향 이성 | 결합 단혼"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 우다온은 음성 원본 릴의 안전심사와 송신 검증 잠금을 각각 확인하고 동행 호송 없이 출발하지 않는다.\n- 업무: 양재1동.","관직":"품계 일반 시민. 직함은 음성기록 원본 호송원. 릴 상자는 안전심사와 송신 검증이 각각 자물쇠를 채운 뒤에만 출발하고, 단독 호송은 방재대 요청이어도 거절한다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다.","관계":"최지우의 편집 흔적 검증에 원본을 넘기고, 정호준의 안전심사를 호송 조건으로 삼으며, 표지안의 기술원장 전령로를 일부 빌려 쓴다.","야망":"어느 교섭자도 중간에 끌 수 없는 이중 봉인 호송로를 만들어, 음성기록이 승자의 선전 조각으로 잘리지 않게 한다.","공포":"호송 중 릴이 바뀌고, 조작된 목소리가 유언 진본으로 인준되어 연구자가 증인 인질이 되는 것.","개입":"끊긴 호송로를 열어 릴을 제시간에 닿게 하거나, 상자 무게가 다른 바꿔치기를 밝혀 호송원을 실격시킬 수 있다."},"biography":"편집 잡음을 사람 말보다 먼저 듣고, 원본 릴을 정치 일정에 맞춰 늦게 열라는 요청을 모욕으로 여긴다. 검증 전까지는 방송 문구를 읽지 않는다.\n\n- 소속: Arc\n- 생업: 음성 원본 호송\n- 품계: 일반 시민\n- 직함: 음성기록 원본 호송원\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 우다온은 음성 원본 릴의 안전심사와 송신 검증 잠금을 각각 확인하고 동행 호송 없이 출발하지 않는다.\n- 업무: 양재1동.\n\n**관직.** 품계 일반 시민. 직함은 음성기록 원본 호송원. 릴 상자는 안전심사와 송신 검증이 각각 자물쇠를 채운 뒤에만 출발하고, 단독 호송은 방재대 요청이어도 거절한다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다.\n\n**관계.** 최지우의 편집 흔적 검증에 원본을 넘기고, 정호준의 안전심사를 호송 조건으로 삼으며, 표지안의 기술원장 전령로를 일부 빌려 쓴다.\n\n**야망.** 어느 교섭자도 중간에 끌 수 없는 이중 봉인 호송로를 만들어, 음성기록이 승자의 선전 조각으로 잘리지 않게 한다.\n\n**공포.** 호송 중 릴이 바뀌고, 조작된 목소리가 유언 진본으로 인준되어 연구자가 증인 인질이 되는 것.\n\n**개입.** 끊긴 호송로를 열어 릴을 제시간에 닿게 하거나, 상자 무게가 다른 바꿔치기를 밝혀 호송원을 실격시킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 15 | 무력 −40 | 물질 0 | 공동 5 | 원칙 70 | 공개 45 | 자격 45 | 분산 20 | 변혁 5\n- 욕망: 갈망 5 | 독점 25 | 위험 −5 | 과시 −30 | 지속 10 | 지향 이성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"우다온","type":"계약","to":"최지우","basis":"최지우의 편집 흔적 검증에 원본을 넘기고"},{"from":"우다온","type":"계약","to":"정호준","basis":"정호준의 안전심사를 호송 조건으로 삼으며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0079', 'ace0-d55c-c591', '{"id":"person-0079","name":"Go Choyun","title":"Daechi Shutter Check Witness","position":"Daechi Shutter Check Witness","characterId":"K079","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Attending Shutter and Light Checks","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-gochoyun","detailRoute":"/people/person-0079","birthDate":"2075-06-24","birthday":"06-24","age":51,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"disclose","name":"Witnessing inspection disclosure","rating":60},{"id":"sample","name":"Sample-record review","rating":55}],"traits":[{"id":"resist-disclosure-delays","name":"Resist Disclosure Delays","description":"Go Choyun regards delaying inspection disclosure to prevent unrest as political interference.","behavior":"Go Choyun records only the receipt time of delay orders, does not execute them, and refuses to bargain over disclosure timing.","stress":"If concealment threatens both food storage and light control, Go Choyun may become firmer against delay orders.","relationship":"Go Choyun may follow Jeong Hojun''s immediate-disclosure position while still requiring simultaneous resident and safety-review stamps for unsealing.","effects":[]},{"id":"no-missing-inspection-figures","name":"No Missing Inspection Figures","description":"Go Choyun treats even one missing entry on a check sheet as a defect in check disclosure.","behavior":"Go Choyun rejects blank entries on check sheets and designed an alternative way of verifying in the incident when entry to a sealed passage was refused.","stress":"If researchers risk being blamed for concealment, Go Choyun may be especially wary of gaps in inspection figures.","relationship":"When supporting Jang Yerin''s inspection network through testimony, Go Choyun may emphasize complete public numerical records.","effects":[]}],"narrative":"She checks dual signatures and designed alternate verification. Disclosure witnessing is supported without copying control of the entire inspection network.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":20,"Force":-30,"Material":10,"Communal":-10,"Principle":40,"Public":30,"Eligibility":50,"Dispersed":5,"Transformative":5},"desire":{"Longing":10,"Monopoly":10,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Attending Shutter and Light Checks","Rank":"Ordinary Citizen","Title":"Daechi Shutter Check Witness","Duty":"Daechi 1-dong. Go Choyun cross-checks Daechi''s shutter-check sheets against the lock markers and does not announce check results before the residents'' witness and the inspector have both signed.","Values":"Authority −5 | Openness 20 | Force −30 | Materialism 10 | Communal −10 | Principle 40 | Publicity 30 | Qualification 50 | Decentralization 5 | Transformation 5","Desires":"Craving 10 | Monopoly 10 | Risk −10 | Display 0 | Persistence 15 | Orientation None | Union Contract Cohabitation"},"sections":{"Life":"2126 generation. Grew up in the Daechi underground inspection room. Go Choyun cross-checks Daechi''s shutter-check sheets against the lock markers and does not announce check results before the residents'' witness and the inspector have both signed.\n- Duty: Daechi 1-dong.","Offices":"Rank: Ordinary Citizen. Title: Daechi Shutter Check Witness. The lock marker on a check sheet is lifted only when the residents'' witness and the inspector both sign, and delay orders are only logged with their time of receipt and never carried out.","Anecdote":"In 2125, refused permission to enter the sealed zone and designed a bypass verification.","Relationships":"Backs the check results of neighboring settlements'' inspectors with attendance, follows the case for full disclosure, and returns the public copies of the check sheets to the neighboring settlements.","Ambition":"Raises immediate disclosure of exceeded limits to a rule no one can refuse, so that orders from above cannot bury the checks.","Fear":"That a single day''s cover-up will bring down the food-storage shutters and light control at once, and that the inspector will be left to bear the blame.","Intervention":"Can confirm the posting time of Go Choyun''s test sheet against the sealed samples, or cross-check the correction marks in the numeric fields."},"biography":"Tolerates not even a single blank on the check sheet, and calls delay for the sake of preventing panic politics rather than checking. Never treats the disclosure time as a bargaining chip.\n\n- Affiliation: Arc\n- Livelihood: Attending Shutter and Light Checks\n- Rank: Ordinary Citizen\n- Title: Daechi Shutter Check Witness\n**Life.** 2126 generation. Grew up in the Daechi underground inspection room. Go Choyun cross-checks Daechi''s shutter-check sheets against the lock markers and does not announce check results before the residents'' witness and the inspector have both signed.\n- Duty: Daechi 1-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Daechi Shutter Check Witness. The lock marker on a check sheet is lifted only when the residents'' witness and the inspector both sign, and delay orders are only logged with their time of receipt and never carried out.\n\n**Anecdote.** In 2125, refused permission to enter the sealed zone and designed a bypass verification.\n\n**Relations.** Backs the check results of neighboring settlements'' inspectors with attendance, follows the case for full disclosure, and returns the public copies of the check sheets to the neighboring settlements.\n\n**Ambition.** Raises immediate disclosure of exceeded limits to a rule no one can refuse, so that orders from above cannot bury the checks.\n\n**Fear.** That a single day''s cover-up will bring down the food-storage shutters and light control at once, and that the inspector will be left to bear the blame.\n\n**Intervention.** Can confirm the posting time of Go Choyun''s test sheet against the sealed samples, or cross-check the correction marks in the numeric fields.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 20 | Force −30 | Materialism 10 | Communal −10 | Principle 40 | Publicity 30 | Qualification 50 | Decentralization 5 | Transformation 5\n- Desires: Craving 10 | Monopoly 10 | Risk −10 | Display 0 | Persistence 15 | Orientation None | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Go Choyun","type":"Oath","to":"Jang Yerin","basis":"Backing Jang Yerin''s testing network operations with testimony,"},{"from":"Go Choyun","type":"Oath","to":"Eom Saeul","basis":"Return the copy of the sealed check slip to Eom Saeul of Yeongdeungpo-dong."}],"incoming":[{"from":"Gi Seojin","type":"Contract","to":"Go Choyun","basis":"Post Go Choyun''s public test sheet on the outside of the box"}]}}', '{"id":"person-0079","name":"고초윤","title":"대치 셔터 점검 입회인","position":"대치 셔터 점검 입회인","characterId":"K079","rank":"일반 시민","commonTier":"T5","occupation":"셔터·불빛 점검 입회","gender":"여성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-고초윤","detailRoute":"/people/person-0079","birthDate":"2075-06-24","birthday":"06-24","age":51,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"disclose","name":"검사표 공개 입회","rating":60},{"id":"sample","name":"표본 기록 심사","rating":55}],"traits":[{"id":"resist-disclosure-delays","name":"공개 지연 불복","description":"고초윤은 혼란 방지를 명분으로 검사 공개를 늦추는 것을 정치적 개입으로 본다.","behavior":"지연 명령서는 받은 시각만 기록하고 집행하지 않으며 공개 시각을 흥정하지 않는다.","stress":"은폐가 식량 보관과 불빛 단속을 함께 무너뜨릴 우려가 커지면 지연 명령에 더욱 단호할 수 있다.","relationship":"정호준의 즉시 공개론을 따르면서도 봉인 해제에는 주민대표와 안전심사의 동시 날인을 요구할 수 있다.","effects":[]},{"id":"no-missing-inspection-figures","name":"검사 숫자 공백 거부","description":"고초윤은 점검표 한 칸의 누락도 점검 공개의 결함으로 여긴다.","behavior":"점검표의 빈칸을 용납하지 않으며, 봉쇄된 통로 진입을 거절당한 일에서는 다른 방법으로 확인할 길을 설계했다.","stress":"은폐의 책임이 연구자에게 전가될 우려가 있으면 검사 수치의 공백을 더욱 경계할 수 있다.","relationship":"장예린의 검사망을 증언으로 뒷받침할 때도 수치가 빠지지 않은 공개 기록을 중시할 수 있다.","effects":[]}],"narrative":"검사표의 이중 날인을 확인하고 우회 검증을 설계했다. 공개 입회와 검증 설계를 평가하며 검사망 전체 운영을 복사하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ace0-d55c-c591","name":"한양 고씨","crest":"clan-crests/ace0-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":20,"무력":-30,"물질":10,"공동":-10,"원칙":40,"공개":30,"자격":50,"분산":5,"변혁":5},"desire":{"갈망":10,"독점":10,"위험":-10,"과시":0,"지속":15,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"Arc","생업":"셔터·불빛 점검 입회","품계":"일반 시민","직함":"대치 셔터 점검 입회인","업무":"대치1동. 고초윤은 대치의 셔터 점검표와 잠금 표식을 맞춰 보고, 주민 쪽 입회인과 점검자가 함께 서명하기 전에는 점검 결과를 알리지 않는다.","가치관":"권위 −5 | 개방 20 | 무력 −30 | 물질 10 | 공동 −10 | 원칙 40 | 공개 30 | 자격 50 | 분산 5 | 변혁 5","욕망":"갈망 10 | 독점 10 | 위험 −10 | 과시 0 | 지속 15 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 대치 지하 점검실에서 자랐다. 고초윤은 대치의 셔터 점검표와 잠금 표식을 맞춰 보고, 주민 쪽 입회인과 점검자가 함께 서명하기 전에는 점검 결과를 알리지 않는다.\n- 업무: 대치1동.","관직":"품계 일반 시민. 직함은 대치 셔터 점검 입회인. 점검표는 주민 쪽 입회인과 점검자가 함께 서명해야 잠금 표식이 풀리고, 지연 명령서는 받은 시각만 기록한 채 따르지 않는다.","일화":"2125년 봉인 구역 진입 허가를 거절하고 우회 검증을 설계했다.","관계":"이웃 거주지 점검 담당의 점검 결과를 입회로 받치고, 빠짐없는 공개를 따르며, 점검표 공개본을 이웃 거주지에 돌려준다.","야망":"기준을 넘는 결과가 나오면 즉시 공개하는 것을 누구도 거부할 수 없는 규칙으로 올려, 윗사람의 지시가 점검을 덮지 못하게 한다.","공포":"하루의 은폐가 식량 보관 칸의 셔터와 불빛 단속을 동시에 무너뜨리고, 그 책임을 점검자가 뒤집어쓰는 것.","개입":"고초윤의 검사표 게시 시각을 봉인 표본으로 확인하거나 숫자 칸의 정정 흔적을 대조할 수 있다."},"biography":"점검표 한 칸의 빈칸도 용납하지 않고, 혼란 방지를 위한 지연을 점검이 아니라 정치로 부른다. 공개 시각을 흥정 거리로 삼지 않는다.\n\n- 소속: Arc\n- 생업: 셔터·불빛 점검 입회\n- 품계: 일반 시민\n- 직함: 대치 셔터 점검 입회인\n**생애.** 2126년 세대. 대치 지하 점검실에서 자랐다. 고초윤은 대치의 셔터 점검표와 잠금 표식을 맞춰 보고, 주민 쪽 입회인과 점검자가 함께 서명하기 전에는 점검 결과를 알리지 않는다.\n- 업무: 대치1동.\n\n**관직.** 품계 일반 시민. 직함은 대치 셔터 점검 입회인. 점검표는 주민 쪽 입회인과 점검자가 함께 서명해야 잠금 표식이 풀리고, 지연 명령서는 받은 시각만 기록한 채 따르지 않는다.\n\n**일화.** 2125년 봉인 구역 진입 허가를 거절하고 우회 검증을 설계했다.\n\n**관계.** 이웃 거주지 점검 담당의 점검 결과를 입회로 받치고, 빠짐없는 공개를 따르며, 점검표 공개본을 이웃 거주지에 돌려준다.\n\n**야망.** 기준을 넘는 결과가 나오면 즉시 공개하는 것을 누구도 거부할 수 없는 규칙으로 올려, 윗사람의 지시가 점검을 덮지 못하게 한다.\n\n**공포.** 하루의 은폐가 식량 보관 칸의 셔터와 불빛 단속을 동시에 무너뜨리고, 그 책임을 점검자가 뒤집어쓰는 것.\n\n**개입.** 고초윤의 검사표 게시 시각을 봉인 표본으로 확인하거나 숫자 칸의 정정 흔적을 대조할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 20 | 무력 −30 | 물질 10 | 공동 −10 | 원칙 40 | 공개 30 | 자격 50 | 분산 5 | 변혁 5\n- 욕망: 갈망 10 | 독점 10 | 위험 −10 | 과시 0 | 지속 15 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"고초윤","type":"맹세","to":"장예린","basis":"장예린의 검사망 운영을 증언으로 받치고"},{"from":"고초윤","type":"맹세","to":"엄새울","basis":"영등포동의 엄새울에게 봉인한 점검 쪽지의 사본을 돌려준다"}],"incoming":[{"from":"기서진","type":"계약","to":"고초윤","basis":"고초윤의 공개 검사표를 상자 겉면에 붙인다"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0080', 'bc30-bd84-c131-88f5', '{"id":"person-0080","name":"Bae Seoyul","title":"Counterfeit Medicine Sample Victims'' Representative","position":"Counterfeit Medicine Sample Victims'' Representative","characterId":"K080","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Medicine Harm Evidence and Roster Management","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-baeseoyul","detailRoute":"/people/person-0080","birthDate":"2085-07-18","birthday":"07-18","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"evidence","name":"Preserving victim samples and registers","rating":60},{"id":"dose","name":"Scarce-medicine allocation","rating":45}],"traits":[{"id":"keep-samples-sealed","name":"Keep Samples Sealed","description":"Bae Seoyul prioritizes keeping evidence sealed over expressing anger.","behavior":"Bae Seoyul double-seals the victim register and remaining medicine packets, opening appraisal only with the treatment guild and safety review present together.","stress":"If counterfeit medicine risks using forged certification stamps, Bae Seoyul may become still less willing to compromise sample seals.","relationship":"When entrusting samples to Ryu Eunbi, Bae Seoyul may look for intact seals.","effects":[]},{"id":"open-channels-for-anger","name":"Open Channels for Anger","description":"Bae Seoyul channels anger over counterfeit medicine into demands for public verification and manufacturing-route records.","behavior":"Bae Seoyul demands efficacy verification from Jeong Hojun and seeks public-ledger entries for counterfeit production routes.","stress":"If technical certification risks becoming a wrapper for poison, Bae Seoyul may express restrained anger through demands for open verification.","relationship":"With Jeong Hojun, Bae Seoyul may emphasize demands for efficacy verification rather than reassurance.","effects":[]}],"narrative":"He double-seals victim registers and medicine bags and shared scarce supplies. Evidence preservation is central; victim status does not establish a disease.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc30-bd84-c131-88f5","name":"Bunseong Bae Clan","crest":"clan-crests/bc30-bd84-c131-88f5.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":10,"Force":-35,"Material":20,"Communal":5,"Principle":50,"Public":40,"Eligibility":45,"Dispersed":25,"Transformative":15},"desire":{"Longing":40,"Monopoly":20,"Risk":-20,"Display":-20,"Sustained":0,"Orientation":"Same-Sex","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Medicine Harm Evidence and Roster Management","Rank":"Ordinary Citizen","Title":"Counterfeit Medicine Sample Victims'' Representative","Duty":"Daechi 1-dong. Bae Seoyul matches copies of Daechi''s certification stamp against the victims'' medicine pouches to find traces of forgery, and does not release samples before they are sealed.","Values":"Authority −30 | Openness 10 | Force −35 | Material 20 | Communal 5 | Principle 50 | Publicity 40 | Qualification 45 | Dispersal 25 | Transformation 15","Desires":"Craving 40 | Exclusivity 20 | Risk −20 | Display −20 | Persistence 0 | Orientation Same-sex | Union Polyamorous"},"sections":{"Life":"Generation of 2126. Grew up at the Jegi-dong infirmary. When appraising the leftover samples from the medicine pouches with Jin Chaeon, Bae Seoyul also checks the seal on the victim roll.\n- Duties: Yangjae 2-dong.\n- Duties: Daechi 1-dong. Bae Seoyul matches copies of Daechi''s certification stamp against the victims'' medicine pouches to find traces of forgery, and does not release samples before they are sealed.","Offices":"Rank: Ordinary Citizen. Title: Counterfeit Medicine Sample Victims'' Representative. He double-seals the victim roll and the leftover medicine pouches, and opens appraisal only when the Healing Guild and Safety Review are together in one place.","Anecdote":"In 2125, during a medicine shortage, halved the prescription amounts and shared them out to everyone.","Relationships":"He entrusts the samples to Ryu Eunbi, demands efficacy verification from Jeong Hojun, and borrows the safety of Jin Chaeon''s laboratory building as a place for appraisal.","Ambition":"He aims to post the fake drugs'' manufacturing routes on the public ledger, so that medicine comes down from the market price of spoils.","Fear":"That the fake drugs spread among the refugees will be used by forging the Daechi certification stamp, and that technical certification itself will become the packaging of poison.","Intervention":"He can cross-check Bae Seoyul''s victim roll against the seals on the recovered medicine pouches and verify copies bearing the forged stamp."},"biography":"He notices the blur of the print on a medicine pouch before the severity of the illness. He hides his anger but does not yield on the sample seal.\n\n- Affiliation: Arc\n- Livelihood: Medicine Harm Evidence and Roster Management\n- Rank: Ordinary Citizen\n- Title: Counterfeit Medicine Sample Victims'' Representative\n**Life.** Generation of 2126. Grew up at the Jegi-dong infirmary. When appraising the leftover samples from the medicine pouches with Jin Chaeon, Bae Seoyul also checks the seal on the victim roll.\n- Duties: Yangjae 2-dong.\n- Duties: Daechi 1-dong. Bae Seoyul matches copies of Daechi''s certification stamp against the victims'' medicine pouches to find traces of forgery, and does not release samples before they are sealed.\n\n**Office.** Rank: Ordinary Citizen. Title: Counterfeit Medicine Sample Victims'' Representative. He double-seals the victim roll and the leftover medicine pouches, and opens appraisal only when the Healing Guild and Safety Review are together in one place.\n\n**Anecdote.** In 2125, during a medicine shortage, halved the prescription amounts and shared them out to everyone.\n\n**Relationships.** He entrusts the samples to Ryu Eunbi, demands efficacy verification from Jeong Hojun, and borrows the safety of Jin Chaeon''s laboratory building as a place for appraisal.\n\n**Ambition.** He aims to post the fake drugs'' manufacturing routes on the public ledger, so that medicine comes down from the market price of spoils.\n\n**Fear.** That the fake drugs spread among the refugees will be used by forging the Daechi certification stamp, and that technical certification itself will become the packaging of poison.\n\n**Intervention.** He can cross-check Bae Seoyul''s victim roll against the seals on the recovered medicine pouches and verify copies bearing the forged stamp.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 10 | Force −35 | Material 20 | Communal 5 | Principle 50 | Publicity 40 | Qualification 45 | Dispersal 25 | Transformation 15\n- Desires: Craving 40 | Exclusivity 20 | Risk −20 | Display −20 | Persistence 0 | Orientation Same-sex | Union Polyamorous\n:::","relations":{"outgoing":[{"from":"Bae Seoyul","type":"Contract","to":"Ryu Eunbi","basis":"He entrusts the samples to Ryu Eunbi, and"},{"from":"Bae Seoyul","type":"Contract","to":"Jeong Hojun","basis":"Demanding verification of Jeong Hojun''s drug efficacy"}],"incoming":[]}}', '{"id":"person-0080","name":"배서율","title":"가짜 약품 표본 피해자 대표","position":"가짜 약품 표본 피해자 대표","characterId":"K080","rank":"일반 시민","commonTier":"T5","occupation":"약품 피해 증거·명부 관리","gender":"남성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-배서율","detailRoute":"/people/person-0080","birthDate":"2085-07-18","birthday":"07-18","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"evidence","name":"피해 표본·명부 보존","rating":60},{"id":"dose","name":"부족 약재 배분","rating":45}],"traits":[{"id":"keep-samples-sealed","name":"표본 봉인 고수","description":"배서율은 분노를 드러내는 일보다 피해 증거의 봉인을 지키는 일을 우선한다.","behavior":"피해자 명부와 잔여 약봉지를 이중 봉인하고 치료길드와 안전심사가 함께 있을 때만 감정을 연다.","stress":"가짜 약이 인증 도장을 위조해 쓸 우려가 커지면 표본 봉인을 더욱 양보하지 않을 수 있다.","relationship":"류은비에게 표본을 맡길 때 봉인 보존이 지켜지는지를 중시할 수 있다.","effects":[]},{"id":"open-channels-for-anger","name":"분노의 공개 경로","description":"배서율은 가짜 약에 대한 분노를 공개 검증과 제조 경로 기록의 요구로 향하게 한다.","behavior":"정호준에게 약효 검증을 요구하고 가짜 약의 제조 경로를 공개 원장에 올리려 한다.","stress":"기술 인증이 독의 포장이 될 우려가 커지면 숨긴 분노를 공개 검증 요구로 표현할 수 있다.","relationship":"정호준과의 관계에서는 위로보다 약효 검증을 요구하는 태도가 두드러질 수 있다.","effects":[]}],"narrative":"피해 명부와 약봉지를 이중 봉인하며 부족 약재를 나눴다. 피해 증거 보존이 중심이며 피해 경험을 특정 질병으로 단정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc30-bd84-c131-88f5","name":"분성 배씨","crest":"clan-crests/bc30-bd84-c131-88f5.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":10,"무력":-35,"물질":20,"공동":5,"원칙":50,"공개":40,"자격":45,"분산":25,"변혁":15},"desire":{"갈망":40,"독점":20,"위험":-20,"과시":-20,"지속":0,"지향":"동성","결합":"다자"},"fields":{"소속":"Arc","생업":"약품 피해 증거·명부 관리","품계":"일반 시민","직함":"가짜 약품 표본 피해자 대표","업무":"대치1동. 배서율은 대치의 인증 도장 사본과 피해 약봉지를 맞춰 위조 흔적을 찾고 봉인 전에는 표본을 내놓지 않는다.","가치관":"권위 −30 | 개방 10 | 무력 −35 | 물질 20 | 공동 5 | 원칙 50 | 공개 40 | 자격 45 | 분산 25 | 변혁 15","욕망":"갈망 40 | 독점 20 | 위험 −20 | 과시 −20 | 지속 0 | 지향 동성 | 결합 다자"},"sections":{"생애":"2126년 세대. 제기동 의무소에서 자랐다. 배서율은 진채온과 약봉지의 잔여 표본을 감정할 때 피해자 명부의 봉인을 함께 확인한다.\n- 업무: 양재2동.\n- 업무: 대치1동. 배서율은 대치의 인증 도장 사본과 피해 약봉지를 맞춰 위조 흔적을 찾고 봉인 전에는 표본을 내놓지 않는다.","관직":"품계 일반 시민. 직함은 가짜 약품 표본 피해자 대표. 피해자 명부와 잔여 약봉지를 이중 봉인하고, 감정은 치료길드와 안전심사가 한자리에 있을 때만 연다.","일화":"2125년 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다.","관계":"류은비에게 표본을 맡기고, 정호준의 약효 검증을 요구하며, 진채온의 실험동 안전을 감정 장소로 빌린다.","야망":"가짜 약품의 제조 경로를 공개 원장에 올려, 의약품이 전리품 시세에서 내려오게 한다.","공포":"피난민에게 퍼진 가짜 약이 대치 인증 도장을 위조해 쓰이고, 기술 인증 자체가 독의 포장이 되는 것.","개입":"배서율의 피해자 명부와 회수한 약봉지의 봉인을 대조하고 위조 도장이 찍힌 사본을 확인할 수 있다."},"biography":"약봉지의 인쇄 흐림을 병세보다 먼저 본다. 분노를 숨기되 표본 봉인은 양보하지 않는다.\n\n- 소속: Arc\n- 생업: 약품 피해 증거·명부 관리\n- 품계: 일반 시민\n- 직함: 가짜 약품 표본 피해자 대표\n**생애.** 2126년 세대. 제기동 의무소에서 자랐다. 배서율은 진채온과 약봉지의 잔여 표본을 감정할 때 피해자 명부의 봉인을 함께 확인한다.\n- 업무: 양재2동.\n- 업무: 대치1동. 배서율은 대치의 인증 도장 사본과 피해 약봉지를 맞춰 위조 흔적을 찾고 봉인 전에는 표본을 내놓지 않는다.\n\n**관직.** 품계 일반 시민. 직함은 가짜 약품 표본 피해자 대표. 피해자 명부와 잔여 약봉지를 이중 봉인하고, 감정은 치료길드와 안전심사가 한자리에 있을 때만 연다.\n\n**일화.** 2125년 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다.\n\n**관계.** 류은비에게 표본을 맡기고, 정호준의 약효 검증을 요구하며, 진채온의 실험동 안전을 감정 장소로 빌린다.\n\n**야망.** 가짜 약품의 제조 경로를 공개 원장에 올려, 의약품이 전리품 시세에서 내려오게 한다.\n\n**공포.** 피난민에게 퍼진 가짜 약이 대치 인증 도장을 위조해 쓰이고, 기술 인증 자체가 독의 포장이 되는 것.\n\n**개입.** 배서율의 피해자 명부와 회수한 약봉지의 봉인을 대조하고 위조 도장이 찍힌 사본을 확인할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 10 | 무력 −35 | 물질 20 | 공동 5 | 원칙 50 | 공개 40 | 자격 45 | 분산 25 | 변혁 15\n- 욕망: 갈망 40 | 독점 20 | 위험 −20 | 과시 −20 | 지속 0 | 지향 동성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"배서율","type":"계약","to":"류은비","basis":"류은비에게 표본을 맡기고"},{"from":"배서율","type":"계약","to":"정호준","basis":"정호준의 약효 검증을 요구하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0081', 'b958-bb38-d654-67f3', '{"id":"person-0081","name":"Ryu Haneul","title":"Blackout Emergency Powers Clerk","position":"Blackout Emergency Powers Clerk","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Emergency Powers Log Recording","gender":"Female","stage":"S3","state":"S03","stateName":"Arc","detailRoute":"/people/person-0081","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0081","name":"류하늘","title":"대정전 비상권한 서기","position":"대정전 비상권한 서기","rank":"일반 시민","commonTier":"T5","occupation":"비상권한 일지 기록","gender":"여성","stage":"S3","state":"S03","stateName":"Arc","detailRoute":"/people/person-0081","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0082', 'c5c4-c601-c6d4', '{"id":"person-0082","name":"Eom Dohan","title":"Researcher Dispatch Escort Chief","position":"Researcher Dispatch Escort Chief","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Researcher Escort","gender":"Male","stage":"S3","state":"S03","stateName":"Arc","detailRoute":"/people/person-0082","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0082","name":"엄도한","title":"연구자 파견 호송책","position":"연구자 파견 호송책","rank":"일반 시민","commonTier":"T5","occupation":"연구자 호송","gender":"남성","stage":"S3","state":"S03","stateName":"Arc","detailRoute":"/people/person-0082","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0083', 'c5ec-d568-c591', '{"id":"person-0083","name":"Yeo Dasom","title":"Yangjae Parts and Copy Records Clerk","position":"Council Technology Sharing Clerk","characterId":"K083","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Technology Sharing Document Recording","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-yeodasom","detailRoute":"/people/person-0083","birthDate":"2092-08-03","birthday":"08-03","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"sharing","name":"Technical-sharing copy preparation","rating":60},{"id":"surgery","name":"Stanching bleeding during a blackout","rating":45}],"traits":[{"id":"stop-for-missing-pages","name":"Stop for Missing Pages","description":"Yeo Dasom places the completeness of certification copies ahead of meeting progress.","behavior":"Yeo Dasom stops writing when certification pages are missing and refuses to file drafts with blank hostage-alternative fields.","stress":"Yeo Dasom may be especially cautious about recording incomplete documents.","relationship":"When transcribing Jeong Hojun''s draft and bundling Jeong Yura''s termination clauses, Yeo Dasom may emphasize that required documents are not omitted.","effects":[]},{"id":"smaller-nations-review-first","name":"Check the Copy First","description":"Yeo Dasom prioritizes giving the receiving side time to look over parts lists and software copies before they are handed over.","behavior":"Yeo Dasom places a copy into the storage box only after the receiving side has read the parts list copy.","stress":"If winter parts exchange risks being dragged along by a stronger party''s terms, Yeo Dasom may insist more firmly on that review order.","relationship":"In exchanging minimum-fuel copies with a neighboring settlement''s records keeper, Yeo Dasom may seek to keep access from being tied to one side''s conditions.","effects":[]}],"narrative":"She records sharing copies and termination clauses and kept stanching bleeding during a blackout. That episode supports limited skill, not a full medical career.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c5ec-d568-c591","name":"Hamyang Yeo Clan","crest":"clan-crests/c5ec-d568-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":10,"Force":-35,"Material":10,"Communal":0,"Principle":40,"Public":30,"Eligibility":55,"Dispersed":10,"Transformative":15},"desire":{"Longing":0,"Monopoly":10,"Risk":15,"Display":-10,"Sustained":20,"Orientation":"None","Union":"Monogamy"},"fields":{"Affiliation":"Arc","Livelihood":"Technology Sharing Document Recording","Rank":"Ordinary Citizen","Title":"Council Technology Sharing Clerk","Duty":"Yangjae 1-dong. Before filing a parts-exchange list, Yeo Dasom cross-checks the receiving side''s reading order against the wording to make sure no hostage demand is slipped in, and binds a copy of the neighboring settlement''s minimum fuel line.","Values":"Authority −15 | Openness 10 | Force −35 | Material 10 | Communal 0 | Principle 40 | Publicity 30 | Qualification 55 | Dispersal 10 | Transformation 15","Desires":"Craving 0 | Exclusivity 10 | Risk 15 | Display −10 | Persistence 20 | Orientation No preference | Union Monogamous"},"sections":{"Life":"Generation of 2126. Grew up in a Jegi-dong underground shelter room. Before filing a parts-exchange list, Yeo Dasom cross-checks the receiving side''s reading order against the wording to make sure no hostage demand is slipped in, and binds a copy of the neighboring settlement''s minimum fuel line.\n- Duties: Yangjae 1-dong.","Offices":"Rank: Ordinary Citizen. Title: Council Technology Sharing Clerk. A technology-sharing copy is placed at other participants'' seats only after the delegates taking part in the negotiation have read it, and a draft whose hostage-substitution column is blank is not filed.","Anecdote":"In 2125, when the power went out during emergency care, she kept stanching the bleeding by the light of a handheld phone.","Relationships":"As clerk, she copies out the parts lists the maintenance staff need, puts the wording of the exchange termination conditions into the same bundle, and exchanges copies of the minimum fuel line with a neighboring settlement''s records keeper.","Ambition":"Raise verification-data sharing to an independent item of parts exchange, so that the records do not fall to being an appendix of a stronger party''s deal.","Fear":"","Intervention":"Can cross-check the parts-exchange list Yeo Dasom bound against the neighboring settlement''s minimum fuel copy to confirm any missing access or hostage-related wording."},"biography":"If a page number is missing from a copy, she stops her pen first, and if she sees wording that hides knowledge behind a ransom clause, she leaves her seat. She writes numbers large and interpretations short.\n\n- Affiliation: Arc\n- Livelihood: Technology Sharing Document Recording\n- Rank: Ordinary Citizen\n- Title: Council Technology Sharing Clerk\n**Life.** Generation of 2126. Grew up in a Jegi-dong underground shelter room. Before filing a parts-exchange list, Yeo Dasom cross-checks the receiving side''s reading order against the wording to make sure no hostage demand is slipped in, and binds a copy of the neighboring settlement''s minimum fuel line.\n- Duties: Yangjae 1-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Council Technology Sharing Clerk. A technology-sharing copy is placed at other participants'' seats only after the delegates taking part in the negotiation have read it, and a draft whose hostage-substitution column is blank is not filed.\n\n**Anecdote.** In 2125, when the power went out during emergency care, she kept stanching the bleeding by the light of a handheld phone.\n\n**Relations.** As clerk, she copies out the parts lists the maintenance staff need, puts the wording of the exchange termination conditions into the same bundle, and exchanges copies of the minimum fuel line with a neighboring settlement''s records keeper.\n\n**Ambition.** Raise verification-data sharing to an independent item of parts exchange, so that the records do not fall to being an appendix of a stronger party''s deal.\n\n**Intervention.** Can cross-check the parts-exchange list Yeo Dasom bound against the neighboring settlement''s minimum fuel copy to confirm any missing access or hostage-related wording.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 10 | Force −35 | Materialism 10 | Communal 0 | Principle 40 | Transparency 30 | Qualification 55 | Dispersal 10 | Transformation 15\n- Desires: Craving 0 | Monopoly 10 | Risk 15 | Display −10 | Persistence 20 | Orientation None | Union Monogamous\n:::","relations":{"outgoing":[{"from":"Yeo Dasom","type":"Contract","to":"U Oreum","basis":"Exchange copies of the machine-body parts list and food weighing records with U Oreum of Yeouido"}],"incoming":[]}}', '{"id":"person-0083","name":"여다솜","title":"양재 부품·사본 기록 서기","position":"협의 기술공유 서기","characterId":"K083","rank":"일반 시민","commonTier":"T5","occupation":"기술공유 문서 기록","gender":"여성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-여다솜","detailRoute":"/people/person-0083","birthDate":"2092-08-03","birthday":"08-03","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"sharing","name":"기술공유 사본 작성","rating":60},{"id":"surgery","name":"정전 중 응급 지혈 지속","rating":45}],"traits":[{"id":"stop-for-missing-pages","name":"쪽수 빠지면 중지","description":"여다솜은 인증 사본의 완전성을 회의 진행보다 앞세운다.","behavior":"인증 사본의 쪽수가 빠지면 필기를 멈추고 인질 대체 칸이 빈 초안은 철하지 않는다.","stress":"불완전한 문서를 남기는 데 더욱 신중할 수 있다.","relationship":"정호준의 초안을 옮기고 정유라의 종료조건을 묶을 때도 필요한 문서가 빠지지 않는지를 중시할 수 있다.","effects":[]},{"id":"smaller-nations-review-first","name":"사본 먼저 확인","description":"여다솜은 부품 목록과 소프트웨어 사본을 넘기기 전에 받는 쪽이 먼저 훑어볼 시간을 주는 일을 중시한다.","behavior":"받는 쪽 사람이 부품 목록 사본을 읽은 뒤에만 보관함에 올린다.","stress":"겨울 부품 교환이 힘센 쪽의 조건에 딸려 갈 우려가 있으면 열람 순서를 더욱 고수할 수 있다.","relationship":"이웃 거주지의 기록 담당과 연료 최저선 사본을 맞바꿀 때도 자료 접근이 한쪽 조건에 묶이지 않도록 중시할 수 있다.","effects":[]}],"narrative":"공유 사본과 종료조건을 기록하고 정전 중 응급 지혈을 이어 갔다. 이례적 일화는 제한 숙련으로 남기며 의료 경력 전반을 만들지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c5ec-d568-c591","name":"함양 여씨","crest":"clan-crests/c5ec-d568-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":10,"무력":-35,"물질":10,"공동":0,"원칙":40,"공개":30,"자격":55,"분산":10,"변혁":15},"desire":{"갈망":0,"독점":10,"위험":15,"과시":-10,"지속":20,"지향":"무성향","결합":"단혼"},"fields":{"소속":"Arc","생업":"기술공유 문서 기록","품계":"일반 시민","직함":"협의 기술공유 서기","업무":"양재1동. 여다솜은 부품 교환 목록을 철하기 전에 받는 쪽의 열람 순서와 인질 요구가 끼어 있지 않은지 문구를 대조하고, 이웃 거주지의 연료 최저선 사본을 묶는다.","가치관":"권위 −15 | 개방 10 | 무력 −35 | 물질 10 | 공동 0 | 원칙 40 | 공개 30 | 자격 55 | 분산 10 | 변혁 15","욕망":"갈망 0 | 독점 10 | 위험 15 | 과시 −10 | 지속 20 | 지향 무성향 | 결합 단혼"},"sections":{"생애":"2126년 세대. 제기동 지하 대피방에서 자랐다. 여다솜은 부품 교환 목록을 철하기 전에 받는 쪽의 열람 순서와 인질 요구가 끼어 있지 않은지 문구를 대조하고, 이웃 거주지의 연료 최저선 사본을 묶는다.\n- 업무: 양재1동.","관직":"품계 일반 시민. 직함은 협의 기술공유 서기. 기술공유 사본은 교섭에 참여한 대표가 열람한 뒤에만 다른 참가자의 자리에 올리고, 인질 대체 칸이 빈 초안은 철하지 않는다.","일화":"2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다.","관계":"정비 담당이 필요로 하는 부품 목록을 서기로서 옮겨 적고, 교환 종료 조건 문구를 같은 묶음에 넣으며, 이웃 거주지의 기록 담당과 연료 최저선 사본을 교환한다.","야망":"검증 자료 공유를 부품 교환의 독립 항목으로 올려, 기록이 힘센 쪽 거래의 부록으로 떨어지지 않게 한다.","공포":"","개입":"여다솜이 묶은 부품 교환 목록과 이웃 거주지의 연료 최저선 사본을 대조해 빠진 열람 또는 인질 관련 문구를 확인할 수 있다."},"biography":"사본의 쪽수가 빠지면 먼저 펜을 멈추고, 지식을 몸값 조항 뒤에 숨기는 문구를 보면 자리를 뜬다. 숫자는 크게, 해석은 짧게 적는다.\n\n- 소속: Arc\n- 생업: 기술공유 문서 기록\n- 품계: 일반 시민\n- 직함: 협의 기술공유 서기\n**생애.** 2126년 세대. 제기동 지하 대피방에서 자랐다. 여다솜은 부품 교환 목록을 철하기 전에 받는 쪽의 열람 순서와 인질 요구가 끼어 있지 않은지 문구를 대조하고, 이웃 거주지의 연료 최저선 사본을 묶는다.\n- 업무: 양재1동.\n\n**관직.** 품계 일반 시민. 직함은 협의 기술공유 서기. 기술공유 사본은 교섭에 참여한 대표가 열람한 뒤에만 다른 참가자의 자리에 올리고, 인질 대체 칸이 빈 초안은 철하지 않는다.\n\n**일화.** 2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다.\n\n**관계.** 정비 담당이 필요로 하는 부품 목록을 서기로서 옮겨 적고, 교환 종료 조건 문구를 같은 묶음에 넣으며, 이웃 거주지의 기록 담당과 연료 최저선 사본을 교환한다.\n\n**야망.** 검증 자료 공유를 부품 교환의 독립 항목으로 올려, 기록이 힘센 쪽 거래의 부록으로 떨어지지 않게 한다.\n\n**개입.** 여다솜이 묶은 부품 교환 목록과 이웃 거주지의 연료 최저선 사본을 대조해 빠진 열람 또는 인질 관련 문구를 확인할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 10 | 무력 −35 | 물질 10 | 공동 0 | 원칙 40 | 공개 30 | 자격 55 | 분산 10 | 변혁 15\n- 욕망: 갈망 0 | 독점 10 | 위험 15 | 과시 −10 | 지속 20 | 지향 무성향 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"여다솜","type":"계약","to":"우오름","basis":"여의도의 우오름과 기계 몸 부품 목록 사본과 식량 계량 기록을 교환한다"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0084', 'ae30-d589-c8fc', '{"id":"person-0084","name":"Gi Seojin","title":"Non-Military Joint Survey Courier","position":"Non-Military Joint Survey Courier","characterId":"K084","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Survey Document Delivery","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#Person-Gi-Seojin","detailRoute":"/people/person-0084","birthDate":"2092-09-01","birthday":"09-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"mission","name":"Joint-investigation signature checks","rating":60},{"id":"departure","name":"Departure and dispatch checks","rating":50}],"traits":[{"id":"wait-for-three-stamps","name":"Wait for Three Stamps","description":"Gi Seojin makes complete approval from three validating bodies a departure condition rather than prioritizing delivery speed alone.","behavior":"Gi Seojin waits for treatment-guild, safety-review, and transmission-verification stamps and stopped an unsigned departure by a train without a dispatch schedule.","stress":"","relationship":"When reporting arrival times to Choi Jiu, Gi Seojin may still prioritize departure only after all three stamps are secured.","effects":[]},{"id":"nonmilitary-investigations","name":"Nonmilitary Investigations","description":"Gi Seojin rejects turning joint investigations into military escort operations.","behavior":"Gi Seojin tears up requests to turn investigators into escorts and returns routes containing military-escort fields.","stress":"","relationship":"","effects":[]}],"narrative":"He checks three signatures and stopped an undocumented train. Delivery-condition enforcement is supported, not diplomatic authority or armed escort expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ae30-d589-c8fc","name":"Haengju Gi Clan","crest":"clan-crests/ae30-d589-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":35,"Force":-40,"Material":5,"Communal":5,"Principle":45,"Public":55,"Eligibility":40,"Dispersed":20,"Transformative":0},"desire":{"Longing":45,"Monopoly":-5,"Risk":40,"Display":25,"Sustained":5,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Survey Document Delivery","Rank":"Ordinary Citizen","Title":"Non-Military Joint Survey Courier","Duty":"Daechi 1-dong. Gi Seojin checks whether the Healing, Safety Review, and Transmission Verification seals have gathered on the Daechi joint investigation note, and turns the route back if there is a military escort column.","Values":"Authority 0 | Openness 35 | Force −40 | Materialism 5 | Communal 5 | Principle 45 | Transparency 55 | Qualification 40 | Dispersal 20 | Transformation 0","Desires":"Craving 45 | Monopoly −5 | Risk 40 | Display 25 | Persistence 5 | Orientation Bisexual | Union Contract Cohabitation"},"sections":{"Life":"Generation of 2126. Raised at the Sinnae transfer duty station. Gi Seojin checks whether the Healing, Safety Review, and Transmission Verification seals have gathered on the Daechi joint investigation note, and turns the route back if there is a military escort column.\n- Work: Daechi 1-dong.","Offices":"Rank: Ordinary Citizen. Title: Non-Military Joint Survey Courier. An investigation note departs only after the three seals of the Healing Guild, Safety Review, and Transmission Verification have gathered, and a route with a military escort column written on it is sent back.","Anecdote":"In 2125 he stopped a train with no dispatch sheet and blocked a departure without signatures.","Relationships":"He hands the arrival time over to Choe Jiu''s breaking-news pact, and pastes Go Choyun''s public inspection sheet on the outside of the box.","Ambition":"Leave a public route for completing the joint investigation of Jegi-dong, Daechi, and Sangam without force.","Fear":"","Intervention":""},"biography":"He checks the color of the escort flag before the temperature of the sample box, and tears up notes telling him to turn the investigation team into an escort team. He speaks little and keeps to the arrival time.\n\n- Affiliation: Arc\n- Occupation: Survey Document Delivery\n- Rank: Ordinary Citizen\n- Title: Non-Military Joint Survey Courier\n**Life.** Generation of 2126. Raised at the Sinnae transfer duty station. Gi Seojin checks whether the Healing, Safety Review, and Transmission Verification seals have gathered on the Daechi joint investigation note, and turns the route back if there is a military escort column.\n- Work: Daechi 1-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Non-Military Joint Survey Courier. An investigation note departs only after the three seals of the Healing Guild, Safety Review, and Transmission Verification have gathered, and a route with a military escort column written on it is sent back.\n\n**Anecdote.** In 2125 he stopped a train with no dispatch sheet and blocked a departure without signatures.\n\n**Relations.** He hands the arrival time over to Choe Jiu''s breaking-news pact, and pastes Go Choyun''s public inspection sheet on the outside of the box.\n\n**Ambition.** Leave a public route for completing the joint investigation of Jegi-dong, Daechi, and Sangam without force.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness 35 | Force −40 | Materialism 5 | Communal 5 | Principle 45 | Transparency 55 | Qualification 40 | Dispersal 20 | Transformation 0\n- Desires: Craving 45 | Monopoly −5 | Risk 40 | Display 25 | Persistence 5 | Orientation Bisexual | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Gi Seojin","type":"Contract","to":"Ryu Eunbi","basis":""},{"from":"Gi Seojin","type":"Contract","to":"Go Choyun","basis":"Post Go Choyun''s public test sheet on the outside of the box"}],"incoming":[]}}', '{"id":"person-0084","name":"기서진","title":"비군사 공동조사 전령","position":"비군사 공동조사 전령","characterId":"K084","rank":"일반 시민","commonTier":"T5","occupation":"조사 문서 전달","gender":"남성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-기서진","detailRoute":"/people/person-0084","birthDate":"2092-09-01","birthday":"09-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"mission","name":"공동조사 날인 확인","rating":60},{"id":"departure","name":"배차표·출발 확인","rating":50}],"traits":[{"id":"wait-for-three-stamps","name":"세 날인 대기","description":"기서진은 전달의 신속함보다 세 검증 주체의 날인 완비를 출발 기준으로 삼는다.","behavior":"치료길드·안전심사·송신 검증의 날인이 모여야 출발하고 배차표 없는 열차의 무서명 출발을 막았다.","stress":"","relationship":"최지우에게 도착 시각을 넘길 때도 세 날인이 갖춰진 출발이라는 조건을 우선할 수 있다.","effects":[]},{"id":"nonmilitary-investigations","name":"조사단 비군사성","description":"기서진은 공동조사가 군사 호위로 바뀌는 것을 거부한다.","behavior":"조사단을 호위단으로 바꾸라는 쪽지를 찢고 군사 호위 칸이 적힌 경로를 되돌려 보낸다.","stress":"","relationship":"","effects":[]}],"narrative":"조사 문서의 세 날인을 확인하고 무표 열차를 세웠다. 전달 조건 집행을 평가하며 외교 대표 권한이나 무장 호위는 부여하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ae30-d589-c8fc","name":"행주 기씨","crest":"clan-crests/ae30-d589-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":35,"무력":-40,"물질":5,"공동":5,"원칙":45,"공개":55,"자격":40,"분산":20,"변혁":0},"desire":{"갈망":45,"독점":-5,"위험":40,"과시":25,"지속":5,"지향":"양성","결합":"계약동거"},"fields":{"소속":"Arc","생업":"조사 문서 전달","품계":"일반 시민","직함":"비군사 공동조사 전령","업무":"대치1동. 기서진은 대치 공동조사 쪽지에 치료·안전심사·송신 검증 날인이 모였는지 확인하고 군사 호위 칸이 있으면 경로를 되돌린다.","가치관":"권위 0 | 개방 35 | 무력 −40 | 물질 5 | 공동 5 | 원칙 45 | 공개 55 | 자격 40 | 분산 20 | 변혁 0","욕망":"갈망 45 | 독점 −5 | 위험 40 | 과시 25 | 지속 5 | 지향 양성 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 신내 환승 당직에서 자랐다. 기서진은 대치 공동조사 쪽지에 치료·안전심사·송신 검증 날인이 모였는지 확인하고 군사 호위 칸이 있으면 경로를 되돌린다.\n- 업무: 대치1동.","관직":"품계 일반 시민. 직함은 비군사 공동조사 전령. 조사 쪽지는 치료길드·안전심사·송신 검증의 세 날인이 모인 뒤에만 출발하고, 군사 호위 칸이 적힌 경로는 되돌려 보낸다.","일화":"2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다.","관계":"최지우의 속보 협약에 도착 시각을 넘기며, 고초윤의 공개 검사표를 상자 겉면에 붙인다.","야망":"제기동·대치·상암의 공동조사를 무력 없이 끝내는 공개 경로를 남긴다.","공포":"","개입":""},"biography":"표본 상자의 온도보다 호송 깃발의 색깔을 먼저 확인하고, 조사단을 호위단으로 바꾸라는 쪽지를 찢는다. 말은 적고 도착 시각은 지킨다.\n\n- 소속: Arc\n- 생업: 조사 문서 전달\n- 품계: 일반 시민\n- 직함: 비군사 공동조사 전령\n**생애.** 2126년 세대. 신내 환승 당직에서 자랐다. 기서진은 대치 공동조사 쪽지에 치료·안전심사·송신 검증 날인이 모였는지 확인하고 군사 호위 칸이 있으면 경로를 되돌린다.\n- 업무: 대치1동.\n\n**관직.** 품계 일반 시민. 직함은 비군사 공동조사 전령. 조사 쪽지는 치료길드·안전심사·송신 검증의 세 날인이 모인 뒤에만 출발하고, 군사 호위 칸이 적힌 경로는 되돌려 보낸다.\n\n**일화.** 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다.\n\n**관계.** 최지우의 속보 협약에 도착 시각을 넘기며, 고초윤의 공개 검사표를 상자 겉면에 붙인다.\n\n**야망.** 제기동·대치·상암의 공동조사를 무력 없이 끝내는 공개 경로를 남긴다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 35 | 무력 −40 | 물질 5 | 공동 5 | 원칙 45 | 공개 55 | 자격 40 | 분산 20 | 변혁 0\n- 욕망: 갈망 45 | 독점 −5 | 위험 40 | 과시 25 | 지속 5 | 지향 양성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"기서진","type":"계약","to":"류은비","basis":""},{"from":"기서진","type":"계약","to":"고초윤","basis":"고초윤의 공개 검사표를 상자 겉면에 붙인다"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0085', 'c1a1-c9c4-cc9c-5b8b', '{"id":"person-0085","name":"Song Byeolha","title":"Survey Records Examiner","position":"Survey Records Examiner","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Survey Record Cross-Checking","gender":"Male","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0085","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0085","name":"송별하","title":"측량 기록 심사관","position":"측량 기록 심사관","rank":"일반 시민","commonTier":"T5","occupation":"측량 기록 대조","gender":"남성","stage":"S2","state":"S03","stateName":"Arc","detailRoute":"/people/person-0085","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0086', 'c784-c870-c591-6797', '{"id":"person-0086","name":"Im Hajun","title":"Ordinary Citizen, Currently Missing","position":"","characterId":"K086","rank":"None","commonTier":"T1","occupation":"Chief Pump Engineer","gender":"Male","stage":"Key","state":"arc","stateName":"Arc","sourceRoute":"/world/Core-Characters#Im-Hajun","detailRoute":"/people/person-0086","birthDate":"2072-12-03","birthday":"12-03","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":14,"effective":14},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k086-pump-maintenance","name":"Pump maintenance","rating":70}],"traits":[{"id":"k086-trait-1","name":"Sealed process copies","description":"Left an access boundary around process copies through a seal.","behavior":"Left an access boundary around process copies through a seal.","stress":"","relationship":"Taught Im Chowon maintenance without finishing the instruction.","effects":[]}],"narrative":"He took charge of the O family''s pump maintenance and learned pump standards, then taught Im Chowon maintenance without completing the instruction.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41460-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K086","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c784-c870-c591-6797","name":"Joyang Im Clan","crest":"clan-crests/c784-c870-c591-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"Authority":-10,"Openness":10,"Force":-30,"Material":20,"Communal":30,"Principle":10,"Public":-40,"Eligibility":50,"Dispersed":20,"Transformative":-20},"desire":{"Longing":40,"Monopoly":20,"Risk":-10,"Display":-20,"Sustained":30,"Orientation":"Reason","Union":"Monogamy"},"fields":{},"sections":{"Life":"Generation of 2126. In 2119, O Gyeongjae, the legitimate eldest son of the O clan, was a minor. Im Hajun took charge of the O family''s pump maintenance. Having learned the pump specifications on duty at the Ttukseom heat source, he taught pump maintenance to his adopted son Im Chowon but did not finish the instruction. In winter 2125, Im Hajun disappeared. Bak Nuri served as interim steward.","Offices":"Rank: None. Title: Ordinary Citizen, Currently Missing. He formerly took charge of the O family''s pump maintenance. Livelihood nickname: Chief of Pump Engineering. The seat has been vacant since winter 2125.","Anecdote":"","Houses":"Joyang Im clan. A family that has taken turns checking the shutters and locks of the outer passages every winter.","Relationships":"On night checks he takes turns with neighboring families on patrol sections and reminds the young to keep to the no-light rule."},"biography":"Im Hajun, who had taken charge of the O family''s pump maintenance, disappeared in winter 2125. The records of the Ttukseom heat source duty in Seongsu 1-ga 2-dong and of the sealed box preserve the work he was handling before he disappeared.\n\n**Life.** Generation of 2126. In 2119, O Gyeongjae, the legitimate eldest son of the O clan, was a minor. Im Hajun took charge of the O family''s pump maintenance. Having learned the pump specifications on duty at the Ttukseom heat source, he taught pump maintenance to his adopted son Im Chowon but did not finish the instruction. In winter 2125, Im Hajun disappeared. Bak Nuri served as interim steward.\n\n**Office.** Rank: None. Title: Ordinary Citizen, Currently Missing. He formerly took charge of the O family''s pump maintenance. Livelihood nickname: Chief of Pump Engineering. The seat has been vacant since winter 2125.\n\n**House.** Joyang Im clan. A family that has taken turns checking the shutters and locks of the outer passages every winter.\n\n**Relations.** On night checks he takes turns with neighboring families on patrol sections and reminds the young to keep to the no-light rule.","relations":{"outgoing":[],"incoming":[{"from":"O Gyeongjae","type":"Contract","to":"Im Hajun","basis":"After Im Hajun''s disappearance, checks the pump-maintenance records he left, as Stationmaster of Samseong Station"},{"from":"Bak Nu-ri","type":"Master and Disciple","to":"Im Hajun","basis":"Learned the pump-cleaning process from the missing chief administrator"},{"from":"Bak Serin","type":"Kinship","to":"Im Hajun","basis":"Guardianship of the Pump Engineering House''s kinship process"},{"from":"Yeo Rian","type":"Contract","to":"Im Hajun","basis":"and recorded as a scribe the pump-cleaning process that Bak Nuri and Im Hajun shared,"},{"from":"Jong Na-sol","type":"Contract","to":"Im Hajun","basis":"Watched Im Hajun''s night inspection route to the very end, and"},{"from":"Beom Han-deul","type":"Oath","to":"Im Hajun","basis":"Bases testimony on the expiry marks left after Im Hajun''s disappearance"}]}}', '{"id":"person-0086","name":"임하준","title":"일반 시민, 현재 실종","position":"","characterId":"K086","rank":"없음","commonTier":"T1","occupation":"펌프기술 총관","gender":"남성","stage":"주요","state":"arc","stateName":"Arc","sourceRoute":"/world/Core-Characters#임하준","detailRoute":"/people/person-0086","birthDate":"2072-12-03","birthday":"12-03","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":14,"effective":14},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k086-pump-maintenance","name":"펌프 정비","rating":70}],"traits":[{"id":"k086-trait-1","name":"닫힌 사본 함","description":"공정 사본의 접근 경계를 봉인으로 남겼다.","behavior":"공정 사본의 접근 경계를 봉인으로 남겼다.","stress":"","relationship":"임초원에게 기술을 가르쳤으나 교육을 마치지는 못했다.","effects":[]}],"narrative":"오씨 집안의 펌프 정비를 맡았고 펌프 규격을 익혀 임초원에게 정비를 가르쳤으나 교육을 마치지 못했다. 실종 전날 공정 사본을 봉인했다. 실종 이유는 미정이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41460-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K086","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c784-c870-c591-6797","name":"조양 임씨","crest":"clan-crests/c784-c870-c591-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"권위":-10,"개방":10,"무력":-30,"물질":20,"공동":30,"원칙":10,"공개":-40,"자격":50,"분산":20,"변혁":-20},"desire":{"갈망":40,"독점":20,"위험":-10,"과시":-20,"지속":30,"지향":"이성","결합":"단혼"},"fields":{},"sections":{"생애":"2126년 세대. 2119년 오씨 적장자 오경재가 미성년이었다. 임하준이 오씨 집안의 펌프 정비를 도맡았다. 뚝섬 열원 당직에서 펌프 규격을 익힌 그는 양자 임초원에게 펌프 정비를 가르쳤으나 교육을 마치지 못했다. 2125년 겨울 임하준이 실종되었다. 임시 관리인은 박누리가 맡았다.","관직":"품계 없음. 직함은 일반 시민, 현재 실종. 오씨 집안의 펌프 정비를 도맡았던 사람이다. 생업 별명은 펌프기술 총관. 2125년 겨울 이후 자리가 비어 있다.","일화":"","가문":"조양 임씨 집안. 겨울마다 바깥 통로의 셔터와 잠금장치를 번갈아 점검해 온 집안이다.","관계":"밤 점검 때 이웃 가족과 순찰 구간을 번갈아 서고, 불빛을 켜지 않는 규칙을 어린 사람들에게 일러 준다."},"biography":"오씨 집안의 펌프 정비를 도맡았던 임하준은 2125년 겨울 실종되었다. 성수1가2동의 뚝섬 열원 당직과 봉인함 기록에 그가 실종되기 전 맡았던 일이 남아 있다.\n\n**생애.** 2126년 세대. 2119년 오씨 적장자 오경재가 미성년이었다. 임하준이 오씨 집안의 펌프 정비를 도맡았다. 뚝섬 열원 당직에서 펌프 규격을 익힌 그는 양자 임초원에게 펌프 정비를 가르쳤으나 교육을 마치지 못했다. 2125년 겨울 임하준이 실종되었다. 임시 관리인은 박누리가 맡았다.\n\n**관직.** 품계 없음. 직함은 일반 시민, 현재 실종. 오씨 집안의 펌프 정비를 도맡았던 사람이다. 생업 별명은 펌프기술 총관. 2125년 겨울 이후 자리가 비어 있다.\n\n**가문.** 조양 임씨 집안. 겨울마다 바깥 통로의 셔터와 잠금장치를 번갈아 점검해 온 집안이다.\n\n**관계.** 밤 점검 때 이웃 가족과 순찰 구간을 번갈아 서고, 불빛을 켜지 않는 규칙을 어린 사람들에게 일러 준다.","relations":{"outgoing":[],"incoming":[{"from":"오경재","type":"계약","to":"임하준","basis":"임하준이 실종된 뒤 삼성역 역장으로 그가 남긴 펌프 정비 기록을 확인"},{"from":"박누리","type":"스승과 제자","to":"임하준","basis":"펌프 세정 공정을 실종 총관에게 배움"},{"from":"박세린","type":"친족","to":"임하준","basis":"펌프기술가문 친족 공정의 후견"},{"from":"여리안","type":"계약","to":"임하준","basis":"박누리와 임하준이 나누던 펌프 세정 공정을 서기로 남겼고"},{"from":"종나솔","type":"계약","to":"임하준","basis":"임하준의 야간 점검 동선을 마지막까지 봤으며"},{"from":"범한들","type":"맹세","to":"임하준","basis":"임하준의 실종 뒤에 남은 만료 표시를 증언의 바탕으로 삼는다"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0087', 'c784-c608-cc9c-6797', '{"id":"person-0087","name":"Im Chowon","title":"Pump Engineer, Adopted Child of Im Hajun","position":"Pump Engineer, Adopted Child of Im Hajun","characterId":"K087","rank":"Teacher","commonTier":"T5","occupation":"Pump Engineer","gender":"Female","stage":"Key","state":"arc","stateName":"Arc","sourceRoute":"/world/Core-Characters#Im-Chowon","detailRoute":"/people/person-0087","birthDate":"2100-06-11","birthday":"06-11","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":9,"effective":9},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":13,"effective":13},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k087-seal-witness","name":"Seal witnessing","rating":60},{"id":"k087-pump-maintenance","name":"Pump maintenance","rating":60}],"traits":[{"id":"k087-trait-1","name":"A witness who does not open","description":"Distinguishes the seal she checked from copies she did not open.","behavior":"Distinguishes the seal she checked from copies she did not open.","stress":"","relationship":"Works with O Gyeongjae technically without interfering in the O family''s affairs.","effects":[]}],"narrative":"She learned pump maintenance from her adoptive father but stayed out of the O family''s affairs. On the shift after the disappearance, she checked the original seal without opening the copies and left a witness entry. Her technical alliance and stewardship rivalry are separate ties.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-c608-cc9c-6797","name":"Yecheon Im Clan","crest":"clan-crests/c784-c608-cc9c-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":10,"Communal":-20,"Principle":20,"Public":20,"Eligibility":80,"Dispersed":40,"Transformative":10},"desire":{"Longing":20,"Monopoly":-20,"Risk":20,"Display":-30,"Sustained":10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{},"sections":{"Life":"Generation of 2126. Grew up beside the pumps. What was learned from Im Hajun was pump maintenance technology, not a share in the O family''s affairs. Rank: Teacher. On the shift after the disappearance in the winter of 2125, she confirmed the seal on the original box. In 2126, O Gyeongjae, as Stationmaster of Samseong Station, checked the pump-maintenance records Im Hajun left behind. Im Chowon remains a pump technician at the opening.","Offices":"Rank: Teacher. Title: Pump Engineer, Adopted Child of Im Hajun. Livelihood nickname: Pump Technician.","Anecdote":"","Houses":"Yecheon Im clan. A teaching family that has long taught children reading, writing and winter rules.","Relationships":"Adopted son of Im Hajun. Pump technical alliance with O Gyeongjae."},"biography":"Pump technician Im Chowon is the adopted son of the missing Im Hajun. In Seongsu 1-ga 2-dong, she takes over the pump maintenance records and cross-checks the seal on the original box, verified at the shift after the disappearance, against the Council of Elders'' records. The maintenance training she received from Im Hajun was never completed.\n\n**Life.** Generation of 2126. Grew up beside the pumps. What she learned from Im Hajun was pump maintenance skills, not a share in the O family''s affairs. Her rank is Teacher. At the shift after the disappearance in winter 2125, she verified the seal on the original box. In 2126, O Gyeongjae, as Stationmaster of Samseong Station, checked the pump-maintenance records Im Hajun left behind. Im Chowon remains a pump technician at the opening.\n\n**Office.** Rank: Teacher. Title: Pump Engineer, Adopted Child of Im Hajun. Livelihood nickname: Pump Technician.\n\n**House.** Yecheon Im clan. A teaching family that has long taught children reading, writing and winter rules.\n\n**Relations.** Adopted son of Im Hajun. Pump technical alliance with O Gyeongjae.","relations":{"outgoing":[],"incoming":[{"from":"O Gyeongjae","type":"Contract","to":"Im Chowon","basis":"Formed the pump technical alliance by exchanging signed maintenance know-how"},{"from":"Han Somi","type":"Rivalry","to":"Im Chowon","basis":""},{"from":"Gang Ye-jun","type":"Contract","to":"Im Chowon","basis":""},{"from":"Alexander Miller","type":"Grudge","to":"Im Chowon","basis":""},{"from":"Heo Gyeom","type":"Contract","to":"Im Chowon","basis":"Checks Im Chowon''s public design against it under the lid"}]}}', '{"id":"person-0087","name":"임초원","title":"펌프기술자, 임하준의 양자","position":"펌프기술자, 임하준의 양자","characterId":"K087","rank":"교사","commonTier":"T5","occupation":"펌프기술자","gender":"여성","stage":"주요","state":"arc","stateName":"Arc","sourceRoute":"/world/Core-Characters#임초원","detailRoute":"/people/person-0087","birthDate":"2100-06-11","birthday":"06-11","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":9,"effective":9},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":13,"effective":13},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k087-seal-witness","name":"봉인 증언","rating":60},{"id":"k087-pump-maintenance","name":"펌프 정비","rating":60}],"traits":[{"id":"k087-trait-1","name":"열지 않는 증인","description":"자신이 확인한 봉인과 열지 않은 사본을 구분한다.","behavior":"자신이 확인한 봉인과 열지 않은 사본을 구분한다.","stress":"","relationship":"오경재와 기술 동맹을 맺되 오씨 집안의 일에는 나서지 않는다.","effects":[]}],"narrative":"양부에게 펌프 정비를 배웠지만 오씨 집안의 일에는 나서지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-c608-cc9c-6797","name":"예천 임씨","crest":"clan-crests/c784-c608-cc9c-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"권위":-30,"개방":20,"무력":-20,"물질":10,"공동":-20,"원칙":20,"공개":20,"자격":80,"분산":40,"변혁":10},"desire":{"갈망":20,"독점":-20,"위험":20,"과시":-30,"지속":10,"지향":"동성","결합":"계약동거"},"fields":{},"sections":{"생애":"2126년 세대. 펌프 곁에서 자랐다. 임하준에게 배운 것은 오씨 집안의 일이 아니라 펌프 정비 기술이었다. 품계는 교사다. 2125년 겨울 실종 다음 교대에 원본 함의 봉인을 확인하였다. 2126년 오경재는 삼성역 역장으로 일하며 임하준이 남긴 펌프 정비 기록을 확인했다. 임초원은 개막에 펌프기술자로 남는다.","관직":"품계 교사. 직함 펌프기술자, 임하준의 양자. 생업 별명은 펌프기술자.","일화":"","가문":"예천 임씨 집안. 대대로 아이들에게 글과 겨울 수칙을 가르쳐 온 교사 집안이다.","관계":"임하준의 양자. 오경재와 펌프 기술 동맹."},"biography":"펌프기술자 임초원은 실종된 임하준의 양자다. 성수1가2동에서 펌프 정비 기록을 인계하고, 실종 다음 교대에 확인한 원본 함의 봉인을 원로회 기록과 대조한다. 임하준에게 배운 정비 교육은 끝나지 않았다.\n\n**생애.** 2126년 세대. 펌프 곁에서 자랐다. 임하준에게 배운 것은 오씨 집안의 일이 아니라 펌프 정비 기술이었다. 품계는 교사다. 2125년 겨울 실종 다음 교대에 원본 함의 봉인을 확인하였다. 2126년 오경재는 삼성역 역장으로 일하며 임하준이 남긴 펌프 정비 기록을 확인했다. 임초원은 개막에 펌프기술자로 남는다.\n\n**관직.** 품계 교사. 직함 펌프기술자, 임하준의 양자. 생업 별명은 펌프기술자.\n\n**가문.** 예천 임씨 집안. 대대로 아이들에게 글과 겨울 수칙을 가르쳐 온 교사 집안이다.\n\n**관계.** 임하준의 양자. 오경재와 펌프 기술 동맹.","relations":{"outgoing":[],"incoming":[{"from":"오경재","type":"계약","to":"임초원","basis":"서명한 정비 기술을 맞바꿔 펌프 기술 동맹을 맺음"},{"from":"한소미","type":"경쟁","to":"임초원","basis":""},{"from":"강예준","type":"계약","to":"임초원","basis":""},{"from":"알렉산더 밀러","type":"원한","to":"임초원","ba