INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0102', 'ba85-c5f0-c548', '{"id":"person-0102","name":"Myeong Gang-san","title":"Godeok-Cheonho Flooded Tunnel Explorer","position":"Godeok-Cheonho Flooded Tunnel Explorer","rank":"Teacher","commonTier":"T5","occupation":"Recording Flooded Tunnel Depth and Vibration","gender":"Male","stage":"S2","state":"S04","stateName":"Arc","detailRoute":"/people/person-0102","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0102","name":"명강산","title":"고덕-천호 침수터널 탐사원","position":"고덕-천호 침수터널 탐사원","rank":"교사","commonTier":"T5","occupation":"침수터널 수심·진동 기록","gender":"남성","stage":"S2","state":"S04","stateName":"Arc","detailRoute":"/people/person-0102","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0103', 'c81c-ce60-c6d0', '{"id":"person-0103","name":"Je Ha-yul","title":"Workshop Build Records Officer","position":"Workshop Build Records Officer","rank":"Teacher","commonTier":"T5","occupation":"Writing Workshop Build Records","gender":"Female","stage":"S2","state":"S04","stateName":"Arc","detailRoute":"/people/person-0103","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0103","name":"제하율","title":"공방 조립기록 실무관","position":"공방 조립기록 실무관","rank":"교사","commonTier":"T5","occupation":"공방 조립기록 작성","gender":"여성","stage":"S2","state":"S04","stateName":"Arc","detailRoute":"/people/person-0103","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0104', 'bcc0-cd08-acc4', '{"id":"person-0104","name":"Byeon O-reum","title":"Cheonho Concourse Stationmaster","position":"Cheonho Concourse Stationmaster","characterId":"K103","rank":"Ordinary Citizen","commonTier":"T4","occupation":"Waiting-Hall Food Window Duty","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-byeon-oreum","detailRoute":"/people/person-0104","birthDate":"2100-07-31","birthday":"07-31","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"water-board","name":"Check notice board management","rating":60},{"id":"referral","name":"Public-channel referral","rating":50}],"traits":[{"id":"water-supply-channels-first","name":"Food Window First","description":"Byeon Oreum prioritizes residents'' food window over transit cargo in waiting-hall operations.","behavior":"Byeon brings the check boards into the waiting hall and keeps cargo away from the food window.","stress":"If a cold snap threatens a fuel shortage, Byeon may place greater emphasis on waiting-hall food and fuel information and counter access.","relationship":"Byeon may enforce the food minimum set by the alley watchers at the counter while clashing with them if night patrols close it.","effects":[]},{"id":"turn-away-favor-requests","name":"Turn Away Favor Requests","description":"Byeon Oreum favors handling requests through publicly accessible counters rather than private favors.","behavior":"In 2125, Byeon turned away a private favor request and directed the requester to the public counter.","stress":"As the cold snap makes the fuel counter more important, Byeon may try to preserve public procedures over private requests.","relationship":"Even when cooperating with Han Somi, Byeon may retain a public-broadcast approach to monitoring recovery promises.","effects":[]}],"narrative":"Title: Cheonho Concourse Stationmaster.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bcc0-cd08-acc4","name":"Byeon Clan of Chogye","crest":"clan-crests/bcc0-cd08-acc4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":10,"Force":-15,"Material":20,"Communal":25,"Principle":5,"Public":-15,"Eligibility":40,"Dispersed":15,"Transformative":5},"desire":{"Longing":0,"Monopoly":-30,"Risk":40,"Display":5,"Sustained":5,"Orientation":"Fluid","Union":"None"},"fields":{"Affiliation":"Arc","Livelihood":"Waiting-Hall Food Window Duty","Rank":"Ordinary Citizen","Title":"Cheonho Concourse Stationmaster","Values":"Authority 10 | Openness 10 | Force −15 | Material 20 | Communal 25 | Principle 5 | Publicity −15 | Qualification 40 | Dispersion 15 | Transformation 5","Desires":"Craving 0 | Monopoly −30 | Risk 40 | Display 5 | Persistence 5 | Orientation Fluid | Attachment None"},"sections":{"Life":"Generation of 2126. Byeon Oreum grew up on waiting hall duty. Byeon Oreum took the post of Cheonho Waiting Hall Stationmaster as a substitute duty after an unexcused shift absence.\n- Byeon Oreum''s work as Cheonho Waiting Hall Stationmaster is tied to Amsa 1-dong.","Offices":"No rank. Title: Cheonho Concourse Stationmaster. Moves the alley-by-alley food-bin boards to the waiting hall as well, and if fuel goes only to one household''s storeroom, convenes a gathering by residents'' signatures.","Anecdote":"In 2125, Byeon Oreum turned away a private solicitation and sent it to the public window. Because of this, the signature for the Cheonho Waiting Hall Stationmaster post was entered in the ledger.","Relationships":"Enforces the alley watchers'' food minimum at the waiting hall window, relays news from neighboring settlements by platform broadcast, and clashes with the night patrol when it closes the food window.","Ambition":"Aims to make the Cheonho waiting hall a hub where the food minimum and spare-parts exchange take place under one roof, so that residents do not become mere numbers in a stronger party''s dealings.","Fear":"Byeon Oreum fears that a fuel shortage in the cold will leave Cheonho residents to leave their homes and drift.","Intervention":"Can bring in the measured food-bin table to enforce the minimum line, or expose the tampering with the board to invalidate a watcher''s signature."},"biography":"When the alley food bins run empty, Byeon Oreum regards meetings as a luxury and asks about the food-bin level before names. Gentle, yet never lets cargo stand in front of the food window.\n\n- Affiliation: Arc\n- Livelihood: Waiting-Hall Food Window Duty\n- Rank: Ordinary Citizen\n- Title: Cheonho Concourse Stationmaster\n**Life.** Generation of 2126. Byeon Oreum grew up on waiting hall duty. Byeon Oreum took the post of Cheonho Waiting Hall Stationmaster as a substitute duty after an unexcused shift absence.\n- Byeon Oreum''s work as Cheonho Waiting Hall Stationmaster is tied to Amsa 1-dong.\n\n**Office.** No rank. Title: Cheonho Concourse Stationmaster. Moves the alley-by-alley food-bin boards to the waiting hall as well, and if fuel goes only to one household''s storeroom, convenes a gathering by residents'' signatures.\n\n**Anecdote.** In 2125, Byeon Oreum turned away a private solicitation and sent it to the public window. Because of this, the signature for the Cheonho Waiting Hall Stationmaster post was entered in the ledger.\n\n**Relationships.** Enforces the alley watchers'' food minimum at the waiting hall window, relays news from neighboring settlements by platform broadcast, and clashes with the night patrol when it closes the food window.\n\n**Ambition.** Aims to make the Cheonho waiting hall a hub where the food minimum and spare-parts exchange take place under one roof, so that residents do not become mere numbers in a stronger party''s dealings.\n\n**Fear.** Byeon Oreum fears that a fuel shortage in the cold will leave Cheonho residents to leave their homes and drift.\n\n**Intervention.** Can bring in the measured food-bin table to enforce the minimum line, or expose the tampering with the board to invalidate a watcher''s signature.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness 10 | Force −15 | Material 20 | Communal 25 | Principle 5 | Publicity −15 | Qualification 40 | Dispersion 15 | Transformation 5\n- Desires: Craving 0 | Monopoly −30 | Risk 40 | Display 5 | Persistence 5 | Orientation Fluid | Attachment None\n:::","relations":{"outgoing":[{"from":"Byeon O-reum","type":"Command","to":"Jang Minjae","basis":"enforcing Jang Minjae''s posted food-bin counts at the waiting hall food counter"},{"from":"Byeon O-reum","type":"Command","to":"Han Somi","basis":"Monitoring Han Somi''s livelihood recovery pledge through platform announcements, and"}],"incoming":[]}}', '{"id":"person-0104","name":"변오름","title":"천호 대합실 역장","position":"천호 대합실 역장","characterId":"K103","rank":"일반 시민","commonTier":"T4","occupation":"대합실 식량 창구 당직","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-변오름","detailRoute":"/people/person-0104","birthDate":"2100-07-31","birthday":"07-31","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"water-board","name":"점검 게시판 운영","rating":60},{"id":"referral","name":"공개 창구 안내","rating":50}],"traits":[{"id":"water-supply-channels-first","name":"식량 창구 우선","description":"변오름은 대합실 운영에서 이동 화물보다 주민의 식량 창구를 먼저 지킨다.","behavior":"점검 게시판을 대합실로 옮기고 화물을 식량 창구 앞에 두지 않는다.","stress":"한파로 연료가 모자랄 우려가 커지면 대합실의 식량·연료 정보와 창구 접근을 더 중시할 수 있다.","relationship":"골목 당번이 정한 식량 최저선을 창구에서 집행하되, 밤 순찰이 창구를 닫으면 충돌할 수 있다.","effects":[]},{"id":"turn-away-favor-requests","name":"청탁 돌려보내기","description":"변오름은 사적 청탁보다 누구나 이용하는 공개 창구를 통한 처리를 선호한다.","behavior":"2125년 사적 청탁을 받아들이지 않고 요청자를 공개 창구로 보냈다.","stress":"혹한으로 연료 창구의 중요성이 커지면 사적 요청보다 공개 절차를 지키려 할 수 있다.","relationship":"한소미와 협력하더라도 생활 복구 공약을 공개 방송으로 감시하는 태도를 유지할 수 있다.","effects":[]}],"narrative":"직함은 천호 대합실 역장.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bcc0-cd08-acc4","name":"초계 변씨","crest":"clan-crests/bcc0-cd08-acc4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":10,"무력":-15,"물질":20,"공동":25,"원칙":5,"공개":-15,"자격":40,"분산":15,"변혁":5},"desire":{"갈망":0,"독점":-30,"위험":40,"과시":5,"지속":5,"지향":"유동","결합":"없음"},"fields":{"소속":"Arc","생업":"대합실 식량 창구 당직","품계":"일반 시민","직함":"천호 대합실 역장","가치관":"권위 10 | 개방 10 | 무력 −15 | 물질 20 | 공동 25 | 원칙 5 | 공개 −15 | 자격 40 | 분산 15 | 변혁 5","욕망":"갈망 0 | 독점 −30 | 위험 40 | 과시 5 | 지속 5 | 지향 유동 | 결합 없음"},"sections":{"생애":"2126년 세대. 변오름은 대합실 당직에서 자랐다. 변오름은 교대 무단 결근 대체 당직으로 천호 대합실 역장 자리를 맡았다.\n- 변오름의 천호 대합실 역장 업무는 암사1동과 연결된다.","관직":"품계 일반 시민. 직함은 천호 대합실 역장. 골목별 식량통 게시판을 대합실에도 옮기고, 연료가 한 집 창고로만 가면 주민 서명으로 모임을 연다.","일화":"2125년 변오름은 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 천호 대합실 역장 자리의 서명이 장부에 올랐다.","관계":"골목 당번의 식량 최저선을 대합실 창구에서 집행하고, 이웃 거주지의 소식을 승강장 방송으로 알리며, 밤 순찰이 식량 창구를 닫을 때 충돌한다.","야망":"천호 대합실을 식량 최저선과 예비 부품 교환이 한 지붕 아래서 이루어지는 허브로 만들어, 주민이 힘센 쪽 거래의 숫자가 되지 않게 한다.","공포":"변오름은 한파 속 연료가 모자라 천호 주민이 살던 곳을 떠나 떠돌게 되는 것을 두려워한다.","개입":"식량통 실측표를 가져와 최저선을 관철하거나, 게시판 조작을 밝혀 당번 서명을 무효로 만들 수 있다."},"biography":"골목 식량통이 비면 회의를 사치로 여기고, 이름보다 식량통 남은 양을 먼저 묻는다. 온화하나 화물을 식량 창구 앞에 두지 않는다.\n\n- 소속: Arc\n- 생업: 대합실 식량 창구 당직\n- 품계: 일반 시민\n- 직함: 천호 대합실 역장\n**생애.** 2126년 세대. 변오름은 대합실 당직에서 자랐다. 변오름은 교대 무단 결근 대체 당직으로 천호 대합실 역장 자리를 맡았다.\n- 변오름의 천호 대합실 역장 업무는 암사1동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 천호 대합실 역장. 골목별 식량통 게시판을 대합실에도 옮기고, 연료가 한 집 창고로만 가면 주민 서명으로 모임을 연다.\n\n**일화.** 2125년 변오름은 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 천호 대합실 역장 자리의 서명이 장부에 올랐다.\n\n**관계.** 골목 당번의 식량 최저선을 대합실 창구에서 집행하고, 이웃 거주지의 소식을 승강장 방송으로 알리며, 밤 순찰이 식량 창구를 닫을 때 충돌한다.\n\n**야망.** 천호 대합실을 식량 최저선과 예비 부품 교환이 한 지붕 아래서 이루어지는 허브로 만들어, 주민이 힘센 쪽 거래의 숫자가 되지 않게 한다.\n\n**공포.** 변오름은 한파 속 연료가 모자라 천호 주민이 살던 곳을 떠나 떠돌게 되는 것을 두려워한다.\n\n**개입.** 식량통 실측표를 가져와 최저선을 관철하거나, 게시판 조작을 밝혀 당번 서명을 무효로 만들 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 10 | 무력 −15 | 물질 20 | 공동 25 | 원칙 5 | 공개 −15 | 자격 40 | 분산 15 | 변혁 5\n- 욕망: 갈망 0 | 독점 −30 | 위험 40 | 과시 5 | 지속 5 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"변오름","type":"지휘","to":"장민재","basis":"장민재의 식량통 수 게시를 대합실 식량 창구에서 집행하고"},{"from":"변오름","type":"지휘","to":"한소미","basis":"한소미의 생활 복구 공약을 승강장 방송으로 감시하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0105', 'd45c-c2e0-cc3d', '{"id":"person-0105","name":"Pyo Nu-ri","title":"Godeok Base Stabling Operations Chief","position":"Godeok Base Stabling Operations Chief","characterId":"K104","rank":"Ordinary Citizen","commonTier":"T4","occupation":"Managing Stabling Track Bay Assignments and Dispatch","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-pyo-nuri","detailRoute":"/people/person-0105","birthDate":"2080-03-04","birthday":"03-04","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"dispatch","name":"Freight-car sequencing","rating":60}],"traits":[{"id":"stop-at-unchalked-compartments","name":"Stop at Unchalked Compartments","description":"Pyo Nuri does not treat unchalked or unassigned holding compartments as ready for dispatch.","behavior":"Pyo redraws workshop and guard chalk marks before the whistle and holds modified compartments without allocation lines on the gravel.","stress":"If empty compartments risk becoming encampments, Pyo may enforce allocation marks and dispatch stops more strictly.","relationship":"Even after receiving Lee Juntaek''s maintenance-completion stamp, Pyo may verify holding allocation before sounding the whistle.","effects":[]},{"id":"synchronize-pump-room-clocks","name":"Synchronize Pump-Room Clocks","description":"Pyo Nuri seeks to align the dedicated line on the holding board with the pump-room whistle at one dispatch time.","behavior":"When the parts extension was cut off, Pyo fixed the dedicated line and withheld the whistle for Amsa-bound compartments.","stress":"Pyo may hold more firmly to board-based timing control.","relationship":"If Han Somi''s brake parts arrive late, Pyo may postpone the dedicated line and adjust dispatch to the supply schedule.","effects":[]}],"narrative":"She fixed the dedicated car line and withheld the whistle when parts supply lapsed. Car allocation and timing are strengths, not vehicle maintenance.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d45c-c2e0-cc3d","name":"Sinchang Pyo Clan","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":10,"Force":-20,"Material":10,"Communal":25,"Principle":10,"Public":-25,"Eligibility":35,"Dispersed":15,"Transformative":5},"desire":{"Longing":45,"Monopoly":40,"Risk":10,"Display":25,"Sustained":40,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Managing Stabling Track Bay Assignments and Dispatch","Rank":"Ordinary Citizen","Title":"Godeok Base Stabling Operations Chief","Values":"Authority 0 | Openness 10 | Force −20 | Material 10 | Communal 25 | Principle 10 | Disclosure −25 | Qualification 35 | Dispersion 15 | Transformation 5","Desires":"Craving 45 | Exclusivity 40 | Risk 10 | Display 25 | Endurance 40 | Orientation None | Union Contract Cohabitation"},"sections":{"Life":"Born in the 2126 generation. Pyo Nuri grew up at the Sinjeong Depot. Pyo Nuri took the post of Godeok Base Stabling Operations Chief through a defect report filed just before a derailment.\n- Pyo Nuri''s work as Godeok Base Stabling Operations Chief is tied to Godeok 2-dong.","Offices":"Rank: Ordinary Citizen. Title: Godeok Base Stabling Operations Chief. Before the whistle, redraws the workshop chalk and defense chalk bay by bay, and sets converted bays with no line on the gravel.","Anecdote":"On the day the central parts extension was cut off, Pyo Nuri fixed the pump-room dedicated line to the stabling board and did not sound the whistle for the Amsa-bound bay.","Relationships":"Receives orders to change the maintenance-completion seal from the stabling bay to the whistle, and checks Jeong Siu''s Cheonwang wheel compatibility on the bay line. If Han Somi''s small brake parts arrive late, postpones the dedicated line by a day.","Ambition":"Aligns the stabling board''s dedicated line with the pump-room whistle at a single time, so that central-district releases follow the chalk of the Godeok bays.","Fear":"Pyo Nuri fears that empty stabling bays will turn into encampment tents.","Intervention":"Can load a brake box onto a bay where the pump-room dedicated line has been erased, or move a note from a converted bay on the gravel onto the stabling board."},"biography":"Sees a spot where the stabling-track bay chalk has been erased as an empty one, and summons first whichever party''s release whistle comes later than the succession council''s message. When bays overlap, draws lines rather than words.\n\n- Affiliation: Arc\n- Occupation: Managing Stabling Track Bay Assignments and Dispatch\n- Rank: Ordinary Citizen\n- Title: Godeok Base Stabling Operations Chief\n**Life.** Born in the 2126 generation. Pyo Nuri grew up at the Sinjeong Depot. Pyo Nuri took the post of Godeok Base Stabling Operations Chief through a defect report filed just before a derailment.\n- Pyo Nuri''s work as Godeok Base Stabling Operations Chief is tied to Godeok 2-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Godeok Base Stabling Operations Chief. Before the whistle, redraws the workshop chalk and defense chalk bay by bay, and sets converted bays with no line on the gravel.\n\n**Anecdote.** On the day the central parts extension was cut off, Pyo Nuri fixed the pump-room dedicated line to the stabling board and did not sound the whistle for the Amsa-bound bay.\n\n**Relationships.** Receives orders to change the maintenance-completion seal from the stabling bay to the whistle, and checks Jeong Siu''s Cheonwang wheel compatibility on the bay line. If Han Somi''s small brake parts arrive late, postpones the dedicated line by a day.\n\n**Ambition.** Aligns the stabling board''s dedicated line with the pump-room whistle at a single time, so that central-district releases follow the chalk of the Godeok bays.\n\n**Fear.** Pyo Nuri fears that empty stabling bays will turn into encampment tents.\n\n**Intervention.** Can load a brake box onto a bay where the pump-room dedicated line has been erased, or move a note from a converted bay on the gravel onto the stabling board.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 0 | Openness 10 | Force −20 | Material 10 | Communal 25 | Principle 10 | Disclosure −25 | Qualification 35 | Dispersion 15 | Transformation 5\n- Desires: Craving 45 | Exclusivity 40 | Risk 10 | Display 25 | Endurance 40 | Orientation None | Union Contract Cohabitation\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0105","name":"표누리","title":"고덕기지 유치 실무장","position":"고덕기지 유치 실무장","characterId":"K104","rank":"일반 시민","commonTier":"T4","occupation":"유치선 칸 배정·출고 관리","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-표누리","detailRoute":"/people/person-0105","birthDate":"2080-03-04","birthday":"03-04","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"dispatch","name":"화차 순서 조정","rating":60}],"traits":[{"id":"stop-at-unchalked-compartments","name":"분필 없는 칸 정지","description":"표누리는 분필과 배정 줄이 없는 유치 칸을 출고 가능한 자리로 인정하지 않는다.","behavior":"호각 전에 공방과 수비 분필을 다시 긋고 줄이 없는 개조칸은 자갈에 세운다.","stress":"빈 칸이 숙영 천막으로 바뀔 우려가 커지면 칸 배정 표시와 출고 정지를 더 엄격히 적용할 수 있다.","relationship":"이준택의 정비 완료 도장을 받아도 유치 칸의 배정 확인을 거쳐 호각으로 이어갈 수 있다.","effects":[]},{"id":"synchronize-pump-room-clocks","name":"펌프실 시각 맞춤","description":"표누리는 유치 칠판의 전용줄과 펌프실 호각을 같은 출고 시각에 맞추려 한다.","behavior":"부품 연장이 끊긴 날 전용줄을 고정하고 암사행 칸의 호각을 보류했다.","stress":"칠판 배정에 따른 시각 통제를 더 고수할 수 있다.","relationship":"한소미의 제동 부품이 늦으면 전용줄을 미루며 공급 일정에 맞춰 출고를 조정할 수 있다.","effects":[]}],"narrative":"전용줄을 고정하고 부품 연장이 끊긴 날 호각을 울리지 않았다. 칸 배정과 출고 시각 조정이 강점이며 차량 정비는 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d45c-c2e0-cc3d","name":"신창 표씨","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":10,"무력":-20,"물질":10,"공동":25,"원칙":10,"공개":-25,"자격":35,"분산":15,"변혁":5},"desire":{"갈망":45,"독점":40,"위험":10,"과시":25,"지속":40,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"Arc","생업":"유치선 칸 배정·출고 관리","품계":"일반 시민","직함":"고덕기지 유치 실무장","가치관":"권위 0 | 개방 10 | 무력 −20 | 물질 10 | 공동 25 | 원칙 10 | 공개 −25 | 자격 35 | 분산 15 | 변혁 5","욕망":"갈망 45 | 독점 40 | 위험 10 | 과시 25 | 지속 40 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 표누리는 신정 차량기지에서 자랐다. 표누리는 탈선 직전 결함 보고로 고덕기지 유치 실무장 자리를 맡았다.\n- 표누리의 고덕기지 유치 실무장 업무는 고덕2동과 연결된다.","관직":"품계 일반 시민. 직함은 고덕기지 유치 실무장. 호각 전에 공방 분필과 수비 분필을 칸마다 다시 긋고, 줄이 없는 개조칸은 자갈에 세운다.","일화":"중앙 부품 연장이 끊긴 날 표누리는 펌프실 전용줄을 유치 칠판에 고정하고 암사행 칸의 호각을 울리지 않았다.","관계":"정비 완료 도장을 유치 칸에서 호각으로 바꾸는 지휘를 받고, 정시우의 천왕 차륜 호환을 칸 줄에서 확인한다. 한소미의 소형 제동 부품이 늦게 오면 전용줄을 하루 미룬다.","야망":"유치 칠판의 전용줄을 펌프실 호각과 한 시각에 맞춰, 중앙권역 출고가 고덕 칸의 분필을 따르게 한다.","공포":"표누리는 빈 유치 칸이 숙영 천막으로 바뀌는 상황을 두려워한다.","개입":"펌프실 전용줄이 지워진 칸에 제동 상자를 올리거나, 자갈 위 개조칸의 쪽지를 유치 칠판에 옮길 수 있다."},"biography":"유치선 칸 분필이 지워진 자리를 빈 사람으로 보고, 후계 회의 전갈보다 출고 호각이 늦은 쪽을 먼저 부른다. 칸이 겹치면 말보다 줄을 친다.\n\n- 소속: Arc\n- 생업: 유치선 칸 배정·출고 관리\n- 품계: 일반 시민\n- 직함: 고덕기지 유치 실무장\n**생애.** 2126년 세대. 표누리는 신정 차량기지에서 자랐다. 표누리는 탈선 직전 결함 보고로 고덕기지 유치 실무장 자리를 맡았다.\n- 표누리의 고덕기지 유치 실무장 업무는 고덕2동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 고덕기지 유치 실무장. 호각 전에 공방 분필과 수비 분필을 칸마다 다시 긋고, 줄이 없는 개조칸은 자갈에 세운다.\n\n**일화.** 중앙 부품 연장이 끊긴 날 표누리는 펌프실 전용줄을 유치 칠판에 고정하고 암사행 칸의 호각을 울리지 않았다.\n\n**관계.** 정비 완료 도장을 유치 칸에서 호각으로 바꾸는 지휘를 받고, 정시우의 천왕 차륜 호환을 칸 줄에서 확인한다. 한소미의 소형 제동 부품이 늦게 오면 전용줄을 하루 미룬다.\n\n**야망.** 유치 칠판의 전용줄을 펌프실 호각과 한 시각에 맞춰, 중앙권역 출고가 고덕 칸의 분필을 따르게 한다.\n\n**공포.** 표누리는 빈 유치 칸이 숙영 천막으로 바뀌는 상황을 두려워한다.\n\n**개입.** 펌프실 전용줄이 지워진 칸에 제동 상자를 올리거나, 자갈 위 개조칸의 쪽지를 유치 칠판에 옮길 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 10 | 무력 −20 | 물질 10 | 공동 25 | 원칙 10 | 공개 −25 | 자격 35 | 분산 15 | 변혁 5\n- 욕망: 갈망 45 | 독점 40 | 위험 10 | 과시 25 | 지속 40 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0106', 'ba85-c5f0-c548', '{"id":"person-0106","name":"Myeong U-sol","title":"Cheonho Workshop Market Auctioneer","position":"Cheonho Workshop Market Auctioneer","characterId":"K105","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Recording Workshop Market Dispatch and Rationing","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-myeong-usol","detailRoute":"/people/person-0106","birthDate":"2077-12-27","birthday":"12-27","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"ration","name":"Emergency-ration disclosure","rating":60},{"id":"trade","name":"Logistics under disclosed terms","rating":55}],"traits":[{"id":"no-military-boot-priority-in-bids","name":"No Military Boot Priority in Bids","description":"Myeong Woosol rejects military-boot bidding priority that displaces essential civilian goods.","behavior":"They question fabric and gear origins and allow military supply priority only when the garrison issues a warning.","stress":"They may scrutinize allocation conditions to protect civilian pump-packing supplies.","relationship":"They may expect transparent allocation order from Yu Haeun and Gu Doyeong and react adversely to price ledgers that commandeer Cheonho prices.","effects":[]},{"id":"transparent-emergency-rations","name":"Transparent Emergency Rations","description":"Myeong Woosol values open ration and shipment information over warehouse lockdowns during supply uncertainty.","behavior":"They lifted a warehouse lockdown and published emergency ration sheets during crop-failure rumors, and post shipment quantities on the occupational board.","stress":"If military-boot priority threatens civilian supplies, they may use public quantities and ration order to explain allocation decisions.","relationship":"They may align Yu Haeun''s board with Gu Doyeong''s transport order and expect trading partners to disclose ration information.","effects":[]}],"narrative":"He opened storage and disclosed rations during crop-failure rumors. Trade coordination and supply judgment are supported; an auctioneer title alone does not add auction mastery.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41450-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K105","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-41450-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ba85-c5f0-c548","name":"Yeonan Myeong Clan","crest":"clan-crests/ba85-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":15,"Force":-30,"Material":30,"Communal":25,"Principle":-5,"Public":-20,"Eligibility":35,"Dispersed":15,"Transformative":-5},"desire":{"Longing":25,"Monopoly":25,"Risk":-20,"Display":40,"Sustained":30,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Recording Workshop Market Dispatch and Rationing","Rank":"Ordinary Citizen","Title":"Cheonho Workshop Market Auctioneer","Values":"Authority −10 | Openness 15 | Force −30 | Material 30 | Communal 25 | Principle −5 | Disclosure −20 | Qualification 35 | Dispersion 15 | Transformation −5","Desires":"Craving 25 | Exclusivity 25 | Risk −20 | Display 40 | Endurance 30 | Orientation Same-sex | Union Non-exclusive"},"sections":{"Life":"Born in the 2126 generation. Myeong Usol grew up at Noryangjin Wharf. Myeong Usol took the post of Cheonho Workshop Market auctioneer through the public disclosure of a scale recheck.\n- Myeong Usol''s work as Cheonho Workshop Market auctioneer is tied to Cheonho 3-dong.","Offices":"Rank: Ordinary Citizen. Title: Cheonho Workshop Market Auctioneer. Posts release quantities on the trade board, and permits military priority only when the garrison has issued an alarm.","Anecdote":"In 2125, Myeong Usol lifted the warehouse lockdown on a bad-harvest rumor and published emergency ration tickets. Because of this, the signature for the Cheonho Workshop Market auctioneer post was entered in the ledger.","Relationships":"Enforces Yu Haeun''s trade board through auctions, shares packing transport and turn order with Gu Doyeong, and turns to resentment if Nam Yungyeong''s price ledger hijacks the Cheonho market rate.","Ambition":"Puts leather, pump packing, and small gears up for auction as essential items under the common standard, so that whoever holds the parts cannot hold winter stove repairs hostage.","Fear":"Myeong Usol fears that civilian pump packing will vanish.","Intervention":"Can obtain substitute fabric, or expose hidden orders in the boot warehouse to break the auction lock."},"biography":"Presses workshops that hide the origin of fabric and gears, and believes that the market price of a single pair of shoes saves people sooner than protective gear does. Enjoys haggling, but refuses boot-priority winning bids.\n\n- Affiliation: Arc\n- Occupation: Recording Workshop Market Dispatch and Rationing\n- Rank: Ordinary Citizen\n- Title: Cheonho Workshop Market Auctioneer\n**Life.** Born in the 2126 generation. Myeong Usol grew up at Noryangjin Wharf. Myeong Usol took the post of Cheonho Workshop Market auctioneer through the public disclosure of a scale recheck.\n- Myeong Usol''s work as Cheonho Workshop Market auctioneer is tied to Cheonho 3-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Cheonho Workshop Market Auctioneer. Posts release quantities on the trade board, and permits military priority only when the garrison has issued an alarm.\n\n**Anecdote.** In 2125, Myeong Usol lifted the warehouse lockdown on a bad-harvest rumor and published emergency ration tickets. Because of this, the signature for the Cheonho Workshop Market auctioneer post was entered in the ledger.\n\n**Relationships.** Enforces Yu Haeun''s trade board through auctions, shares packing transport and turn order with Gu Doyeong, and turns to resentment if Nam Yungyeong''s price ledger hijacks the Cheonho market rate.\n\n**Ambition.** Puts leather, pump packing, and small gears up for auction as essential items under the common standard, so that whoever holds the parts cannot hold winter stove repairs hostage.\n\n**Fear.** Myeong Usol fears that civilian pump packing will vanish.\n\n**Intervention.** Can obtain substitute fabric, or expose hidden orders in the boot warehouse to break the auction lock.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −10 | Openness 15 | Force −30 | Material 30 | Communal 25 | Principle −5 | Disclosure −20 | Qualification 35 | Dispersion 15 | Transformation −5\n- Desires: Craving 25 | Exclusivity 25 | Risk −20 | Display 40 | Endurance 30 | Orientation Same-sex | Union Non-exclusive\n:::","relations":{"outgoing":[{"from":"Myeong U-sol","type":"Command","to":"Yu Haeun","basis":"and enforces Yu Haeun''s trade board by auction,"},{"from":"Myeong U-sol","type":"Command","to":"Gu Do-yeong","basis":"Sharing turns with Gu Doyeong''s packing transport"}],"incoming":[]}}', '{"id":"person-0106","name":"명우솔","title":"천호 공방시장 경매사","position":"천호 공방시장 경매사","characterId":"K105","rank":"일반 시민","commonTier":"T3","occupation":"공방시장 출고·배급 기록","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-명우솔","detailRoute":"/people/person-0106","birthDate":"2077-12-27","birthday":"12-27","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"ration","name":"비상배급표 공개","rating":60},{"id":"trade","name":"공개 조건 물류 거래","rating":55}],"traits":[{"id":"no-military-boot-priority-in-bids","name":"군화 우선 낙찰 거부","description":"명우솔은 민수용 필수품을 밀어내는 군화 우선 낙찰을 거부한다.","behavior":"원단과 기어의 출처를 추궁하고 군수 우선은 수비대의 경보가 있을 때만 허용한다.","stress":"민수용 펌프 패킹의 공급을 지키기 위해 우선 배정 조건을 더 따질 수 있다.","relationship":"유하은과 구도영에게는 공개된 배정 순서를 기대하며 천호 시세를 가로채는 가격 원장에는 적대적으로 반응할 수 있다.","effects":[]},{"id":"transparent-emergency-rations","name":"비상배급 공개","description":"명우솔은 공급 불안 때 창고 봉쇄보다 배급과 출고 정보의 공개를 중시한다.","behavior":"흉작 소문 때 창고 봉쇄를 풀고 비상배급표를 공개했으며 출고 수량을 직능 칠판에 올린다.","stress":"군화 우선 계약으로 민수 물자가 줄 우려가 생기면 공개 수량과 배급 순서로 공급 판단을 설명하려 할 수 있다.","relationship":"유하은의 칠판과 구도영의 운송 순번을 맞추며 거래 상대에게도 배급 정보의 공개를 기대할 수 있다.","effects":[]}],"narrative":"흉작 소문에 창고를 열고 배급표를 공개했다. 실제 거래 조정과 공급 판단이 근거이며 경매 직함만으로 경매 전문 숙련을 추가하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41450-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K105","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-41450-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ba85-c5f0-c548","name":"연안 명씨","crest":"clan-crests/ba85-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":15,"무력":-30,"물질":30,"공동":25,"원칙":-5,"공개":-20,"자격":35,"분산":15,"변혁":-5},"desire":{"갈망":25,"독점":25,"위험":-20,"과시":40,"지속":30,"지향":"동성","결합":"비독점"},"fields":{"소속":"Arc","생업":"공방시장 출고·배급 기록","품계":"일반 시민","직함":"천호 공방시장 경매사","가치관":"권위 −10 | 개방 15 | 무력 −30 | 물질 30 | 공동 25 | 원칙 −5 | 공개 −20 | 자격 35 | 분산 15 | 변혁 −5","욕망":"갈망 25 | 독점 25 | 위험 −20 | 과시 40 | 지속 30 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 명우솔은 노량진 선창에서 자랐다. 명우솔은 저울 재점검 공개로 천호 공방시장 경매사 자리를 맡았다.\n- 명우솔의 천호 공방시장 경매사 업무는 천호3동과 연결된다.","관직":"품계 일반 시민. 직함은 천호 공방시장 경매사. 출고 수량을 직능 칠판에 공개하고, 군수 우선은 수비대의 경보가 있을 때만 허용한다.","일화":"2125년 명우솔은 흉작 소문에 창고 봉쇄를 풀고 비상배급표를 공개했다. 이 일로 천호 공방시장 경매사 자리의 서명이 장부에 올랐다.","관계":"유하은의 직능 칠판을 경매로 집행하고, 구도영의 패킹 운송과 순번을 나누며, 남윤경의 가격 원장이 천호 시세를 가로채면 원한으로 돌아선다.","야망":"가죽·펌프 패킹·소형 기어를 공동규격의 필수 품목으로 경매에 올려, 부품을 쥔 쪽이 겨울 난로 수리를 볼모로 삼지 못하게 한다.","공포":"명우솔은 민수용 펌프 패킹이 사라지는 상황을 두려워한다.","개입":"대체 원단을 구하거나, 군화 창고의 숨은 발주를 폭로해 경매 잠금을 풀 수 있다."},"biography":"원단과 기어의 출처를 숨기는 공방을 추궁하고, 신발 한 켤레의 시세가 방호보다 먼저 사람을 살린다고 믿는다. 흥정을 즐기되 군화 우선 낙찰은 거부한다.\n\n- 소속: Arc\n- 생업: 공방시장 출고·배급 기록\n- 품계: 일반 시민\n- 직함: 천호 공방시장 경매사\n**생애.** 2126년 세대. 명우솔은 노량진 선창에서 자랐다. 명우솔은 저울 재점검 공개로 천호 공방시장 경매사 자리를 맡았다.\n- 명우솔의 천호 공방시장 경매사 업무는 천호3동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 천호 공방시장 경매사. 출고 수량을 직능 칠판에 공개하고, 군수 우선은 수비대의 경보가 있을 때만 허용한다.\n\n**일화.** 2125년 명우솔은 흉작 소문에 창고 봉쇄를 풀고 비상배급표를 공개했다. 이 일로 천호 공방시장 경매사 자리의 서명이 장부에 올랐다.\n\n**관계.** 유하은의 직능 칠판을 경매로 집행하고, 구도영의 패킹 운송과 순번을 나누며, 남윤경의 가격 원장이 천호 시세를 가로채면 원한으로 돌아선다.\n\n**야망.** 가죽·펌프 패킹·소형 기어를 공동규격의 필수 품목으로 경매에 올려, 부품을 쥔 쪽이 겨울 난로 수리를 볼모로 삼지 못하게 한다.\n\n**공포.** 명우솔은 민수용 펌프 패킹이 사라지는 상황을 두려워한다.\n\n**개입.** 대체 원단을 구하거나, 군화 창고의 숨은 발주를 폭로해 경매 잠금을 풀 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 15 | 무력 −30 | 물질 30 | 공동 25 | 원칙 −5 | 공개 −20 | 자격 35 | 분산 15 | 변혁 −5\n- 욕망: 갈망 25 | 독점 25 | 위험 −20 | 과시 40 | 지속 30 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"명우솔","type":"지휘","to":"유하은","basis":"유하은의 직능 칠판을 경매로 집행하고"},{"from":"명우솔","type":"지휘","to":"구도영","basis":"구도영의 패킹 운송과 순번을 나누며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0107', 'c81c-ce60-c6d0', '{"id":"person-0107","name":"Je Ba-reum","title":"Gil-dong Alley Infirmary First-Aid Officer","position":"Gil-dong Alley Infirmary First-Aid Officer","characterId":"K106","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Alley First Aid and Medicine Distribution","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-je-bareum","detailRoute":"/people/person-0107","birthDate":"2101-05-31","birthday":"05-31","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"dose","name":"Scarce-medicine allocation","rating":60},{"id":"water-board","name":"Hypothermia notice board management","rating":55}],"traits":[{"id":"dehydrated-patients-first","name":"Dehydrated Patients First","description":"Je Bareum prioritizes care by checking alley dehydration counts before succession discussions.","behavior":"She maintains alley-by-alley hypothermia boards and, when a shutter freezes and will not close, asks about the sick before holding a meeting.","stress":"If a cold snap seems likely to cause a fuel shortage, she may put hypothermia conditions and heating fuel ahead of other debates.","relationship":"She may expect the neighboring check watchers to help make the food minimum actually hold at the care site.","effects":[]},{"id":"minimum-medical-care","name":"Minimum Medical Care","description":"Je Bareum believes minimum medical supplies should remain available to everyone despite succession gaps or shortages.","behavior":"When medicinal herbs ran short she halved the doses to share them with everyone, and if fuel goes only to one household''s storeroom she convenes a residents'' gathering by neighbors'' signatures.","stress":"If the cold threatens to push people out of the village, she may press harder to place a care minimum in the village rules.","relationship":"They may refine minimum-guarantee wording with Im Bada and expect collaborators to support basic civilian supplies over family or military claims.","effects":[]}],"narrative":"She provides neighborhood care, shares scarce medicine, and posts dehydration counts. Medical-supply management is supported, not invented licenses or specialist epidemic treatment.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41670-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K106","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-41670-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c81c-ce60-c6d0","name":"Je Clan of Chilwon","crest":"clan-crests/c81c-ce60-c6d0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":15,"Force":-50,"Material":25,"Communal":40,"Principle":40,"Public":-20,"Eligibility":20,"Dispersed":10,"Transformative":-5},"desire":{"Longing":35,"Monopoly":-30,"Risk":0,"Display":-15,"Sustained":-10,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Alley First Aid and Medicine Distribution","Rank":"Ordinary Citizen","Title":"Gil-dong Alley Infirmary First-Aid Officer","Values":"Authority −5 | Openness 15 | Force −50 | Material 25 | Communal 40 | Principle 40 | Publicity −20 | Credentials 20 | Dispersal 10 | Transformation −5","Desires":"Craving 35 | Monopoly −30 | Risk 0 | Display −15 | Persistence −10 | Orientation Positive | Coupling Non-exclusive"},"sections":{"Life":"Generation of 2126. Je Bareum grew up in the Gil-dong clinic. Je Bareum took the post of Director of the Gil-dong Alley Clinic by way of a counterfeit-medicine seal.\n- Je Bareum''s work as Director of the Gil-dong Alley Clinic is linked to Cheonho 1-dong.","Offices":"Rank: Ordinary Citizen. Title: Gil-dong Alley Infirmary First-Aid Officer. Runs hypothermia bulletin boards for each alley, and if fuel goes only to one household''s storeroom, convenes the residents'' gathering by neighbors'' signatures.","Anecdote":"In 2125, Je Bareum halved the prescription amounts during a medicine shortage and gave them out to everyone. Because of this, the signature for the post of Director of the Gil-dong Alley Clinic entered the ledger.","Relationships":"Upholds the alley watchers'' food minimum through care, takes injured patrol members into the alley, and shares the wording of the care minimum with other alley watchers.","Ambition":"Even if the person in charge changes, nail Gil-dong''s care minimum into the village rules so that residents do not become mere numbers in a stronger party''s deal.","Fear":"Je Bareum fears that a fuel shortage in the cold will spread into mass freezing across several alleys and leave Cheonho residents to leave their homes and drift.","Intervention":"Can bring the measured food-bin tables and the medicinal herb list to force the minimum line through, or expose tampering with the bulletin boards to void a watcher''s signature."},"biography":"When the alley food bins run empty, she considers meetings a luxury and asks about the number of people collapsed from hypothermia before names. Gentle, but she ties the seal cords on the herb boxes herself.\n\n- Affiliation: Arc\n- Livelihood: Alley First Aid and Medicine Distribution\n- Rank: Ordinary Citizen\n- Title: Gil-dong Alley Infirmary First-Aid Officer\n**Life.** Generation of 2126. Je Bareum grew up in the Gil-dong clinic. Je Bareum took the post of Director of the Gil-dong Alley Clinic by way of a counterfeit-medicine seal.\n- Je Bareum''s work as Director of the Gil-dong Alley Clinic is linked to Cheonho 1-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Gil-dong Alley Infirmary First-Aid Officer. Runs hypothermia bulletin boards for each alley, and if fuel goes only to one household''s storeroom, convenes the residents'' gathering by neighbors'' signatures.\n\n**Anecdote.** In 2125, Je Bareum halved the prescription amounts during a medicine shortage and gave them out to everyone. Because of this, the signature for the post of Director of the Gil-dong Alley Clinic entered the ledger.\n\n**Relations.** Upholds the alley watchers'' food minimum through care, takes injured patrol members into the alley, and shares the wording of the care minimum with other alley watchers.\n\n**Ambition.** Even if the person in charge changes, nail Gil-dong''s care minimum into the village rules so that residents do not become mere numbers in a stronger party''s deal.\n\n**Fear.** Je Bareum fears that a fuel shortage in the cold will spread into mass freezing across several alleys and leave Cheonho residents to leave their homes and drift.\n\n**Intervention.** Can bring the measured food-bin tables and the medicinal herb list to force the minimum line through, or expose tampering with the bulletin boards to void a watcher''s signature.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 15 | Force −50 | Material 25 | Communal 40 | Principle 40 | Publicity −20 | Credentials 20 | Dispersal 10 | Transformation −5\n- Desires: Craving 35 | Monopoly −30 | Risk 0 | Display −15 | Persistence −10 | Orientation Positive | Coupling Non-exclusive\n:::","relations":{"outgoing":[{"from":"Je Ba-reum","type":"Command","to":"Jang Minjae","basis":"setting the blanket and food order for hypothermia patients by the numbers Jang Minjae posts"}],"incoming":[]}}', '{"id":"person-0107","name":"제바름","title":"길동 골목의무소 응급처치원","position":"길동 골목의무소 응급처치원","characterId":"K106","rank":"일반 시민","commonTier":"T3","occupation":"골목 응급 처치·약 배분","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-제바름","detailRoute":"/people/person-0107","birthDate":"2101-05-31","birthday":"05-31","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"dose","name":"부족 약재 배분","rating":60},{"id":"water-board","name":"저체온 게시판 운영","rating":55}],"traits":[{"id":"dehydrated-patients-first","name":"탈수 환자 먼저","description":"제바름은 후계 논의보다 골목의 탈수 환자 수를 먼저 확인하는 돌봄 우선 성향을 보인다.","behavior":"골목별 저체온 게시판을 운영하고, 셔터가 얼어 안 닫히면 회의보다 아픈 사람 상황을 먼저 묻는다.","stress":"한파로 연료가 모자랄 조짐이 있으면 다른 논의보다 저체온 현황과 난방 연료를 더 앞세울 수 있다.","relationship":"이웃 점검 당번들에게서는 식량 최저선이 돌봄 현장에서 실제로 지켜지는 협력을 기대할 수 있다.","effects":[]},{"id":"minimum-medical-care","name":"의료 최저선","description":"제바름은 후계 공백이나 물자 부족에도 모두에게 최소한의 의료 공급이 남아야 한다고 여긴다.","behavior":"약재가 모자랄 때 처방량을 반으로 나눠 모두에게 나눴고, 연료가 한 집 창고로만 가면 이웃 서명으로 주민 모임을 연다.","stress":"한파로 사람들이 마을 밖으로 밀려날 우려가 커지면 돌봄 최저선을 마을 규칙에 명시하려는 요구를 강화할 수 있다.","relationship":"임바다와 최저선 문구를 함께 다듬으며 협력자에게도 가문이나 군수보다 시민의 최소 공급을 지지하길 기대할 수 있다.","effects":[]}],"narrative":"골목 진료와 부족 약재 배분, 탈수 게시를 수행한다. 의료 공급 운영을 평가하며 면허나 전염병 특수 치료를 새로 만들지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41670-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K106","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-41670-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c81c-ce60-c6d0","name":"칠원 제씨","crest":"clan-crests/c81c-ce60-c6d0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":15,"무력":-50,"물질":25,"공동":40,"원칙":40,"공개":-20,"자격":20,"분산":10,"변혁":-5},"desire":{"갈망":35,"독점":-30,"위험":0,"과시":-15,"지속":-10,"지향":"양성","결합":"비독점"},"fields":{"소속":"Arc","생업":"골목 응급 처치·약 배분","품계":"일반 시민","직함":"길동 골목의무소 응급처치원","가치관":"권위 −5 | 개방 15 | 무력 −50 | 물질 25 | 공동 40 | 원칙 40 | 공개 −20 | 자격 20 | 분산 10 | 변혁 −5","욕망":"갈망 35 | 독점 −30 | 위험 0 | 과시 −15 | 지속 −10 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 제바름은 길동 의무소에서 자랐다. 제바름은 가짜 약 봉인으로 길동 골목의무소 원장 자리를 맡았다.\n- 제바름의 길동 골목의무소 원장 업무는 천호1동과 연결된다.","관직":"품계 일반 시민. 직함은 길동 골목의무소 응급처치원. 골목별 저체온 게시판을 운영하고, 연료가 한 집 창고로만 가면 이웃 서명으로 주민 모임을 연다.","일화":"2125년 제바름은 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다. 이 일로 길동 골목의무소 원장 자리의 서명이 장부에 올랐다.","관계":"골목 당번의 식량 최저선을 돌봄에서 지키고, 순찰 중 다친 사람을 골목으로 받아들이며, 다른 골목 당번과 돌봄 최저선 문구를 나눈다.","야망":"책임자가 바뀌어도 길동의 돌봄 최저선을 마을 규칙에 못 박아, 주민이 힘센 쪽 거래의 숫자가 되지 않게 한다.","공포":"제바름은 한파 속 연료 부족이 여러 골목의 집단 동결로 번져 천호 주민이 살던 곳을 떠나 떠돌게 되는 것을 두려워한다.","개입":"식량통 실측표와 약재 목록을 가져와 최저선을 관철하거나, 게시판 조작을 밝혀 당번 서명을 무효로 만들 수 있다."},"biography":"골목 식량통이 비면 회의를 사치로 여기고, 이름보다 저체온으로 쓰러진 사람 수를 먼저 묻는다. 온화하나 약재 상자의 봉인 끈은 직접 묶는다.\n\n- 소속: Arc\n- 생업: 골목 응급 처치·약 배분\n- 품계: 일반 시민\n- 직함: 길동 골목의무소 응급처치원\n**생애.** 2126년 세대. 제바름은 길동 의무소에서 자랐다. 제바름은 가짜 약 봉인으로 길동 골목의무소 원장 자리를 맡았다.\n- 제바름의 길동 골목의무소 원장 업무는 천호1동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 길동 골목의무소 응급처치원. 골목별 저체온 게시판을 운영하고, 연료가 한 집 창고로만 가면 이웃 서명으로 주민 모임을 연다.\n\n**일화.** 2125년 제바름은 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다. 이 일로 길동 골목의무소 원장 자리의 서명이 장부에 올랐다.\n\n**관계.** 골목 당번의 식량 최저선을 돌봄에서 지키고, 순찰 중 다친 사람을 골목으로 받아들이며, 다른 골목 당번과 돌봄 최저선 문구를 나눈다.\n\n**야망.** 책임자가 바뀌어도 길동의 돌봄 최저선을 마을 규칙에 못 박아, 주민이 힘센 쪽 거래의 숫자가 되지 않게 한다.\n\n**공포.** 제바름은 한파 속 연료 부족이 여러 골목의 집단 동결로 번져 천호 주민이 살던 곳을 떠나 떠돌게 되는 것을 두려워한다.\n\n**개입.** 식량통 실측표와 약재 목록을 가져와 최저선을 관철하거나, 게시판 조작을 밝혀 당번 서명을 무효로 만들 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 15 | 무력 −50 | 물질 25 | 공동 40 | 원칙 40 | 공개 −20 | 자격 20 | 분산 10 | 변혁 −5\n- 욕망: 갈망 35 | 독점 −30 | 위험 0 | 과시 −15 | 지속 −10 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"제바름","type":"지휘","to":"장민재","basis":"장민재가 게시한 숫자에 맞춰 저체온 환자의 담요와 식량 순서를 정하고"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0108', 'bcc0-cd08-acc4', '{"id":"person-0108","name":"Byeon Seok-hun","title":"Amsa Pump Room Power Plant Chief Operator","position":"Amsa Pump Room Power Plant Chief Operator","characterId":"K107","rank":"Ordinary Citizen","commonTier":"T4","occupation":"Operating Pump Room Power Generation and Distribution","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-Byeon-Seokhun","detailRoute":"/people/person-0108","birthDate":"2068-02-15","birthday":"02-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"power","name":"Pump-room distribution checks","rating":65},{"id":"parts","name":"Defective-parts dispatch inspection","rating":50}],"traits":[{"id":"reduce-power-on-vibration-changes","name":"Reduce Power on Vibration Changes","description":"Byeon Seokhun treats changes in pump-room vibration as signals requiring output adjustment.","behavior":"Byeon reduces output when vibration changes and does not understate the fuel log.","stress":"Byeon may make more conservative output-reduction decisions.","relationship":"While supplying Kim Boram''s guards, Byeon may still reduce supplied output when pump vibration changes.","effects":[]},{"id":"minimum-pump-output-first","name":"Minimum Pump Output First","description":"Byeon Seokhun secures minimum pump operating power before other electricity demands.","behavior":"Byeon schedules charging for Lee Juntaek''s Godeok maintenance vehicles after securing the pump minimum.","stress":"","relationship":"Despite cooperation with Lee Juntaek, friction may arise if maintenance-vehicle charging threatens the pump minimum.","effects":[]}],"narrative":"He reduces output on vibration changes and prioritizes pumps over repair-car charging. Power operation and parts returns are supported; guilt over a disappearance is not a finding of negligence.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bcc0-cd08-acc4","name":"Byeon Clan of Chogye","crest":"clan-crests/bcc0-cd08-acc4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":15,"Force":-25,"Material":25,"Communal":35,"Principle":5,"Public":-20,"Eligibility":50,"Dispersed":25,"Transformative":-10},"desire":{"Longing":45,"Monopoly":-30,"Risk":-30,"Display":-10,"Sustained":-5,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Operating Pump Room Power Generation and Distribution","Rank":"Ordinary Citizen","Title":"Amsa Pump Room Power Plant Chief Operator","Values":"Authority −5 | Openness 15 | Force −25 | Material 25 | Communal 35 | Principle 5 | Publicity −20 | Credentials 50 | Dispersal 25 | Transformation −10","Desires":"Craving 45 | Monopoly −30 | Risk −30 | Display −10 | Persistence −5 | Orientation Fluid | Coupling Non-exclusive"},"sections":{"Life":"Generation of 2126. Byeon Seokhun grew up at the Sinjeong Rail Depot. Byeon Seokhun took the post of Head of Power Operations at the Amsa Pump Room through a defect report filed just before a derailment.\n- Byeon Seokhun''s work as Head of Power Operations at the Amsa Pump Room is linked to Cheonho 2-dong.","Offices":"Rank: Ordinary Citizen. Title: Amsa Pump Room Power Plant Chief Operator. By day he shares output logs with the stationmaster; nighttime distribution is permitted only with double confirmation by the Guard Corps cipher tag and the process supervisor.","Anecdote":"In 2125, Byeon Seokhun sent a box of defective parts back just before shipment. Because of this, the signature for the post of Head of Power Operations at the Amsa Pump Room entered the ledger.","Relationships":"Devotes power to Kim Boram''s command of pump defense, places Godeok maintenance-car charging after the pump minimum line, and regards Im Hajun''s disappearance as a gap in his own night duty.","Ambition":"Bind the power of the pump-room generators and the Godeok holding sidings into one public distribution grid, so that whoever succeeds, the infirmary heating on winter nights does not become a hostage of blackouts.","Fear":"","Intervention":"Can obtain replacement batteries to open dual distribution, or expose tampering with the output log to replace the head of operations."},"biography":"When the vibration in the pump room changes, he lowers output. Taciturn, and never shaves the fuel log.\n\n- Affiliation: Arc\n- Livelihood: Operating Pump Room Power Generation and Distribution\n- Rank: Ordinary Citizen\n- Title: Amsa Pump Room Power Plant Chief Operator\n**Life.** Generation of 2126. Byeon Seokhun grew up at the Sinjeong Rail Depot. Byeon Seokhun took the post of Head of Power Operations at the Amsa Pump Room through a defect report filed just before a derailment.\n- Byeon Seokhun''s work as Head of Power Operations at the Amsa Pump Room is linked to Cheonho 2-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Amsa Pump Room Power Plant Chief Operator. By day he shares output logs with the stationmaster; nighttime distribution is permitted only with double confirmation by the Guard Corps cipher tag and the process supervisor.\n\n**Anecdote.** In 2125, Byeon Seokhun sent a box of defective parts back just before shipment. Because of this, the signature for the post of Head of Power Operations at the Amsa Pump Room entered the ledger.\n\n**Relations.** Devotes power to Kim Boram''s command of pump defense, places Godeok maintenance-car charging after the pump minimum line, and regards Im Hajun''s disappearance as a gap in his own night duty.\n\n**Ambition.** Bind the power of the pump-room generators and the Godeok holding sidings into one public distribution grid, so that whoever succeeds, the infirmary heating on winter nights does not become a hostage of blackouts.\n\n**Intervention.** Can obtain replacement batteries to open dual distribution, or expose tampering with the output log to replace the head of operations.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 15 | Force −25 | Material 25 | Communal 35 | Principle 5 | Publicity −20 | Credentials 50 | Dispersal 25 | Transformation −10\n- Desires: Craving 45 | Monopoly −30 | Risk −30 | Display −10 | Persistence −5 | Orientation Fluid | Coupling Non-exclusive\n:::","relations":{"outgoing":[{"from":"Byeon Seok-hun","type":"Command","to":"Kim Boram","basis":"throwing full strength behind Kim Boram''s pump-guard command"}],"incoming":[]}}', '{"id":"person-0108","name":"변석훈","title":"암사 펌프실 발전운전장","position":"암사 펌프실 발전운전장","characterId":"K107","rank":"일반 시민","commonTier":"T4","occupation":"펌프실 발전·배전 운전","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-변석훈","detailRoute":"/people/person-0108","birthDate":"2068-02-15","birthday":"02-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"power","name":"펌프실 배전 확인","rating":65},{"id":"parts","name":"불량 부품 출고 검사","rating":50}],"traits":[{"id":"reduce-power-on-vibration-changes","name":"진동 바뀌면 감출력","description":"변석훈은 펌프실 진동 변화를 출력 조정이 필요한 신호로 받아들인다.","behavior":"진동이 바뀌면 출력을 낮추고 연료 일지를 축소 기록하지 않는다.","stress":"감출력 판단을 더 보수적으로 할 수 있다.","relationship":"김보람의 수비에 전력을 대면서도 펌프 진동이 바뀌면 공급 출력을 낮출 수 있다.","effects":[]},{"id":"minimum-pump-output-first","name":"펌프 최저선 먼저","description":"변석훈은 다른 전력 수요보다 펌프의 최소 운전 전력을 먼저 확보한다.","behavior":"이준택의 고덕 보수차 충전을 펌프 최저선 확보 다음 순서에 둔다.","stress":"","relationship":"이준택과 협력하더라도 보수차 충전이 펌프 최저선을 침해하면 우선순위를 두고 마찰이 생길 수 있다.","effects":[]}],"narrative":"진동 변화에 출력을 낮추고 보수차 충전을 펌프 뒤에 둔다. 발전 운전과 불량 반송이 근거이며 실종 책임감은 실제 과실 판정이 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bcc0-cd08-acc4","name":"초계 변씨","crest":"clan-crests/bcc0-cd08-acc4.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":15,"무력":-25,"물질":25,"공동":35,"원칙":5,"공개":-20,"자격":50,"분산":25,"변혁":-10},"desire":{"갈망":45,"독점":-30,"위험":-30,"과시":-10,"지속":-5,"지향":"유동","결합":"비독점"},"fields":{"소속":"Arc","생업":"펌프실 발전·배전 운전","품계":"일반 시민","직함":"암사 펌프실 발전운전장","가치관":"권위 −5 | 개방 15 | 무력 −25 | 물질 25 | 공동 35 | 원칙 5 | 공개 −20 | 자격 50 | 분산 25 | 변혁 −10","욕망":"갈망 45 | 독점 −30 | 위험 −30 | 과시 −10 | 지속 −5 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2126년 세대. 변석훈은 신정 차량기지에서 자랐다. 변석훈은 탈선 직전 결함 보고로 암사 펌프실 발전운전장 자리를 맡았다.\n- 변석훈의 암사 펌프실 발전운전장 업무는 천호2동과 연결된다.","관직":"품계 일반 시민. 직함은 암사 펌프실 발전운전장. 주간은 역장과 출력 일지를 공유하고, 야간 배전은 수비대 암호패와 공정 감독의 이중 확인만 허용한다.","일화":"2125년 변석훈은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 암사 펌프실 발전운전장 자리의 서명이 장부에 올랐다.","관계":"김보람의 펌프수비 지휘에 전력을 대고, 고덕 보수차 충전을 펌프 최저선 다음에 두며, 임하준 실종을 자신의 야간 당직 공백으로 여긴다.","야망":"펌프실 발전기와 고덕 유치선의 전력을 하나의 공개 배전망으로 묶어, 후계가 누가 되든 겨울 밤 의무소 난방이 정전의 볼모가 되지 않게 한다.","공포":"","개입":"대체 축전지를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다."},"biography":"펌프실의 진동이 바뀌면 출력을 낮춘다. 과묵하고 연료 일지를 깎지 않는다.\n\n- 소속: Arc\n- 생업: 펌프실 발전·배전 운전\n- 품계: 일반 시민\n- 직함: 암사 펌프실 발전운전장\n**생애.** 2126년 세대. 변석훈은 신정 차량기지에서 자랐다. 변석훈은 탈선 직전 결함 보고로 암사 펌프실 발전운전장 자리를 맡았다.\n- 변석훈의 암사 펌프실 발전운전장 업무는 천호2동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 암사 펌프실 발전운전장. 주간은 역장과 출력 일지를 공유하고, 야간 배전은 수비대 암호패와 공정 감독의 이중 확인만 허용한다.\n\n**일화.** 2125년 변석훈은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 암사 펌프실 발전운전장 자리의 서명이 장부에 올랐다.\n\n**관계.** 김보람의 펌프수비 지휘에 전력을 대고, 고덕 보수차 충전을 펌프 최저선 다음에 두며, 임하준 실종을 자신의 야간 당직 공백으로 여긴다.\n\n**야망.** 펌프실 발전기와 고덕 유치선의 전력을 하나의 공개 배전망으로 묶어, 후계가 누가 되든 겨울 밤 의무소 난방이 정전의 볼모가 되지 않게 한다.\n\n**개입.** 대체 축전지를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 15 | 무력 −25 | 물질 25 | 공동 35 | 원칙 5 | 공개 −20 | 자격 50 | 분산 25 | 변혁 −10\n- 욕망: 갈망 45 | 독점 −30 | 위험 −30 | 과시 −10 | 지속 −5 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"변석훈","type":"지휘","to":"김보람","basis":"김보람의 펌프수비 지휘에 전력을 대고"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0109', 'c885-c601-c554', '{"id":"person-0109","name":"Jong Na-sol","title":"Amsa-Sinjeong Food Transport Train Crew Member","position":"Amsa-Sinjeong Food Transport Train Crew Member","characterId":"K108","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Food Transport Crewing and Lock Checks","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-Jong-Nasol","detailRoute":"/people/person-0109","birthDate":"2080-06-06","birthday":"06-06","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"leak","name":"Door-gap inspection","rating":55},{"id":"seal","name":"Seal and copy comparison","rating":55}],"traits":[{"id":"no-verbal-unloading-orders","name":"No Verbal Unloading Orders","description":"Jong Nasol does not alter unloading procedures on verbal orders alone, even with an accompanying officer or code token.","behavior":"They timestamp access registers and pump-inspection seals together and withhold the unloading bell when door vibration changes.","stress":"If a locked door risks being construed as kidnapping evidence, they may rely more on registers and seal times than verbal explanations.","relationship":"They may uphold unloading conditions despite officers'' demands and value timestamp verification with Byeon Seokhun''s power log.","effects":[]},{"id":"read-blank-fields-aloud","name":"Read Blank Fields Aloud","description":"Jong Nasol is taciturn but does not silently pass over blank register entries.","behavior":"They read blank register fields aloud and compare the night-inspection route they witnessed with other log times.","stress":"They may distinguish observations from unknowns more explicitly.","relationship":"They may compare Go Neulgyeol''s opposite-door observations with Byeon Seokhun''s log while asking collaborators not to fill gaps with speculation.","effects":[]}],"narrative":"Title: Amsa-Sinjeong Food Transport Train Crew Member.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43110-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K108","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c885-c601-c554","name":"Jong Clan of Yeongam","crest":"clan-crests/c885-c601-c554.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":5,"Force":-25,"Material":25,"Communal":35,"Principle":10,"Public":-15,"Eligibility":40,"Dispersed":25,"Transformative":-5},"desire":{"Longing":35,"Monopoly":-25,"Risk":10,"Display":5,"Sustained":35,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Food Transport Crewing and Lock Checks","Rank":"Ordinary Citizen","Title":"Amsa-Sinjeong Food Transport Train Crew Member","Values":"Authority −10 | Openness 5 | Force −25 | Material 25 | Communal 35 | Principle 10 | Publicity −15 | Credential 40 | Decentralization 25 | Transformation −5","Desires":"Craving 35 | Exclusivity −25 | Risk 10 | Display 5 | Continuity 35 | Orientation Same-sex | Union Contract Cohabitation"},"sections":{"Life":"Generation of 2126. Jong Nasol grew up on the Yeongdeungpo underground passage night watch.\n- Jong Nasol''s work as crew member on the Amsa-Sinjeong Food Transport Train is connected to Cheonho 2-dong.\n- Jong Nasol''s work cross-checking Sinjeong and Amsa food transport records is connected to Sinjeong 3-dong.","Offices":"Rank: Ordinary Citizen. Title: Amsa-Sinjeong Food Transport Train Crew Member. She stamps the entry roster and the cargo-car lock marker at the same time, and refuses a verbal disembarkation demand no matter who is accompanying.","Anecdote":"","Relationships":"She guarded the opposite door on the same train at Yeouido, saw Im Hajun''s night inspection route to the very end, and matches times with Byeon Seokhun''s pump room power log.","Ambition":"She aims to enter her opposite-side testimony on the Director-General''s disappearance segment into the Council ledger.","Fear":"Jong Nasol fears that the door she locked will be read as evidence of abduction, and that the Godeok holding line will be turned into the Amsa waiting line.","Intervention":"By matching the opposite-side crew log she can narrow the disappearance segment, or she can find evidence that the door lock was opened from the inside and shake his testimony."},"biography":"If the vibration of the pump room access door changes, she does not ring the disembarkation bell, and she treats an empty tool slot as a missing person. She is taciturn, but reads blanks in the roster aloud.\n\n- Affiliation: Arc\n- Livelihood: Food Transport Crewing and Lock Checks\n- Rank: Ordinary Citizen\n- Title: Amsa-Sinjeong Food Transport Train Crew Member\n**Life.** Generation of 2126. Jong Nasol grew up on the Yeongdeungpo underground passage night watch.\n- Jong Nasol''s work as crew member on the Amsa-Sinjeong Food Transport Train is connected to Cheonho 2-dong.\n- Jong Nasol''s work cross-checking Sinjeong and Amsa food transport records is connected to Sinjeong 3-dong.\n\n**Office.** Rank: Ordinary Citizen. Title: Amsa-Sinjeong Food Transport Train Crew Member. She stamps the entry roster and the cargo-car lock marker at the same time, and refuses a verbal disembarkation demand no matter who is accompanying.\n\n**Relationships.** She guarded the opposite door on the same train at Yeouido, saw Im Hajun''s night inspection route to the very end, and matches times with Byeon Seokhun''s pump room power log.\n\n**Ambition.** She aims to enter her opposite-side testimony on the Director-General''s disappearance segment into the Council ledger.\n\n**Fear.** Jong Nasol fears that the door she locked will be read as evidence of abduction, and that the Godeok holding line will be turned into the Amsa waiting line.\n\n**Intervention.** By matching the opposite-side crew log she can narrow the disappearance segment, or she can find evidence that the door lock was opened from the inside and shake his testimony.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 5 | Force −25 | Material 25 | Communal 35 | Principle 10 | Publicity −15 | Credential 40 | Decentralization 25 | Transformation −5\n- Desires: Craving 35 | Exclusivity −25 | Risk 10 | Display 5 | Continuity 35 | Orientation Same-sex | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Jong Na-sol","type":"Contract","to":"Im Hajun","basis":"Watched Im Hajun''s night inspection route to the very end, and"}],"incoming":[]}}', '{"id":"person-0109","name":"종나솔","title":"암사-신정 식량 수송 열차 승무원","position":"암사-신정 식량 수송 열차 승무원","characterId":"K108","rank":"일반 시민","commonTier":"T3","occupation":"식량 수송 승무·잠금 확인","gender":"여성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-종나솔","detailRoute":"/people/person-0109","birthDate":"2080-06-06","birthday":"06-06","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"leak","name":"문틈 점검","rating":55},{"id":"seal","name":"봉인·사본 대조","rating":55}],"traits":[{"id":"no-verbal-unloading-orders","name":"구두 하차 거부","description":"종나솔은 장교의 동행이나 암호패가 있어도 구두 하차 명령만으로 절차를 바꾸지 않는다.","behavior":"출입 명부와 펌프 점검 봉인을 같은 시각에 찍고 출입문 진동이 바뀌면 하차 벨을 울리지 않는다.","stress":"잠근 문이 납치 증거로 해석될 우려가 생기면 구두 설명보다 명부와 봉인 시각을 더 의지할 수 있다.","relationship":"장교의 요구에도 하차 조건을 지키고 변석훈과는 전력 일지의 시각을 맞추는 확인 관계를 중시할 수 있다.","effects":[]},{"id":"read-blank-fields-aloud","name":"빈칸 소리 내어 읽기","description":"종나솔은 과묵하지만 명부의 빈칸을 조용히 넘기지 않는 확인 성향을 보인다.","behavior":"명부 빈칸을 소리 내어 읽고 자신이 본 야간 점검 동선을 다른 일지의 시각과 맞춘다.","stress":"관찰한 사실과 미확인 부분을 더 분명히 나눌 수 있다.","relationship":"고늘결의 반대편 목격과 변석훈의 일지를 대조하되 협력자에게 빈칸을 추측으로 메우지 않길 요구할 수 있다.","effects":[]}],"narrative":"직함은 암사-신정 식량 수송 열차 승무원.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43110-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K108","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c885-c601-c554","name":"영암 종씨","crest":"clan-crests/c885-c601-c554.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":5,"무력":-25,"물질":25,"공동":35,"원칙":10,"공개":-15,"자격":40,"분산":25,"변혁":-5},"desire":{"갈망":35,"독점":-25,"위험":10,"과시":5,"지속":35,"지향":"동성","결합":"계약동거"},"fields":{"소속":"Arc","생업":"식량 수송 승무·잠금 확인","품계":"일반 시민","직함":"암사-신정 식량 수송 열차 승무원","가치관":"권위 −10 | 개방 5 | 무력 −25 | 물질 25 | 공동 35 | 원칙 10 | 공개 −15 | 자격 40 | 분산 25 | 변혁 −5","욕망":"갈망 35 | 독점 −25 | 위험 10 | 과시 5 | 지속 35 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 종나솔은 영등포 지하 통로 야간 당직에서 자랐다.\n- 종나솔의 암사-신정 식량 수송 열차 승무원 업무는 천호2동과 연결된다.\n- 종나솔의 신정·암사 식량 수송 기록 대조 업무는 신정3동과 연결된다.","관직":"품계 일반 시민. 직함은 암사-신정 식량 수송 열차 승무원. 출입 명부와 화물칸 잠금 표식을 같은 시각에 찍고, 누가 동행하든 구두 하차 요구는 거부한다.","일화":"","관계":"여의도의 같은 열차에서 반대편 문을 지켰고, 임하준의 야간 점검 동선을 마지막까지 봤으며, 변석훈의 펌프실 전력 일지와 시각을 맞춘다.","야망":"총관 실종 구간의 반대편 목격을 평의회 원장에 올린다.","공포":"종나솔은 자신이 잠근 문이 납치의 증거로 읽히고, 고덕 유치선이 암사 대기선으로 바뀌는 상황을 두려워한다.","개입":"반대편 승무 일지를 맞춰 실종 구간을 좁히거나, 문 잠금이 안에서 열린 증거를 찾아 그의 증언을 흔들 수 있다."},"biography":"펌프실 쪽 출입문의 진동이 바뀌면 하차 벨을 울리지 않고, 빈 공구 자리는 사람 실종으로 본다. 과묵하되 명부 빈칸은 소리 내어 읽는다.\n\n- 소속: Arc\n- 생업: 식량 수송 승무·잠금 확인\n- 품계: 일반 시민\n- 직함: 암사-신정 식량 수송 열차 승무원\n**생애.** 2126년 세대. 종나솔은 영등포 지하 통로 야간 당직에서 자랐다.\n- 종나솔의 암사-신정 식량 수송 열차 승무원 업무는 천호2동과 연결된다.\n- 종나솔의 신정·암사 식량 수송 기록 대조 업무는 신정3동과 연결된다.\n\n**관직.** 품계 일반 시민. 직함은 암사-신정 식량 수송 열차 승무원. 출입 명부와 화물칸 잠금 표식을 같은 시각에 찍고, 누가 동행하든 구두 하차 요구는 거부한다.\n\n**관계.** 여의도의 같은 열차에서 반대편 문을 지켰고, 임하준의 야간 점검 동선을 마지막까지 봤으며, 변석훈의 펌프실 전력 일지와 시각을 맞춘다.\n\n**야망.** 총관 실종 구간의 반대편 목격을 평의회 원장에 올린다.\n\n**공포.** 종나솔은 자신이 잠근 문이 납치의 증거로 읽히고, 고덕 유치선이 암사 대기선으로 바뀌는 상황을 두려워한다.\n\n**개입.** 반대편 승무 일지를 맞춰 실종 구간을 좁히거나, 문 잠금이 안에서 열린 증거를 찾아 그의 증언을 흔들 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 5 | 무력 −25 | 물질 25 | 공동 35 | 원칙 10 | 공개 −15 | 자격 40 | 분산 25 | 변혁 −5\n- 욕망: 갈망 35 | 독점 −25 | 위험 10 | 과시 5 | 지속 35 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"종나솔","type":"계약","to":"임하준","basis":"임하준의 야간 점검 동선을 마지막까지 봤으며"}],"incoming":[]}}');
