INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0143', 'c5ec-c758-b839-4f59', '{"id":"person-0143","name":"Yeo Seo-ha","title":"Black Dispatch Slip Investigation Clerk","position":"Black Dispatch Slip Investigation Clerk","rank":"Guard","commonTier":"T5","occupation":"Dispatch Investigation Log and Testimony Recording","gender":"Male","stage":"S3","state":"S05","stateName":"Arc","detailRoute":"/people/person-0143","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0143","name":"여서하","title":"검은 배차표 조사 서기","position":"검은 배차표 조사 서기","rank":"경비대원","commonTier":"T5","occupation":"배차 조사 일지·증언 기록","gender":"남성","stage":"S3","state":"S05","stateName":"Arc","detailRoute":"/people/person-0143","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0144', 'b0a8-c758-b839', '{"id":"person-0144","name":"Nam Hwi-gang","title":"Amsa Bridge Night Passage Check","position":"Amsa Bridge Night Passage Check","characterId":"K143","rank":"Guard","commonTier":"T5","occupation":"Bridge Passage Checks and Light-Out Records","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#Person-Nam-Hwigang","detailRoute":"/people/person-0144","birthDate":"2082-07-09","birthday":"07-09","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K115","recipientName":"Bae Ujin","basis":"It overlaps with Bae Ujin''s guard network, but the bridge levers are held divided.","sourceRef":{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Nam-Hwigang-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k143-bridge-countersign","name":"Bridge light-out confirmation","rating":60}],"traits":[{"id":"k143-choice","name":"Rejects unilateral opening","description":"She spoke briefly on the bridge and confirmed only whose hand lowered the blockade lever. She left sealing hours over praise.","behavior":"Title: Amsa Bridge Night Passage Check.","stress":"Fear. That the night passage key would gather in one person''s hands and the bridge would become a road for taking people away. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Overlapping Bae Woojin''s escort network, but holding the bridge lever divided.","effects":[]},{"id":"k143-boundary","name":"Maintains work boundaries","description":"Office. Rank: Guard. Title: Amsa Bridge Night Passage Check. She took passage requests only after two duty hands confirmed the lights were out, and sent back a single-slip request.","behavior":"Office. Rank: Guard. Title: Amsa Bridge Night Passage Check. She took passage requests only after two duty hands confirmed the lights were out, and sent back a single-slip request.","stress":"Fear. That the night passage key would gather in one person''s hands and the bridge would become a road for taking people away. The actual response is not yet recorded.","relationship":"Relations. Overlapping Bae Woojin''s escort network, but holding the bridge lever divided.","effects":[]}],"narrative":"Title: Amsa Bridge Night Passage Check.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-35,"Force":70,"Material":20,"Communal":30,"Principle":-30,"Public":-45,"Eligibility":-20,"Dispersed":-50,"Transformative":-35},"desire":{"Longing":45,"Monopoly":-30,"Risk":-25,"Display":10,"Sustained":15,"Orientation":"Same-Sex","Union":"None"},"fields":{"Affiliation":"Arc","Livelihood":"Bridge Passage Checks and Light-Out Records","Rank":"Guard","Title":"Amsa Bridge Night Passage Check","Values":"Authority 55 | Openness −35 | Force 70 | Material 20 | Communal 30 | Principle −30 | Publicity −45 | Qualification −20 | Decentralization −50 | Transformation −35","Desires":"Craving 45 | Monopoly −30 | Risk −25 | Display 10 | Persistence 15 | Orientation same-sex | Union none"},"sections":{"Offices":"Rank: Guard. Title: Amsa Bridge Night Passage Check. Passage requests are accepted only after two duty hands confirm the lights are out; a single-slip request is sent back.","Anecdote":"","Relationships":"It overlaps with Bae Ujin''s guard network, but the bridge levers are held divided.","Ambition":"Enter night passage on the bridge as a separate line in the passage log, rather than leaving it to the commander''s verbal instruction.\n\nFear. Nam Hwigang fears that if the night passage key gathers in a single pair of hands, the bridge will become a road for taking people away.","Intervention":"You can add your name to the passage log, or hide an unlit walkway."},"biography":"Nam Hwigang speaks briefly on the bridge and only checks whose hand brings the lockdown lever down. She leaves a sealing time rather than praise.\n\n- Affiliation: Arc\n- Livelihood: Bridge Passage Checks and Light-Out Records\n- Rank: Guard\n- Title: Amsa Bridge Night Passage Check\nLife. Nam Hwigang was born in 2082. Nam Hwigang grew up at the Amsa guard post. Nam Hwigang''s post as Amsa Bridge Night Passage Check opened after stopping a person crossing the bridge with a light lit on a winter night.\n- In work connected with Amsa 2-dong, Nam Hwigang checks the passage bar and the light-out confirmations of two duty hands, and rejects any single-slip request. The passage key cannot be gathered into one person''s hands by the commander''s verbal instruction alone.\n\n**Office.** Rank: Guard. Title: Amsa Bridge Night Passage Check. Passage requests are accepted only after two duty hands confirm the lights are out; a single-slip request is sent back.\n\n**Relations.** It overlaps with Bae Ujin''s guard network, but the bridge levers are held divided.\n\n**Ambition.** Enter night passage on the bridge as a separate line in the passage log, rather than leaving it to the commander''s verbal instruction.\n\nFear. Nam Hwigang fears that if the night passage key gathers in a single pair of hands, the bridge will become a road for taking people away.\n\n**Intervention.** You can add your name to the passage log, or hide an unlit walkway.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −35 | Force 70 | Material 20 | Communal 30 | Principle −30 | Publicity −45 | Qualification −20 | Dispersion −50 | Transformation −35\n- Desires: Longing 45 | Monopoly −30 | Risk −25 | Display 10 | Persistence 15 | Orientation: same-sex | Union: none\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0144","name":"남휘강","title":"암사 다리 야간 통행 점검","position":"암사 다리 야간 통행 점검","characterId":"K143","rank":"경비대원","commonTier":"T5","occupation":"다리 통행 점검·소등 기록","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-남휘강","detailRoute":"/people/person-0144","birthDate":"2082-07-09","birthday":"07-09","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K115","recipientName":"배우진","basis":"배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","sourceRef":{"path":"lore/characters/Cast-State-05.json","anchor":"인물-남휘강-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k143-bridge-countersign","name":"다리 소등 확인","rating":60}],"traits":[{"id":"k143-choice","name":"단독 개방 거부","description":"교량 위에서는 짧게 말하고, 봉쇄 레버를 누구 손으로 내리는지만 확인한다. 칭찬보다 봉인 시각을 남긴다.","behavior":"직함은 암사 다리 야간 통행 점검.","stress":"공포. 야간 통행 열쇠가 한 사람의 손에 모여, 다리가 사람을 끌고 가는 길이 되는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","effects":[]},{"id":"k143-boundary","name":"업무 경계를 지킴","description":"관직. 품계 경비대원. 직함은 암사 다리 야간 통행 점검. 통행 요청은 두 명의 당직이 소등을 확인한 뒤에만 받고, 쪽지 한 장짜리 요청은 돌려보낸다.","behavior":"관직. 품계 경비대원. 직함은 암사 다리 야간 통행 점검. 통행 요청은 두 명의 당직이 소등을 확인한 뒤에만 받고, 쪽지 한 장짜리 요청은 돌려보낸다.","stress":"공포. 야간 통행 열쇠가 한 사람의 손에 모여, 다리가 사람을 끌고 가는 길이 되는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","effects":[]}],"narrative":"직함은 암사 다리 야간 통행 점검.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-35,"무력":70,"물질":20,"공동":30,"원칙":-30,"공개":-45,"자격":-20,"분산":-50,"변혁":-35},"desire":{"갈망":45,"독점":-30,"위험":-25,"과시":10,"지속":15,"지향":"동성","결합":"없음"},"fields":{"소속":"Arc","생업":"다리 통행 점검·소등 기록","품계":"경비대원","직함":"암사 다리 야간 통행 점검","가치관":"권위 55 | 개방 −35 | 무력 70 | 물질 20 | 공동 30 | 원칙 −30 | 공개 −45 | 자격 −20 | 분산 −50 | 변혁 −35","욕망":"갈망 45 | 독점 −30 | 위험 −25 | 과시 10 | 지속 15 | 지향 동성 | 결합 없음"},"sections":{"관직":"품계 경비대원. 직함은 암사 다리 야간 통행 점검. 통행 요청은 두 명의 당직이 소등을 확인한 뒤에만 받고, 쪽지 한 장짜리 요청은 돌려보낸다.","일화":"","관계":"배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","야망":"다리 야간 통행을 사령관의 구두 지시가 아니라 통행 일지에 따로 한 줄로 남긴다.\n\n공포. 남휘강은 야간 통행 열쇠가 한 사람의 손에 모여 다리가 사람을 끌고 가는 길이 되는 일을 두려워한다.","개입":"통행 일지에 이름을 올리거나, 불이 꺼진 보행로를 숨길 수 있다."},"biography":"남휘강은 교량 위에서는 짧게 말하고, 봉쇄 레버를 누구 손으로 내리는지만 확인한다. 칭찬보다 봉인 시각을 남긴다.\n\n- 소속: Arc\n- 생업: 다리 통행 점검·소등 기록\n- 품계: 경비대원\n- 직함: 암사 다리 야간 통행 점검\n생애. 남휘강은 2082년에 태어났다. 남휘강은 암사 경비 초소에서 자랐다. 남휘강의 암사 다리 야간 통행 점검 자리는 겨울 밤 불을 켠 채 다리를 건너던 사람을 막은 일로 열렸다.\n- 남휘강은 암사2동과 이어진 업무에서 통행 막대와 두 당직자의 소등 확인을 점검하고 쪽지 한 장짜리 요청은 반려한다. 사령관의 구두 지시만으로 통행 열쇠를 한 사람에게 모을 수 없다.\n\n**관직.** 품계 경비대원. 직함은 암사 다리 야간 통행 점검. 통행 요청은 두 명의 당직이 소등을 확인한 뒤에만 받고, 쪽지 한 장짜리 요청은 돌려보낸다.\n\n**관계.** 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.\n\n**야망.** 다리 야간 통행을 사령관의 구두 지시가 아니라 통행 일지에 따로 한 줄로 남긴다.\n\n공포. 남휘강은 야간 통행 열쇠가 한 사람의 손에 모여 다리가 사람을 끌고 가는 길이 되는 일을 두려워한다.\n\n**개입.** 통행 일지에 이름을 올리거나, 불이 꺼진 보행로를 숨길 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −35 | 무력 70 | 물질 20 | 공동 30 | 원칙 −30 | 공개 −45 | 자격 −20 | 분산 −50 | 변혁 −35\n- 욕망: 갈망 45 | 독점 −30 | 위험 −25 | 과시 10 | 지속 15 | 지향 동성 | 결합 없음\n:::","relations":{"outgoing":[],"incoming":[]}}');
