s":{"outgoing":[],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0272', 'c774-acbd-c8fc-674e', '{"id":"person-0272","name":"Yi Hong-won","title":"Cardinal (provisional)","position":"Head of the Yi Family of the Arc","characterId":"K271","rank":"Cardinal (provisional)","commonTier":"T1","occupation":"Computer Room Elder","gender":"Male","stage":"Key","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Yi-Hongwon","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":11,"effective":11},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k271-succession-records","name":"Succession-record separation","rating":65}],"traits":[{"id":"k271-trait-1","name":"Cardinal (provisional)","description":"Title: Cardinal (provisional).","behavior":"Title: Cardinal (provisional).","stress":"","relationship":"Lends Bae Woojin the gate without merging gate custody with escort command.","effects":[]}],"narrative":"Title: Cardinal (provisional).","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s11","name":{"ko":"Gangnam Station Directly Held Land"},"holderPersonId":"K271","directLiegePersonId":null,"stateId":"S11","stationRef":{"stationId":"Gangnam","stationName":"Gangnam"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c774-acbd-c8fc-674e","name":"Gyeongju I Clan","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"Authority":10,"Openness":-20,"Force":-10,"Material":30,"Communal":20,"Principle":10,"Public":-10,"Eligibility":80,"Dispersed":10,"Transformative":-30},"desire":{"Longing":0,"Monopoly":20,"Risk":-20,"Display":-30,"Sustained":60,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Livelihood":"Computer Room Elder","Affiliation":"Arc","Rank":"Cardinal (provisional)","Title":"Head of the Yi Family of the Arc"},"sections":{"Life":"Gangnam Station, computer room. Yi Hongwon became head of the Yi family after keeping the Gangnam Station barrier gate and the Gangnam Station duty box unbroken through the winter. The Yi family''s base is Gangnam Station, and the post of family head passes within the Yi clan. The Yi family is an Arc family of believers; since the Arc replaced every earlier religion, it sponsors no other faith. The Arc''s ancient data-center software and the maintenance records for its machine bodies are linked through duty work between the Seocho 4-dong computer room and the Yeoksam 1-dong work district. Bae Ujin''s escort borrows this barrier gate, but the gate belongs to Yi Hongwon.","Offices":"Rank: Cardinal (provisional). Title: Head of the Yi Family of the Arc. Livelihood alias: Computer Room elder.","Anecdote":"","Houses":"The Gyeongju Yi clan. The clan''s members together look after the winter food and fuel share of the Gangnam congregation.","Relationships":"Bak Taegyeom and wheelsets. Gang Minseo and standards. Bae Ujin and the barrier gate.\n\n- Livelihood: Computer Room Elder\n- Affiliation: Arc\n- Rank: Cardinal (provisional)\n- Title: Head of the Yi Family of the Arc\nYi Hongwon handles Computer Room elder duties in Seocho 4-dong. He connects the Gangnam Station computer room, the bulletin board, and the waiting hall''s handover, access, and duty for daily-life supplies as dong-level work reference points. The North Gate is an access duty for Gangnam Station and does not create northern-region domination or a new fortress\n\nThe maintenance apprentices beside Yi Hongwon, the Computer Room elder, and the Computer Room work foremen."},"biography":"**Life.** Gangnam Station, computer room. Yi Hongwon became head of the Yi family after keeping the Gangnam Station barrier gate and the Gangnam Station duty box unbroken through the winter. The Yi family''s base is Gangnam Station, and the post of family head passes within the Yi clan. The Yi family is an Arc family of believers; since the Arc replaced every earlier religion, it sponsors no other faith. The Arc''s ancient data-center software and the maintenance records for its machine bodies are linked through duty work between the Seocho 4-dong computer room and the Yeoksam 1-dong work district. Bae Ujin''s escort borrows this barrier gate, but the gate belongs to Yi Hongwon.\n**Office.** Rank: Cardinal (provisional). Title: Head of the Yi Family of the Arc. Livelihood alias: Computer Room elder.\n**Family.** The Gyeongju Yi clan. The clan''s members together look after the winter food and fuel share of the Gangnam congregation.\n**Relations.** Bak Taegyeom and wheelsets. Gang Minseo and standards. Bae Ujin and the barrier gate.\n\n- Livelihood: Computer Room Elder\n- Affiliation: Arc\n- Rank: Cardinal (provisional)\n- Title: Head of the Yi Family of the Arc\nYi Hongwon handles Computer Room elder duties in Seocho 4-dong. He connects the Gangnam Station computer room bulletin board, and the waiting hall''s handover, access, and duty for daily-life supplies as dong-level work reference points. The North Gate is an access duty for Gangnam Station and does not create northern-region domination or a new fortress\n\nThe maintenance apprentices beside Yi Hongwon, the Computer Room elder, and the Computer Room work foremen.","relations":{"outgoing":[],"incoming":[{"from":"Song Ha-yul","type":"Master and Disciple","to":"Yi Hong-won","basis":"Trains under the family head as a vehicle maintenance apprentice"},{"from":"Jo U-chan","type":"Command","to":"Yi Hong-won","basis":"Divides wheelset processes under the family head''s command"},{"from":"Seo Jin-a","type":"Rivalry","to":"Yi Hong-won","basis":"Contests mixed residential-and-technical governance"},{"from":"Hwang No-eul","type":"Command","to":"Yi Hong-won","basis":""},{"from":"An Dohan","type":"Contract","to":"Yi Hong-won","basis":"Depends on northern wheelset exchange times"},{"from":"Eom Nuri","type":"Contract","to":"Yi Hong-won","basis":""},{"from":"Dan Geonu","type":"Contract","to":"Yi Hong-won","basis":""}]}}', '{"id":"person-0272","name":"이홍원","title":"추기경(잠정)","position":"아크 이씨 가문 수장","characterId":"K271","rank":"추기경(잠정)","commonTier":"T1","occupation":"전산실 원로","gender":"남성","stage":"주요","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-이홍원","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":11,"effective":11},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k271-succession-records","name":"승계 자료 분리","rating":65}],"traits":[{"id":"k271-trait-1","name":"추기경(잠정)","description":"직함은 추기경(잠정).","behavior":"직함은 추기경(잠정).","stress":"","relationship":"배우진에게 문을 빌려 주되 문 관리와 호위 지휘를 나눈다.","effects":[]}],"narrative":"직함은 추기경(잠정).","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s11","name":{"ko":"강남역 직영지"},"holderPersonId":"K271","directLiegePersonId":null,"stateId":"S11","stationRef":{"stationId":"강남","stationName":"강남"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c774-acbd-c8fc-674e","name":"경주 이씨","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"권위":10,"개방":-20,"무력":-10,"물질":30,"공동":20,"원칙":10,"공개":-10,"자격":80,"분산":10,"변혁":-30},"desire":{"갈망":0,"독점":20,"위험":-20,"과시":-30,"지속":60,"지향":"이성","결합":"단혼"},"fields":{"생업":"전산실 원로","소속":"Arc","품계":"추기경(잠정)","직함":"아크 이씨 가문 수장"},"sections":{"생애":"강남역 전산실. 이홍원이 이씨 가문 수장이 된 것은 겨울 동안 강남역 차단문과 강남역 당직함을 끊기지 않게 지킨 뒤였다. 이씨 가문의 근거지는 강남역이고, 가문 수장 자리는 이씨 가문이 잇는다. 이씨 가문은 아크를 믿는 가문이며, 아크가 이전의 모든 종교를 대체했으므로 따로 후원하는 신앙은 없다. 아크의 고대 데이터센터 소프트웨어와 기계 몸체 정비 기록은 서초4동 전산실과 역삼1동 작업 생활권의 당직 업무로 잇는다. 배우진의 호위는 이 차단문을 빌리지만 차단문은 이홍원의 것이다.","관직":"품계 추기경(잠정). 직함은 아크 이씨 가문 수장. 생업 별명은 전산실 원로.","일화":"","가문":"경주 이씨 가문. 가문 사람들은 강남 쪽 신도 모임의 겨울 식량과 연료 몫을 함께 챙긴다.","관계":"박태겸과 차륜. 강민서와 규격. 배우진과 차단문.\n\n- 생업: 전산실 원로\n- 소속: Arc\n- 품계: 추기경(잠정)\n- 직함: 아크 이씨 가문 수장\n이홍원은 서초4동에서 전산실 원로 업무를 맡는다. 강남역 전산실 게시판과 대합실 생활 물자 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다\n\n전산실 원로 이홍원 곁의 정비 도제와 전산실 작업 반장들이다."},"biography":"**생애.** 강남역 전산실. 이홍원이 이씨 가문 수장이 된 것은 겨울 동안 강남역 차단문과 강남역 당직함을 끊기지 않게 지킨 뒤였다. 이씨 가문의 근거지는 강남역이고, 가문 수장 자리는 이씨 가문이 잇는다. 이씨 가문은 아크를 믿는 가문이며, 아크가 이전의 모든 종교를 대체했으므로 따로 후원하는 신앙은 없다. 아크의 고대 데이터센터 소프트웨어와 기계 몸체 정비 기록은 서초4동 전산실과 역삼1동 작업 생활권의 당직 업무로 잇는다. 배우진의 호위는 이 차단문을 빌리지만 차단문은 이홍원의 것이다.\n**관직.** 품계 추기경(잠정). 직함은 아크 이씨 가문 수장. 생업 별명은 전산실 원로.\n**가문.** 경주 이씨 가문. 가문 사람들은 강남 쪽 신도 모임의 겨울 식량과 연료 몫을 함께 챙긴다.\n**관계.** 박태겸과 차륜. 강민서와 규격. 배우진과 차단문.\n\n- 생업: 전산실 원로\n- 소속: Arc\n- 품계: 추기경(잠정)\n- 직함: 아크 이씨 가문 수장\n이홍원은 서초4동에서 전산실 원로 업무를 맡는다. 강남역 전산실 게시판과 대합실 생활 물자 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다\n\n전산실 원로 이홍원 곁의 정비 도제와 전산실 작업 반장들이다.","relations":{"outgoing":[],"incoming":[{"from":"송하율","type":"스승과 제자","to":"이홍원","basis":"차량 정비 도제로 가문 수장 밑에서 수련"},{"from":"조우찬","type":"지휘","to":"이홍원","basis":"차륜 공정을 가문 수장 지휘로 나눔"},{"from":"서진아","type":"경쟁","to":"이홍원","basis":"주거·기술 혼합 통치를 다툼"},{"from":"황노을","type":"지휘","to":"이홍원","basis":""},{"from":"안도한","type":"계약","to":"이홍원","basis":"북부 차륜 교환 시각을 의존"},{"from":"엄누리","type":"계약","to":"이홍원","basis":""},{"from":"단건우","type":"계약","to":"이홍원","basis":""}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0273', 'c1a1-d64d-c8fc-5b8b', '{"id":"person-0273","name":"Song Ha-yul","title":"Vehicle Maintenance Apprentice","position":"Arc Vehicle Maintenance Apprentice","characterId":"K272","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Managing Vehicle Maintenance Logs · Defective Parts Samples","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Song-Hayul","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k272-defect-sample-preservation","name":"Defect sample preservation","rating":50}],"traits":[{"id":"k272-priority","name":"Vehicle Maintenance Apprentice","description":"Title: Vehicle Maintenance Apprentice.","behavior":"Title: Vehicle Maintenance Apprentice.","stress":"","relationship":"","effects":[]},{"id":"k272-accountability","name":"Vehicle Maintenance Apprentice","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Title: Vehicle Maintenance Apprentice.","stress":"","relationship":"","effects":[]}],"narrative":"Title: Vehicle Maintenance Apprentice.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"Song Clan of Hongju","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":-20,"Force":-15,"Material":30,"Communal":25,"Principle":5,"Public":5,"Eligibility":90,"Dispersed":5,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-25,"Risk":10,"Display":20,"Sustained":30,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Livelihood":"Managing Vehicle Maintenance Logs · Defective Parts Samples","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Arc Vehicle Maintenance Apprentice","Values":"Authority 0 | Openness −20 | Force −15 | Materialism 30 | Community 25 | Principle 5 | Publicity 5 | Qualification 90 | Dispersion 5 | Transformation −30","Desires":"Craving 0 | Possessiveness −25 | Risk 10 | Display 20 | Endurance 30 | Orientation: Opposite-sex | Union: Polyamorous"},"sections":{"Life":"Grew up at the Gangnam Station rail depot. The Arc vehicle maintenance apprentice post opened up because of a defect report filed just before a derailment.\n- Song Hayul handles vehicle maintenance logs and defective-part sample management in Seocho 4-dong. Song links the Gangnam Station headquarters board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Song is I Hongwon''s apprentice and shares braking parts with Hwang Jiho through an apprentice exchange with Bak Taegyeom. Song coordinates North Gate torch signals with Gang Taesan","Offices":"Rank: Ordinary Citizen. Title: Arc Vehicle Maintenance Apprentice. Posts maintenance logs directly on the depot''s shared board without going through the squad leader''s sign-off, and cuts defective parts open to keep as samples.","Anecdote":"","Relationships":"","Ambition":"","Fear":"","Intervention":""},"biography":"Quick with the hands and sparing with words. Does not boast about exam scores but cannot tolerate someone siphoning off another person''s tools.\n\n- Livelihood: Managing Vehicle Maintenance Logs · Defective Parts Samples\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Arc Vehicle Maintenance Apprentice\n**Life.** Grew up at the Gangnam Station rail depot. The Arc vehicle maintenance apprentice post opened up because of a defect report filed just before a derailment.\n- Song Hayul handles vehicle maintenance logs and defective-part sample management in Seocho 4-dong. Song links the Gangnam Station headquarters board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Song is I Hongwon''s apprentice and shares braking parts with Hwang Jiho through an apprentice exchange with Bak Taegyeom. Song coordinates North Gate torch signals with Gang Taesan\n\n**Office.** Rank: Ordinary Citizen. Title: Arc Vehicle Maintenance Apprentice. Posts maintenance logs directly on the depot''s shared board without going through the squad leader''s sign-off, and cuts defective parts open to keep as samples.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness −20 | Force −15 | Materialism 30 | Community 25 | Principle 5 | Publicity 5 | Qualification 90 | Dispersion 5 | Transformation −30\n- Desires: Craving 0 | Possessiveness −25 | Risk 10 | Display 20 | Endurance 30 | Orientation: Opposite-sex | Union: Polyamorous\n:::","relations":{"outgoing":[{"from":"Song Ha-yul","type":"Master and Disciple","to":"Yi Hong-won","basis":"Trains under the family head as a vehicle maintenance apprentice"},{"from":"Song Ha-yul","type":"Contract","to":"Isaac Walker","basis":"Sharing brake parts with the Yongsan apprentices"}],"incoming":[{"from":"Dumo","type":"Master and Disciple","to":"Song Ha-yul","basis":"Receives Song Hayul''s apprentice daily work on site"},{"from":"Chu Jihun","type":"Oath","to":"Song Ha-yul","basis":"Receives Song Hayul''s apprentice daily work as grounds for exposure"}]}}', '{"id":"person-0273","name":"송하율","title":"차량 정비 도제","position":"Arc 차량 정비 도제","characterId":"K272","rank":"일반 시민","commonTier":"T5","occupation":"차량 정비 일지·불량 부품 표본 관리","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-송하율","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k272-defect-sample-preservation","name":"불량 표본 보존","rating":50}],"traits":[{"id":"k272-priority","name":"공구에 대한 책임","description":"직함은 차량 정비 도제.","behavior":"직함은 차량 정비 도제.","stress":"","relationship":"","effects":[]},{"id":"k272-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"직함은 차량 정비 도제.","stress":"","relationship":"","effects":[]}],"narrative":"직함은 차량 정비 도제.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"홍주 송씨","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":-20,"무력":-15,"물질":30,"공동":25,"원칙":5,"공개":5,"자격":90,"분산":5,"변혁":-30},"desire":{"갈망":0,"독점":-25,"위험":10,"과시":20,"지속":30,"지향":"이성","결합":"다자"},"fields":{"생업":"차량 정비 일지·불량 부품 표본 관리","소속":"Arc","품계":"일반 시민","직함":"Arc 차량 정비 도제","가치관":"권위 0 | 개방 −20 | 무력 −15 | 물질 30 | 공동 25 | 원칙 5 | 공개 5 | 자격 90 | 분산 5 | 변혁 −30","욕망":"갈망 0 | 독점 −25 | 위험 10 | 과시 20 | 지속 30 | 지향 이성 | 결합 다자"},"sections":{"생애":"강남역 차량기지에서 자랐다. Arc 차량 정비 도제 자리는 탈선 직전에 올린 결함 보고로 열렸다.\n- 송하율은 서초4동에서 차량 정비 일지·불량 부품 표본 관리 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다","관직":"품계 일반 시민. 직함은 Arc 차량 정비 도제. 정비 일지를 작업 반장 결재 없이 차량기지 공용 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.","일화":"","관계":"","야망":"","공포":"","개입":""},"biography":"손이 빠르고 말이 적다.\n\n- 생업: 차량 정비 일지·불량 부품 표본 관리\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: Arc 차량 정비 도제\n**생애.** 강남역 차량기지에서 자랐다. Arc 차량 정비 도제 자리는 탈선 직전에 올린 결함 보고로 열렸다.\n- 송하율은 서초4동에서 차량 정비 일지·불량 부품 표본 관리 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다\n\n**관직.** 품계 일반 시민. 직함은 Arc 차량 정비 도제. 정비 일지를 작업 반장 결재 없이 차량기지 공용 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 −20 | 무력 −15 | 물질 30 | 공동 25 | 원칙 5 | 공개 5 | 자격 90 | 분산 5 | 변혁 −30\n- 욕망: 갈망 0 | 독점 −25 | 위험 10 | 과시 20 | 지속 30 | 지향 이성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"송하율","type":"스승과 제자","to":"이홍원","basis":"차량 정비 도제로 가문 수장 밑에서 수련"},{"from":"송하율","type":"계약","to":"아이작 워커","basis":"제동 부품을 용산 도제와 나눔"}],"incoming":[{"from":"두모","type":"스승과 제자","to":"송하율","basis":"송하율의 도제 일과를 현장에서 받고"},{"from":"추지훈","type":"맹세","to":"송하율","basis":"송하율의 도제 일과를 폭로 근거로 받고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0274', 'c870-c625-cc9c-8d99', '{"id":"person-0274","name":"Jo U-chan","title":"Work Foreman","position":"Arc Work Foreman","characterId":"K273","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Managing Work Crew Rotation · Accident Signatures","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Jo-Uchan","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k273-work-crew-allocation","name":"Work crew allocation","rating":60}],"traits":[{"id":"k273-priority","name":"Demands demonstrated competence","description":"Title: Work Foreman.","behavior":"Office. Rank: Ordinary Citizen. Title: Arc Work Foreman. She rotated the work squads through stations and demanded the squad leader''s and the apprentice''s signatures together for every accident.","stress":"That heat leaking out on a cold night will draw outside machines by light and warmth up to the Seocho 2-dong shutters.","relationship":"","effects":[]},{"id":"k273-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Ordinary Citizen. Title: Arc Work Foreman. She rotated the work squads through stations and demanded the squad leader''s and the apprentice''s signatures together for every accident.","stress":"That heat leaking out on a cold night will draw outside machines by light and warmth up to the Seocho 2-dong shutters.","relationship":"","effects":[]}],"narrative":"Title: Work Foreman.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"Jo Clan of Okcheon","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-20,"Force":-20,"Material":35,"Communal":15,"Principle":5,"Public":5,"Eligibility":65,"Dispersed":10,"Transformative":-25},"desire":{"Longing":-5,"Monopoly":5,"Risk":-10,"Display":5,"Sustained":10,"Orientation":"Reason","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Managing Work Crew Rotation · Accident Signatures","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Arc Work Foreman","Values":"Authority 15 | Openness −20 | Force −20 | Materialism 35 | Community 15 | Principle 5 | Publicity 5 | Qualification 65 | Dispersion 10 | Transformation −25","Desires":"Craving −5 | Possessiveness 5 | Risk −10 | Display 5 | Endurance 10 | Orientation: Opposite-sex | Union: Contract Cohabitation"},"sections":{"Life":"Grew up on waiting-hall duty. The Arc work foreman post opened up as a substitute duty for an unexcused shift absence.\n- Jo Uchan handles work crew rotation and accident signature management in Seocho 4-dong. Jo links the Gangnam Station headquarters board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Under I Hongwon''s command, Jo divides the wheel process and applies Gang Minseo''s repair specifications on site. ","Offices":"Rank: Ordinary Citizen. Title: Arc Work Foreman. Rotates work crews, and for every accident requires the signatures of both the foreman and the apprentice.","Anecdote":"","Relationships":"","Ambition":"","Fear":"That heat leaking out on a cold night will draw outside machines by light and warmth up to the Seocho 2-dong shutters.","Intervention":""},"biography":"Cold toward anyone who cannot prove their skill, and remembers the blame for accidents down to the date. Makes decisions beneath the wheels rather than in meetings.\n\n- Livelihood: Managing Work Crew Rotation · Accident Signatures\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Arc Work Foreman\n**Life.** Grew up on waiting-hall duty. The Arc work foreman post opened up as a substitute duty for an unexcused shift absence.\n- Jo Uchan handles work crew rotation and accident signature management in Seocho 4-dong. Jo links the Gangnam Station headquarters board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Under I Hongwon''s command, Jo divides the wheel process and applies Gang Minseo''s repair specifications on site. \n\n**Office.** Rank: Ordinary Citizen. Title: Arc Work Foreman. Rotates work crews, and for every accident requires the signatures of both the foreman and the apprentice.\n\n**Fear.** That heat leaking out on a cold night will draw outside machines by light and warmth up to the Seocho 2-dong shutters.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −20 | Force −20 | Materialism 35 | Community 15 | Principle 5 | Publicity 5 | Qualification 65 | Dispersion 10 | Transformation −25\n- Desires: Craving −5 | Possessiveness 5 | Risk −10 | Display 5 | Endurance 10 | Orientation: Opposite-sex | Union: Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Jo U-chan","type":"Command","to":"Yi Hong-won","basis":"Divides wheelset processes under the family head''s command"},{"from":"Jo U-chan","type":"Contract","to":"Gang Minseo","basis":"Applies repair standards to the work crew"},{"from":"Jo U-chan","type":"Grudge","to":"Clara Bennett","basis":""}],"incoming":[{"from":"Dumo","type":"Contract","to":"Jo U-chan","basis":"Is assigned by rotation to Jo Uchan''s work crew"},{"from":"Bongbok","type":"Contract","to":"Jo U-chan","basis":"Takes charge of injuries in Jo Uchan''s work crew"},{"from":"Sobong","type":"Contract","to":"Jo U-chan","basis":"Carries Jo Uchan''s restart notices"},{"from":"Gukdu","type":"Command","to":"Jo U-chan","basis":"Moves the logs under Jo Uchan''s command"},{"from":"Eo Yerin","type":"Oath","to":"Jo U-chan","basis":""}]}}', '{"id":"person-0274","name":"조우찬","title":"작업 반장","position":"Arc 작업 반장","characterId":"K273","rank":"일반 시민","commonTier":"T5","occupation":"작업 조 순환·사고 서명 관리","gender":"여성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-조우찬","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k273-work-crew-allocation","name":"작업 조 배치","rating":60}],"traits":[{"id":"k273-priority","name":"작업 반장","description":"직함은 작업 반장.","behavior":"작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","stress":"한파 밤에 열이 새어 나가 외부 기계가 불빛과 열을 따라 서초2동 셔터까지 다가오는 것.","relationship":"","effects":[]},{"id":"k273-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 일반 시민. 직함은 Arc 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","stress":"공포. 한파 밤에 열이 새어 나가 외부 기계가 불빛과 열을 따라 서초2동 셔터까지 다가오는 것.","relationship":"","effects":[]}],"narrative":"직함은 작업 반장.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"옥천 조씨","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-20,"무력":-20,"물질":35,"공동":15,"원칙":5,"공개":5,"자격":65,"분산":10,"변혁":-25},"desire":{"갈망":-5,"독점":5,"위험":-10,"과시":5,"지속":10,"지향":"이성","결합":"계약동거"},"fields":{"생업":"작업 조 순환·사고 서명 관리","소속":"Arc","품계":"일반 시민","직함":"Arc 작업 반장","가치관":"권위 15 | 개방 −20 | 무력 −20 | 물질 35 | 공동 15 | 원칙 5 | 공개 5 | 자격 65 | 분산 10 | 변혁 −25","욕망":"갈망 −5 | 독점 5 | 위험 −10 | 과시 5 | 지속 10 | 지향 이성 | 결합 계약동거"},"sections":{"생애":"대합실 당직에서 자랐다. Arc 작업 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조우찬은 서초4동에서 작업 조 순환·사고 서명 관리 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. ","관직":"품계 일반 시민. 직함은 Arc 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","일화":"","관계":"","야망":"","공포":"한파 밤에 열이 새어 나가 외부 기계가 불빛과 열을 따라 서초2동 셔터까지 다가오는 것.","개입":""},"biography":"숙련을 증명하지 못한 사람에게 차갑고, 사고 책임을 날짜까지 기억한다. 회의보다 차륜 아래에서 결정을 내린다.\n\n- 생업: 작업 조 순환·사고 서명 관리\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: Arc 작업 반장\n**생애.** 대합실 당직에서 자랐다. Arc 작업 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조우찬은 서초4동에서 작업 조 순환·사고 서명 관리 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. \n\n**관직.** 품계 일반 시민. 직함은 Arc 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.\n\n**공포.** 한파 밤에 열이 새어 나가 외부 기계가 불빛과 열을 따라 서초2동 셔터까지 다가오는 것.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −20 | 무력 −20 | 물질 35 | 공동 15 | 원칙 5 | 공개 5 | 자격 65 | 분산 10 | 변혁 −25\n- 욕망: 갈망 −5 | 독점 5 | 위험 −10 | 과시 5 | 지속 10 | 지향 이성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"조우찬","type":"지휘","to":"이홍원","basis":"차륜 공정을 가문 수장 지휘로 나눔"},{"from":"조우찬","type":"계약","to":"강민서","basis":"수리 규격을 작업반에 적용"},{"from":"조우찬","type":"원한","to":"클라라 베넷","basis":""}],"incoming":[{"from":"두모","type":"계약","to":"조우찬","basis":"조우찬의 작업 조에 순환 배치된다"},{"from":"봉복","type":"계약","to":"조우찬","basis":"조우찬의 작업 조 부상을 맡고"},{"from":"소봉","type":"계약","to":"조우찬","basis":"조우찬의 가동 통지를 나르고"},{"from":"국두","type":"지휘","to":"조우찬","basis":"조우찬의 지휘로 일지를 옮기고"},{"from":"어예린","type":"맹세","to":"조우찬","basis":""}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0275', 'c11c-b2ec-c131', '{"id":"person-0275","name":"Seo Jin-a","title":"Residential Community Auditor","position":"Gangnam Station Company Housing Auditor","characterId":"K274","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Fuel and Food Stock Counting","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Seo-Jina","detailRoute":"/people/person-0275","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k274-petition-and-water-record-review","name":"Fuel and food ledger cross-checking","rating":55}],"traits":[{"id":"k274-priority","name":"Responsibility for deprivation","description":"Seo Jin-a posts fuel stocks and food stocks on the same board and asks for a witness when the shutters are closed on cold nights. His wish that every resident can read the ledger is still an ambition, not an established system.","behavior":"He posts the number of fuel drums and food crates on the same board every morning, and never turns off the lights or closes the shutters at night without a counting witness.","stress":"Fear. That the fuel stock record would be altered and the residents of Seocho 2-dong would come to suspect one another overnight.","relationship":"He checks the ledger together with his Seocho 2-dong neighbors and trades fuel stock figures with the patrol crews of the neighboring dong. He marks separately the food share of households that have a family member captured outside.","effects":[]},{"id":"k274-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"He posts the number of fuel drums and food crates on the same board every morning, and never turns off the lights or closes the shutters at night without a counting witness.","stress":"Fear. That the fuel stock record would be altered and the residents of Seocho 2-dong would come to suspect one another overnight.","relationship":"He checks the ledger together with his Seocho 2-dong neighbors and trades fuel stock figures with the patrol crews of the neighboring dong. He marks separately the food share of households that have a family member captured outside.","effects":[]}],"narrative":"Seo Jin-a posts fuel stocks and food stocks on the same board and asks for a witness when the shutters are closed on cold nights. His wish that every resident can read the ledger is still an ambition, not an established system.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":-20,"Force":-5,"Material":20,"Communal":20,"Principle":30,"Public":5,"Eligibility":50,"Dispersed":15,"Transformative":-20},"desire":{"Longing":-15,"Monopoly":-10,"Risk":5,"Display":-25,"Sustained":15,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Fuel and Food Stock Counting","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Gangnam Station Company Housing Auditor","Values":"Authority 10 | Openness −20 | Force −5 | Material 20 | Communal 20 | Principle 30 | Publicity 5 | Credentials 50 | Dispersal 15 | Transformation −20","Desires":"Craving −15 | Possessiveness −10 | Risk 5 | Display −25 | Endurance 15 | Orientation: same-sex | Union: contract cohabitation"},"sections":{"Life":"Grew up at the Seoul Station registry office. The post of Gangnam Station Company Housing Auditor opened with the deletion of a single line from a double ledger.\n- Seo Jin-a handles fuel and food stock counting in Seocho 2-dong. Every morning he counts the fuel drums and food crates and posts the figures on the board, and on cold nights he also confirms the time the shutters are closed. Personal residence or lodging ownership is not presumed. He marks separately the share of households with a family member captured outside","Offices":"Rank: Ordinary Citizen. Title: Gangnam Station Company Housing Auditor. He posts the number of fuel drums and food crates on the same board every morning, and never turns off the lights or closes the shutters at night without a counting witness.","Anecdote":"","Relationships":"He checks the ledger together with his Seocho 2-dong neighbors and trades fuel stock figures with the patrol crews of the neighboring dong. He marks separately the food share of households that have a family member captured outside.","Ambition":"To turn the stock count into one ledger that everyone can read, so that even if the cold drags on, the people of Seocho 2-dong do not split apart over fuel.","Fear":"That the fuel stock records will be altered and the residents of Seocho 2-dong will come to suspect one another overnight.","Intervention":"Can add fuel drums or send someone to check the count together, helping the stock board to be read correctly."},"biography":"Logical and skilled at counting votes. Regards any moment when people go hungry because of technology as a personal defeat.\n\n- Occupation: Fuel and Food Stock Counting\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Gangnam Station Company Housing Auditor\n**Life.** Grew up at the Seoul Station registry office. The post of Gangnam Station Company Housing Auditor opened with the deletion of a single line from a double ledger.\n- Seo Jin-a handles fuel and food stock counting in Seocho 2-dong. Every morning he counts the fuel drums and food crates and posts the figures on the board, and on cold nights he also confirms the time the shutters are closed. Personal residence or lodging ownership is not presumed. He marks separately the share of households with a family member captured outside\n\n**Office.** Rank: Ordinary Citizen. Title: Gangnam Station Company Housing Auditor. He posts the number of fuel drums and food crates on the same board every morning, and never turns off the lights or closes the shutters at night without a counting witness.\n\n**Relations.** He checks the ledger together with his Seocho 2-dong neighbors and trades fuel stock figures with the patrol crews of the neighboring dong. He marks separately the food share of households that have a family member captured outside.\n\n**Ambition.** To turn the stock count into one ledger that everyone can read, so that even if the cold drags on, the people of Seocho 2-dong do not split apart over fuel.\n\n**Fear.** That the fuel stock records will be altered and the residents of Seocho 2-dong will come to suspect one another overnight.\n\n**Intervention.** Can add fuel drums or send someone to check the count together, helping the stock board to be read correctly.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness −20 | Force −5 | Material 20 | Communal 20 | Principle 30 | Publicity 5 | Credentials 50 | Dispersal 15 | Transformation −20\n- Desires: Craving −15 | Possessiveness −10 | Risk 5 | Display −25 | Endurance 15 | Orientation: same-sex | Union: contract cohabitation\n:::","relations":{"outgoing":[{"from":"Seo Jin-a","type":"Rivalry","to":"Yi Hong-won","basis":"Contests mixed residential-and-technical governance"},{"from":"Seo Jin-a","type":"Contract","to":"Han Jae-mok","basis":"Watches the parts exchange boxes at the border using the fuel and food counts he keeps"}],"incoming":[{"from":"Sobong","type":"Contract","to":"Seo Jin-a","basis":"Posts Seo Jina''s fuel and food stock notice side by side on the same wall"},{"from":"Mobok","type":"Command","to":"Seo Jin-a","basis":"Receiving orders to carry out Seo Jina''s housing audit at the base handle,"},{"from":"Pyeong Chaewon","type":"Contract","to":"Seo Jin-a","basis":"and adding the party''s handprint to Seo Jina''s housing audit box"}]}}', '{"id":"person-0275","name":"서진아","title":"주거공동체 감사","position":"강남역 사택 감사","characterId":"K274","rank":"일반 시민","commonTier":"T5","occupation":"연료·식량 재고 계수","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-서진아","detailRoute":"/people/person-0275","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k274-petition-and-water-record-review","name":"연료·식량 장부 대조","rating":55}],"traits":[{"id":"k274-priority","name":"생활 피해의 책임","description":"서진아는 연료 재고와 식량 재고를 같은 판에 붙이고, 한파가 이어지는 밤에는 셔터를 닫는 시각에 입회를 요구한다. 모든 거주민이 장부를 읽게 하려는 뜻은 아직 야망이며 완성된 제도가 아니다.","behavior":"연료 통 수와 식량 상자 수를 매일 아침 같은 게시판에 붙이고, 야간 소등과 셔터 닫기는 계수 입회 없이 하지 않는다.","stress":"연료 재고 기록이 바뀌어 서초2동 거주민이 하룻밤 사이에 서로를 의심하게 되는 것.","relationship":"서초2동 이웃과 장부를 함께 검산하고, 인접한 동의 순찰 조와 연료 재고를 주고받는다. 외곽에서 붙잡힌 가족이 있는 집의 식량 몫은 따로 표시해 둔다.","effects":[]},{"id":"k274-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 일반 시민. 직함은 강남역 사택 감사. 연료 통 수와 식량 상자 수를 매일 아침 같은 게시판에 붙이고, 야간 소등과 셔터 닫기는 계수 입회 없이 하지 않는다.","stress":"공포. 연료 재고 기록이 바뀌어 서초2동 거주민이 하룻밤 사이에 서로를 의심하게 되는 것.","relationship":"관계. 서초2동 이웃과 장부를 함께 검산하고, 인접한 동의 순찰 조와 연료 재고를 주고받는다. 외곽에서 붙잡힌 가족이 있는 집의 식량 몫은 따로 표시해 둔다.","effects":[]}],"narrative":"서진아는 연료 재고와 식량 재고를 같은 판에 붙이고, 한파가 이어지는 밤에는 셔터를 닫는 시각에 입회를 요구한다. 모든 거주민이 장부를 읽게 하려는 뜻은 아직 야망이며 완성된 제도가 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":-20,"무력":-5,"물질":20,"공동":20,"원칙":30,"공개":5,"자격":50,"분산":15,"변혁":-20},"desire":{"갈망":-15,"독점":-10,"위험":5,"과시":-25,"지속":15,"지향":"동성","결합":"계약동거"},"fields":{"생업":"연료·식량 재고 계수","소속":"Arc","품계":"일반 시민","직함":"강남역 사택 감사","가치관":"권위 10 | 개방 −20 | 무력 −5 | 물질 20 | 공동 20 | 원칙 30 | 공개 5 | 자격 50 | 분산 15 | 변혁 −20","욕망":"갈망 −15 | 독점 −10 | 위험 5 | 과시 −25 | 지속 15 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"서울역 등기소에서 자랐다. 강남역 사택 감사 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 서진아는 서초2동에서 연료·식량 재고 계수 업무를 맡는다. 매일 아침 연료 통과 식량 상자를 세어 게시판에 붙이고, 한파 밤에는 셔터를 닫는 시각을 함께 확인한다. 개인 거주나 숙소 소유는 추정하지 않는다. 외곽에서 붙잡힌 가족이 있는 집의 몫을 따로 표시한다","관직":"품계 일반 시민. 직함은 강남역 사택 감사. 연료 통 수와 식량 상자 수를 매일 아침 같은 게시판에 붙이고, 야간 소등과 셔터 닫기는 계수 입회 없이 하지 않는다.","일화":"","관계":"서초2동 이웃과 장부를 함께 검산하고, 인접한 동의 순찰 조와 연료 재고를 주고받는다. 외곽에서 붙잡힌 가족이 있는 집의 식량 몫은 따로 표시해 둔다.","야망":"한파가 길어져도 서초2동 사람이 연료 때문에 서로 갈라서지 않도록 재고 계수를 모두가 읽을 수 있는 장부 한 권으로 만든다.","공포":"연료 재고 기록이 바뀌어 서초2동 거주민이 하룻밤 사이에 서로를 의심하게 되는 것.","개입":"연료 통을 보태 주거나 계수를 함께 검산해 줄 사람을 보내 재고 판이 바르게 읽히도록 도울 수 있다."},"biography":"논리적이고 표를 세는 데 능하다. 기술 탓에 사람이 굶는 순간을 개인적 패배로 여긴다.\n\n- 생업: 연료·식량 재고 계수\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: 강남역 사택 감사\n**생애.** 서울역 등기소에서 자랐다. 강남역 사택 감사 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 서진아는 서초2동에서 연료·식량 재고 계수 업무를 맡는다. 매일 아침 연료 통과 식량 상자를 세어 게시판에 붙이고, 한파 밤에는 셔터를 닫는 시각을 함께 확인한다. 개인 거주나 숙소 소유는 추정하지 않는다. 외곽에서 붙잡힌 가족이 있는 집의 몫을 따로 표시한다\n\n**관직.** 품계 일반 시민. 직함은 강남역 사택 감사. 연료 통 수와 식량 상자 수를 매일 아침 같은 게시판에 붙이고, 야간 소등과 셔터 닫기는 계수 입회 없이 하지 않는다.\n\n**관계.** 서초2동 이웃과 장부를 함께 검산하고, 인접한 동의 순찰 조와 연료 재고를 주고받는다. 외곽에서 붙잡힌 가족이 있는 집의 식량 몫은 따로 표시해 둔다.\n\n**야망.** 한파가 길어져도 서초2동 사람이 연료 때문에 서로 갈라서지 않도록 재고 계수를 모두가 읽을 수 있는 장부 한 권으로 만든다.\n\n**공포.** 연료 재고 기록이 바뀌어 서초2동 거주민이 하룻밤 사이에 서로를 의심하게 되는 것.\n\n**개입.** 연료 통을 보태 주거나 계수를 함께 검산해 줄 사람을 보내 재고 판이 바르게 읽히도록 도울 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 −20 | 무력 −5 | 물질 20 | 공동 20 | 원칙 30 | 공개 5 | 자격 50 | 분산 15 | 변혁 −20\n- 욕망: 갈망 −15 | 독점 −10 | 위험 5 | 과시 −25 | 지속 15 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"서진아","type":"경쟁","to":"이홍원","basis":"주거·기술 혼합 통치를 다툼"},{"from":"서진아","type":"계약","to":"한재목","basis":"연료·식량 재고를 센 숫자로 부품 교환 상자를 경계에서 지켜봄"}],"incoming":[{"from":"소봉","type":"계약","to":"서진아","basis":"서진아의 연료·식량 재고 공지를 같은 벽에 나란히 붙인다"},{"from":"모복","type":"지휘","to":"서진아","basis":"서진아의 주거 감사를 거점 핸들에서 집행하는 지휘를 받고"},{"from":"평채원","type":"계약","to":"서진아","basis":"서진아의 주거 감사 함에 당사자 손도장을 보태고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0276', 'ad8c-c548-b3d9', '{"id":"person-0276","name":"Gwon Do-ha","title":"Rail Cavalry Squad Leader","position":"Gangnam Station Rail Cavalry Squad Leader","characterId":"K275","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Wheel Inspection · Verifying Armament Loading","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#Person-Gwon-Doha","detailRoute":"/people/person-0276","birthDate":"2097-03-04","birthday":"03-04","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k275-escort-timing-coordination","name":"Escort timing coordination","rating":55}],"traits":[{"id":"k275-priority","name":"Discipline before charges","description":"Gwon Doha coordinates northern gate patrol and escort timings and signals. Her strict charge discipline does not establish battlefield victories.","behavior":"Office. Rank: Ordinary Citizen. Title: rail cavalry squad leader. She made wheel checks mandatory before sorties and required the Elder''s and the auditor''s signatures together for arms loading.","stress":"","relationship":"","effects":[]},{"id":"k275-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Ordinary Citizen. Title: rail cavalry squad leader. She made wheel checks mandatory before sorties and required the Elder''s and the auditor''s signatures together for arms loading.","stress":"","relationship":"","effects":[]}],"narrative":"Gwon Doha coordinates northern gate patrol and escort timings and signals. Her strict charge discipline does not establish battlefield victories.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":-15,"Force":5,"Material":40,"Communal":30,"Principle":15,"Public":-5,"Eligibility":70,"Dispersed":20,"Transformative":-25},"desire":{"Longing":35,"Monopoly":15,"Risk":10,"Display":30,"Sustained":30,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Wheel Inspection · Verifying Armament Loading","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Gangnam Station Rail Cavalry Squad Leader","Values":"Authority 20 | Openness −15 | Force 5 | Material 40 | Communal 30 | Principle 15 | Publicity −5 | Credentials 70 | Dispersal 20 | Transformation −25","Desires":"Craving 35 | Possessiveness 15 | Risk 10 | Display 30 | Endurance 30 | Orientation: none specified | Union: none"},"sections":{"Life":"Grew up on waiting-hall duty. The post of Gangnam Station Rail Cavalry Squad Leader opened through substitute duty for an unexcused shift absence.\n- Gwon Doha handles wheel inspection and armament loading verification in Seocho 4-dong. She connects the Gangnam Station headquarters bulletin board, and the waiting-hall handover of living cargo, access, and duty, as dong-level work reference points. The North Gate is Gangnam Station''s approach duty post and does not create rule over the northern district or a new fortress. She takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. She shares corridor signals with Gang Taesan","Offices":"Rank: Ordinary Citizen. Title: Gangnam Station Rail Cavalry Squad Leader. Wheel inspection before sortie is made mandatory.","Anecdote":"","Relationships":"","Ambition":"Ties the patrol schedule to the northern leg of the Gangnam Station escort, and per the duty roster checks the rail cavalry''s wheels and armament loading and sets the order of sorties.","Fear":"","Intervention":""},"biography":"Likes discipline and regards silence on the tracks as part of combat. Says that an assault without skill is close to betrayal.\n\n- Occupation: Wheel Inspection · Verifying Armament Loading\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Gangnam Station Rail Cavalry Squad Leader\n**Life.** Grew up on waiting-hall duty. The post of Gangnam Station Rail Cavalry Squad Leader opened through substitute duty for an unexcused shift absence.\n- Gwon Doha handles wheel inspection and armament loading verification in Seocho 4-dong. She connects the Gangnam Station headquarters bulletin board, and the waiting-hall handover of living cargo, access, and duty, as dong-level work reference points. The North Gate is Gangnam Station''s approach duty post and does not create rule over the northern district or a new fortress. She takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. She shares corridor signals with Gang Taesan\n\n**Office.** Rank: Ordinary Citizen. Title: Gangnam Station Rail Cavalry Squad Leader. Wheel inspection before sortie is made mandatory.\n\n**Ambition.** Ties the patrol schedule to the northern leg of the Gangnam Station escort, and per the duty roster checks the rail cavalry''s wheels and armament loading and sets the order of sorties.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 20 | Openness −15 | Force 5 | Material 40 | Communal 30 | Principle 15 | Publicity −5 | Credentials 70 | Dispersal 20 | Transformation −25\n- Desires: Craving 35 | Possessiveness 15 | Risk 10 | Display 30 | Endurance 30 | Orientation: none specified | Union: none\n:::","relations":{"outgoing":[{"from":"Gwon Do-ha","type":"Contract","to":"Jang Sehwa","basis":"Aligned the northern escort timing"},{"from":"Gwon Do-ha","type":"Contract","to":"Gang Taesan","basis":"Sharing corridor signals"}],"incoming":[{"from":"Yongdubong","type":"Contract","to":"Gwon Do-ha","basis":"Receiving Gwon Doha''s sortie list at the maintenance bay, and"}]}}', '{"id":"person-0276","name":"권도하","title":"궤도기병 반장","position":"강남역 궤도기병 반장","characterId":"K275","rank":"일반 시민","commonTier":"T5","occupation":"차륜 점검·무장 탑재 확인","gender":"여성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-권도하","detailRoute":"/people/person-0276","birthDate":"2097-03-04","birthday":"03-04","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k275-escort-timing-coordination","name":"호송 시각 조정","rating":55}],"traits":[{"id":"k275-priority","name":"돌격보다 규율","description":"권도하는 북문 순찰과 북부 호송의 시각·신호를 맞춘다. 돌격 규율은 강경하지만 전투 승리 근거는 없다.","behavior":"출격 전에 차륜 점검을 의무화한다.","stress":"","relationship":"","effects":[]},{"id":"k275-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 일반 시민. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화한다.","stress":"","relationship":"","effects":[]}],"narrative":"권도하는 북문 순찰과 북부 호송의 시각·신호를 맞춘다. 돌격 규율은 강경하지만 전투 승리 근거는 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"안동 권씨","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":20,"개방":-15,"무력":5,"물질":40,"공동":30,"원칙":15,"공개":-5,"자격":70,"분산":20,"변혁":-25},"desire":{"갈망":35,"독점":15,"위험":10,"과시":30,"지속":30,"지향":"무성향","결합":"없음"},"fields":{"생업":"차륜 점검·무장 탑재 확인","소속":"Arc","품계":"일반 시민","직함":"강남역 궤도기병 반장","가치관":"권위 20 | 개방 −15 | 무력 5 | 물질 40 | 공동 30 | 원칙 15 | 공개 −5 | 자격 70 | 분산 20 | 변혁 −25","욕망":"갈망 35 | 독점 15 | 위험 10 | 과시 30 | 지속 30 | 지향 무성향 | 결합 없음"},"sections":{"생애":"대합실 당직에서 자랐다. 강남역 궤도기병 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권도하는 서초4동에서 차륜 점검·무장 탑재 확인 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다","관직":"품계 일반 시민. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화한다.","일화":"","관계":"","야망":"강남역 호송의 북쪽 구간과 순찰 일정을 묶어, 당직표에 따라 궤도기병의 차륜과 무장 탑재를 점검하고 출동 순서를 맞춘다.","공포":"","개입":""},"biography":"규율을 좋아하고 선로 위의 침묵을 전투의 일부로 본다. 숙련 없는 돌격은 배신에 가깝다고 말한다.\n\n- 생업: 차륜 점검·무장 탑재 확인\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: 강남역 궤도기병 반장\n**생애.** 대합실 당직에서 자랐다. 강남역 궤도기병 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권도하는 서초4동에서 차륜 점검·무장 탑재 확인 업무를 맡는다. 강남역 본사 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다\n\n**관직.** 품계 일반 시민. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화한다.\n\n**야망.** 강남역 호송의 북쪽 구간과 순찰 일정을 묶어, 당직표에 따라 궤도기병의 차륜과 무장 탑재를 점검하고 출동 순서를 맞춘다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 20 | 개방 −15 | 무력 5 | 물질 40 | 공동 30 | 원칙 15 | 공개 −5 | 자격 70 | 분산 20 | 변혁 −25\n- 욕망: 갈망 35 | 독점 15 | 위험 10 | 과시 30 | 지속 30 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"권도하","type":"계약","to":"장세화","basis":"북부 호송 시각을 맞춤"},{"from":"권도하","type":"계약","to":"강태산","basis":"회랑 신호를 공유"}],"incoming":[{"from":"용두봉","type":"계약","to":"권도하","basis":"권도하의 출격 목록을 정비창에서 받고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0277', 'd669-d68c-b355-9ec3', '{"id":"person-0277","name":"Hwang No-eul","title":"Scrap Iron Recovery Crew Foreman","position":"Arc Scrap Iron Recovery Crew Foreman","characterId":"K276","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Verifying Scrap Iron Recovery Weight · Shipments","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#Person-Hwang-Noeul","detailRoute":"/people/person-0277","birthDate":"2097-05-10","birthday":"05-10","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k276-recovered-inventory-management","name":"Recovered inventory management","rating":60}],"traits":[{"id":"k276-priority","name":"Scrap Iron Recovery Crew Foreman","description":"Title: Scrap Iron Recovery Crew Foreman.","behavior":"Title: Scrap Iron Recovery Crew Foreman.","stress":"","relationship":"","effects":[]},{"id":"k276-accountability","name":"Scrap Iron Recovery Crew Foreman","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Title: Scrap Iron Recovery Crew Foreman.","stress":"","relationship":"","effects":[]}],"narrative":"Title: Scrap Iron Recovery Crew Foreman.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d669-d68c-b355-9ec3","name":"Hoedeok Hwang Clan","crest":"clan-crests/d669-d68c-b355-9ec3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":-20,"Force":0,"Material":35,"Communal":25,"Principle":15,"Public":0,"Eligibility":70,"Dispersed":5,"Transformative":-20},"desire":{"Longing":0,"Monopoly":30,"Risk":15,"Display":10,"Sustained":-15,"Orientation":"Fluid","Union":"None"},"fields":{"Livelihood":"Verifying Scrap Iron Recovery Weight · Shipments","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Arc Scrap Iron Recovery Crew Foreman","Values":"Authority 10 | Openness −20 | Force 0 | Material 35 | Communal 25 | Principle 15 | Publicity 0 | Qualification 70 | Dispersion 5 | Reform −20","Desires":"Craving 0 | Monopoly 30 | Risk 15 | Display 10 | Persistence −15 | Orientation Fluid | Bonding None"},"sections":{"Life":"Grew up on waiting-hall duty. The post of Arc Scrap Iron Recovery Crew Foreman opened up through a substitute duty for an unexcused shift absence.\nHwang No-eul handles recovered scrap iron weight and shipment verification in Yeoksam 1-dong. He manages the samples, weight, lot numbers, measurements, work crews, and accident signatures for recovered iron within the Yeoksam 1-dong work-and-living area next to Gangnam Station. The Yeoksam waiting-hall cargo handover is only a reference and does not confirm any factory equipment or warehouse monopoly. He reports stock to I Hong-won and negotiates iron supply terms for machine-body parts with Sin Ga-on.","Offices":"Rank: Ordinary Citizen. Title: Arc Scrap Iron Recovery Crew Foreman. Puts recovered weights on the public scale.","Anecdote":"","Relationships":"","Ambition":"","Fear":"","Intervention":""},"biography":"Pragmatic, but harsh toward those who hide scrap metal. Believes that cheating on weight is the same as shaving down the rails.\n\n- Livelihood: Verifying Scrap Iron Recovery Weight · Shipments\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Arc Scrap Iron Recovery Crew Foreman\n**Life.** Grew up on waiting-hall duty. The post of Arc Scrap Iron Recovery Crew Foreman opened up through a substitute duty for an unexcused shift absence.\nHwang No-eul handles recovered scrap iron weight and shipment verification in Yeoksam 1-dong. He manages the samples, weight, lot numbers, measurements, work crews, and accident signatures for recovered iron within the Yeoksam 1-dong work-and-living area next to Gangnam Station. The Yeoksam waiting-hall cargo handover is only a reference and does not confirm any factory equipment or warehouse monopoly. He reports stock to I Hong-won and negotiates iron supply terms for machine-body parts with Sin Ga-on.\n\n**Office.** Rank: Ordinary Citizen. Title: Arc Scrap Iron Recovery Crew Foreman. Puts recovered weights on the public scale.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness −20 | Force 0 | Material 35 | Communal 25 | Principle 15 | Publicity 0 | Qualification 70 | Dispersion 5 | Reform −20\n- Desires: Craving 0 | Monopoly 30 | Risk 15 | Display 10 | Persistence −15 | Orientation Fluid | Bonding None\n:::","relations":{"outgoing":[{"from":"Hwang No-eul","type":"Command","to":"Yi Hong-won","basis":""},{"from":"Hwang No-eul","type":"Contract","to":"Alexander Miller","basis":"Trades wheel-supply terms with the Railway Division"}],"incoming":[{"from":"Moso","type":"Contract","to":"Hwang No-eul","basis":"Matching shipments to Hwang Noeul''s recovery scale"},{"from":"Bongguk","type":"Command","to":"Hwang No-eul","basis":"Guarding the scale under Hwang Noeul''s command"},{"from":"Sun Hajun","type":"Oath","to":"Hwang No-eul","basis":"Overlaying the agreed weight on Hwang Noeul''s recovery scale"}]}}', '{"id":"person-0277","name":"황노을","title":"철재 회수 작업반장","position":"Arc 철재 회수 작업반장","characterId":"K276","rank":"일반 시민","commonTier":"T5","occupation":"철재 회수 중량·출고 검증","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-황노을","detailRoute":"/people/person-0277","birthDate":"2097-05-10","birthday":"05-10","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k276-recovered-inventory-management","name":"회수 재고 관리","rating":60}],"traits":[{"id":"k276-priority","name":"철재 회수 작업반장","description":"직함은 철재 회수 작업반장.","behavior":"직함은 철재 회수 작업반장.","stress":"","relationship":"","effects":[]},{"id":"k276-accountability","name":"철재 회수 작업반장","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"직함은 철재 회수 작업반장.","stress":"","relationship":"","effects":[]}],"narrative":"직함은 철재 회수 작업반장.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d669-d68c-b355-9ec3","name":"회덕 황씨","crest":"clan-crests/d669-d68c-b355-9ec3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":-20,"무력":0,"물질":35,"공동":25,"원칙":15,"공개":0,"자격":70,"분산":5,"변혁":-20},"desire":{"갈망":0,"독점":30,"위험":15,"과시":10,"지속":-15,"지향":"유동","결합":"없음"},"fields":{"생업":"철재 회수 중량·출고 검증","소속":"Arc","품계":"일반 시민","직함":"Arc 철재 회수 작업반장","가치관":"권위 10 | 개방 −20 | 무력 0 | 물질 35 | 공동 25 | 원칙 15 | 공개 0 | 자격 70 | 분산 5 | 변혁 −20","욕망":"갈망 0 | 독점 30 | 위험 15 | 과시 10 | 지속 −15 | 지향 유동 | 결합 없음"},"sections":{"생애":"대합실 당직에서 자랐다. Arc 철재 회수 작업반장 자리는 교대 무단 결근의 대체 당직으로 열렸다.\n황노을은 역삼1동에서 철재 회수 중량·출고 검증 업무를 맡는다. 회수 철재의 표본·중량·묶음 번호·실측·작업 조·사고 서명을 강남역 인접 역삼1동 작업 생활권 안에서 관리한다. 역삼 대합실 화물 인계는 참고일 뿐 공장 설비나 창고 독점을 확정하지 않는다. 이홍원에게 재고를 보고하고 신가온과 기체 부품용 철재 공급 조건을 거래한다. ","관직":"품계 일반 시민. 직함은 Arc 철재 회수 작업반장. ","일화":"","관계":"","야망":"","공포":"","개입":""},"biography":"실리적이나 고철을 숨기는 사람을 가혹하게 다룬다. 무게를 속이는 일은 선로를 깎는 일과 같다고 본다.\n\n- 생업: 철재 회수 중량·출고 검증\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: Arc 철재 회수 작업반장\n**생애.** 대합실 당직에서 자랐다. Arc 철재 회수 작업반장 자리는 교대 무단 결근의 대체 당직으로 열렸다.\n황노을은 역삼1동에서 철재 회수 중량·출고 검증 업무를 맡는다. 회수 철재의 표본·중량·묶음 번호·실측·작업 조·사고 서명을 강남역 인접 역삼1동 작업 생활권 안에서 관리한다. 역삼 대합실 화물 인계는 참고일 뿐 공장 설비나 창고 독점을 확정하지 않는다. 이홍원에게 재고를 보고하고 신가온과 기체 부품용 철재 공급 조건을 거래한다. \n\n**관직.** 품계 일반 시민. 직함은 Arc 철재 회수 작업반장. \n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 −20 | 무력 0 | 물질 35 | 공동 25 | 원칙 15 | 공개 0 | 자격 70 | 분산 5 | 변혁 −20\n- 욕망: 갈망 0 | 독점 30 | 위험 15 | 과시 10 | 지속 −15 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"황노을","type":"지휘","to":"이홍원","basis":""},{"from":"황노을","type":"계약","to":"알렉산더 밀러","basis":"차륜 공급 조건을 철도 본부와 거래"}],"incoming":[{"from":"모소","type":"계약","to":"황노을","basis":"황노을의 회수 저울과 출고를 맞추고"},{"from":"봉국","type":"지휘","to":"황노을","basis":"황노을의 지휘로 저울을 지키고"},{"from":"순하준","type":"맹세","to":"황노을","basis":"황노을의 회수 저울에 협약 중량을 겹치고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0278', 'b450-b450-b989', '{"id":"person-0278","name":"Dumo","title":"Wheel Mechanic, Song Ha-yul''s Practical Aide","position":"Arc Wheel Mechanic, Song Ha-yul''s Practical Aide","characterId":"K277","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Wheel Maintenance Logs · Defective Parts Samples","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#inmul-dumo","detailRoute":"/people/person-0278","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k277-defect-sample-cutting","name":"Defect sample cutting","rating":55}],"traits":[{"id":"k277-priority","name":"Wheel Mechanic, Song Ha-yul''s Practical Aide","description":"Title: Wheel Mechanic, Song Ha-yul''s Practical Aide.","behavior":"Title: Wheel Mechanic, Song Ha-yul''s Practical Aide.","stress":"","relationship":"","effects":[]},{"id":"k277-accountability","name":"Wheel Mechanic, Song Ha-yul''s Practical Aide","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Title: Wheel Mechanic, Song Ha-yul''s Practical Aide.","stress":"","relationship":"","effects":[]}],"narrative":"Title: Wheel Mechanic, Song Ha-yul''s Practical Aide.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b450-b450-b989","name":"Dureung Du Clan","crest":"clan-crests/b450-b450-b989.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":-20,"Force":-20,"Material":30,"Communal":10,"Principle":10,"Public":0,"Eligibility":90,"Dispersed":0,"Transformative":-25},"desire":{"Longing":40,"Monopoly":-10,"Risk":-10,"Display":10,"Sustained":-15,"Orientation":"Same-Sex","Union":"Polyamorous"},"fields":{"Livelihood":"Wheel Maintenance Logs · Defective Parts Samples","Affiliation":"Arc","Rank":"Ordinary Citizen","Title":"Arc Wheel Mechanic, Song Ha-yul''s Practical Aide","Values":"Authority 10 | Openness −20 | Force −20 | Material 30 | Communal 10 | Principle 10 | Publicity 0 | Qualification 90 | Dispersion 0 | Reform −25","Desires":"Craving 40 | Monopoly −10 | Risk −10 | Display 10 | Persistence −15 | Orientation Same-sex | Bonding Multiple"},"sections":{"Life":"Grew up at the Gangnam Station rolling-stock depot. The post of Arc wheel mechanic and Song Ha-yul''s practical aide opened up through a defect report made just before a derailment.\nDumo handles wheel maintenance logs and defective-part sample management in Yeoksam 1-dong. Records samples, weights, measurements, work crews, and accident signatures, operating within the work-and-living area of Yeoksam 1-dong next to Gangnam Station. Since the Arc has no factory, parts are kept as samples of worn and broken components pulled from machine bodies. Takes over Song Ha-yul''s apprentice routine on site and is rotated into Jo U-chan''s work crew. ","Offices":"Rank: Ordinary Citizen. Title: Arc Wheel Mechanic, Song Ha-yul''s Practical Aide.","Anecdote":"","Relationships":"","Ambition":"","Fear":"","Intervention":""},"biography":"Quick-handed and sparing with words, regards snatching other people''s tools as the same offense as cheating on the test. Cannot stand a crew chief who passes along defective samples without cutting them.\n\n- Livelihood: Wheel Maintenance Logs · Defective Parts Samples\n- Affiliation: Arc\n- Rank: Ordinary Citizen\n- Title: Arc Wheel Mechanic, Song Ha-yul''s Practical Aide\n**Life.** Grew up at the Gangnam Station rolling-stock depot. The post of Arc wheel mechanic and Song Ha-yul''s practical aide opened up through a defect report made just before a derailment.\nDumo handles wheel maintenance logs and defective-part sample management in Yeoksam 1-dong. Records samples, weights, measurements, work crews, and accident signatures, operating within the work-and-living area of Yeoksam 1-dong next to Gangnam Station. Since the Arc has no factory, parts are kept as samples of worn and broken components pulled from machine bodies. Takes over Song Ha-yul''s apprentice routine on site and is rotated into Jo U-chan''s work crew. \n\n**Office.** Rank: Ordinary Citizen. Title: Arc Wheel Mechanic, Song Ha-yul''s Practical Aide.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness −20 | Force −20 | Material 30 | Communal 10 | Principle 10 | Publicity 0 | Qualification 90 | Dispersion 0 | Reform −25\n- Desires: Craving 40 | Monopoly −10 | Risk −10 | Display 10 | Persistence −15 | Orientation Same-sex | Bonding Multiple\n:::","relations":{"outgoing":[{"from":"Dumo","type":"Master and Disciple","to":"Song Ha-yul","basis":"Receives Song Hayul''s apprentice daily work on site"},{"from":"Dumo","type":"Contract","to":"Jo U-chan","basis":"Is assigned by rotation to Jo Uchan''s work crew"}],"incoming":[{"from":"Gukdu","type":"Contract","to":"Dumo","basis":"Attach Dumo''s maintenance sample number to the ledger"},{"from":"Yongdubong","type":"Contract","to":"Dumo","basis":"Use Dumo''s wheel sample in the cavalry car"},{"from":"Eo Yerin","type":"Oath","to":"Dumo","basis":""}]}}', '{"id":"person-0278","name":"두모","title":"차륜 정비사, 송하율의 실무 담당자","position":"Arc 차륜 정비사, 송하율의 실무 담당자","characterId":"K277","rank":"일반 시민","commonTier":"T5","occupation":"차륜 정비 일지·불량 부품 표본 관리","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-두모","detailRoute":"/people/person-0278","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k277-defect-sample-cutting","name":"불량 표본 절단","rating":55}],"traits":[{"id":"k277-priority","name":"차륜 정비사, 송하율의 실무 담당자","description":"직함은 차륜 정비사, 송하율의 실무 담당자.","behavior":"직함은 차륜 정비사, 송하율의 실무 담당자.","stress":"","relationship":"","effects":[]},{"id":"k277-accountability","name":"차륜 정비사, 송하율의 실무 담당자","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"직함은 차륜 정비사, 송하율의 실무 담당자.","stress":"","relationship":"","effects":[]}],"narrative":"직함은 차륜 정비사, 송하율의 실무 담당자.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b450-b450-b989","name":"두릉 두씨","crest":"clan-crests/b450-b450-b989.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":-20,"무력":-20,"물질":30,"공동":10,"원칙":10,"공개":0,"자격":90,"분산":0,"변혁":-25},"desire":{"갈망":40,"독점":-10,"위험":-10,"과시":10,"지속":-15,"지향":"동성","결합":"다자"},"fields":{"생업":"차륜 정비 일지·불량 부품 표본 관리","소속":"Arc","품계":"일반 시민","직함":"Arc 차륜 정비사, 송하율의 실무 담당자","가치관":"권위 10 | 개방 −20 | 무력 −20 | 물질 30 | 공동 10 | 원칙 10 | 공개 0 | 자격 90 | 분산 0 | 변혁 −25","욕망":"갈망 40 | 독점 −10 | 위험 −10 | 과시 10 | 지속 −15 | 지향 동성 | 결합 다자"},"sections":{"생애":"강남역 차량기지에서 자랐다. Arc 차륜 정비사, 송하율의 실무 담당자 자리는 탈선 직전 결함 보고로 열렸다.\n두모는 역삼1동에서 차륜 정비 일지·불량 부품 표본 관리 업무를 맡는다. 표본·중량·실측·작업 조·사고 서명을 기록하며 강남역 인접 역삼1동 작업 생활권에서 움직인다. Arc에는 공장이 없어 부품은 기계 몸체에서 떼어낸 마모품과 고장품 표본으로 보관한다. 송하율의 도제 일과를 현장에서 받고 조우찬의 작업 조에 순환 배치된다. ","관직":"품계 일반 시민. 직함은 Arc 차륜 정비사, 송하율의 실무 담당자. ","일화":"","관계":"","야망":"","공포":"","개입":""},"biography":"손이 빠르고 말이 적으며, 남의 공구를 빼돌리는 일을 시험 부정과 같은 죄로 본다. 결함 표본을 자르지 않고 넘기는 반장을 참지 못한다.\n\n- 생업: 차륜 정비 일지·불량 부품 표본 관리\n- 소속: Arc\n- 품계: 일반 시민\n- 직함: Arc 차륜 정비사, 송하율의 실무 담당자\n**생애.** 강남역 차량기지에서 자랐다. Arc 차륜 정비사, 송하율의 실무 담당자 자리는 탈선 직전 결함 보고로 열렸다.\n두모는 역삼1동에서 차륜 정비 일지·불량 부품 표본 관리 업무를 맡는다. 표본·중량·실측·작업 조·사고 서명을 기록하며 강남역 인접 역삼1동 작업 생활권에서 움직인다. Arc에는 공장이 없어 부품은 기계 몸체에서 떼어낸 마모품과 고장품 표본으로 보관한다. 송하율의 도제 일과를 현장에서 받고 조우찬의 작업 조에 순환 배치된다. \n\n**관직.** 품계 일반 시민. 직함은 Arc 차륜 정비사, 송하율의 실무 담당자. \n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 −20 | 무력 −20 | 물질 30 | 공동 10 | 원칙 10 | 공개 0 | 자격 90 | 분산 0 | 변혁 −25\n- 욕망: 갈망 40 | 독점 −10 | 위험 −10 | 과시 10 | 지속 −15 | 지향 동성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"두모","type":"스승과 제자","to":"송하율","basis":"송하율의 도제 일과를 현장에서 받고"},{"from":"두모","type":"계약","to":"조우찬","basis":"조우찬의 작업 조에 순환 배치된다"}],"incoming":[{"from":"국두","type":"계약","to":"두모","basis":"두모의 정비 표본 번호를 원장에 붙인다"},{"from":"용두봉","type":"계약","to":"두모","basis":"두모의 차륜 표본을 기병 칸에 쓴다"},{"from":"어예린","type":"맹세","to":"두모","basis":""}]}}');
