INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0286', 'b450-b450-b989', '{"id":"person-0286","name":"Duguk","title":"Seoul Station Northern Gate Escort Outpost Chief","position":"Seoul Station Northern Gate Escort Outpost Chief","characterId":"K285","rank":"Stationmaster","commonTier":"T3","occupation":"Northern Gate Escort Personnel, Wheel Inspection Sheet Posting","gender":"Female","stage":"S2","state":"geography:duchy:11350","stateName":"Nowon-gu","sourceRoute":"/world/Cast-State-11#Person-Duguk","detailRoute":"/people/person-0286","birthDate":"2078-01-13","birthday":"01-13","age":48,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k285-escort-connection-coordination","name":"Escort connection coordination","rating":55}],"traits":[{"id":"k285-priority","name":"Rejects toll demands","description":"Duguk coordinates patrol shifts and light escort connections. She firmly rejects toll demands, while the missing slot’s actual cargo remains unknown.","behavior":"Office. Rank: Stationmaster. Title: Seoul Station Northern Gate Escort Outpost Chief. She pasted the convoy personnel and the wheel check table on one chalkboard.","stress":"","relationship":"Relations. Received Gwon Doha''s north gate patrol at the outpost and split the rotations and torches with Yong Mo. Matched the link hours with Ha Seon''s light convoys.","effects":[]},{"id":"k285-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Stationmaster. Title: Seoul S