INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0396', 'cd08-c131-c8fc', '{"id":"person-0396","name":"Cho Siram","title":"Party to the Merit Reward Auction","position":"Myeongdong Station Witness","characterId":"K395","rank":"Clerk","commonTier":"T4","occupation":"Testimony · Assistant","gender":"Female","stage":"S3","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-15#Character-Chosiram","detailRoute":"/people/person-0396","birthDate":"2086-12-13","birthday":"12-13","age":40,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"public-objection","name":"Public objection","rating":45}],"traits":[{"id":"evidenced-choice","name":"Objects to being treated as a lot","description":"After a number is left without an opening price, challenges adjusted bids and asks that certificates not be treated as goods numbers. The award outcome is unknown.","behavior":"Shown in the confirmed choice: Objects to being treated as a lot. It is not established as an invariable disposition in other situations.","stress":"May challenge bids and labels when reduced to a number.","relationship":"Challenges Eun Taeho’s bids and seeks restoration of Yun Seorin’s blank entry.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"Title: Party to the Merit Reward Auction.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"","relationship":"Challenges Eun Taeho’s bids and seeks restoration of Yun Seorin’s blank entry.","effects":[]}],"narrative":"After a number is left without an ope