INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0399', 'c815-c9c4-c8fc-912d', '{"id":"person-0399","name":"Jeong Yura","title":"Cardinal (provisional)","position":"Arc Contract Auditor","characterId":"K398","rank":"Cardinal (provisional)","commonTier":"T1","occupation":"Contract Auditor","gender":"Female","stage":"Key","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#Character-Jeong-Yura","detailRoute":"/people/person-0399","birthDate":"2090-01-26","birthday":"01-26","age":36,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K422","recipientName":"No Seram","basis":"No Seram''s existing relationship record is as follows. She aligns with Jeong Yura''s audit direction, but keeps the archive key separate.","sourceRef":{"path":"lore/characters/Cast-State-16.json","anchor":"Character-No-Seram-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":15,"effective":15},"martial":{"base":12,"effective":12},"stewardship":{"base":13,"effective":13},"intrigue":{"base":14,"effective":14},"learning":{"base":14,"effective":14},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k398-exit-audit","name":"Exit-clause auditing","rating":75}],"traits":[{"id":"k398-trait-1","name":"Exit conditions first","description":"Secures exit terms and audit rights first.","behavior":"Secures exit terms and audit rights first.","stress":"","relationship":"Carries agreements through Jang Sehwa’s escort and disputes ratification with Yun Seorin.","effects":[]}],"narrative":"Title: Cardinal (provisional).","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s16","name":{"ko":"Suseo Station Directly Managed Land"},"holderPersonId":"K398","directLiegePersonId":null,"stateId":"S16","stationRef":{"stationId":"Suseo","stationName":"Suseo"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c815-c9c4-c8fc-912d","name":"Jinju Jeong Clan","crest":"clan-crests/c815-c9c4-c8fc-912d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"Authority":-40,"Openness":30,"Force":-40,"Material":0,"Communal":10,"Principle":30,"Public":40,"Eligibility":30,"Dispersed":50,"Transformative":-10},"desire":{"Longing":20,"Monopoly":-20,"Risk":-10,"Display":-20,"Sustained":30,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Contract Auditor","Affiliation":"Arc","Community Role":"Contract Auditor","Duty":"Arc Contract Auditor"},"sections":{"Life":"Born on 2090-01-26, Jeong Yura serves as Arc Contract Auditor at the Suseo Station union workshop in the winter. She checks the members'' direct election and public vote records, and distinguishes government offices conferred by the Republic of Korea from community duties.\n- Jeong Yura serves as Arc Contract Auditor at the Suseo Station union workshop in Suseo-dong. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.\n- Jeong Yura serves as Arc Contract Auditor at the Suseo Station work reference point in Suseo-dong.\n\nThey are the members who handle contracts, audits, and mediation for the Suseo Station headquarters and the union workshop. The contract auditor checks the members’ voting records, and voting conflicts between factions spill over into daily work as well."},"biography":"In the winter at Suseo, Jeong Yura first cross-checks the machine-body repair records against the patrol shift signatures. On days when fuel, food and patrol schedules overlap, she records the time of receipt and the order of handover in the same ledger.\n\n- Livelihood: Contract Auditor\n- Affiliation: Arc\n- Community Role: Contract Auditor\n- Duty: Arc Contract Auditor\n**Life.** Born on 2090-01-26, Jeong Yura serves as Arc Contract Auditor at the Suseo Station union workshop in the winter. She checks the members'' direct election and public vote records, and distinguishes government offices conferred by the Republic of Korea from community duties.\n- Jeong Yura serves as Arc Contract Auditor at the Suseo Station union workshop in Suseo-dong. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.\n- Jeong Yura serves as Arc Contract Auditor at the Suseo Station work reference point in Suseo-dong.\n\nThey are the members who handle contracts, audits, and mediation for the Suseo Station headquarters and the union workshop. The contract auditor checks the members’ voting records, and voting conflicts between factions spill over into daily work as well.","relations":{"outgoing":[],"incoming":[{"from":"Jeong Seoon","type":"Kinship","to":"Jeong Yura","basis":"Distant relative of the Jeong branch family"},{"from":"Im Gyeore","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Ha Yunmok","type":"Contract","to":"Jeong Yura","basis":"seeks to build the loss-compensation clause into the gate tax rate"},{"from":"Ha Seojin","type":"Command","to":"Jeong Yura","basis":"Fair-copies the standard text as contract clerk"},{"from":"Gwak Eunjae","type":"Command","to":"Jeong Yura","basis":"Enforces audit rights in practice"},{"from":"Sim Yuri","type":"Command","to":"Jeong Yura","basis":"Chairs the pharmacy meeting"},{"from":"Jang Pil-gyu","type":"Rivalry","to":"Jeong Yura","basis":""},{"from":"Jang Useok","type":"Contract","to":"Jeong Yura","basis":"Consults the termination-condition sentences in the audit ledger"},{"from":"Choe Eunjae","type":"Contract","to":"Jeong Yura","basis":"Draws the technology-sharing wording into the certification clauses"},{"from":"Gang Ye-jun","type":"Rivalry","to":"Jeong Yura","basis":""},{"from":"Cheon Neuru","type":"Contract","to":"Jeong Yura","basis":"Preserves Jeong Yura''s standard form as the original title"},{"from":"Cheon Neulsaem","type":"Contract","to":"Jeong Yura","basis":"Obeys Jeong Yura''s cross-verification but refuses concealed distribution"},{"from":"Seop Do-yun","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Elena Morozova","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Chu Bo-ram","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Dan Yu-jin","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Cho Tae-on","type":"Oath","to":"Jeong Yura","basis":""},{"from":"Chang Goun","type":"Contract","to":"Jeong Yura","basis":""},{"from":"Geun Juha","type":"Contract","to":"Jeong Yura","basis":""}]}}', '{"id":"person-0399","name":"정유라","title":"추기경(잠정)","position":"Arc 계약 감사관","characterId":"K398","rank":"추기경(잠정)","commonTier":"T1","occupation":"계약감사관","gender":"여성","stage":"주요","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#인물-정유라","detailRoute":"/people/person-0399","birthDate":"2090-01-26","birthday":"01-26","age":36,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K422","recipientName":"노세람","basis":"노세람의 기존 관계 기록은 다음과 같다. 정유라의 감사 방향과 맞되, 서고 열쇠는 따로 둔다.","sourceRef":{"path":"lore/characters/Cast-State-16.json","anchor":"인물-노세람-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":15,"effective":15},"martial":{"base":12,"effective":12},"stewardship":{"base":13,"effective":13},"intrigue":{"base":14,"effective":14},"learning":{"base":14,"effective":14},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k398-exit-audit","name":"종료조건 감사","rating":75}],"traits":[{"id":"k398-trait-1","name":"나갈 조건부터","description":"계약의 종료조건과 감사권을 먼저 확보한다.","behavior":"계약의 종료조건과 감사권을 먼저 확보한다.","stress":"","relationship":"장세화의 호송에 협의를 싣고 윤서린과 인준을 다툰다.","effects":[]}],"narrative":"직함은 추기경(잠정).","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s16","name":{"ko":"수서역 직영지"},"holderPersonId":"K398","directLiegePersonId":null,"stateId":"S16","stationRef":{"stationId":"수서","stationName":"수서"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c815-c9c4-c8fc-912d","name":"진주 정씨","crest":"clan-crests/c815-c9c4-c8fc-912d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"권위":-40,"개방":30,"무력":-40,"물질":0,"공동":10,"원칙":30,"공개":40,"자격":30,"분산":50,"변혁":-10},"desire":{"갈망":20,"독점":-20,"위험":-10,"과시":-20,"지속":30,"지향":"유동","결합":"비독점"},"fields":{"생업":"계약감사관","소속":"Arc","공동체 역할":"계약 감사관","직무":"Arc 계약 감사관"},"sections":{"생애":"2090-01-26에 태어난 정유라는 겨울의 수서역 조합 작업장에서 Arc 계약 감사관 업무를 맡는다. 조합원 공개 표결 기록과 계약 문서를 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 정유라는 수서동의 수서역 조합 작업장에서 Arc 계약 감사관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.\n- 정유라는 수서동의 수서역 업무 기준점에서 Arc 계약 감사관 업무를 맡는다.\n\n수서역 본부와 조합 작업장의 계약·감사·중재를 맡는 조합원들이다. 계약 감사관은 조합원 표결 기록을 확인하고, 파벌 간 표결 갈등이 일상 업무에도 번진다."},"biography":"정유라는 겨울의 수서에서 기계 몸 정비 기록과 순찰 교대 서명을 먼저 대조한다. 연료·식량·순찰 일정이 겹치는 날에는 접수 시각과 인계 순서를 같은 장부에 남긴다.\n\n- 생업: 계약감사관\n- 소속: Arc\n- 공동체 역할: 계약 감사관\n- 직무: Arc 계약 감사관\n**생애.** 2090-01-26에 태어난 정유라는 겨울의 수서역 조합 작업장에서 Arc 계약 감사관 업무를 맡는다. 조합원 공개 표결 기록과 계약 문서를 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 정유라는 수서동의 수서역 조합 작업장에서 Arc 계약 감사관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.\n- 정유라는 수서동의 수서역 업무 기준점에서 Arc 계약 감사관 업무를 맡는다.\n\n수서역 본부와 조합 작업장의 계약·감사·중재를 맡는 조합원들이다. 계약 감사관은 조합원 표결 기록을 확인하고, 파벌 간 표결 갈등이 일상 업무에도 번진다.","relations":{"outgoing":[],"incoming":[{"from":"정서온","type":"친족","to":"정유라","basis":"정씨 분가의 먼 친척"},{"from":"임겨레","type":"계약","to":"정유라","basis":""},{"from":"하윤목","type":"계약","to":"정유라","basis":"손실보상 조항을 관문 세율에 넣으려 함"},{"from":"하서진","type":"지휘","to":"정유라","basis":"표준 문장을 계약 서기로 정서"},{"from":"곽은재","type":"지휘","to":"정유라","basis":"감사권을 실무로 집행"},{"from":"심유리","type":"지휘","to":"정유라","basis":"약국 회의를 사회"},{"from":"장필규","type":"경쟁","to":"정유라","basis":""},{"from":"장우석","type":"계약","to":"정유라","basis":"종료 조건 문장을 감사 원장에 참고"},{"from":"최은재","type":"계약","to":"정유라","basis":"기술공유 문장을 인증 조항에 끌어들임"},{"from":"강예준","type":"경쟁","to":"정유라","basis":""},{"from":"천늘우","type":"계약","to":"정유라","basis":"정유라의 표준 서식을 원판 제목으로 남긴다"},{"from":"천늘샘","type":"계약","to":"정유라","basis":"정유라의 교차검증에는 복종하되 은폐 배전은 거부한다"},{"from":"섭도윤","type":"계약","to":"정유라","basis":""},{"from":"엘레나 모로조바","type":"계약","to":"정유라","basis":""},{"from":"추보람","type":"계약","to":"정유라","basis":""},{"from":"단유진","type":"계약","to":"정유라","basis":""},{"from":"초태온","type":"맹세","to":"정유라","basis":""},{"from":"창고운","type":"계약","to":"정유라","basis":""},{"from":"근주하","type":"계약","to":"정유라","basis":""}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0400', 'd558-c9c4-c8fc', '{"id":"person-0400","name":"Ha Seojin","title":"Contract Clerk","position":"Contract Clerk","characterId":"K399","rank":"Guild Member","commonTier":"T5","occupation":"Draft End Date · Audit Clause Entry · Exemption Field Check","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#Character-Ha-Seojin","detailRoute":"/people/person-0400","birthDate":"2072-08-13","birthday":"08-13","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"treaty-drafting","name":"Draft transcription","rating":65}],"traits":[{"id":"evidenced-choice","name":"Checks wording thoroughly","description":"Writes expiry and audit clauses first and transcribes standard terms. Seals counterfeit medicine boxes instead of burning them.","behavior":"Shown in the confirmed choice: Checks wording thoroughly. It is not established as an invariable disposition in other situations.","stress":"May delay decisions over unresolved wording.","relationship":"Connects Jeong Yura’s standards to Jang Sehwa’s escort clauses.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"Seeks continuity of the specific records entrusted to this person, rather than new authority.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"Loss of the assigned records or a blocked handover may heighten concern about accountability.","relationship":"Connects Jeong Yura’s standards to Jang Sehwa’s escort clauses.","effects":[]}],"narrative":"Writes expiry and audit clauses first and transcribes standard terms. Seals counterfeit medicine boxes instead of burning them.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d558-c9c4-c8fc","name":"Jinju Ha Clan","crest":"clan-crests/d558-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-40,"Openness":35,"Force":-25,"Material":-5,"Communal":5,"Principle":30,"Public":25,"Eligibility":15,"Dispersed":50,"Transformative":15},"desire":{"Longing":45,"Monopoly":15,"Risk":30,"Display":20,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Draft End Date · Audit Clause Entry · Exemption Field Check","Affiliation":"Arc","Community Role":"Guild Member","Duty":"Contract Clerk","Values":"Authority −40 | Openness 35 | Force −25 | Material −5 | Communal 5 | Principle 30 | Publicity 25 | Qualification 15 | Decentralization 50 | Transformation 15","Desires":"Craving 45 | Monopoly 15 | Risk 30 | Display 20 | Persistence 40 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Ha Seojin, born on 2072-08-13, handles contract clerk duties at the Suseo Station union workshop in the winter. Checking direct union member elections and public vote records, Ha Seojin distinguishes offices conferred by the government of the Republic of Korea from community duties.\n- Ha Seojin handles contract clerk duties at the Suseo Station union workshop in Suseo-dong. This work reference point does not establish residence, exact facility boundaries, rank, a holding, or possession rights.","Duty":"The community role is guild member, and the duty is food ledger clerk. This duty is an internal function of the Arc and is neither a Republic of Korea government civil service office nor a rank.","Anecdote":"In 2125, Ha Seojin collected fake medicine boxes at the auction house and sealed them instead of burning them. The measures taken that day and the testimony remain in the same work ledger.","Relationships":"Ha Seojin''s existing relationship record is as follows: Ha Seojin writes out Jeong Yura''s standard sentences in fair copy, inserts Jang Sehwa''s escort clause into the draft, and owes a debt for having demanded Ha Yunmok''s gate ledger as an attached document.","Goals":"Ha Seojin intends to keep the signing, handover, and disclosure procedures of the contract clerk work verifiable in the Suseo Station union ledger.","Fear":"That the signature or handover records of the contract clerk work are altered, so that Ha Seojin''s scope of responsibility and the union members'' disclosure procedure collapse together.","Intervention":"Ha Seojin can cross-check the relevant signatures and handover times and can make the records public, but cannot grant new offices, ranks, rights, or holdings."},"biography":"At the Nonhyeon 2-dong workshop in the winter, Ha Seojin first cross-checks the food clerk''s work records against the shift signatures. On days when fuel, food and patrol schedules overlap, Ha Seojin records the receipt time and handover order in the same ledger.\n\n- Livelihood: Draft End Date · Audit Clause Entry · Exemption Field Check\n- Affiliation: Arc\n- Community Role: Guild Member\n- Duty: Contract Clerk\n**Life.** Ha Seojin, born on 2072-08-13, handles contract clerk duties at the Suseo Station union workshop in the winter. Checking direct union member elections and public vote records, Ha Seojin distinguishes offices conferred by the government of the Republic of Korea from community duties.\n- Ha Seojin handles contract clerk duties at the Suseo Station union workshop in Suseo-dong. This work reference point does not establish residence, exact facility boundaries, rank, a holding, or possession rights.\n\n**Duty.** The community role is guild member, and the duty is food ledger clerk. This duty is an internal function of the Arc and is neither a Republic of Korea government civil service office nor a rank.\n\n**Anecdote.** In 2125, Ha Seojin collected fake medicine boxes at the auction house and sealed them instead of burning them. The measures taken that day and the testimony remain in the same work ledger.\n\n**Relationships.** Ha Seojin''s existing relationship record is as follows: Ha Seojin writes out Jeong Yura''s standard sentences in fair copy, inserts Jang Sehwa''s escort clause into the draft, and owes a debt for having demanded Ha Yunmok''s gate ledger as an attached document.\n\n**Goal.** Ha Seojin intends to keep the signing, handover, and disclosure procedures of the contract clerk work verifiable in the Suseo Station union ledger.\n\n**Fear.** That the signature or handover records of the contract clerk work are altered, so that Ha Seojin''s scope of responsibility and the union members'' disclosure procedure collapse together.\n\n**Intervention.** Ha Seojin can cross-check the relevant signatures and handover times and can make the records public, but cannot grant new offices, ranks, rights, or holdings.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −40 | Openness 35 | Force −25 | Material −5 | Communal 5 | Principle 30 | Publicity 25 | Qualification 15 | Decentralization 50 | Transformation 15\n- Desires: Craving 45 | Monopoly 15 | Risk 30 | Display 20 | Persistence 40 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Ha Seojin","type":"Command","to":"Jeong Yura","basis":"Fair-copies the standard text as contract clerk"}],"incoming":[{"from":"An Taegyeong","type":"Contract","to":"Ha Seojin","basis":"Aligns dual-council practice with the contract clerk"},{"from":"Seon Chobyeol","type":"Command","to":"Ha Seojin","basis":"A contract that enforces Ha Seojin''s standard sentences through copy transport, and"},{"from":"Yeong Maon","type":"Command","to":"Ha Seojin","basis":"enforces Ha Seojin''s draft escort on the road, and"},{"from":"Seon Hansom","type":"Contract","to":"Ha Seojin","basis":"guards Ha Seojin''s draft box underground, and"},{"from":"Mae Dohan","type":"Contract","to":"Ha Seojin","basis":"opens Ha Seojin''s draft box in the capacity of a party concerned, and"}]}}', '{"id":"person-0400","name":"하서진","title":"계약 서기","position":"계약 서기","characterId":"K399","rank":"조합원","commonTier":"T5","occupation":"초안 종료일·감사 조항 기재·면제 칸 확인","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#인물-하서진","detailRoute":"/people/person-0400","birthDate":"2072-08-13","birthday":"08-13","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"treaty-drafting","name":"문안 정서","rating":65}],"traits":[{"id":"evidenced-choice","name":"문구를 끝까지 확인","description":"종료일과 감사 조항부터 쓰고 표준 문장을 정서한다. 가짜 약 상자를 불태우지 않고 봉인했다.","behavior":"확인된 선택: 문구를 끝까지 확인. 다른 상황까지 불변 성향으로 확정하지 않는다.","stress":"불명확한 문구를 끝내지 못하면 결정을 늦출 수 있다.","relationship":"정유라의 표준문과 장세화의 호송 조항을 연결한다.","effects":[]},{"id":"handover-continuity","name":"기록 단절 경계","description":"새 권한이 아니라 맡은 기록의 연속성을 지키려 한다.","behavior":"맡은 기록과 서명의 연결을 확인하려 한다.","stress":"맡은 기록을 잃거나 인계가 막히면 책임에 대한 우려가 커질 수 있다.","relationship":"정유라의 표준문과 장세화의 호송 조항을 연결한다.","effects":[]}],"narrative":"종료일과 감사 조항부터 쓰고 표준 문장을 정서한다. 가짜 약 상자를 불태우지 않고 봉인했다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d558-c9c4-c8fc","name":"진주 하씨","crest":"clan-crests/d558-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-40,"개방":35,"무력":-25,"물질":-5,"공동":5,"원칙":30,"공개":25,"자격":15,"분산":50,"변혁":15},"desire":{"갈망":45,"독점":15,"위험":30,"과시":20,"지속":40,"지향":"유동","결합":"비독점"},"fields":{"생업":"초안 종료일·감사 조항 기재·면제 칸 확인","소속":"Arc","공동체 역할":"조합원","직무":"계약 서기","가치관":"권위 −40 | 개방 35 | 무력 −25 | 물질 −5 | 공동 5 | 원칙 30 | 공개 25 | 자격 15 | 분산 50 | 변혁 15","욕망":"갈망 45 | 독점 15 | 위험 30 | 과시 20 | 지속 40 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2072-08-13에 태어난 하서진은 겨울의 수서역 조합 작업장에서 계약 서기 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 하서진은 수서동의 수서역 조합 작업장에서 계약 서기 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.","직무":"공동체 역할은 조합원이며 직무는 식량 출납 서기이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 품계가 아니다.","일화":"2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 조치와 증언은 같은 업무 장부에 남아 있다.","관계":"하서진의 기존 관계 기록은 다음과 같다. 정유라의 표준 문장을 정서하고, 장세화의 호송 조항을 초안에 넣으며, 하윤목의 관문 원장을 부속 문서로 요구해 온 빚이 있다.","목표":"하서진은 계약 서기 업무의 서명·인계·공개 절차를 수서역 조합 장부에서 검증 가능하게 유지하려 한다.","공포":"계약 서기 업무의 서명이나 인계 기록이 바뀌어 하서진의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.","개입":"하서진은 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다."},"biography":"하서진은 겨울의 논현2동 작업장에서 식량 출납 서기 업무 기록과 교대 서명을 먼저 대조한다. 연료·식량·순찰 일정이 겹치는 날에는 접수 시각과 인계 순서를 같은 장부에 남긴다.\n\n- 생업: 초안 종료일·감사 조항 기재·면제 칸 확인\n- 소속: Arc\n- 공동체 역할: 조합원\n- 직무: 계약 서기\n**생애.** 2072-08-13에 태어난 하서진은 겨울의 수서역 조합 작업장에서 계약 서기 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 하서진은 수서동의 수서역 조합 작업장에서 계약 서기 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.\n\n**직무.** 공동체 역할은 조합원이며 직무는 식량 출납 서기이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 품계가 아니다.\n\n**일화.** 2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 조치와 증언은 같은 업무 장부에 남아 있다.\n\n**관계.** 하서진의 기존 관계 기록은 다음과 같다. 정유라의 표준 문장을 정서하고, 장세화의 호송 조항을 초안에 넣으며, 하윤목의 관문 원장을 부속 문서로 요구해 온 빚이 있다.\n\n**목표.** 하서진은 계약 서기 업무의 서명·인계·공개 절차를 수서역 조합 장부에서 검증 가능하게 유지하려 한다.\n\n**공포.** 계약 서기 업무의 서명이나 인계 기록이 바뀌어 하서진의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.\n\n**개입.** 하서진은 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −40 | 개방 35 | 무력 −25 | 물질 −5 | 공동 5 | 원칙 30 | 공개 25 | 자격 15 | 분산 50 | 변혁 15\n- 욕망: 갈망 45 | 독점 15 | 위험 30 | 과시 20 | 지속 40 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"하서진","type":"지휘","to":"정유라","basis":"표준 문장을 계약 서기로 정서"}],"incoming":[{"from":"안태경","type":"계약","to":"하서진","basis":"이중 의회 실무를 계약 서기와 맞춤"},{"from":"선초별","type":"지휘","to":"하서진","basis":"하서진의 표준 문장을 사본 운송으로 집행하는 계약이고"},{"from":"영마온","type":"지휘","to":"하서진","basis":"하서진의 초안 호송을 길에서 집행하고"},{"from":"선한솜","type":"계약","to":"하서진","basis":"하서진의 초안함을 지하에서 지키고"},{"from":"매도한","type":"계약","to":"하서진","basis":"하서진의 초안함을 관계자 자격으로 열고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0401', 'acfd-d604-d48d', '{"id":"person-0401","name":"Gwak Eunjae","title":"Audit Assistant","position":"Audit Assistant","characterId":"K400","rank":"Guild Member","commonTier":"T5","occupation":"Tunnel Patrol Delay Records","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#person-gwak-eunjae","detailRoute":"/people/person-0401","birthDate":"2099-12-11","birthday":"12-11","age":27,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":12,"effective":12},"intrigue":{"base":12,"effective":12},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"implementation-audit","name":"Contract implementation audit","rating":65}],"traits":[{"id":"evidenced-choice","name":"Distrusts oral promises","description":"Records blackouts and escort delays in one audit and refuses closure before public review. Burns copies and preserves originals in a forged-stamp incident.","behavior":"Shown in the confirmed choice: Distrusts oral promises. It is not established as an invariable disposition in other situations.","stress":"May delay closure over gaps and private meetings.","relationship":"Checks Jeong Hojun’s performance and uses Ra Jinwoo’s ledger to estimate losses.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"Title: Audit Assistant.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"","relationship":"Checks Jeong Hojun’s performance and uses Ra Jinwoo’s ledger to estimate losses.","effects":[]}],"narrative":"Records blackouts and escort delays in one audit and refuses closure before public review. Bur