INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0441', 'b958-bb38-d654-67f3', '{"id":"person-0441","name":"Ryu Donghyeon","title":"Power Device Patrol","position":"Power Device Patrol","characterId":"K441","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Guard & Patrol","gender":"Female","stage":"S4","state":"geography:duchy:11590","stateName":"Dongjak-gu","sourceRoute":"/world/Cast-State-02#person-ryu-donghyeon","detailRoute":"/people/person-0441","birthDate":"2083-12-17","birthday":"12-17","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":8,"effective":8},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k441-training-report-review","name":"Training-report review","rating":45}],"traits":[{"id":"k441-action-priority","name":"Reopen a wrong report","description":"In 2125, when the first report of a bridge-raid exercise proved wrong, she reopened the observation column. By this deed the signature of the power installation patrol post rose into the ledger.","behavior":"In 2125, when the first report of a bridge-raid exercise proved wrong, she reopened the observation column. By this deed the signature of the power installation patrol post rose into the ledger.","stress":"That if the hand-generator patrol duty post stands empty, light and heat discipline slips and outside machines come into the alleys.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k441-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift witho