INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0450', 'c720-ac15-b989', '{"id":"person-0450","name":"Yu Hayeong","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0450","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0450","name":"유하영","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0450","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0451', 'b0a8-c758-b839', '{"id":"person-0451","name":"Nam Sieun","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0451","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0451","name":"남시은","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0451","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0452', 'c2ec-ccad-c1a1', '{"id":"person-0452","name":"Sim Dahyeon","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K452","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-sim-dahyeon","detailRoute":"/people/person-0452","birthDate":"2102-05-12","birthday":"05-12","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"Document transcription","rating":45}],"traits":[{"id":"stated-priority","name":"Preserves even wet records","description":"They dried and transcribed a wet authorization paper. Preservation is clearer evidence than the sanitation title; broad sanitation practice is unconfirmed.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"They dried and transcribed a wet authorization paper. Preservation is clearer evidence than the sanitation title; broad sanitation practice is unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":30,"Force":-75,"Material":-25,"Communal":10,"Principle":70,"Public":25,"Eligibility":15,"Dispersed":15,"Transformative":-15},"desire":{"Longing":15,"Monopoly":-35,"Risk":-10,"Display":-30,"Sustained":-20,"Orientation":"Fluid","Union":"Polyamorous"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −20 | Openness 30 | Force −75 | Material −25 | Communal 10 | Principle 70 | Publicity 25 | Credentials 15 | Dispersion 15 | Transformation −15","Desires":"Craving 15 | Monopoly −35 | Risk −10 | Display −30 | Persistence −20 | Orientation fluid | Bonding multiple partners"},"sections":{"Life":"Born on 2102-05-12. As of the 2126 opening, holds the post of Quarantine Records Officer and carries on the existing duty and records. The succession record for that post opened with the deletion of a single line from the double ledger.\n- The quarantine records and duty key handover desk in Jegi-dong is Sim Dahyeon''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, dried a water-soaked ratification document on a platform and left it as a transcribed copy. That day''s record remained as a handover basis for the next duty officer to confirm.","Relationships":"Sim Dahyeon, when handing over the quarantine duty shift, brings the entry records and the transcript preserved from the soaked documents to Ra Seyeong. Ra Seyeong checks the quarantine entry seals and release records, searches for omissions together with Sim Dahyeon, and decides on release only after the temperature and medicinal-efficacy records arrive.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty. Trusts a single line in the ledger over loud talk.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born on 2102-05-12. As of the 2126 opening, holds the post of Quarantine Records Officer and carries on the existing duty and records. The succession record for that post opened with the deletion of a single line from the double ledger.\n- The quarantine records and duty key handover desk in Jegi-dong is Sim Dahyeon''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125, dried a water-soaked ratification document on a platform and left it as a transcribed copy. That day''s record remained as a handover basis for the next duty officer to confirm.\n\n**Relationships.** Sim Dahyeon, when handing over the quarantine duty shift, brings the entry records and the transcript preserved from the soaked documents to Ra Seyeong. Ra Seyeong checks the quarantine entry seals and release records, searches for omissions together with Sim Dahyeon, and decides on release only after the temperature and medicinal-efficacy records arrive.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −20 | Openness 30 | Force −75 | Material −25 | Communal 10 | Principle 70 | Publicity 25 | Credentials 15 | Dispersion 15 | Transformation −15\n- Desires: Craving 15 | Monopoly −35 | Risk −10 | Display −30 | Persistence −20 | Orientation fluid | Bonding multiple partners\n:::","relations":{"outgoing":[{"from":"Sim Dahyeon","type":"Contract","to":"Ra Seyeong","basis":"Sim Dahyeon, when handing over the quarantine duty shift, brings the entry records and the transcript preserved from the soaked documents to Ra Seyeong. Ra Seyeong checks the quarantine entry seals and release records, searches for omissions together with Sim Dahyeon, and decides on release only after the temperature and medicinal-efficacy records arrive."}],"incoming":[]}}', '{"id":"person-0452","name":"심다현","title":"방역 기록관","position":"방역 구호원","characterId":"K452","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-심다현","detailRoute":"/people/person-0452","birthDate":"2102-05-12","birthday":"05-12","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"문서 필사","rating":45}],"traits":[{"id":"stated-priority","name":"젖은 기록도 남긴다","description":"젖은 인준 문서를 말려 필사했다. 방역 직함보다 문서 보존 행동이 명확하며 광범위한 방역 수행은 미확인이다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"젖은 인준 문서를 말려 필사했다. 방역 직함보다 문서 보존 행동이 명확하며 광범위한 방역 수행은 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":30,"무력":-75,"물질":-25,"공동":10,"원칙":70,"공개":25,"자격":15,"분산":15,"변혁":-15},"desire":{"갈망":15,"독점":-35,"위험":-10,"과시":-30,"지속":-20,"지향":"유동","결합":"다자"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −20 | 개방 30 | 무력 −75 | 물질 −25 | 공동 10 | 원칙 70 | 공개 25 | 자격 15 | 분산 15 | 변혁 −15","욕망":"갈망 15 | 독점 −35 | 위험 −10 | 과시 −30 | 지속 −20 | 지향 유동 | 결합 다자"},"sections":{"생애":"2102-05-12에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 심다현의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"심다현은 방역 당직을 넘길 때 출입 기록과 젖은 문서에서 보존한 필사본을 라세영에게 가져간다. 라세영은 격리 출입 도장과 해제 기록을 확인하며 심다현과 함께 누락을 찾고, 체온·약효 기록이 도착한 뒤 해제를 판단한다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2102-05-12에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 심다현의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 심다현은 방역 당직을 넘길 때 출입 기록과 젖은 문서에서 보존한 필사본을 라세영에게 가져간다. 라세영은 격리 출입 도장과 해제 기록을 확인하며 심다현과 함께 누락을 찾고, 체온·약효 기록이 도착한 뒤 해제를 판단한다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 30 | 무력 −75 | 물질 −25 | 공동 10 | 원칙 70 | 공개 25 | 자격 15 | 분산 15 | 변혁 −15\n- 욕망: 갈망 15 | 독점 −35 | 위험 −10 | 과시 −30 | 지속 −20 | 지향 유동 | 결합 다자\n:::","relations":{"outgoing":[{"from":"심다현","type":"계약","to":"라세영","basis":"심다현은 방역 당직을 넘길 때 출입 기록과 젖은 문서에서 보존한 필사본을 라세영에게 가져간다. 라세영은 격리 출입 도장과 해제 기록을 확인하며 심다현과 함께 누락을 찾고, 체온·약효 기록이 도착한 뒤 해제를 판단한다."}],"incoming":[]}}');
