INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0467', 'c815-b3d9-b798', '{"id":"person-0467","name":"Jeong Seojun","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0467","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0467","name":"정서준","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0467","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0468', 'ac15-c9c4-c8fc', '{"id":"person-0468","name":"Gang Daryu","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Management Relief Worker","characterId":"K468","rank":"Relief Worker","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-gang-dal-yu","detailRoute":"/people/person-0468","birthDate":"2084-05-04","birthday":"05-04","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"Home visits during isolation","rating":50}],"traits":[{"id":"stated-priority","name":"Care continues through isolation","description":"Isolation of a suspected case accompanied continued home visits. Infection judgment and continuity are narrowly reflected; appraisal expertise is not derived from the title.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Isolation of a suspected case accompanied continued home visits. Infection judgment and continuity are narrowly reflected; appraisal expertise is not derived from the title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":30,"Force":-55,"Material":5,"Communal":20,"Principle":30,"Public":25,"Eligibility":30,"Dispersed":25,"Transformative":-15},"desire":{"Longing":10,"Monopoly":25,"Risk":10,"Display":20,"Sustained":5,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −20 | Openness 30 | Force −55 | Material 5 | Communal 20 | Principle 30 | Transparency 25 | Qualification 30 | Decentralization 25 | Transformation −15","Desires":"Craving 10 | Monopoly 25 | Risk 10 | Display 20 | Persistence 5 | Orientation Fluid | Bonding Monogamous"},"sections":{"Life":"Born 2084-05-04. As of the 2126 opening, holds the duties of Medicinal Herb Logistics Merchant, continuing the existing watch and records. The succession record for that duty opened with the sealing of counterfeit medicine.\n- The handover desk for medicinal herb management records and watch keys in Jegi-dong is Gang Dal-yu''s work reference point. This work reference point does not fix a residence, exact facility boundaries, ranks, holdings, or rights of possession.","Offices":"Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, kept a suspected-contagion patient in an isolation compartment and never stopped making house calls. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Gang Daryu brings the origins and drying dates of the medicinal herbs he manages to Dong Juha for inspection. Dong Juha checks the dates and origins on the tally posts and verifies the treatment assignment seal, so that herbs meant for quarantined patients are not mixed into unverified bulk dispatches.","Ambition":"From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Medicinal Supplies Management Records & Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicinal Supplies Logistics Merchant\n**Life.** Born 2084-05-04. As of the 2126 opening, holds the duties of Medicinal Herb Logistics Merchant, continuing the existing watch and records. The succession record for that duty opened with the sealing of counterfeit medicine.\n- The handover desk for medicinal herb management records and watch keys in Jegi-dong is Gang Dal-yu''s work reference point. This work reference point does not fix a residence, exact facility boundaries, ranks, holdings, or rights of possession.\n\n**Office.** Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.\n\n**Anecdote.** In 2125, kept a suspected-contagion patient in an isolation compartment and never stopped making house calls. That day''s record remained as a handover basis for the next duty shift to verify.\n\n**Relationships.** Gang Daryu brings the origins and drying dates of the medicinal herbs he manages to Dong Juha for inspection. Dong Juha checks the dates and origins on the tally posts and verifies the treatment assignment seal, so that herbs meant for quarantined patients are not mixed into unverified bulk dispatches.\n\n**Ambition.** From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.\n\n**Fear.** Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 30 | Force −55 | Material 5 | Communal 20 | Principle 30 | Transparency 25 | Qualification 30 | Decentralization 25 | Transformation −15\n- Desires: Craving 10 | Monopoly 25 | Risk 10 | Display 20 | Persistence 5 | Orientation Fluid | Bonding Monogamous\n:::","relations":{"outgoing":[{"from":"Gang Daryu","type":"Contract","to":"Dong Juha","basis":"Gang Daryu brings the origins and drying dates of the medicinal herbs he manages to Dong Juha for inspection. Dong Juha checks the dates and origins on the tally posts and verifies the treatment assignment seal, so that herbs meant for quarantined patients are not mixed into unverified bulk dispatches."}],"incoming":[]}}', '{"id":"person-0468","name":"강달유","title":"약재 물류상","position":"약재 관리 구호원","characterId":"K468","rank":"구호원","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-강달유","detailRoute":"/people/person-0468","birthDate":"2084-05-04","birthday":"05-04","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"격리 중 왕진","rating":50}],"traits":[{"id":"stated-priority","name":"격리해도 돌봄을 잇는다","description":"의심 환자를 격리하면서 왕진을 이어갔다. 감염 판단과 치료 지속은 좁게 반영하고 약재 감별은 직함에서 만들지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"의심 환자를 격리하면서 왕진을 이어갔다. 감염 판단과 치료 지속은 좁게 반영하고 약재 감별은 직함에서 만들지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ac15-c9c4-c8fc","name":"진주 강씨","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":30,"무력":-55,"물질":5,"공동":20,"원칙":30,"공개":25,"자격":30,"분산":25,"변혁":-15},"desire":{"갈망":10,"독점":25,"위험":10,"과시":20,"지속":5,"지향":"유동","결합":"단혼"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약재 물류상","가치관":"권위 −20 | 개방 30 | 무력 −55 | 물질 5 | 공동 20 | 원칙 30 | 공개 25 | 자격 30 | 분산 25 | 변혁 −15","욕망":"갈망 10 | 독점 25 | 위험 10 | 과시 20 | 지속 5 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2084-05-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 강달유의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"강달유는 관리하는 약재의 출처와 건조 일자를 동주하에게 가져가 검수받는다. 동주하는 말목의 날짜와 원산지를 살피고 진료 배정 날인을 확인해, 격리 환자에게 쓸 약재가 확인되지 않은 대량 출고에 섞이지 않게 한다.","야망":"약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약재 물류상\n**생애.** 2084-05-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 강달유의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 강달유는 관리하는 약재의 출처와 건조 일자를 동주하에게 가져가 검수받는다. 동주하는 말목의 날짜와 원산지를 살피고 진료 배정 날인을 확인해, 격리 환자에게 쓸 약재가 확인되지 않은 대량 출고에 섞이지 않게 한다.\n\n**야망.** 약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 30 | 무력 −55 | 물질 5 | 공동 20 | 원칙 30 | 공개 25 | 자격 30 | 분산 25 | 변혁 −15\n- 욕망: 갈망 10 | 독점 25 | 위험 10 | 과시 20 | 지속 5 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"강달유","type":"계약","to":"동주하","basis":"강달유는 관리하는 약재의 출처와 건조 일자를 동주하에게 가져가 검수받는다. 동주하는 말목의 날짜와 원산지를 살피고 진료 배정 날인을 확인해, 격리 환자에게 쓸 약재가 확인되지 않은 대량 출고에 섞이지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0469', 'c870-cc3d-b155-66fa', '{"id":"person-0469","name":"Jo Chaewon","title":"Outpost Courier","position":"The Government Outpost Courier","rank":"Sergeant","commonTier":"T5","occupation":"Outpost Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"The Government","detailRoute":"/people/person-0469","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0469","name":"조채원","title":"초소 전령","position":"정부 초소 전령","rank":"병장","commonTier":"T5","occupation":"초소 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"정부","detailRoute":"/people/person-0469","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
