INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0476', 'c2e0-d3c9-c0b0', '{"id":"person-0476","name":"Sin Subin","title":"Gateway Duty Officer","position":"Gateway Duty Officer","rank":"Guard","commonTier":"T5","occupation":"Gate Personnel Ledger Custody","gender":"Male","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0476","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0476","name":"신수빈","title":"관문 당직","position":"관문 당직","rank":"경비대원","commonTier":"T5","occupation":"관문 인명 장부 보관","gender":"남성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0476","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0477', 'ad8c-c548-b3d9', '{"id":"person-0477","name":"Gwon Geumyun","title":"Testimony Scout","position":"Testimony Scout","characterId":"K477","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Registry Ledger Structure and Storage","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#inmul-Gwon-Geumyun","detailRoute":"/people/person-0477","birthDate":"2064-12-19","birthday":"12-19","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k477-roster-rescue","name":"Life roster rescue","rating":45}],"traits":[{"id":"k477-choice","name":"Names first in fire","description":"Anecdote. In the 2125 station fire she carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In the 2125 station fire she carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k477-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In the 2125 station fire she carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28125-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K477","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28125-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-10,"Force":-25,"Material":-30,"Communal":0,"Principle":55,"Public":-25,"Eligibility":15,"Dispersed":-20,"Transformative":-20},"desire":{"Longing":30,"Monopoly":5,"Risk":30,"Display":-10,"Sustained":20,"Orientation":"Same-Sex","Union":"Polyamorous"},"fields":{"Livelihood":"Registry Ledger Structure and Storage","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Testimony Scout","Values":"Authority 15 | Openness −10 | Force −25 | Material −30 | Communal 0 | Principle 55 | Publicity −25 | Credentials 15 | Decentralization −20 | Transformation −20","Desires":"Craving 30 | Monopoly 5 | Risk 30 | Display −10 | Persistence 20 | Orientation Same-sex | Bonding Polyamorous"},"sections":{"Life":"Raised on the waiting hall watch. The Testimony Scout post opened through a substitute watch for an unexcused shift absence.\n- Gwon Geumyun''s work of rescuing and safekeeping the name ledger connects to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.","Anecdote":"During the 2125 station fire, she carried out the name ledger first. Because of this, the signature for the Testimony Scout post was entered in the ledger.","Relationships":"Through the handover of the work of rescuing and safekeeping the name ledger, she is connected to senior watch members of the same living sphere.","Ambition":"From the Testimony Scout post, she continues the records of rescuing and safekeeping the name ledger so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between watches.","Fear":"","Intervention":"You can set up a witness for the watch handover of the work of rescuing and safekeeping the name ledger, or expose the empty key of that post."},"biography":"She guards against the watch being broken and against the name ledger disappearing, both together. The ledger was also the first thing she carried out during the fire.\n\n- Livelihood: Registry Ledger Structure and Storage\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Testimony Scout\n**Life.** Raised on the waiting hall watch. The Testimony Scout post opened through a substitute watch for an unexcused shift absence.\n- Gwon Geumyun''s work of rescuing and safekeeping the name ledger connects to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Post and Grade.** The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.\n\n**Anecdote.** During the 2125 station fire, she carried out the name ledger first. Because of this, the signature for the Testimony Scout post was entered in the ledger.\n\n**Relations.** Through the handover of the work of rescuing and safekeeping the name ledger, she is connected to senior watch members of the same living sphere.\n\n**Ambition.** From the Testimony Scout post, she continues the records of rescuing and safekeeping the name ledger so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between watches.\n\n**Intervention.** You can set up a witness for the watch handover of the work of rescuing and safekeeping the name ledger, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −10 | Force −25 | Materialism −30 | Community 0 | Principle 55 | Publicity −25 | Qualification 15 | Dispersion −20 | Transformation −20\n- Desires: Craving 30 | Possessiveness 5 | Risk 30 | Display −10 | Persistence 20 | Orientation Same-sex | Union Polyamorous\n:::","relations":{"outgoing":[{"from":"Gwon Geumyun","type":"Contract","to":"Cha Se-on","basis":"Gwon Geum-yun takes the register of persons, saved from the fire and kept safe, to Cha Se-on. Cha Se-on examines the testimony about the register and the handwriting of the original, leaving a basis for distinguishing records lost during the rescue from records added later."}],"incoming":[]}}', '{"id":"person-0477","name":"권금윤","title":"증언 탐사원","position":"증언 탐사원","characterId":"K477","rank":"일반 시민","commonTier":"T3","occupation":"인명 장부 구조·보관","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-권금윤","detailRoute":"/people/person-0477","birthDate":"2064-12-19","birthday":"12-19","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k477-roster-rescue","name":"인명 장부 구조","rating":45}],"traits":[{"id":"k477-choice","name":"불 속에서 이름 먼저","description":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k477-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28125-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K477","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28125-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"안동 권씨","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-10,"무력":-25,"물질":-30,"공동":0,"원칙":55,"공개":-25,"자격":15,"분산":-20,"변혁":-20},"desire":{"갈망":30,"독점":5,"위험":30,"과시":-10,"지속":20,"지향":"동성","결합":"다자"},"fields":{"생업":"인명 장부 구조·보관","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"증언 탐사원","가치관":"권위 15 | 개방 −10 | 무력 −25 | 물질 −30 | 공동 0 | 원칙 55 | 공개 −25 | 자격 15 | 분산 −20 | 변혁 −20","욕망":"갈망 30 | 독점 5 | 위험 30 | 과시 −10 | 지속 20 | 지향 동성 | 결합 다자"},"sections":{"생애":"대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권금윤의 인명 장부 구조·보관 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","관계":"인명 장부 구조·보관 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"증언 탐사원 자리에서 인명 장부 구조·보관 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"","개입":"인명 장부 구조·보관 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"당직이 끊기는 것과 인명 장부가 사라지는 것을 함께 경계한다. 화재 때 먼저 들고 나온 것도 그 장부였다.\n\n- 생업: 인명 장부 구조·보관\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 증언 탐사원\n**생애.** 대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권금윤의 인명 장부 구조·보관 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.\n\n**관계.** 인명 장부 구조·보관 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 증언 탐사원 자리에서 인명 장부 구조·보관 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**개입.** 인명 장부 구조·보관 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −10 | 무력 −25 | 물질 −30 | 공동 0 | 원칙 55 | 공개 −25 | 자격 15 | 분산 −20 | 변혁 −20\n- 욕망: 갈망 30 | 독점 5 | 위험 30 | 과시 −10 | 지속 20 | 지향 동성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"권금윤","type":"계약","to":"차세온","basis":"권금윤은 화재에서 구해 보관한 인명 장부를 차세온에게 가져간다. 차세온은 장부에 관한 증언과 원본의 필적을 살펴, 구조 과정에서 사라진 기록과 나중에 덧쓴 기록을 구분할 근거를 남긴다."}],"incoming":[]}}');
