INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0483', 'ace0-d55c-c591', '{"id":"person-0483","name":"Go Supho","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0483","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0483","name":"고숲호","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0483","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0484', 'bb38-b0a8-d3c9-6587', '{"id":"person-0484","name":"Mun Cheolmin","title":"Medicine Storage Clerk","position":"Medicine Storage Relief Worker","characterId":"K484","rank":"Relief Worker","commonTier":"T3","occupation":"Medicine Release Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-mun-cheolmin","detailRoute":"/people/person-0484","birthDate":"2065-07-31","birthday":"07-31","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"Ledger preservation","rating":40}],"traits":[{"id":"stated-priority","name":"People ledger first","description":"The people ledger was taken out first during a fire. Prioritizing records is visible, but prescribing skill or rescue command is not recorded.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The people ledger was taken out first during a fire. Prioritizing records is visible, but prescribing skill or rescue command is not recorded.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":40,"Force":-55,"Material":-25,"Communal":25,"Principle":45,"Public":15,"Eligibility":25,"Dispersed":20,"Transformative":0},"desire":{"Longing":50,"Monopoly":-40,"Risk":-15,"Display":10,"Sustained":30,"Orientation":"Bisexual","Union":"Polyamorous"},"fields":{"Livelihood":"Medicine Release Records and Duty Keys Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicine Storage Clerk","Values":"Authority −30 | Openness 40 | Force −55 | Materialism −25 | Community 25 | Principle 45 | Publicity 15 | Qualification 25 | Dispersion 20 | Transformation 0","Desires":"Craving 50 | Possessiveness −40 | Risk −15 | Display 10 | Persistence 30 | Orientation Bisexual | Union Polyamorous"},"sections":{"Life":"Born on 2065-07-31. As of the opening of 2126, she holds the duties of Prescription Clerk, continuing the existing watch and records. In the succession record of that post, it opened up as a replacement watch for an unexcused shift absence.\n- The prescription record and watch-key handover desk in Jegi-dong is Mun Cheolmin''s work reference point. This work reference point does not establish a residence, exact facility boundaries, a rank, a holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Medicine Storage Relief Worker. She hands over only the keys and records of her own post, and writes in the ledger the time of receipt of the keys and records she has handed over.","Anecdote":"In the 2125 station fire, carried out the register of lives first. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Mun Cheolmin hands over the ledger of lives rescued from the fire, together with the prescription records, to Jeon Sol. Jeon Sol finds the patients missing from the bed waitlist roster and confirms the treatment order by severity, so that no one is dropped from treatment merely because the ledger was lost.","Ambition":"From the Medicine Storage Relief Worker post, she carries on the White Cross Order''s ledger so that it is not broken.","Fear":"She fears that the Medicine Storage Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"She chooses first not to break the watch. She trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Medicine Release Records and Duty Keys Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicine Storage Clerk\n**Life.** Born on 2065-07-31. As of the opening of 2126, she holds the duties of Prescription Clerk, continuing the existing watch and records. In the succession record of that post, it opened up as a replacement watch for an unexcused shift absence.\n- The prescription record and watch-key handover desk in Jegi-dong is Mun Cheolmin''s work reference point. This work reference point does not establish a residence, exact facility boundaries, a rank, a holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Medicine Storage Relief Worker. She hands over only the keys and records of her own post, and writes in the ledger the time of receipt of the keys and records she has handed over.\n\n**Anecdote.** In the 2125 station fire, carried out the register of lives first. That day''s record remained as a handover basis for the next duty shift to verify.\n\n**Relations.** Mun Cheolmin hands over the ledger of lives rescued from the fire, together with the prescription records, to Jeon Sol. Jeon Sol finds the patients missing from the bed waitlist roster and confirms the treatment order by severity, so that no one is dropped from treatment merely because the ledger was lost.\n\n**Ambition.** From the Medicine Storage Relief Worker post, she carries on the White Cross Order''s ledger so that it is not broken.\n\n**Fear.** She fears that the Medicine Storage Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 40 | Force −55 | Materialism −25 | Community 25 | Principle 45 | Publicity 15 | Qualification 25 | Dispersion 20 | Transformation 0\n- Desires: Craving 50 | Possessiveness −40 | Risk −15 | Display 10 | Persistence 30 | Orientation Bisexual | Union Polyamorous\n:::","relations":{"outgoing":[{"from":"Mun Cheolmin","type":"Contract","to":"Jeon Sol","basis":"Mun Cheolmin hands over the ledger of lives rescued from the fire, together with the prescription records, to Jeon Sol. Jeon Sol finds the patients missing from the bed waitlist roster and confirms the treatment order by severity, so that no one is dropped from treatment merely because the ledger was lost."}],"incoming":[]}}', '{"id":"person-0484","name":"문철민","title":"약 보관 서기","position":"약 보관 구호원","characterId":"K484","rank":"구호원","commonTier":"T3","occupation":"약 출고 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-문철민","detailRoute":"/people/person-0484","birthDate":"2065-07-31","birthday":"07-31","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"장부 보존","rating":40}],"traits":[{"id":"stated-priority","name":"인명 장부부터","description":"화재에서 인명 장부를 먼저 들고 나왔다. 기록의 우선순위는 보이지만 처방 기술이나 구조 지휘 경력은 적혀 있지 않다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약 보관 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약 보관 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"화재에서 인명 장부를 먼저 들고 나왔다. 기록의 우선순위는 보이지만 처방 기술이나 구조 지휘 경력은 적혀 있지 않다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":40,"무력":-55,"물질":-25,"공동":25,"원칙":45,"공개":15,"자격":25,"분산":20,"변혁":0},"desire":{"갈망":50,"독점":-40,"위험":-15,"과시":10,"지속":30,"지향":"양성","결합":"다자"},"fields":{"생업":"약 출고 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약 보관 서기","가치관":"권위 −30 | 개방 40 | 무력 −55 | 물질 −25 | 공동 25 | 원칙 45 | 공개 15 | 자격 25 | 분산 20 | 변혁 0","욕망":"갈망 50 | 독점 −40 | 위험 −15 | 과시 10 | 지속 30 | 지향 양성 | 결합 다자"},"sections":{"생애":"2065-07-31에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 문철민의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"문철민은 화재에서 구한 인명 장부를 처방 기록과 함께 전솔에게 넘긴다. 전솔은 병상 대기 명부에서 빠진 환자를 찾아 중증도로 진료 순서를 확인하고, 장부가 소실됐다는 이유만으로 치료에서 누락되지 않게 한다.","야망":"약 보관 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약 보관 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약 출고 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약 보관 서기\n**생애.** 2065-07-31에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 문철민의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 문철민은 화재에서 구한 인명 장부를 처방 기록과 함께 전솔에게 넘긴다. 전솔은 병상 대기 명부에서 빠진 환자를 찾아 중증도로 진료 순서를 확인하고, 장부가 소실됐다는 이유만으로 치료에서 누락되지 않게 한다.\n\n**야망.** 약 보관 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약 보관 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 40 | 무력 −55 | 물질 −25 | 공동 25 | 원칙 45 | 공개 15 | 자격 25 | 분산 20 | 변혁 0\n- 욕망: 갈망 50 | 독점 −40 | 위험 −15 | 과시 10 | 지속 30 | 지향 양성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"문철민","type":"계약","to":"전솔","basis":"문철민은 화재에서 구한 인명 장부를 처방 기록과 함께 전솔에게 넘긴다. 전솔은 병상 대기 명부에서 빠진 환자를 찾아 중증도로 진료 순서를 확인하고, 장부가 소실됐다는 이유만으로 치료에서 누락되지 않게 한다."}],"incoming":[]}}');
