INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0499', 'c6b0-b2e8-c591', '{"id":"person-0499","name":"U Hajin","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K499","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#person-u-hajin","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k499-medical-escort-dispatch-reconciliation","name":"Medical escort dispatch reconciliation","rating":50}],"traits":[{"id":"k499-priority","name":"Records displaced services","description":"U Hajin matched new dispatch times individually and handed over displaced medical services separately. Reconciliation grants no operating command.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"That if the transport train escort duty stood empty, someone being escorted to the hospital could be kidnapped or taken hostage on the way and no one would know.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k499-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"That if the transport train escort duty stood empty, someone being escorted to the hospital could be kidnapped or taken hostage on the way and no one would know.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"U Hajin matched new dispatch times individually and handed over displaced medical services separately. Reconciliation grants no operating command.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":45,"Force":-40,"Material":-10,"Communal":20,"Principle":25,"Public":20,"Eligibility":15,"Dispersed":30,"Transformative":5},"desire":{"Longing":35,"Monopoly":-5,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −15 | Openness 45 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 20 | Qualification 15 | Decentralization 30 | Reform 5","Desires":"Craving 35 | Monopoly −5 | Risk −10 | Display 0 | Persistence 15 | Orientation Opposite sex | Union Monogamy"},"sections":{"Life":"Born 2066-08-11. Grew up at the Seoul Station Registry Office. At the 2126 opening, holds the Medical Escort Records Officer duty post; the post''s handover record preserves the line \"opened with the deletion of one line from a double ledger.\"\n- The dispatch, shift, maintenance, passage screening, stretcher handover and duty-key record desk in Sinnae 1-dong is proposed as U Hajin''s reference point for medical escort records and duty-key handover work. It is a proposal to reconcile handover records in the winter, and it does not confirm operating trains, new facilities, weapons, passage tolls, market monopolies, residence, exact facility boundaries, ranks, holdings, or possession rights.","Offices":"Rank: Escort. Title: Medical Escort Recorder. Hands over the medical escort times on the seasonal dispatch table together with the keys and records of one''s own duty post, making the scope of the handover clear.","Anecdote":"The seasons change, and the medical train running times that Jang Sehwa wrote out in divided form pass over to the new dispatch table. U Hajin matches the departure times in the medical escort records against the medical train columns of the new dispatch table one by one, separately notes the medical escort runs that were pushed into the general train columns, and hands them over together with the duty key. The medical escort times on the seasonal dispatch table left behind then became the handover standard for the next duty officer.","Relationships":"Hands the medical escort times on the seasonal dispatch table to a senior duty officer of the same living sphere, and cross-checks them against the next shift''s receipt time in the same duty sphere.","Ambition":"Seeks to leave the medical escort times on the seasonal dispatch table as a public handover line that the next shift can check again.","Fear":"Fears that if the receipt time for the medical escort times on the seasonal dispatch table is left blank, responsibility will be shoved onto the patient and passenger lists.","Intervention":"Can set up a handover witness for the medical escort times on the seasonal dispatch table, or make public any missing signature box before the next shift."},"biography":"U Hajin, born 2066-08-11, first checks the order of the medical escort times on the seasonal dispatch table. Trusts handover times and signature boxes rather than loud voices.\n\n- Livelihood: Medical Escort Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Medical Escort Recorder\n**Life.** Born 2066-08-11. Grew up at the Seoul Station Registry Office. At the 2126 opening, holds the Medical Escort Records Officer duty post; the post''s handover record preserves the line \"opened with the deletion of one line from a double ledger.\"\n- The dispatch, shift, maintenance, passage screening, stretcher handover and duty-key record desk in Sinnae 1-dong is proposed as U Hajin''s reference point for medical escort records and duty-key handover work. It is a proposal to reconcile handover records in the winter, and it does not confirm operating trains, new facilities, weapons, passage tolls, market monopolies, residence, exact facility boundaries, ranks, holdings, or possession rights.\n\n**Office.** Rank: Escort. Title: Medical Escort Recorder. Hands over the medical escort times on the seasonal dispatch table together with the keys and records of one''s own duty post, making the scope of the handover clear.\n\n**Anecdote.** The seasons change, and the medical train running times that Jang Sehwa wrote out in divided form pass over to the new dispatch table. U Hajin matches the departure times in the medical escort records against the medical train columns of the new dispatch table one by one, separately notes the medical escort runs that were pushed into the general train columns, and hands them over together with the duty key. The medical escort times on the seasonal dispatch table left behind then became the handover standard for the next duty officer.\n\n**Relations.** Hands the medical escort times on the seasonal dispatch table to a senior duty officer of the same living sphere, and cross-checks them against the next shift''s receipt time in the same duty sphere.\n\n**Ambition.** Seeks to leave the medical escort times on the seasonal dispatch table as a public handover line that the next shift can check again.\n\n**Fear.** Fears that if the receipt time for the medical escort times on the seasonal dispatch table is left blank, responsibility will be shoved onto the patient and passenger lists.\n\n**Intervention.** Can set up a handover witness for the medical escort times on the seasonal dispatch table, or make public any missing signature box before the next shift.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 45 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 20 | Qualification 15 | Decentralization 30 | Reform 5\n- Desires: Craving 35 | Monopoly −5 | Risk −10 | Display 0 | Persistence 15 | Orientation Opposite sex | Union Monogamy\n:::","relations":{"outgoing":[{"from":"U Hajin","type":"Contract","to":"Jeon Miri","basis":"U Hajin separately records the medical escort runs that were pushed out of the seasonal schedule into ordinary train cars and passes them to Jeon Miri. Jeon Miri checks patient severity and transfer times and reflects them in the Medical Team duty room, so that stretcher order is not erased just because the schedule changed."}],"incoming":[]}}', '{"id":"person-0499","name":"우하진","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K499","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-우하진","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k499-medical-escort-dispatch-reconciliation","name":"의무호송 배차 대조","rating":50}],"traits":[{"id":"k499-priority","name":"밀려난 편을 남김","description":"우하진은 새 배차표와 의무호송 출발을 하나씩 맞추고 일반 칸으로 밀려난 편을 따로 넘겼다. 기록 대조가 운행 지휘권은 아니다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"호송 열차 동행 당직이 비면 병원으로 가는 길에서 호송 대상이 납치되거나 인질로 잡혀도 아무도 모르게 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k499-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 호송 열차 동행 당직이 비면 병원으로 가는 길에서 호송 대상이 납치되거나 인질로 잡혀도 아무도 모르게 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"우하진은 새 배차표와 의무호송 출발을 하나씩 맞추고 일반 칸으로 밀려난 편을 따로 넘겼다. 기록 대조가 운행 지휘권은 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":45,"무력":-40,"물질":-10,"공동":20,"원칙":25,"공개":20,"자격":15,"분산":30,"변혁":5},"desire":{"갈망":35,"독점":-5,"위험":-10,"과시":0,"지속":15,"지향":"이성","결합":"단혼"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −15 | 개방 45 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 20 | 자격 15 | 분산 30 | 변혁 5","욕망":"갈망 35 | 독점 −5 | 위험 −10 | 과시 0 | 지속 15 | 지향 이성 | 결합 단혼"},"sections":{"생애":"2066-08-11에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 우하진의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 계절 배차표의 의무호송 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"계절이 바뀌어, 장세화가 나눠 적은 의료열차 운행 시간이 새 배차표로 넘어간다. 우하진은 의무호송 기록의 출발 시각을 새 배차표의 의료열차 칸과 하나씩 맞추고, 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 당직 열쇠와 함께 넘긴다. 그때 남긴 계절 배차표의 의무호송 시각이 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 계절 배차표의 의무호송 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"계절 배차표의 의무호송 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"계절 배차표의 의무호송 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"계절 배차표의 의무호송 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2066-08-11생인 우하진은 계절 배차표의 의무호송 시각의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2066-08-11에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 우하진의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 계절 배차표의 의무호송 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 계절이 바뀌어, 장세화가 나눠 적은 의료열차 운행 시간이 새 배차표로 넘어간다. 우하진은 의무호송 기록의 출발 시각을 새 배차표의 의료열차 칸과 하나씩 맞추고, 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 당직 열쇠와 함께 넘긴다. 그때 남긴 계절 배차표의 의무호송 시각이 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 계절 배차표의 의무호송 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 계절 배차표의 의무호송 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 계절 배차표의 의무호송 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 계절 배차표의 의무호송 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 45 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 20 | 자격 15 | 분산 30 | 변혁 5\n- 욕망: 갈망 35 | 독점 −5 | 위험 −10 | 과시 0 | 지속 15 | 지향 이성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"우하진","type":"계약","to":"전미리","basis":"우하진은 계절 배차표에서 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 전미리에게 전한다. 전미리는 환자 중증도와 이송 시각을 확인하고 의료조 당직실에 반영해, 배차표가 바뀌었다고 들것 순서가 지워지지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0500', 'ad6c-b2a5-c131', '{"id":"person-0500","name":"Gu Sohui","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K500","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-gu-sohui","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"Original document custody","rating":40}],"traits":[{"id":"stated-priority","name":"Keeps the original compartment","description":"After a forged seal was exposed, copies were burned and the original compartment guarded. Personal discovery of the forgery or sanitation command is not assumed.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"After a forged seal was exposed, copies were burned and the original compartment guarded. Personal discovery of the forgery or sanitation command is not assumed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":40,"Force":-60,"Material":-10,"Communal":30,"Principle":60,"Public":30,"Eligibility":25,"Dispersed":25,"Transformative":-15},"desire":{"Longing":20,"Monopoly":35,"Risk":-30,"Display":-15,"Sustained":30,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −15 | Openness 40 | Force −60 | Materialism −10 | Community 30 | Principle 60 | Publicity 30 | Qualification 25 | Decentralization 25 | Reform −15","Desires":"Craving 20 | Monopoly 35 | Risk −30 | Display −15 | Persistence 30 | Orientation None | Union None"},"sections":{"Life":"Born 2070-09-14. As of the 2126 opening, holds the Quarantine Records Officer duties, continuing the existing duty and records. The succession record for that post opens with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Gu Sohui''s work reference point. This work reference point does not confirm residence, exact facility boundaries, ranks, holdings, or possession rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.","Relationships":"Gu Sohui brings the original quarantine records and the entry seal to Ra Seyeong to check a suspicious copy. Ra Seyeong examines the quarantine entry and release records to confirm whether a forged seal got through, and does not declare a release before the temperature and medicinal-efficacy records arrive.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single ledger line rather than loud voices.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born 2070-09-14. As of the 2126 opening, holds the Quarantine Records Officer duties, continuing the existing duty and records. The succession record for that post opens with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Gu Sohui''s work reference point. This work reference point does not confirm residence, exact facility boundaries, ranks, holdings, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.\n\n**Relations.** Gu Sohui brings the original quarantine records and the entry seal to Ra Seyeong to check a suspicious copy. Ra Seyeong examines the quarantine entry and release records to confirm whether a forged seal got through, and does not declare a release before the temperature and medicinal-efficacy records arrive.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 40 | Force −60 | Materialism −10 | Community 30 | Principle 60 | Publicity 30 | Qualification 25 | Decentralization 25 | Reform −15\n- Desires: Craving 20 | Monopoly 35 | Risk −30 | Display −15 | Persistence 30 | Orientation None | Union None\n:::","relations":{"outgoing":[{"from":"Gu Sohui","type":"Contract","to":"Ra Seyeong","basis":"Gu Sohui brings the original quarantine records and the entry seal to Ra Seyeong to check a suspicious copy. Ra Seyeong examines the quarantine entry and release records to confirm whether a forged seal got through, and does not declare a release before the temperature and medicinal-efficacy records arrive."}],"incoming":[]}}', '{"id":"person-0500","name":"구소희","title":"방역 기록관","position":"방역 구호원","characterId":"K500","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-구소희","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"원본 보관","rating":40}],"traits":[{"id":"stated-priority","name":"원본 칸을 지킨다","description":"위조 도장이 드러난 뒤 사본을 불사르고 원본 칸을 지켰다. 위조를 직접 발견했다거나 방역을 지휘했다고 단정하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"위조 도장이 드러난 뒤 사본을 불사르고 원본 칸을 지켰다. 위조를 직접 발견했다거나 방역을 지휘했다고 단정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":40,"무력":-60,"물질":-10,"공동":30,"원칙":60,"공개":30,"자격":25,"분산":25,"변혁":-15},"desire":{"갈망":20,"독점":35,"위험":-30,"과시":-15,"지속":30,"지향":"무성향","결합":"없음"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −15 | 개방 40 | 무력 −60 | 물질 −10 | 공동 30 | 원칙 60 | 공개 30 | 자격 25 | 분산 25 | 변혁 −15","욕망":"갈망 20 | 독점 35 | 위험 −30 | 과시 −15 | 지속 30 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2070-09-14에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 구소희의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 체온·약효 기록이 도착하기 전에는 해제를 선언하지 않는다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2070-09-14에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 구소희의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 체온·약효 기록이 도착하기 전에는 해제를 선언하지 않는다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 40 | 무력 −60 | 물질 −10 | 공동 30 | 원칙 60 | 공개 30 | 자격 25 | 분산 25 | 변혁 −15\n- 욕망: 갈망 20 | 독점 35 | 위험 −30 | 과시 −15 | 지속 30 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"구소희","type":"계약","to":"라세영","basis":"구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 체온·약효 기록이 도착하기 전에는 해제를 선언하지 않는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0501', 'bbfc-c5ec-d765-9594', '{"id":"person-0501","name":"Min Pahyeon","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"The Government","detailRoute":"/people/person-0501","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0501","name":"민파현","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"정부","detailRoute":"/people/person-0501","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0502', 'c9c4-d48d-ae30', '{"id":"person-0502","name":"Jin Junhyeok","title":"Auction Clerk","position":"Myeongdong Station Records Clerk","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Handover Log","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0502","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0502","name":"진준혁","title":"경매 서기","position":"명동역 기록 서기","rank":"일반 시민","commonTier":"T5","occupation":"기록·인수인계 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0502","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
