INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0524', 'bb38-b0a8-d3c9-6587', '{"id":"person-0524","name":"Mun Aeun","title":"Gateway Duty Officer","position":"Gateway Duty Officer","rank":"Guard","commonTier":"T5","occupation":"Gate Shift Coordination","gender":"Male","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0524","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0524","name":"문아은","title":"관문 당직","position":"관문 당직","rank":"경비대원","commonTier":"T5","occupation":"관문 교대 조정","gender":"남성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0524","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0525', 'c591-c911-d654-694a', '{"id":"person-0525","name":"Yang Katae","title":"Testimony Scout","position":"Testimony Scout","characterId":"K525","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Registry Ledger Structure and Storage","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#character-yangkatae","detailRoute":"/people/person-0525","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k525-roster-rescue","name":"Life roster rescue","rating":45}],"traits":[{"id":"k525-choice","name":"Life records first","description":"Anecdote. In the 2125 station fire he carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In the 2125 station fire he carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k525-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In the 2125 station fire he carried out the roster of lives first. By this deed the signature of the testimony surveyor post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28185-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K525","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28185-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c591-c911-d654-694a","name":"Junghwa Yang Clan","crest":"clan-crests/c591-c911-d654-694a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-15,"Force":-35,"Material":-30,"Communal":5,"Principle":50,"Public":-20,"Eligibility":15,"Dispersed":-35,"Transformative":-20},"desire":{"Longing":40,"Monopoly":-10,"Risk":-20,"Display":30,"Sustained":5,"Orientation":"Bisexual","Union":"Polyamorous"},"fields":{"Livelihood":"Registry Ledger Structure and Storage","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Testimony Scout","Values":"Authority 15 | Openness −15 | Force −35 | Materialism −30 | Community 5 | Principle 50 | Publicity −20 | Credentials 15 | Decentralization −35 | Transformation −20","Desires":"Craving 40 | Monopoly −10 | Risk −20 | Display 30 | Endurance 5 | Orientation Bisexual | Bonding Polyamorous"},"sections":{"Life":"Grew up on Waiting Hall duty. The Testimony Surveyor post opened up as a replacement duty after an unexcused shift absence.\n- Yang Katae''s work of rescuing and keeping the life ledger is connected to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.","Anecdote":"During the 2125 station fire, he carried out the name ledger first. Because of this, the signature for the Testimony Scout post was entered in the ledger.","Relationships":"Through the handover of the work of rescuing and safekeeping the name ledger, he is connected to senior watch members of the same living sphere.","Ambition":"From the Testimony Scout post, he continues the records of rescuing and safekeeping the name ledger so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between watches.","Fear":"","Intervention":"You can set up a witness for the watch handover of the work of rescuing and safekeeping the name ledger, or expose the empty key of that post."},"biography":"Like the life ledger pulled out of the station fire, the duty records are secured first. Judgments are made in favor of preserving the ledger.\n\n- Livelihood: Registry Ledger Structure and Storage\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Testimony Scout\n**Life.** Grew up on Waiting Hall duty. The Testimony Surveyor post opened up as a replacement duty after an unexcused shift absence.\n- Yang Katae''s work of rescuing and keeping the life ledger is connected to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Position and Grade.** The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.\n\n**Anecdote.** During the 2125 station fire, he carried out the name ledger first. Because of this, the signature for the Testimony Scout post was entered in the ledger.\n\n**Relationships.** Through the handover of the work of rescuing and safekeeping the name ledger, he is connected to senior watch members of the same living sphere.\n\n**Ambition.** From the Testimony Scout post, he continues the records of rescuing and safekeeping the name ledger so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between watches.\n\n**Intervention.** You can set up a witness for the watch handover of the work of rescuing and safekeeping the name ledger, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −15 | Force −35 | Materialism −30 | Community 5 | Principle 50 | Publicity −20 | Credentials 15 | Decentralization −35 | Transformation −20\n- Desires: Craving 40 | Monopoly −10 | Risk −20 | Display 30 | Endurance 5 | Orientation Bisexual | Bonding Polyamorous\n:::","relations":{"outgoing":[{"from":"Yang Katae","type":"Contract","to":"Cha Se-on","basis":"Yang Ka-tae takes the register of persons saved from the fire to Cha Se-on and reports the damaged condition of the records. Cha Se-on examines the original handwriting and the testimony, does not arbitrarily fill in the illegible parts, and leaves a basis for verification."}],"incoming":[]}}', '{"id":"person-0525","name":"양카태","title":"증언 탐사원","position":"증언 탐사원","characterId":"K525","rank":"일반 시민","commonTier":"T3","occupation":"인명 장부 구조·보관","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-양카태","detailRoute":"/people/person-0525","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k525-roster-rescue","name":"인명 장부 구조","rating":45}],"traits":[{"id":"k525-choice","name":"인명 기록 우선","description":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k525-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28185-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K525","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28185-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c591-c911-d654-694a","name":"중화 양씨","crest":"clan-crests/c591-c911-d654-694a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-15,"무력":-35,"물질":-30,"공동":5,"원칙":50,"공개":-20,"자격":15,"분산":-35,"변혁":-20},"desire":{"갈망":40,"독점":-10,"위험":-20,"과시":30,"지속":5,"지향":"양성","결합":"다자"},"fields":{"생업":"인명 장부 구조·보관","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"증언 탐사원","가치관":"권위 15 | 개방 −15 | 무력 −35 | 물질 −30 | 공동 5 | 원칙 50 | 공개 −20 | 자격 15 | 분산 −35 | 변혁 −20","욕망":"갈망 40 | 독점 −10 | 위험 −20 | 과시 30 | 지속 5 | 지향 양성 | 결합 다자"},"sections":{"생애":"대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 양카태의 인명 장부 구조·보관 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","관계":"인명 장부 구조·보관 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"증언 탐사원 자리에서 인명 장부 구조·보관 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"","개입":"인명 장부 구조·보관 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"역사 화재에서 꺼낸 인명 장부처럼 당직 기록도 먼저 챙긴다. 장부를 남기는 쪽으로 판단한다.\n\n- 생업: 인명 장부 구조·보관\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 증언 탐사원\n**생애.** 대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 양카태의 인명 장부 구조·보관 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.\n\n**관계.** 인명 장부 구조·보관 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 증언 탐사원 자리에서 인명 장부 구조·보관 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**개입.** 인명 장부 구조·보관 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −15 | 무력 −35 | 물질 −30 | 공동 5 | 원칙 50 | 공개 −20 | 자격 15 | 분산 −35 | 변혁 −20\n- 욕망: 갈망 40 | 독점 −10 | 위험 −20 | 과시 30 | 지속 5 | 지향 양성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"양카태","type":"계약","to":"차세온","basis":"양카태는 화재에서 구한 인명 장부를 차세온에게 가져가 기록의 손상 상태를 알린다. 차세온은 원본 필적과 증언을 살펴 읽히지 않는 부분을 임의로 채우지 않고 확인 근거를 남긴다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0526', NULL, '{"id":"person-0526","name":"Pavel Nemets","title":"Dispatch Clerk","position":"Dispatch Clerk","rank":"Clerk","commonTier":"T5","occupation":"Flooded Section Collapse Report and Closure","gender":"Male","stage":"S4","state":"S07","stateName":"The Government","detailRoute":"/people/person-0526","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0526","name":"파벨 네메츠","title":"배차 서기","position":"배차 서기","rank":"주사","commonTier":"T5","occupation":"침수 구간 붕괴 보고·폐쇄","gender":"남성","stage":"S4","state":"S07","stateName":"정부","detailRoute":"/people/person-0526","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
