INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0528', 'bc31-c218-c6d0', '{"id":"person-0528","name":"Baek Buk-rae","title":"Stand-In Courier","position":"Currency Exchange Courier","rank":"Clerk","commonTier":"T5","occupation":"Currency Exchange Courier Takeover and Ledger Delivery","gender":"Male","stage":"S4","state":"S09","stateName":"Free City","detailRoute":"/people/person-0528","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0528","name":"백북래","title":"대역 전령","position":"환전 전령","rank":"서기","commonTier":"T5","occupation":"환전 전령 인수·장부 전달","gender":"남성","stage":"S4","state":"S09","stateName":"자유도시","detailRoute":"/people/person-0528","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}');
