INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0540', 'ad6c-b2a5-c131', '{"id":"person-0540","name":"Gu Nam-hui","title":"Heat and Light Watch","position":"Heat and Light Watch","rank":"Guard","commonTier":"T5","occupation":"Watching for approaching outside machines","gender":"Female","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0540","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0540","name":"구남희","title":"열·빛 감시 담당","position":"열·빛 감시 담당","rank":"경비대원","commonTier":"T5","occupation":"외부 기계 접근 감시","gender":"여성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0540","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0541', 'bbfc-c5ec-d765-9594', '{"id":"person-0541","name":"Min Yeon-u","title":"Copy Herald","position":"Copy Herald","characterId":"K541","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Protecting the Convoy Casualty Ledger","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#character-minyeonu","detailRoute":"/people/person-0541","birthDate":"2085-09-25","birthday":"09-25","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k541-escort-roster","name":"Escort roster preservation","rating":45}],"traits":[{"id":"k541-choice","name":"Rosters before cargo","description":"Anecdote. In 2125, meeting a raid mid-convoy, she secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125, meeting a raid mid-convoy, she secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k541-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125, meeting a raid mid-convoy, she secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41480-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K541","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-41480-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":25,"Openness":-5,"Force":-35,"Material":-30,"Communal":15,"Principle":40,"Public":-5,"Eligibility":20,"Dispersed":-40,"Transformative":-40},"desire":{"Longing":20,"Monopoly":10,"Risk":30,"Display":25,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Protecting the Convoy Casualty Ledger","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Copy Herald","Values":"Authority 25 | Openness −5 | Force −35 | Materialism −30 | Community 15 | Principle 40 | Publicity −5 | Credentials 20 | Decentralization −40 | Transformation −40","Desires":"Craving 20 | Monopoly 10 | Risk 30 | Display 25 | Endurance −10 | Orientation Opposite-sex | Bonding Non-exclusive"},"sections":{"Life":"Grew up on Sinnae transfer duty. The Copy Courier post opened up by stopping a ticketless departing train.\n- Min Yeonu''s work of protecting the convoy life ledger is connected to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.","Anecdote":"In 2125, caught in an ambush during a convoy, secured the life ledger before the cargo. Because of this, the signature of the Copy Courier post was entered in the ledger.","Relationships":"Through the handover of the convoy life-ledger protection work, connected to senior duty staff in the same living sphere.","Ambition":"From the Copy Courier post, to carry on the records of convoy life-ledger protection so that the ledger of the Seoul Metropolitan Government Local Civil Service is not broken between duty shifts.","Fear":"","Intervention":"Can appoint a witness to the duty handover of the convoy life-ledger protection work, or expose the empty key of that post."},"biography":"She chooses to keep the escort roster ledger connected even when the convoy wavers. She trusts the names she secured before the cargo during a raid.\n\n- Livelihood: Protecting the Convoy Casualty Ledger\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Copy Herald\n**Life.** Grew up on Sinnae transfer duty. The Copy Courier post opened up by stopping a ticketless departing train.\n- Min Yeonu''s work of protecting the convoy life ledger is connected to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Post and Grade.** A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.\n\n**Anecdote.** In 2125, caught in an ambush during a convoy, secured the life ledger before the cargo. Because of this, the signature of the Copy Courier post was entered in the ledger.\n\n**Relationships.** Through the handover of the convoy life-ledger protection work, connected to senior duty staff in the same living sphere.\n\n**Ambition.** From the Copy Courier post, to carry on the records of convoy life-ledger protection so that the ledger of the Seoul Metropolitan Government Local Civil Service is not broken between duty shifts.\n\n**Intervention.** Can appoint a witness to the duty handover of the convoy life-ledger protection work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 25 | Openness −5 | Force −35 | Materialism −30 | Community 15 | Principle 40 | Publicity −5 | Qualification 20 | Dispersal −40 | Transformation −40\n- Desires: Craving 20 | Possessiveness 10 | Risk 30 | Display 25 | Persistence −10 | Orientation heterosexual | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Min Yeon-u","type":"Contract","to":"Seop Do-yun","basis":"Min Yeonu passes to Seop Doyun the escort casualty ledger and copy taken from the raid. Seop Doyun sends the news to the Records Office and the council hall along with testimony to confirm the missing personnel, so that escort losses are not conveyed merely as cargo figures."}],"incoming":[]}}', '{"id":"person-0541","name":"민연우","title":"사본 전령","position":"사본 전령","characterId":"K541","rank":"일반 시민","commonTier":"T3","occupation":"호송 인명 장부 보호","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-민연우","detailRoute":"/people/person-0541","birthDate":"2085-09-25","birthday":"09-25","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k541-escort-roster","name":"호송 장부 보전","rating":45}],"traits":[{"id":"k541-choice","name":"화물보다 인명 장부","description":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k541-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41480-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K541","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-41480-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"bbfc-c5ec-d765-9594","name":"여흥 민씨","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":25,"개방":-5,"무력":-35,"물질":-30,"공동":15,"원칙":40,"공개":-5,"자격":20,"분산":-40,"변혁":-40},"desire":{"갈망":20,"독점":10,"위험":30,"과시":25,"지속":-10,"지향":"이성","결합":"비독점"},"fields":{"생업":"호송 인명 장부 보호","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"사본 전령","가치관":"권위 25 | 개방 −5 | 무력 −35 | 물질 −30 | 공동 15 | 원칙 40 | 공개 −5 | 자격 20 | 분산 −40 | 변혁 −40","욕망":"갈망 20 | 독점 10 | 위험 30 | 과시 25 | 지속 −10 | 지향 이성 | 결합 비독점"},"sections":{"생애":"신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 민연우의 호송 인명 장부 보호 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.","일화":"2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","관계":"호송 인명 장부 보호 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"사본 전령 자리에서 호송 인명 장부 보호 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"","개입":"호송 인명 장부 보호 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"호송이 흔들려도 인명 장부를 잇는 쪽을 고른다. 습격 때 화물보다 먼저 챙긴 이름들을 믿는다.\n\n- 생업: 호송 인명 장부 보호\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 사본 전령\n**생애.** 신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 민연우의 호송 인명 장부 보호 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.\n\n**일화.** 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 호송 인명 장부 보호 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 사본 전령 자리에서 호송 인명 장부 보호 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**개입.** 호송 인명 장부 보호 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 25 | 개방 −5 | 무력 −35 | 물질 −30 | 공동 15 | 원칙 40 | 공개 −5 | 자격 20 | 분산 −40 | 변혁 −40\n- 욕망: 갈망 20 | 독점 10 | 위험 30 | 과시 25 | 지속 −10 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"민연우","type":"계약","to":"섭도윤","basis":"민연우는 습격에서 챙긴 호송 인명 장부와 사본을 섭도윤에게 전달한다. 섭도윤은 인원 누락을 확인할 증언과 함께 기록청과 회의장에 소식을 보내, 호송 손실이 화물 숫자로만 전해지지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0542', NULL, '{"id":"person-0542","name":"Andrei Ivanov","title":"Relay Duty","position":"Relay Duty","rank":"Clerk","commonTier":"T5","occupation":"Preserving False Bulletins · Correction Broadcast","gender":"Male","stage":"S4","state":"S07","stateName":"The Government","detailRoute":"/people/person-0542","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0542","name":"안드레이 이바노프","title":"중계 당직","position":"중계 당직","rank":"주사","commonTier":"T5","occupation":"거짓 속보 보존·정정 방송","gender":"남성","stage":"S4","state":"S07","stateName":"정부","detailRoute":"/people/person-0542","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0543', 'ae40-ad11-c0b0-91d1', '{"id":"person-0543","name":"Kim Reum-ho","title":"Market Patrol","position":"Market Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Ridge Patrol · Checking for Ambush Traces","gender":"Female","stage":"S4","state":"S08","stateName":"The Government","detailRoute":"/people/person-0543","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":9,"effective":9}}}}', '{"id":"person-0543","name":"김름호","title":"시장 순찰대","position":"시장 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"능선 초계·매복 흔적 확인","gender":"여성","stage":"S4","state":"S08","stateName":"정부","detailRoute":"/people/person-0543","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":9,"effective":9}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0544', 'c774-ad11-c8fc-674e', '{"id":"person-0544","name":"I Ba-seok","title":"Transmission Duty","position":"Vault Duty","characterId":"K544","rank":"Clerk","commonTier":"T5","occupation":"Vault Duty Shift Change and Record Handover","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-09#person-i-baseok","detailRoute":"/people/person-0544","birthDate":"2102-06-12","birthday":"06-12","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"frozen-lock","name":"Frozen-lock cleaning","rating":40}],"traits":[{"id":"frozen-lock-disposition","name":"Descends to do the work","description":"Cleans the frozen door instead of only awaiting reports.","behavior":"Cleans the frozen door instead of only awaiting reports.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"bounded-handover","name":"Bounded handover","description":"Keeps duty continuous without inventing authority.","behavior":"Hands over only duty keys and records.","stress":"Fears vacant duty becoming dependence.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Descended on a rope to clean the door when the lock froze. The short anecdote and handover do not establish expert command, combat or institutional success.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c774-ad11-c8fc-674e","name":"Gwangju I Clan","crest":"clan-crests/c774-ad11-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":30,"Force":-35,"Material":-20,"Communal":0,"Principle":25,"Public":60,"Eligibility":15,"Dispersed":30,"Transformative":-5},"desire":{"Longing":30,"Monopoly":-10,"Risk":35,"Display":-25,"Sustained":35,"Orientation":"Same-Sex","Union":"None"},"fields":{"Livelihood":"Vault Duty Shift Change and Record Handover","Affiliation":"Free City","Rank":"Clerk","Title":"Vault Duty","Values":"Authority −15 | Openness 30 | Force −35 | Materialism −20 | Community 0 | Principle 25 | Publicity 60 | Qualification 15 | Dispersal 30 | Transformation −5","Desires":"Craving 30 | Possessiveness −10 | Risk 35 | Display −25 | Persistence 35 | Orientation same-sex | Bonding none"},"sections":{"Life":"Born 2102-06-12; the approved birth cohort is Cohort 4. Active at the opening of 2126. Grew up at the Yeouido Vault Watch. The Vault Watch post opened when she kept the vault secure through a three-day blackout.\n- I Baseok hands over to the senior watch the Vault Watch shift and record handover work related to Yeoui-dong.","Offices":"Rank: Clerk. Title: Vault Duty. She hands over only the keys and records of her own post and creates no authority that does not exist.","Anecdote":"In 2125, when the vault lock froze, she tied on a rope, climbed down, and wiped the door clean. Because of this, the signature of the Vault Watch post was entered in the ledger.","Relationships":"Bound by handover to a senior watch from the same living sphere.","Ambition":"From the vault watch post, keeps the market ledger unbroken.","Fear":"That if the vault watch falls vacant, the food and fuel tallies in the vault get used in bargains over people held captive.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"She chooses first not to break the watch. She trusts a single line in the ledger over loud talk.\n\n- Livelihood: Vault Duty Shift Change and Record Handover\n- Affiliation: Free City\n- Rank: Clerk\n- Title: Vault Duty\n**Life.** Born 2102-06-12; the approved birth cohort is Cohort 4. Active at the opening of 2126. Grew up at the Yeouido Vault Watch. The Vault Watch post opened when she kept the vault secure through a three-day blackout.\n- I Baseok hands over to the senior watch the Vault Watch shift and record handover work related to Yeoui-dong.\n\n**Office.** Rank: Clerk. Title: Vault Duty. She hands over only the keys and records of her own post and creates no authority that does not exist.\n\n**Anecdote.** In 2125, when the vault lock froze, she tied on a rope, climbed down, and wiped the door clean. Because of this, the signature of the Vault Watch post was entered in the ledger.\n\n**Relationships.** Bound by handover to a senior watch from the same living sphere.\n\n**Ambition.** From the vault watch post, keeps the market ledger unbroken.\n\n**Fear.** That if the vault watch falls vacant, the food and fuel tallies in the vault get used in bargains over people held captive.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 30 | Force −35 | Materialism −20 | Community 0 | Principle 25 | Publicity 60 | Qualification 15 | Dispersal 30 | Transformation −5\n- Desires: Craving 30 | Possessiveness −10 | Risk 35 | Display −25 | Persistence 35 | Orientation same-sex | Bonding none\n:::","relations":{"outgoing":[{"from":"I Ba-seok","type":"Contract","to":"Song Jaemin","basis":"I Baseok wipes down the frozen vault door, then informs Song Jaemin of the lock status and the shift handover details. Song Jaemin checks the custody records for each key piece to distinguish mechanical freezing from gaps in the key handover."}],"incoming":[]}}', '{"id":"person-0544","name":"이바석","title":"송신 당직","position":"금고 당직","characterId":"K544","rank":"서기","commonTier":"T5","occupation":"금고 당직 교대·기록 인수","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-09#인물-이바석","detailRoute":"/people/person-0544","birthDate":"2102-06-12","birthday":"06-12","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"frozen-lock","name":"동결 잠금 청소","rating":40}],"traits":[{"id":"frozen-lock-disposition","name":"직접 내려가는 당직","description":"얼어붙은 문을 남의 보고만 기다리지 않고 닦는다.","behavior":"얼어붙은 문을 남의 보고만 기다리지 않고 닦는다.","stress":"","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-handover","name":"경계를 지키는 인계","description":"당직을 잇되 없는 권한을 만들지 않는다.","behavior":"자기 열쇠와 기록만 넘긴다.","stress":"당직 공백이 외부 의존으로 번질 것을 경계한다.","relationship":"선배 당직과 인수인계로 연결된다.","effects":[]}],"narrative":"잠금이 얼자 밧줄을 매고 내려가 문을 닦았다. 짧은 일화와 인계만으로 전문 지휘·전투·제도 성립을 추정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c774-ad11-c8fc-674e","name":"광주 이씨","crest":"clan-crests/c774-ad11-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":30,"무력":-35,"물질":-20,"공동":0,"원칙":25,"공개":60,"자격":15,"분산":30,"변혁":-5},"desire":{"갈망":30,"독점":-10,"위험":35,"과시":-25,"지속":35,"지향":"동성","결합":"없음"},"fields":{"생업":"금고 당직 교대·기록 인수","소속":"자유도시","품계":"서기","직함":"금고 당직","가치관":"권위 −15 | 개방 30 | 무력 −35 | 물질 −20 | 공동 0 | 원칙 25 | 공개 60 | 자격 15 | 분산 30 | 변혁 −5","욕망":"갈망 30 | 독점 −10 | 위험 35 | 과시 −25 | 지속 35 | 지향 동성 | 결합 없음"},"sections":{"생애":"2102-06-12 출생으로 승인된 출생군은 4군이다. 2126년 개막에 활동했다. 여의도 금고 당직에서 자랐다. 금고 당직 자리는 정전 사흘 금고 유지로 열렸다.\n- 이바석은 여의동과 관련한 금고 당직 교대·기록 인수 업무를 선배 당직과 인수인계한다.","관직":"품계 서기. 직함은 금고 당직. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","일화":"2125년 금고 잠금이 얼자 밧줄을 매고 내려가 문을 닦았다. 이 일로 금고 당직 자리의 서명이 장부에 올랐다.","관계":"같은 생활권 선배 당직과 인수인계로 묶인다.","야망":"금고 당직 자리에서 시장 장부를 끊기지 않게 잇는다.","공포":"금고 당직이 비면 금고 안의 식량표와 연료표가 사람을 붙잡는 흥정에 쓰이는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 금고 당직 교대·기록 인수\n- 소속: 자유도시\n- 품계: 서기\n- 직함: 금고 당직\n**생애.** 2102-06-12 출생으로 승인된 출생군은 4군이다. 2126년 개막에 활동했다. 여의도 금고 당직에서 자랐다. 금고 당직 자리는 정전 사흘 금고 유지로 열렸다.\n- 이바석은 여의동과 관련한 금고 당직 교대·기록 인수 업무를 선배 당직과 인수인계한다.\n\n**관직.** 품계 서기. 직함은 금고 당직. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 금고 잠금이 얼자 밧줄을 매고 내려가 문을 닦았다. 이 일로 금고 당직 자리의 서명이 장부에 올랐다.\n\n**관계.** 같은 생활권 선배 당직과 인수인계로 묶인다.\n\n**야망.** 금고 당직 자리에서 시장 장부를 끊기지 않게 잇는다.\n\n**공포.** 금고 당직이 비면 금고 안의 식량표와 연료표가 사람을 붙잡는 흥정에 쓰이는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 30 | 무력 −35 | 물질 −20 | 공동 0 | 원칙 25 | 공개 60 | 자격 15 | 분산 30 | 변혁 −5\n- 욕망: 갈망 30 | 독점 −10 | 위험 35 | 과시 −25 | 지속 35 | 지향 동성 | 결합 없음\n:::","relations":{"outgoing":[{"from":"이바석","type":"계약","to":"송재민","basis":"이바석은 얼어붙은 금고 문을 닦은 뒤 잠금 상태와 당직 인계 내용을 송재민에게 알린다. 송재민은 키 조각별 보관 기록을 확인해 기계 결빙과 열쇠 인수의 공백을 구분한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0545', 'bc15-bc00-c591', '{"id":"person-0545","name":"Bak Dol-yun","title":"Family Herald","position":"Herald","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Herald · Manuscript Handover","gender":"Female","stage":"S4","state":"S10","stateName":"The Government","detailRoute":"/people/person-0545","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0545","name":"박돌윤","title":"가족 전령","position":"전령","rank":"일반 시민","commonTier":"T5","occupation":"전령·필사본 인계","gender":"여성","stage":"S4","state":"S10","stateName":"정부","detailRoute":"/people/person-0545","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0546', 'cd5c-c0ad-b155-5d14', '{"id":"person-0546","name":"Choe Sae-a","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0546","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0546","name":"최새아","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0546","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0547', 'c815-b3d9-b798', '{"id":"person-0547","name":"Jeong Da-eun","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K547","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#person-jeong-daeun","detailRoute":"/people/person-0547","birthDate":"2066-12-01","birthday":"12-01","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k547-escort-signature-reconciliation","name":"Escort signature reconciliation","rating":50}],"traits":[{"id":"k547-priority","name":"Distinguishes actual departures","description":"Jeong Daeun placed conflicting dispatch sheets side by side and used escort signatures to establish actual departures, without declaring a politically superior sheet.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"That if the medicine transport escort duty stood empty, crates and patients could arrive empty-handed from the winter tunnel stretch with no one to check.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k547-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"That if the medicine transport escort duty stood empty, crates and patients could arrive empty-handed from the winter tunnel stretch with no one to check.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Jeong Daeun placed conflicting dispatch sheets side by side and used escort signatures to establish actual departures, without declaring a politically superior sheet.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c815-b3d9-b798","name":"Dongnae Jeong Clan","crest":"clan-crests/c815-b3d9-b798.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":45,"Force":-40,"Material":0,"Communal":15,"Principle":40,"Public":20,"Eligibility":25,"Dispersed":40,"Transformative":5},"desire":{"Longing":15,"Monopoly":0,"Risk":-10,"Display":-10,"Sustained":-10,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −20 | Openness 45 | Force −40 | Materialism 0 | Community 15 | Principle 40 | Publicity 20 | Qualification 25 | Dispersal 40 | Transformation 5","Desires":"Craving 15 | Possessiveness 0 | Risk −10 | Display −10 | Persistence −10 | Orientation none | Bonding non-exclusive"},"sections":{"Life":"Born 2066-12-01. Grew up at the Seoul Station Registry Office. At the opening of 2126 he holds the Medical Escort Recordkeeper watch, and his post handover record retains the entry \"opened by deleting one line from the double ledger.\"\n- A record desk for dispatch, shifts, maintenance, passage review, stretcher handover, and watch keys in Sinnae 1-dong is proposed as the reference point for Jeong Daeun''s medical escort record and watch-key handover duty. It is a proposal to cross-check winter handover records, and it does not confirm running trains, new facilities, armament, tolls, market monopolies, residence, exact facility boundaries, titles, holdings, or possession rights.","Offices":"Rank: Escort. Title: Medical Escort Recorder. He hands over the two conflicting dispatch sheets together with the keys and records of his own watch, making the scope of the handover clear.","Anecdote":"Bak Taegyeom''s Yongsan Escort House dispatch sheet and the Sinnae dispatch sheet list different medical escort runs for the same section. Jeong Daeun copies the relevant columns of the two sheets side by side, identifies the run that actually departed by the escort officer''s signature, and attaches it to the record going to Jang Sehwa. The two conflicting dispatch sheets he left then became the handover standard for the next watch.","Relationships":"He hands the two conflicting dispatch sheets to the senior watch of the same living sphere and checks them against the next shift''s receipt time in the same duty area.","Ambition":"He intends to leave the two conflicting dispatch sheets as a public handover line that the next shift can check again.","Fear":"He fears that the receipt time on the two conflicting dispatch sheets will be left blank and responsibility will be shifted onto the patient and passenger lists.","Intervention":"He can set up a witness for the handover of the two conflicting dispatch sheets, or make public the missing signature fields before the next shift."},"biography":"Born on 2066-12-01, Jeong Daeun first checks the order of two conflicting dispatch sheets. He trusts handover times and signature boxes more than loud voices.\n\n- Livelihood: Medical Escort Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Medical Escort Recorder\n**Life.** Born 2066-12-01. Grew up at the Seoul Station Registry Office. At the opening of 2126 he holds the Medical Escort Recordkeeper watch, and his post handover record retains the entry \"opened by deleting one line from the double ledger.\"\n- A record desk for dispatch, shifts, maintenance, passage review, stretcher handover, and watch keys in Sinnae 1-dong is proposed as the reference point for Jeong Daeun''s medical escort record and watch-key handover duty. It is a proposal to cross-check winter handover records, and it does not confirm running trains, new facilities, armament, tolls, market monopolies, residence, exact facility boundaries, titles, holdings, or possession rights.\n\n**Office.** Rank: Escort. Title: Medical Escort Recorder. He hands over the two conflicting dispatch sheets together with the keys and records of his own watch, making the scope of the handover clear.\n\n**Anecdote.** Bak Taegyeom''s Yongsan Escort House dispatch sheet and the Sinnae dispatch sheet list different medical escort runs for the same section. Jeong Daeun copies the relevant columns of the two sheets side by side, identifies the run that actually departed by the escort officer''s signature, and attaches it to the record going to Jang Sehwa. The two conflicting dispatch sheets he left then became the handover standard for the next watch.\n\n**Relationships.** He hands the two conflicting dispatch sheets to the senior watch of the same living sphere and checks them against the next shift''s receipt time in the same duty area.\n\n**Ambition.** He intends to leave the two conflicting dispatch sheets as a public handover line that the next shift can check again.\n\n**Fear.** He fears that the receipt time on the two conflicting dispatch sheets will be left blank and responsibility will be shifted onto the patient and passenger lists.\n\n**Intervention.** He can set up a witness for the handover of the two conflicting dispatch sheets, or make public the missing signature fields before the next shift.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 45 | Force −40 | Material 0 | Communal 15 | Principle 40 | Publicity 20 | Qualification 25 | Dispersal 40 | Transformation 5\n- Desires: Longing 15 | Monopoly 0 | Risk −10 | Display −10 | Endurance −10 | Orientation: None | Bonding: Non-exclusive\n:::","relations":{"outgoing":[{"from":"Jeong Da-eun","type":"Contract","to":"Jeon Miri","basis":"Jeong Daeun sorts the medical escort runs that diverge between the two dispatch schedules by actual escort signatures and hands them to Jeon Miri. Jeon Miri checks patient severity and transfer times so that a run that never departed is not treated as having handed over arriving patients."}],"incoming":[]}}', '{"id":"person-0547","name":"정다은","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K547","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-정다은","detailRoute":"/people/person-0547","birthDate":"2066-12-01","birthday":"12-01","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k547-escort-signature-reconciliation","name":"호송 서명 대조","rating":50}],"traits":[{"id":"k547-priority","name":"실제 출발을 가림","description":"정다은은 서로 다른 두 배차표를 나란히 옮기고 호송원 서명으로 실제 출발을 가렸다. 어느 표가 정치적으로 우월한지는 단정하지 않는다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"약품 호송 동행 당직이 비면 겨울 터널 구간에서 호송 상자와 환자가 빈 채로 도착해도 확인할 사람이 없게 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k547-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 약품 호송 동행 당직이 비면 겨울 터널 구간에서 호송 상자와 환자가 빈 채로 도착해도 확인할 사람이 없게 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"정다은은 서로 다른 두 배차표를 나란히 옮기고 호송원 서명으로 실제 출발을 가렸다. 어느 표가 정치적으로 우월한지는 단정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c815-b3d9-b798","name":"동래 정씨","crest":"clan-crests/c815-b3d9-b798.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":45,"무력":-40,"물질":0,"공동":15,"원칙":40,"공개":20,"자격":25,"분산":40,"변혁":5},"desire":{"갈망":15,"독점":0,"위험":-10,"과시":-10,"지속":-10,"지향":"무성향","결합":"비독점"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −20 | 개방 45 | 무력 −40 | 물질 0 | 공동 15 | 원칙 40 | 공개 20 | 자격 25 | 분산 40 | 변혁 5","욕망":"갈망 15 | 독점 0 | 위험 −10 | 과시 −10 | 지속 −10 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2066-12-01에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 정다은의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 엇갈린 두 배차표와 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"박태겸의 용산호송가 배차표와 신내 배차표가 같은 구간에 서로 다른 의무호송 편을 올린다. 정다은은 두 배차표의 해당 칸을 나란히 옮기고, 실제로 떠난 편을 호송원 서명으로 가려 장세화에게 갈 기록에 붙인다. 그때 남긴 엇갈린 두 배차표가 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 엇갈린 두 배차표를 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"엇갈린 두 배차표를 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"엇갈린 두 배차표의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"엇갈린 두 배차표의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2066-12-01생인 정다은은 엇갈린 두 배차표의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2066-12-01에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 정다은의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 엇갈린 두 배차표와 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 박태겸의 용산호송가 배차표와 신내 배차표가 같은 구간에 서로 다른 의무호송 편을 올린다. 정다은은 두 배차표의 해당 칸을 나란히 옮기고, 실제로 떠난 편을 호송원 서명으로 가려 장세화에게 갈 기록에 붙인다. 그때 남긴 엇갈린 두 배차표가 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 엇갈린 두 배차표를 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 엇갈린 두 배차표를 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 엇갈린 두 배차표의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 엇갈린 두 배차표의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 45 | 무력 −40 | 물질 0 | 공동 15 | 원칙 40 | 공개 20 | 자격 25 | 분산 40 | 변혁 5\n- 욕망: 갈망 15 | 독점 0 | 위험 −10 | 과시 −10 | 지속 −10 | 지향 무성향 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"정다은","type":"계약","to":"전미리","basis":"정다은은 두 배차표에서 엇갈린 의무호송 편을 실제 호송원 서명으로 가려 전미리에게 넘긴다. 전미리는 환자 중증도와 이송 시각을 확인해, 떠나지 않은 편이 도착할 환자를 인계한 것으로 처리되지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0548', 'ac15-c9c4-c8fc', '{"id":"person-0548","name":"Gang Bayu","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K548","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-gangbayu","detailRoute":"/people/person-0548","birthDate":"2102-03-10","birthday":"03-10","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"Original document custody","rating":40}],"traits":[{"id":"stated-priority","name":"Original compartment before copies","description":"In the forged-seal incident they destroyed copies and protected originals. Recorded custody is kept distinct from unconfirmed sanitation expertise.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"In the forged-seal incident they destroyed copies and protected originals. Recorded custody is kept distinct from unconfirmed sanitation expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":35,"Force":-75,"Material":-30,"Communal":15,"Principle":70,"Public":35,"Eligibility":20,"Dispersed":15,"Transformative":-10},"desire":{"Longing":-10,"Monopoly":25,"Risk":-15,"Display":-10,"Sustained":0,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −20 | Openness 35 | Force −75 | Material −30 | Communal 15 | Principle 70 | Publicity 35 | Qualification 20 | Dispersal 15 | Transformation −10","Desires":"Longing −10 | Monopoly 25 | Risk −15 | Display −10 | Endurance 0 | Orientation: Fluid | Bonding: Non-exclusive"},"sections":{"Life":"Born on 2102-03-10. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty and records. The succession record for that post bears the entry that it was opened by the deletion of one line from a double ledger.\n- The quarantine records and on-duty key handover desk in Jegi-dong is Gang Bayu''s work reference point. This work reference point does not confirm residence, exact facility boundaries, ranks, holdings or possession rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.","Relationships":"Gang Bayu brings the original quarantine records to Ra Seyeong to check a suspicious entry seal. Ra Seyeong examines the quarantine and release records so that quarantined patients are not freed early because of a forged copy, and waits for the temperature and medicinal-efficacy records to arrive.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty. Trusts a single ledger line more than loud voices.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born on 2102-03-10. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty and records. The succession record for that post bears the entry that it was opened by the deletion of one line from a double ledger.\n- The quarantine records and on-duty key handover desk in Jegi-dong is Gang Bayu''s work reference point. This work reference point does not confirm residence, exact facility boundaries, ranks, holdings or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.\n\n**Relationships.** Gang Bayu brings the original quarantine records to Ra Seyeong to check a suspicious entry seal. Ra Seyeong examines the quarantine and release records so that quarantined patients are not freed early because of a forged copy, and waits for the temperature and medicinal-efficacy records to arrive.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 35 | Force −75 | Material −30 | Communal 15 | Principle 70 | Publicity 35 | Qualification 20 | Dispersal 15 | Transformation −10\n- Desires: Longing −10 | Monopoly 25 | Risk −15 | Display −10 | Endurance 0 | Orientation: Fluid | Bonding: Non-exclusive\n:::","relations":{"outgoing":[{"from":"Gang Bayu","type":"Contract","to":"Ra Seyeong","basis":"Gang Bayu brings the original quarantine records to Ra Seyeong to check a suspicious entry seal. Ra Seyeong examines the quarantine and release records so that quarantined patients are not freed early because of a forged copy, and waits for the temperature and medicinal-efficacy records to arrive."}],"incoming":[]}}', '{"id":"person-0548","name":"강바유","title":"방역 기록관","position":"방역 구호원","characterId":"K548","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-강바유","detailRoute":"/people/person-0548","birthDate":"2102-03-10","birthday":"03-10","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"원본 보관","rating":40}],"traits":[{"id":"stated-priority","name":"사본보다 원본 칸","description":"위조 도장 사건에서 사본을 없애고 원본 칸을 남겼다. 확인된 보관 행동과 미확인 방역 기술을 구분한다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"위조 도장 사건에서 사본을 없애고 원본 칸을 남겼다. 확인된 보관 행동과 미확인 방역 기술을 구분한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ac15-c9c4-c8fc","name":"진주 강씨","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":35,"무력":-75,"물질":-30,"공동":15,"원칙":70,"공개":35,"자격":20,"분산":15,"변혁":-10},"desire":{"갈망":-10,"독점":25,"위험":-15,"과시":-10,"지속":0,"지향":"유동","결합":"비독점"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −20 | 개방 35 | 무력 −75 | 물질 −30 | 공동 15 | 원칙 70 | 공개 35 | 자격 20 | 분산 15 | 변혁 −10","욕망":"갈망 −10 | 독점 25 | 위험 −15 | 과시 −10 | 지속 0 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2102-03-10에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 강바유의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"강바유는 방역 기록 원본을 라세영에게 가져가 의심스러운 출입 날인을 확인한다. 라세영은 격리와 해제 기록을 살펴 위조 사본 때문에 격리 환자가 먼저 풀려나지 않게 하고 체온·약효 기록의 도착을 기다린다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2102-03-10에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 강바유의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 강바유는 방역 기록 원본을 라세영에게 가져가 의심스러운 출입 날인을 확인한다. 라세영은 격리와 해제 기록을 살펴 위조 사본 때문에 격리 환자가 먼저 풀려나지 않게 하고 체온·약효 기록의 도착을 기다린다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 35 | 무력 −75 | 물질 −30 | 공동 15 | 원칙 70 | 공개 35 | 자격 20 | 분산 15 | 변혁 −10\n- 욕망: 갈망 −10 | 독점 25 | 위험 −15 | 과시 −10 | 지속 0 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"강바유","type":"계약","to":"라세영","basis":"강바유는 방역 기록 원본을 라세영에게 가져가 의심스러운 출입 날인을 확인한다. 라세영은 격리와 해제 기록을 살펴 위조 사본 때문에 격리 환자가 먼저 풀려나지 않게 하고 체온·약효 기록의 도착을 기다린다."}],"incoming":[]}}');
