INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0563', 'ace0-d55c-c591', '{"id":"person-0563","name":"Go Haho","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0563","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0563","name":"고하호","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0563","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0564', 'bb38-b0a8-d3c9-6587', '{"id":"person-0564","name":"Mun Dongeun","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Management Relief Worker","characterId":"K564","rank":"Relief Worker","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-mun-dong-eun","detailRoute":"/people/person-0564","birthDate":"2100-02-01","birthday":"02-01","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"Emergency bleeding control","rating":55}],"traits":[{"id":"stated-priority","name":"Continues care in darkness","description":"Emergency bleeding control continued with phone lighting after power failed. Actual apprentice performance is recognized without granting independent medical status.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Emergency bleeding control continued with phone lighting after power failed. Actual apprentice performance is recognized without granting independent medical status.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":40,"Force":-60,"Material":10,"Communal":25,"Principle":25,"Public":20,"Eligibility":25,"Dispersed":15,"Transformative":-10},"desire":{"Longing":0,"Monopoly":-30,"Risk":-30,"Display":-25,"Sustained":25,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −25 | Openness 40 | Force −60 | Materialism 10 | Communality 25 | Principle 25 | Publicity 20 | Qualification 25 | Decentralization 15 | Transformation −10","Desires":"Craving 0 | Possessiveness −30 | Risk −30 | Display −25 | Endurance 25 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Born on 2100-02-01. As of the opening of 2126, holds the post of Medicinal Supply Logistician and continues the existing watch and records. In the succession record of that post, it was opened by a counterfeit medicine seal.\n- The Jegi-dong medicinal herb management records and watch-key handover desk is Mun Dongeun''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, when the power went out during emergency care, continued stanching the bleeding by the light of a handheld phone. That day''s record remained as the handover basis for the next shift to verify.","Relationships":"Mun Dongeun informs Su Hyoeun of the herbs used in emergency care and their storage condition after the blackout. Su Hyoeun checks the fuel remainder and output log to review the supply to the drying room and clinic, and Mun Dongeun records in the management log that damaged herbs must not be mixed into later treatment.","Ambition":"From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger over loud voices.\n\n- Livelihood: Medicinal Supplies Management Records & Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicinal Supplies Logistics Merchant\n**Life.** Born on 2100-02-01. As of the opening of 2126, holds the post of Medicinal Supply Logistician and continues the existing watch and records. In the succession record of that post, it was opened by a counterfeit medicine seal.\n- The Jegi-dong medicinal herb management records and watch-key handover desk is Mun Dongeun''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.\n\n**Anecdote.** In 2125, when the power went out during emergency care, continued stanching the bleeding by the light of a handheld phone. That day''s record remained as the handover basis for the next shift to verify.\n\n**Relationships.** Mun Dongeun informs Su Hyoeun of the herbs used in emergency care and their storage condition after the blackout. Su Hyoeun checks the fuel remainder and output log to review the supply to the drying room and clinic, and Mun Dongeun records in the management log that damaged herbs must not be mixed into later treatment.\n\n**Ambition.** From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.\n\n**Fear.** Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 40 | Force −60 | Materialism 10 | Communality 25 | Principle 25 | Publicity 20 | Qualification 25 | Decentralization 15 | Transformation −10\n- Desires: Craving 0 | Possessiveness −30 | Risk −30 | Display −25 | Endurance 25 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Mun Dongeun","type":"Contract","to":"Su Hyoeun","basis":"Mun Dongeun informs Su Hyoeun of the herbs used in emergency care and their storage condition after the blackout. Su Hyoeun checks the fuel remainder and output log to review the supply to the drying room and clinic, and Mun Dongeun records in the management log that damaged herbs must not be mixed into later treatment."}],"incoming":[]}}', '{"id":"person-0564","name":"문동은","title":"약재 물류상","position":"약재 관리 구호원","characterId":"K564","rank":"구호원","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-문동은","detailRoute":"/people/person-0564","birthDate":"2100-02-01","birthday":"02-01","age":26,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"응급 지혈 수행","rating":55}],"traits":[{"id":"stated-priority","name":"어두워져도 치료를 잇는다","description":"응급 처치 중 정전에도 휴대전화 불빛으로 작업을 계속했다. 구호원의 실제 수행은 인정하되 독립 응급처치원 수준으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"응급 처치 중 정전에도 휴대전화 불빛으로 작업을 계속했다. 구호원의 실제 수행은 인정하되 독립 응급처치원 수준으로 확대하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":40,"무력":-60,"물질":10,"공동":25,"원칙":25,"공개":20,"자격":25,"분산":15,"변혁":-10},"desire":{"갈망":0,"독점":-30,"위험":-30,"과시":-25,"지속":25,"지향":"유동","결합":"비독점"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약재 물류상","가치관":"권위 −25 | 개방 40 | 무력 −60 | 물질 10 | 공동 25 | 원칙 25 | 공개 20 | 자격 25 | 분산 15 | 변혁 −10","욕망":"갈망 0 | 독점 −30 | 위험 −30 | 과시 −25 | 지속 25 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2100-02-01에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 문동은의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"문동은은 응급 처치 때 쓴 약재와 정전 뒤의 보관 상태를 수효은에게 알린다. 수효은은 연료 잔량과 출력 일지를 확인해 건조실·진료소 공급을 살피고, 문동은은 손상된 약재가 다음 진료에 섞이지 않도록 관리 기록에 남긴다.","야망":"약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약재 물류상\n**생애.** 2100-02-01에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 문동은의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 문동은은 응급 처치 때 쓴 약재와 정전 뒤의 보관 상태를 수효은에게 알린다. 수효은은 연료 잔량과 출력 일지를 확인해 건조실·진료소 공급을 살피고, 문동은은 손상된 약재가 다음 진료에 섞이지 않도록 관리 기록에 남긴다.\n\n**야망.** 약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 40 | 무력 −60 | 물질 10 | 공동 25 | 원칙 25 | 공개 20 | 자격 25 | 분산 15 | 변혁 −10\n- 욕망: 갈망 0 | 독점 −30 | 위험 −30 | 과시 −25 | 지속 25 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"문동은","type":"계약","to":"수효은","basis":"문동은은 응급 처치 때 쓴 약재와 정전 뒤의 보관 상태를 수효은에게 알린다. 수효은은 연료 잔량과 출력 일지를 확인해 건조실·진료소 공급을 살피고, 문동은은 손상된 약재가 다음 진료에 섞이지 않도록 관리 기록에 남긴다."}],"incoming":[]}}');
