INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0566', 'c190-bc00-c591', '{"id":"person-0566","name":"Son Byeolyeon","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0566","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0566","name":"손별연","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"일반 시민","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0566","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
