INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0588', 'ac15-c9c4-c8fc', '{"id":"person-0588","name":"Gang Geumyu","title":"Passage Sentry Duty","position":"Passage Sentry Duty","rank":"Guard","commonTier":"T5","occupation":"Passage guard and kidnap watch","gender":"Female","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0588","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0588","name":"강금유","title":"통로 보초 담당","position":"통로 보초 담당","rank":"경비대원","commonTier":"T5","occupation":"통로 보초·납치 경계","gender":"여성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0588","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0589', 'c870-c625-cc9c-8d99', '{"id":"person-0589","name":"Jo Seowon","title":"Copy Herald","position":"Copy Herald","characterId":"K589","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Flooded Section Collapse Report and Closure","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#inmul-joseowon","detailRoute":"/people/person-0589","birthDate":"2068-09-06","birthday":"09-06","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":8,"effective":8},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k589-flood-closure","name":"Flood section closure","rating":45}],"traits":[{"id":"k589-choice","name":"Closes dangerous sections promptly","description":"Anecdote. In 2125 he did not sit on the collapse report of a flooded section and closed it on the spot. By this deed the signature of the copy courier post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125 he did not sit on the collapse report of a flooded section and closed it on the spot. By this deed the signature of the copy courier post rose into the ledger.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k589-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125 he did not sit on the collapse report of a flooded section and closed it on the spot. By this deed the signature of the copy courier post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28245-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K589","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28245-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"Jo Clan of Okcheon","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":5,"Force":-30,"Material":-25,"Communal":15,"Principle":45,"Public":-10,"Eligibility":5,"Dispersed":-30,"Transformative":-40},"desire":{"Longing":0,"Monopoly":-5,"Risk":-5,"Display":-20,"Sustained":25,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Livelihood":"Flooded Section Collapse Report and Closure","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Copy Herald","Values":"Authority 15 | Openness 5 | Force −30 | Materialism −25 | Communal 15 | Principle 45 | Publicity −10 | Qualification 5 | Decentralization −30 | Transformation −40","Desires":"Craving 0 | Monopoly −5 | Risk −5 | Display −20 | Persistence 25 | Orientation Bisexual | Bonding Non-exclusive"},"sections":{"Life":"Grew up on the Sinnae transfer duty. The Copy Courier post opened because of a stop put to a ticketless departing train.\n- Jo Seowon''s flooded-section collapse reporting and closure work is tied to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.","Anecdote":"In 2125 he did not put off the report of a flooded-section collapse and closed the section immediately. Because of this, the signature of the Copy Courier post was entered in the ledger.","Relationships":"Through the handover of the flooded-section collapse reporting and closure work, he is linked to senior duty officers in the same living sphere.","Ambition":"From the Copy Courier post, he carries on the flooded-section collapse reporting and closure records so that the Seoul Metropolitan Local Civil Service''s ledger is not broken between duty shifts.","Fear":"","Intervention":"He can bring in a witness to the duty handover of the flooded-section collapse reporting and closure work, or expose the empty key of that post."},"biography":"Rather than delay the collapse report and pass the duty along, he chooses to leave a closure record. Loud talk cannot take the place of one line of report.\n\n- Livelihood: Flooded Section Collapse Report and Closure\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Copy Herald\n**Life.** Grew up on the Sinnae transfer duty. The Copy Courier post opened because of a stop put to a ticketless departing train.\n- Jo Seowon''s flooded-section collapse reporting and closure work is tied to Jongno 1·2·3·4-ga-dong.\n\n**Civil Servant Position and Grade.** A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.\n\n**Anecdote.** In 2125 he did not put off the report of a flooded-section collapse and closed the section immediately. Because of this, the signature of the Copy Courier post was entered in the ledger.\n\n**Relationships.** Through the handover of the flooded-section collapse reporting and closure work, he is linked to senior duty officers in the same living sphere.\n\n**Ambition.** From the Copy Courier post, he carries on the flooded-section collapse reporting and closure records so that the Seoul Metropolitan Local Civil Service''s ledger is not broken between duty shifts.\n\n**Intervention.** He can bring in a witness to the duty handover of the flooded-section collapse reporting and closure work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness 5 | Force −30 | Materialism −25 | Communal 15 | Principle 45 | Publicity −10 | Qualification 5 | Decentralization −30 | Transformation −40\n- Desires: Craving 0 | Monopoly −5 | Risk −5 | Display −20 | Persistence 25 | Orientation Bisexual | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Jo Seowon","type":"Contract","to":"Seo Ra-on","basis":"Jo Seowon relays news of the closure of the flooded, collapsed section to Seo Raon. Seo Raon checks the field survey and the bulletin together to update the map, and leaves unconfirmed detour roads as dotted lines."}],"incoming":[]}}', '{"id":"person-0589","name":"조서원","title":"사본 전령","position":"사본 전령","characterId":"K589","rank":"일반 시민","commonTier":"T3","occupation":"침수 구간 붕괴 보고·폐쇄","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-조서원","detailRoute":"/people/person-0589","birthDate":"2068-09-06","birthday":"09-06","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":8,"effective":8},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k589-flood-closure","name":"침수 구간 폐쇄","rating":45}],"traits":[{"id":"k589-choice","name":"위험 구간 즉시 닫음","description":"일화. 2125년 침수 구간 붕괴 보고를 미루지 않고 당장 폐쇄했다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 침수 구간 붕괴 보고를 미루지 않고 당장 폐쇄했다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k589-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 침수 구간 붕괴 보고를 미루지 않고 당장 폐쇄했다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28245-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K589","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28245-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"옥천 조씨","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":5,"무력":-30,"물질":-25,"공동":15,"원칙":45,"공개":-10,"자격":5,"분산":-30,"변혁":-40},"desire":{"갈망":0,"독점":-5,"위험":-5,"과시":-20,"지속":25,"지향":"양성","결합":"비독점"},"fields":{"생업":"침수 구간 붕괴 보고·폐쇄","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"사본 전령","가치관":"권위 15 | 개방 5 | 무력 −30 | 물질 −25 | 공동 15 | 원칙 45 | 공개 −10 | 자격 5 | 분산 −30 | 변혁 −40","욕망":"갈망 0 | 독점 −5 | 위험 −5 | 과시 −20 | 지속 25 | 지향 양성 | 결합 비독점"},"sections":{"생애":"신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 조서원의 침수 구간 붕괴 보고·폐쇄 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.","일화":"2125년 침수 구간 붕괴 보고를 미루지 않고 당장 폐쇄했다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","관계":"침수 구간 붕괴 보고·폐쇄 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"사본 전령 자리에서 침수 구간 붕괴 보고·폐쇄 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"","개입":"침수 구간 붕괴 보고·폐쇄 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"붕괴 보고를 미뤄 당직을 넘기기보다 폐쇄 기록을 남기는 쪽을 고른다. 큰소리는 보고 한 줄을 대신하지 못한다.\n\n- 생업: 침수 구간 붕괴 보고·폐쇄\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 사본 전령\n**생애.** 신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 조서원의 침수 구간 붕괴 보고·폐쇄 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.\n\n**일화.** 2125년 침수 구간 붕괴 보고를 미루지 않고 당장 폐쇄했다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 침수 구간 붕괴 보고·폐쇄 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 사본 전령 자리에서 침수 구간 붕괴 보고·폐쇄 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**개입.** 침수 구간 붕괴 보고·폐쇄 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 5 | 무력 −30 | 물질 −25 | 공동 15 | 원칙 45 | 공개 −10 | 자격 5 | 분산 −30 | 변혁 −40\n- 욕망: 갈망 0 | 독점 −5 | 위험 −5 | 과시 −20 | 지속 25 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"조서원","type":"계약","to":"서라온","basis":"조서원은 침수 붕괴 구간의 폐쇄 소식을 서라온에게 전달한다. 서라온은 현장 측량과 속보를 함께 확인해 지도를 갱신하고, 확인되지 않은 우회 도로는 점선으로 남긴다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0590', NULL, '{"id":"person-0590","name":"Juliana Reed","title":"Relay Duty","position":"Relay Duty","rank":"Clerk","commonTier":"T5","occupation":"Spare Battery Rotation & Transmission Upkeep","gender":"Female","stage":"S4","state":"S07","stateName":"The Government","detailRoute":"/people/person-0590","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0590","name":"줄리아나 리드","title":"중계 당직","position":"중계 당직","rank":"주사","commonTier":"T5","occupation":"예비 전지 교대·송신 유지","gender":"여성","stage":"S4","state":"S07","stateName":"정부","detailRoute":"/people/person-0590","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
