INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0608', 'bc31-c218-c6d0', '{"id":"person-0608","name":"Baek Garae","title":"Antenna Technician","position":"Vault Technician","rank":"Clerk","commonTier":"T5","occupation":"Vault Equipment Inspection & Maintenance","gender":"Female","stage":"S4","state":"S09","stateName":"Free City","detailRoute":"/people/person-0608","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0608","name":"백가래","title":"안테나 정비사","position":"금고 정비사","rank":"서기","commonTier":"T5","occupation":"금고 설비 점검·정비","gender":"여성","stage":"S4","state":"S09","stateName":"자유도시","detailRoute":"/people/person-0608","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}');
