INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0610', 'c720-ac15-b989', '{"id":"person-0610","name":"Yu Sahun","title":"Wheel Technician","position":"Arc Wheel Technician","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Arc Wheel Maintenance Records & Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0610","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0610","name":"유사훈","title":"차륜 정비사","position":"Arc 차륜 정비사","rank":"일반 시민","commonTier":"T5","occupation":"Arc 차륜 정비 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0610","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0611', 'b0a8-c758-b839', '{"id":"person-0611","name":"Nam Chawon","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0611","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0611","name":"남차원","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0611","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0612', 'c2ec-ccad-c1a1', '{"id":"person-0612","name":"Sim Pahyeon","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Management Relief Worker","characterId":"K612","rank":"Relief Worker","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-sim pahyeon","detailRoute":"/people/person-0612","birthDate":"2084-02-08","birthday":"02-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"Home visits during isolation","rating":50}],"traits":[{"id":"stated-priority","name":"Isolation alongside home visits","description":"Isolation and continued home visits appear together in the record. Evidence is confined to this care decision rather than the whole medicine-management role.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Isolation and continued home visits appear together in the record. Evidence is confined to this care decision rather than the whole medicine-management role.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":25,"Force":-60,"Material":-5,"Communal":25,"Principle":25,"Public":15,"Eligibility":25,"Dispersed":15,"Transformative":0},"desire":{"Longing":-5,"Monopoly":-10,"Risk":40,"Display":-5,"Sustained":15,"Orientation":"Fluid","Union":"None"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −10 | Openness 25 | Force −60 | Materialism −5 | Community 25 | Principle 25 | Publicity 15 | Qualification 25 | Decentralization 15 | Transformation 0","Desires":"Longing −5 | Monopoly −10 | Risk 40 | Display −5 | Persistence 15 | Orientation: fluid | Bonding: none"},"sections":{"Life":"Born on 2084-02-08. As of the 2126 opening, holds the post of Medicinal Supply Merchant, continuing the existing watches and records. The succession record for that post opened with a counterfeit medicine seal.\n- The medicinal supply management records and watch-key handover desk in Jegi-dong is Sim Pahyeon''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, kept a suspected-contagion patient in an isolation compartment and never stopped making house calls. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Sim Pahyeon continues treating patients in the quarantine ward and hands the medicine management and entry records over to Ra Seyeong. Ra Seyeong checks the quarantine seal and release records so that the fact that house calls continued is not mistaken for a quarantine release.","Ambition":"From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger over loud talk.\n\n- Livelihood: Medicinal Supplies Management Records & Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicinal Supplies Logistics Merchant\n**Life.** Born on 2084-02-08. As of the 2126 opening, holds the post of Medicinal Supply Merchant, continuing the existing watches and records. The succession record for that post opened with a counterfeit medicine seal.\n- The medicinal supply management records and watch-key handover desk in Jegi-dong is Sim Pahyeon''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.\n\n**Anecdote.** In 2125, kept a suspected-contagion patient in an isolation compartment and never stopped making house calls. That day''s record remained as a handover basis for the next duty shift to verify.\n\n**Relations.** Sim Pahyeon continues treating patients in the quarantine ward and hands the medicine management and entry records over to Ra Seyeong. Ra Seyeong checks the quarantine seal and release records so that the fact that house calls continued is not mistaken for a quarantine release.\n\n**Ambition.** From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.\n\n**Fear.** Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −10 | Openness 25 | Force −60 | Materialism −5 | Community 25 | Principle 25 | Publicity 15 | Qualification 25 | Decentralization 15 | Transformation 0\n- Desires: Craving −5 | Monopoly −10 | Risk 40 | Display −5 | Persistence 15 | Orientation Fluid | Bonding None\n:::","relations":{"outgoing":[{"from":"Sim Pahyeon","type":"Contract","to":"Ra Seyeong","basis":"Sim Pahyeon continues treating patients in the quarantine ward and hands the medicine management and entry records over to Ra Seyeong. Ra Seyeong checks the quarantine seal and release records so that the fact that house calls continued is not mistaken for a quarantine release."}],"incoming":[]}}', '{"id":"person-0612","name":"심파현","title":"약재 물류상","position":"약재 관리 구호원","characterId":"K612","rank":"구호원","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-심파현","detailRoute":"/people/person-0612","birthDate":"2084-02-08","birthday":"02-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"격리 중 왕진","rating":50}],"traits":[{"id":"stated-priority","name":"격리와 왕진을 함께","description":"의심 환자의 격리와 왕진 지속이 함께 기록돼 있다. 약재 관리 전반보다 이 돌봄 선택에 근거를 한정한다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"의심 환자의 격리와 왕진 지속이 함께 기록돼 있다. 약재 관리 전반보다 이 돌봄 선택에 근거를 한정한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":25,"무력":-60,"물질":-5,"공동":25,"원칙":25,"공개":15,"자격":25,"분산":15,"변혁":0},"desire":{"갈망":-5,"독점":-10,"위험":40,"과시":-5,"지속":15,"지향":"유동","결합":"없음"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약재 물류상","가치관":"권위 −10 | 개방 25 | 무력 −60 | 물질 −5 | 공동 25 | 원칙 25 | 공개 15 | 자격 25 | 분산 15 | 변혁 0","욕망":"갈망 −5 | 독점 −10 | 위험 40 | 과시 −5 | 지속 15 | 지향 유동 | 결합 없음"},"sections":{"생애":"2084-02-08에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 심파현의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"심파현은 격리 칸의 환자 진료를 이어가며 약재 관리와 출입 기록을 라세영에게 넘긴다. 라세영은 격리 도장과 해제 기록을 확인해 왕진이 계속된 사실을 격리 해제로 오인하지 않게 한다.","야망":"약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약재 물류상\n**생애.** 2084-02-08에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 심파현의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 심파현은 격리 칸의 환자 진료를 이어가며 약재 관리와 출입 기록을 라세영에게 넘긴다. 라세영은 격리 도장과 해제 기록을 확인해 왕진이 계속된 사실을 격리 해제로 오인하지 않게 한다.\n\n**야망.** 약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 25 | 무력 −60 | 물질 −5 | 공동 25 | 원칙 25 | 공개 15 | 자격 25 | 분산 15 | 변혁 0\n- 욕망: 갈망 −5 | 독점 −10 | 위험 40 | 과시 −5 | 지속 15 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"심파현","type":"계약","to":"라세영","basis":"심파현은 격리 칸의 환자 진료를 이어가며 약재 관리와 출입 기록을 라세영에게 넘긴다. 라세영은 격리 도장과 해제 기록을 확인해 왕진이 계속된 사실을 격리 해제로 오인하지 않게 한다."}],"incoming":[]}}');
