INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0625', 'bc15-bc00-c591', '{"id":"person-0625","name":"Bak Geumeun","title":"Refugee Recorder","position":"Records Transcriber","characterId":"K625","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Transcribed Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#person-bak-geumeun","detailRoute":"/people/person-0625","birthDate":"2084-05-08","birthday":"05-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"provenance-copy","name":"Relief-provenance transcription","rating":50}],"traits":[{"id":"provenance-copy-disposition","name":"Refugee Recorder","description":"Title: Refugee Recorder.","behavior":"Title: Refugee Recorder.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"recorded-boundary","name":"Refugee Recorder","description":"Title: Refugee Recorder.","behavior":"Title: Refugee Recorder.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Title: Refugee Recorder.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-65,"Openness":60,"Force":-50,"Material":-15,"Communal":90,"Principle":40,"Public":45,"Eligibility":40,"Dispersed":45,"Transformative":-10},"desire":{"Longing":35,"Monopoly":-5,"Risk":-20,"Display":-10,"Sustained":25,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Livelihood":"Transcribed Records and Duty Keys Handover","Affiliation":"The Government","Rank":"Ordinary Citizen","Title":"Records Transcriber","Values":"Authority −65 | Openness 60 | Force −50 | Materialism −15 | Community 90 | Principle 40 | Publicity 45 | Qualification 40 | Decentralization 45 | Transformation −10","Desires":"Craving 35 | Monopoly −5 | Risk −20 | Display −10 | Persistence 25 | Orientation None | Bonding Non-monopolistic"},"sections":{"Life":"Born 2084-05-08, active at the 2126 opening. Grew up at the Seoul Station registry office. The duty log of the Records Copyist records the deletion of one line from a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Bak Geumeun''s records copies and duty-key handover. It does not confirm current posting, residence, holding, or ownership.","Offices":"Rank: Ordinary Citizen. Title: Records Transcriber. He hands over only the keys and transcripts of his own duty and creates no authority that he does not have. He takes orders only from his own duty superior.","Anecdote":"","Relationships":"Bak Geumeun learned the key handover order from a senior on duty in the same living area.","Ambition":"","Fear":"","Intervention":""},"biography":"- Livelihood: Transcribed Records and Duty Keys Handover\n- Affiliation: The Government\n- Rank: Ordinary Citizen\n- Title: Records Transcriber\n**Life.** Born 2084-05-08, active at the 2126 opening. Grew up at the Seoul Station registry office. The duty log of the Records Copyist records the deletion of one line from a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Bak Geumeun''s records copies and duty-key handover. It does not confirm current posting, residence, holding, or ownership.\n\n**Office.** Rank: Ordinary Citizen. Title: Records Transcriber. He hands over only the keys and transcripts of his own duty and creates no authority that he does not have. He takes orders only from his own duty superior.\n\n**Relationships.** Bak Geumeun learned the key handover order from a senior on duty in the same living area.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −65 | Openness 60 | Force −50 | Material −15 | Communal 90 | Principle 40 | Transparency 45 | Qualification 40 | Decentralization 45 | Transformation −10\n- Desires: Craving 35 | Monopoly −5 | Risk −20 | Display −10 | Persistence 25 | Orientation None | Bonding Non-monopolistic\n:::","relations":{"outgoing":[{"from":"Bak Geumeun","type":"Contract","to":"Yun Choa","basis":""}],"incoming":[]}}', '{"id":"person-0625","name":"박금은","title":"피난 기록관","position":"기록 필사원","characterId":"K625","rank":"일반 시민","commonTier":"T5","occupation":"기록 필사본·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-박금은","detailRoute":"/people/person-0625","birthDate":"2084-05-08","birthday":"05-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"provenance-copy","name":"구호 출처 필사","rating":50}],"traits":[{"id":"provenance-copy-disposition","name":"피난 기록관","description":"직함은 피난 기록관.","behavior":"직함은 피난 기록관.","stress":"","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"recorded-boundary","name":"피난 기록관","description":"직함은 피난 기록관.","behavior":"직함은 피난 기록관.","stress":"","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"직함은 피난 기록관.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-65,"개방":60,"무력":-50,"물질":-15,"공동":90,"원칙":40,"공개":45,"자격":40,"분산":45,"변혁":-10},"desire":{"갈망":35,"독점":-5,"위험":-20,"과시":-10,"지속":25,"지향":"무성향","결합":"비독점"},"fields":{"생업":"기록 필사본·당직 열쇠 인계","소속":"정부","품계":"일반 시민","직함":"기록 필사원","가치관":"권위 −65 | 개방 60 | 무력 −50 | 물질 −15 | 공동 90 | 원칙 40 | 공개 45 | 자격 40 | 분산 45 | 변혁 −10","욕망":"갈망 35 | 독점 −5 | 위험 −20 | 과시 −10 | 지속 25 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2084-05-08 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 기록 필사원 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 박금은의 기록 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 일반 시민. 직함은 기록 필사원. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 지시는 자기 당직의 상관에게서만 받는다.","일화":"","관계":"박금은은 같은 생활권의 선배 당직에게서 열쇠 인계 순서를 배웠다.","야망":"","공포":"","개입":""},"biography":"- 생업: 기록 필사본·당직 열쇠 인계\n- 소속: 정부\n- 품계: 일반 시민\n- 직함: 기록 필사원\n**생애.** 2084-05-08 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 기록 필사원 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 박금은의 기록 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 일반 시민. 직함은 기록 필사원. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 지시는 자기 당직의 상관에게서만 받는다.\n\n**관계.** 박금은은 같은 생활권의 선배 당직에게서 열쇠 인계 순서를 배웠다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −65 | 개방 60 | 무력 −50 | 물질 −15 | 공동 90 | 원칙 40 | 공개 45 | 자격 40 | 분산 45 | 변혁 −10\n- 욕망: 갈망 35 | 독점 −5 | 위험 −20 | 과시 −10 | 지속 25 | 지향 무성향 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"박금은","type":"계약","to":"윤초아","basis":""}],"incoming":[]}}');
