INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0636', 'c2e0-d3c9-c0b0', '{"id":"person-0636","name":"Sin Kabin","title":"Fuel and Food Counting","position":"Fuel and Food Counting","rank":"Guard","commonTier":"T5","occupation":"Counting winter fuel and food stock","gender":"Female","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0636","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0636","name":"신카빈","title":"연료·식량 계수 담당","position":"연료·식량 계수 담당","rank":"경비대원","commonTier":"T5","occupation":"겨울 연료·식량 재고 세기","gender":"여성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0636","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0637', 'ad8c-c548-b3d9', '{"id":"person-0637","name":"Gwon Harin","title":"Copy Herald","position":"Copy Herald","characterId":"K637","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Clearing Snow from the Transfer Passage and Evacuating the Wounded","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#Person-Gwon-Harin","detailRoute":"/people/person-0637","birthDate":"2085-11-12","birthday":"11-12","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k637-snow-transfer","name":"Snow clearance and injured transfer","rating":50}],"traits":[{"id":"k637-choice","name":"Moves the injured first","description":"Anecdote. In 2125 she broke open the snow-blocked transfer passage and moved the injured first. By this deed the signature of the copy courier post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125 she broke open the snow-blocked transfer passage and moved the injured first. By this deed the signature of the copy courier post rose into the ledger.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k637-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125 she broke open the snow-blocked transfer passage and moved the injured first. By this deed the signature of the copy courier post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41281-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41281-S06","directLiegePersonId":"K1007"}],"directOwnership":false},{"id":"title:barony-gu-41285-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41285-S06","directLiegePersonId":"K1007"}],"directOwnership":false},{"id":"title:barony-gu-41287-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41287-S06","directLiegePersonId":"K1007"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":10,"Force":-30,"Material":-35,"Communal":5,"Principle":40,"Public":-15,"Eligibility":20,"Dispersed":-25,"Transformative":-30},"desire":{"Longing":-5,"Monopoly":10,"Risk":15,"Display":-20,"Sustained":40,"Orientation":"Fluid","Union":"None"},"fields":{"Livelihood":"Clearing Snow from the Transfer Passage and Evacuating the Wounded","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Copy Herald","Values":"Authority 15 | Openness 10 | Force −30 | Material −35 | Communal 5 | Principle 40 | Transparency −15 | Qualification 20 | Decentralization −25 | Transformation −30","Desires":"Craving −5 | Monopoly 10 | Risk 15 | Display −20 | Persistence 40 | Orientation Fluid | Bonding None"},"sections":{"Life":"Grew up at the Sinnae transfer duty. The Copy Courier post opened through stopping a train departing without tickets.\n- Gwon Harin''s transfer-passage snow removal and injured-transport work is connected to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.","Anecdote":"In 2125, cleared a transfer passage blocked by heavy snow and moved the injured first. Because of this, the signature for the Copy Courier post was entered in the ledger.","Relationships":"Through the handover of the transfer-passage snow removal and injured-transport work, is connected to a senior on duty in the same living area.","Ambition":"To continue the transfer-passage snow removal and injured-transport records from the Copy Courier post, so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between duty shifts.","Fear":"","Intervention":"Can bring in a witness to the duty handover of the transfer-passage snow removal and injured-transport work, or expose an empty key of that post."},"biography":"Chooses not to let go of the injured and the records even when snow blocks the passage. Trusts a duty that continues over loud talk.\n\n- Livelihood: Clearing Snow from the Transfer Passage and Evacuating the Wounded\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Copy Herald\n**Life.** Grew up at the Sinnae transfer duty. The Copy Courier post opened through stopping a train departing without tickets.\n- Gwon Harin''s transfer-passage snow removal and injured-transport work is connected to Jongno 1·2·3·4-ga-dong.\n\n**Civil Servant Position·Grade.** A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.\n\n**Anecdote.** In 2125, cleared a transfer passage blocked by heavy snow and moved the injured first. Because of this, the signature for the Copy Courier post was entered in the ledger.\n\n**Relationships.** Through the handover of the transfer-passage snow removal and injured-transport work, is connected to a senior on duty in the same living area.\n\n**Ambition.** To continue the transfer-passage snow removal and injured-transport records from the Copy Courier post, so that the ledger of the Seoul Metropolitan Government Local Civil Servants Organization does not break between duty shifts.\n\n**Intervention.** Can bring in a witness to the duty handover of the transfer-passage snow removal and injured-transport work, or expose an empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness 10 | Force −30 | Material −35 | Communal 5 | Principle 40 | Transparency −15 | Qualification 20 | Decentralization −25 | Transformation −30\n- Desires: Craving −5 | Monopoly 10 | Risk 15 | Display −20 | Persistence 40 | Orientation Fluid | Bonding None\n:::","relations":{"outgoing":[{"from":"Gwon Harin","type":"Contract","to":"Yeon Jiu","basis":"Gwon Harin hands over the wounded she carried from the cleared transfer passage to Yeon Jiu. Yeon Jiu checks their breathing and severity, assigns beds, and does not push slow-moving patients aside through administrative records alone."}],"incoming":[]}}', '{"id":"person-0637","name":"권하린","title":"사본 전령","position":"사본 전령","characterId":"K637","rank":"일반 시민","commonTier":"T3","occupation":"환승 통로 제설·부상자 이송","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-권하린","detailRoute":"/people/person-0637","birthDate":"2085-11-12","birthday":"11-12","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k637-snow-transfer","name":"제설과 부상자 이송","rating":50}],"traits":[{"id":"k637-choice","name":"부상자 먼저 이송","description":"일화. 2125년 폭설에 막힌 환승 통로를 뚫어 부상자를 먼저 옮겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 폭설에 막힌 환승 통로를 뚫어 부상자를 먼저 옮겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k637-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 폭설에 막힌 환승 통로를 뚫어 부상자를 먼저 옮겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41281-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41281-S06","directLiegePersonId":"K1007"}],"directOwnership":false},{"id":"title:barony-gu-41285-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41285-S06","directLiegePersonId":"K1007"}],"directOwnership":false},{"id":"title:barony-gu-41287-S06","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K637","stateId":"S06","politicalParentTitleId":"title:duchy-41280-S06","personalLieges":[{"holdingId":"holding:opening-barony-gu-41287-S06","directLiegePersonId":"K1007"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"안동 권씨","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":10,"무력":-30,"물질":-35,"공동":5,"원칙":40,"공개":-15,"자격":20,"분산":-25,"변혁":-30},"desire":{"갈망":-5,"독점":10,"위험":15,"과시":-20,"지속":40,"지향":"유동","결합":"없음"},"fields":{"생업":"환승 통로 제설·부상자 이송","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"사본 전령","가치관":"권위 15 | 개방 10 | 무력 −30 | 물질 −35 | 공동 5 | 원칙 40 | 공개 −15 | 자격 20 | 분산 −25 | 변혁 −30","욕망":"갈망 −5 | 독점 10 | 위험 15 | 과시 −20 | 지속 40 | 지향 유동 | 결합 없음"},"sections":{"생애":"신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 권하린의 환승 통로 제설·부상자 이송 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.","일화":"2125년 폭설에 막힌 환승 통로를 뚫어 부상자를 먼저 옮겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","관계":"환승 통로 제설·부상자 이송 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"사본 전령 자리에서 환승 통로 제설·부상자 이송 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"","개입":"환승 통로 제설·부상자 이송 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"폭설에 통로가 막혀도 부상자와 기록을 놓지 않는 쪽을 고른다. 큰소리보다 이어지는 당직을 믿는다.\n\n- 생업: 환승 통로 제설·부상자 이송\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 사본 전령\n**생애.** 신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 권하린의 환승 통로 제설·부상자 이송 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.\n\n**일화.** 2125년 폭설에 막힌 환승 통로를 뚫어 부상자를 먼저 옮겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 환승 통로 제설·부상자 이송 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 사본 전령 자리에서 환승 통로 제설·부상자 이송 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**개입.** 환승 통로 제설·부상자 이송 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 10 | 무력 −30 | 물질 −35 | 공동 5 | 원칙 40 | 공개 −15 | 자격 20 | 분산 −25 | 변혁 −30\n- 욕망: 갈망 −5 | 독점 10 | 위험 15 | 과시 −20 | 지속 40 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"권하린","type":"계약","to":"연지우","basis":"권하린은 제설한 환승 통로에서 옮긴 부상자를 연지우에게 인계한다. 연지우는 호흡과 중증도를 확인해 침상을 배정하고 이동이 늦은 환자를 행정 기록만으로 밀어내지 않는다."}],"incoming":[]}}');
