INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0690', 'c720-bb34-c1a1-5ebe', '{"id":"person-0690","name":"Yu Daryeong","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0690","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0690","name":"유달영","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0690","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0691', 'b0a8-c758-b839', '{"id":"person-0691","name":"Nam Reumeun","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K691","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#inmul-nam-reumeun","detailRoute":"/people/person-0691","birthDate":"2085-03-21","birthday":"03-21","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k691-transfer-headcount-classification","name":"Transfer headcount classification","rating":45}],"traits":[{"id":"k691-priority","name":"Separates patient lists","description":"Nam Reumeun separated patients from ordinary passengers and recounted before departure. Classification is neither diagnosis nor citizenship screening.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"That if the food transport escort duty stood empty, crates could be swapped midway or people taken in the winter tunnel and no one would know.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k691-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: Escort. Title: Medical Escort Recorder. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"That if the food transport escort duty stood empty, crates could be swapped midway or people taken in the winter tunnel and no one would know.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Nam Reumeun separated patients from ordinary passengers and recounted before departure. Classification is neither diagnosis nor citizenship screening.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":50,"Force":-55,"Material":0,"Communal":25,"Principle":30,"Public":30,"Eligibility":25,"Dispersed":30,"Transformative":10},"desire":{"Longing":35,"Monopoly":-5,"Risk":-10,"Display":-40,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −15 | Openness 50 | Force −55 | Materialism 0 | Communalism 25 | Principle 30 | Transparency 30 | Qualification 25 | Decentralization 30 | Transformation 10","Desires":"Craving 35 | Possessiveness −5 | Risk −10 | Display −40 | Persistence 40 | Orientation Fluid | Bonding Non-monogamous"},"sections":{"Life":"Born on 2085-03-21. Grew up at the Seoul Station Registry Office. At the opening of 2126, holds the Medical Escort Records Officer duty, and the record of taking over the post remains, opened by the deletion of one line in a double ledger.\n- The Sinnae 1-dong dispatch, shift change, maintenance, passage inspection, stretcher handover and duty-key record desk is proposed as the work reference point for Nam Reumeun''s medical escort records and duty-key handover. It is a proposal for cross-checking handover records of the winter and does not confirm operating trains, new facilities, armaments, passage tolls, market monopolies, residence, exact facility boundaries, ranks, holdings or possession rights.","Offices":"Rank: Escort. Title: Medical Escort Recorder. Hands over the arrival time of the delayed dispatch message together with the keys and records of their own duty, making the scope of the handover clear.","Anecdote":"At the Sinnae Station market, the line of transit passengers stretches to the medical train platform. Nam Reumeun writes down the patients who boarded the medical escort car separately from ordinary transit passengers on the list. The arrival time of the delayed dispatch message recorded then became the handover standard for the next duty.","Relationships":"Hands over the arrival time of the delayed dispatch message to a senior on duty from the same living sphere, and cross-checks it against the receipt time of the next shift change in the same duty sphere.","Ambition":"Aims to leave the arrival time of the delayed dispatch message as a public handover line that the next shift can check again.","Fear":"Fears that the receipt time of the delayed dispatch message''s arrival time will be left blank and the responsibility shifted onto the patient and passenger lists.","Intervention":"Can appoint a witness for the handover of the delayed dispatch message''s arrival time, or make a missing signature field public before the next shift change."},"biography":"Nam Reumeun, born 2085-03-21, first checks the order of the arrival time of the delayed dispatch message. Trusts handover times and signature fields more than loud voices.\n\n- Livelihood: Medical Escort Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Medical Escort Recorder\n**Life.** Born on 2085-03-21. Grew up at the Seoul Station Registry Office. At the opening of 2126, holds the Medical Escort Records Officer duty, and the record of taking over the post remains, opened by the deletion of one line in a double ledger.\n- The Sinnae 1-dong dispatch, shift change, maintenance, passage inspection, stretcher handover and duty-key record desk is proposed as the work reference point for Nam Reumeun''s medical escort records and duty-key handover. It is a proposal for cross-checking handover records of the winter and does not confirm operating trains, new facilities, armaments, passage tolls, market monopolies, residence, exact facility boundaries, ranks, holdings or possession rights.\n\n**Office.** Rank: Escort. Title: Medical Escort Recorder. Hands over the arrival time of the delayed dispatch message together with the keys and records of their own duty, making the scope of the handover clear.\n\n**Anecdote.** At the Sinnae Station market, the line of transit passengers stretches to the medical train platform. Nam Reumeun writes down the patients who boarded the medical escort car separately from ordinary transit passengers on the list. The arrival time of the delayed dispatch message recorded then became the handover standard for the next duty.\n\n**Relationships.** Hands over the arrival time of the delayed dispatch message to a senior on duty from the same living sphere, and cross-checks it against the receipt time of the next shift change in the same duty sphere.\n\n**Ambition.** Aims to leave the arrival time of the delayed dispatch message as a public handover line that the next shift can check again.\n\n**Fear.** Fears that the receipt time of the delayed dispatch message''s arrival time will be left blank and the responsibility shifted onto the patient and passenger lists.\n\n**Intervention.** Can appoint a witness for the handover of the delayed dispatch message''s arrival time, or make a missing signature field public before the next shift change.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 50 | Force −55 | Materialism 0 | Communalism 25 | Principle 30 | Transparency 30 | Qualification 25 | Decentralization 30 | Transformation 10\n- Desires: Craving 35 | Possessiveness −5 | Risk −10 | Display −40 | Persistence 40 | Orientation Fluid | Bonding Non-monogamous\n:::","relations":{"outgoing":[{"from":"Nam Reumeun","type":"Contract","to":"Jeon Miri","basis":"Nam Reumeun hands Jeon Miri the medical-train patient list, recounted just before departure. Jeon Miri checks severity and transfer times, distinguishes ordinary transferring passengers from patients actually in the medical car, and keeps the stretcher order continuous."}],"incoming":[]}}', '{"id":"person-0691","name":"남름은","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K691","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-남름은","detailRoute":"/people/person-0691","birthDate":"2085-03-21","birthday":"03-21","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k691-transfer-headcount-classification","name":"이송 인원 분류","rating":45}],"traits":[{"id":"k691-priority","name":"환자 명단 분리","description":"남름은은 환자와 일반 환승객을 갈라 적고 출발 직전 다시 셌다. 분류는 의료 진단이나 국민 선별이 아니다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"식량 호송 동행 당직이 비면 겨울 터널에서 호송 상자가 중간에 바뀌거나 사람이 잡혀 가도 아무도 모르게 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k691-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 식량 호송 동행 당직이 비면 겨울 터널에서 호송 상자가 중간에 바뀌거나 사람이 잡혀 가도 아무도 모르게 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"남름은은 환자와 일반 환승객을 갈라 적고 출발 직전 다시 셌다. 분류는 의료 진단이나 국민 선별이 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":50,"무력":-55,"물질":0,"공동":25,"원칙":30,"공개":30,"자격":25,"분산":30,"변혁":10},"desire":{"갈망":35,"독점":-5,"위험":-10,"과시":-40,"지속":40,"지향":"유동","결합":"비독점"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −15 | 개방 50 | 무력 −55 | 물질 0 | 공동 25 | 원칙 30 | 공개 30 | 자격 25 | 분산 30 | 변혁 10","욕망":"갈망 35 | 독점 −5 | 위험 −10 | 과시 −40 | 지속 40 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2085-03-21에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 남름은의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 지연된 배차 전갈의 도착 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"신내역 시장에서 환승객 줄이 의료열차 승강장까지 늘어선다. 남름은은 의무호송 칸에 오른 환자와 일반 환승객을 명단에서 갈라 적는다. 그때 남긴 지연된 배차 전갈의 도착 시각이 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 지연된 배차 전갈의 도착 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"지연된 배차 전갈의 도착 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"지연된 배차 전갈의 도착 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"지연된 배차 전갈의 도착 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2085-03-21생인 남름은은 지연된 배차 전갈의 도착 시각의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2085-03-21에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다는 기록이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 남름은의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·직위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 지연된 배차 전갈의 도착 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 신내역 시장에서 환승객 줄이 의료열차 승강장까지 늘어선다. 남름은은 의무호송 칸에 오른 환자와 일반 환승객을 명단에서 갈라 적는다. 그때 남긴 지연된 배차 전갈의 도착 시각이 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 지연된 배차 전갈의 도착 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 지연된 배차 전갈의 도착 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 지연된 배차 전갈의 도착 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 지연된 배차 전갈의 도착 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 50 | 무력 −55 | 물질 0 | 공동 25 | 원칙 30 | 공개 30 | 자격 25 | 분산 30 | 변혁 10\n- 욕망: 갈망 35 | 독점 −5 | 위험 −10 | 과시 −40 | 지속 40 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"남름은","type":"계약","to":"전미리","basis":"남름은은 출발 직전 다시 센 의료열차 환자 명단을 전미리에게 넘긴다. 전미리는 중증도와 이송 시각을 확인해 일반 환승객과 실제 의료칸 환자를 구분하며 들것 순서를 잇는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0692', 'c2ec-ccad-c1a1', '{"id":"person-0692","name":"Sim Bahyeon","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K692","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-sim-bahyeon","detailRoute":"/people/person-0692","birthDate":"2094-05-13","birthday":"05-13","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"Original document custody","rating":40}],"traits":[{"id":"stated-priority","name":"Duty that keeps originals","description":"The forged-seal episode records burning copies and guarding originals. That custody choice alone does not justify sanitation outcomes.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The forged-seal episode records burning copies and guarding originals. That custody choice alone does not justify sanitation outcomes.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":40,"Force":-70,"Material":-25,"Communal":30,"Principle":70,"Public":30,"Eligibility":15,"Dispersed":20,"Transformative":-5},"desire":{"Longing":5,"Monopoly":30,"Risk":-15,"Display":10,"Sustained":30,"Orientation":"Same-Sex","Union":"Monogamy"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −15 | Openness 40 | Force −70 | Materialism −25 | Communalism 30 | Principle 70 | Transparency 30 | Qualification 15 | Decentralization 20 | Transformation −5","Desires":"Craving 5 | Possessiveness 30 | Risk −15 | Display 10 | Persistence 30 | Orientation Same-sex | Bonding Monogamous"},"sections":{"Life":"Born on 2094-05-13. As of the opening of 2126, holds the Epidemic-Control Records Officer duty and continues the existing duty and records. The succession record of that duty was opened by the deletion of one line in a double ledger.\n- The epidemic-control records and duty-key handover desk in Jegi-dong is made the work reference point for Sim Bahyeon. This placement does not confirm residence, exact facility boundaries, ranks, holdings or possession rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.","Relationships":"Sim Bahyeon brings the original quarantine records and the suspicious seal to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that a forged copy is not used as grounds for release.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"First chooses not to break the duty chain. Trusts a single ledger line more than loud voices.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born on 2094-05-13. As of the opening of 2126, holds the Epidemic-Control Records Officer duty and continues the existing duty and records. The succession record of that duty was opened by the deletion of one line in a double ledger.\n- The epidemic-control records and duty-key handover desk in Jegi-dong is made the work reference point for Sim Bahyeon. This placement does not confirm residence, exact facility boundaries, ranks, holdings or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.\n\n**Relationships.** Sim Bahyeon brings the original quarantine records and the suspicious seal to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that a forged copy is not used as grounds for release.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 40 | Force −70 | Materialism −25 | Communalism 30 | Principle 70 | Transparency 30 | Qualification 15 | Decentralization 20 | Transformation −5\n- Desires: Craving 5 | Possessiveness 30 | Risk −15 | Display 10 | Persistence 30 | Orientation Same-sex | Bonding Monogamous\n:::","relations":{"outgoing":[{"from":"Sim Bahyeon","type":"Contract","to":"Ra Seyeong","basis":"Sim Bahyeon brings the original quarantine records and the suspicious seal to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that a forged copy is not used as grounds for release."}],"incoming":[]}}', '{"id":"person-0692","name":"심바현","title":"방역 기록관","position":"방역 구호원","characterId":"K692","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-심바현","detailRoute":"/people/person-0692","birthDate":"2094-05-13","birthday":"05-13","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"원본 보관","rating":40}],"traits":[{"id":"stated-priority","name":"원본을 남기는 당직","description":"위조 도장이 드러난 사건에서 사본을 불사르고 원본 칸을 지켰다. 이 보관 선택만으로 방역 성과를 추정하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"위조 도장이 드러난 사건에서 사본을 불사르고 원본 칸을 지켰다. 이 보관 선택만으로 방역 성과를 추정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":40,"무력":-70,"물질":-25,"공동":30,"원칙":70,"공개":30,"자격":15,"분산":20,"변혁":-5},"desire":{"갈망":5,"독점":30,"위험":-15,"과시":10,"지속":30,"지향":"동성","결합":"단혼"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −15 | 개방 40 | 무력 −70 | 물질 −25 | 공동 30 | 원칙 70 | 공개 30 | 자격 15 | 분산 20 | 변혁 −5","욕망":"갈망 5 | 독점 30 | 위험 −15 | 과시 10 | 지속 30 | 지향 동성 | 결합 단혼"},"sections":{"생애":"2094-05-13에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 심바현의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"심바현은 방역 원본과 의심 날인을 라세영에게 가져간다. 라세영은 격리 출입·해제 기록을 확인해 위조 사본이 해제 근거로 쓰이지 않게 한다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2094-05-13에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 심바현의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 심바현은 방역 원본과 의심 날인을 라세영에게 가져간다. 라세영은 격리 출입·해제 기록을 확인해 위조 사본이 해제 근거로 쓰이지 않게 한다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 40 | 무력 −70 | 물질 −25 | 공동 30 | 원칙 70 | 공개 30 | 자격 15 | 분산 20 | 변혁 −5\n- 욕망: 갈망 5 | 독점 30 | 위험 −15 | 과시 10 | 지속 30 | 지향 동성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"심바현","type":"계약","to":"라세영","basis":"심바현은 방역 원본과 의심 날인을 라세영에게 가져간다. 라세영은 격리 출입·해제 기록을 확인해 위조 사본이 해제 근거로 쓰이지 않게 한다."}],"incoming":[]}}');
