INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0707', 'ac15-c9c4-c8fc', '{"id":"person-0707","name":"Gang Mayu","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0707","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0707","name":"강마유","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0707","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0708', 'c870-d3c9-c591-8d99', '{"id":"person-0708","name":"Jo Awon","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Management Relief Worker","characterId":"K708","rank":"Relief Worker","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-jo-awon","detailRoute":"/people/person-0708","birthDate":"2064-06-25","birthday":"06-25","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"Emergency bleeding control","rating":55}],"traits":[{"id":"stated-priority","name":"Changes the light and continues care","description":"Phone light allowed emergency care to continue during an outage. The performed work is recognized without inventing a full medical career or outcomes.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicinal Supplies Management Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Phone light allowed emergency care to continue during an outage. The performed work is recognized without inventing a full medical career or outcomes.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-d3c9-c591-8d99","name":"Pyeongyang Jo Clan","crest":"clan-crests/c870-d3c9-c591-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":25,"Force":-50,"Material":0,"Communal":20,"Principle":40,"Public":15,"Eligibility":25,"Dispersed":20,"Transformative":-15},"desire":{"Longing":45,"Monopoly":-5,"Risk":40,"Display":15,"Sustained":35,"Orientation":"Fluid","Union":"None"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −20 | Openness 25 | Force −50 | Material 0 | Communal 20 | Principle 40 | Publicity 15 | Qualification 25 | Dispersion 20 | Transformation −15","Desires":"Craving 45 | Monopoly −5 | Risk 40 | Display 15 | Continuity 35 | Orientation Fluid | Bonding None"},"sections":{"Life":"Born on 2064-06-25. As of the 2126 opening, holds the post of Medicinal Herb Logistics Chief, continuing the existing watch and records. The succession record for that post was opened by a forged medicine seal.\n- The Jegi-dong desk for medicinal herb management records and watch-key handovers is set as Jo Awon''s work reference point. This placement does not fix residence, exact facility boundaries, ranks, holdings, or holding rights.","Offices":"Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, when the power went out during emergency care, continued stanching the bleeding by the light of a handheld phone. That day''s record remained as the handover basis for the next shift to verify.","Relationships":"Jo Awon informs Su Hyoeun of the condition of the herbs under her care and the quantity needed during treatment. Su Hyoeun checks the drying room and clinic output logs to find where a gap in storage power led to herb damage.","Ambition":"From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Jo Awon would rather keep the watch unbroken. Jo Awon trusts a single line in the ledger more than a loud voice.\n\n- Livelihood: Medicinal Supplies Management Records & Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicinal Supplies Logistics Merchant\n**Life.** Born on 2064-06-25. As of the 2126 opening, holds the post of Medicinal Herb Logistics Chief, continuing the existing watch and records. The succession record for that post was opened by a forged medicine seal.\n- The Jegi-dong desk for medicinal herb management records and watch-key handovers is set as Jo Awon''s work reference point. This placement does not fix residence, exact facility boundaries, ranks, holdings, or holding rights.\n\n**Office.** Rank: Relief Worker. Title: Medicinal Supplies Management Relief Worker. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.\n\n**Anecdote.** In 2125, when the power went out during emergency care, continued stanching the bleeding by the light of a handheld phone. That day''s record remained as the handover basis for the next shift to verify.\n\n**Relations.** Jo Awon informs Su Hyoeun of the condition of the herbs under her care and the quantity needed during treatment. Su Hyoeun checks the drying room and clinic output logs to find where a gap in storage power led to herb damage.\n\n**Ambition.** From the post of Medicinal Supplies Management Relief Worker, keeps the White Cross Order''s ledgers continuous and unbroken.\n\n**Fear.** Fears that the Medicinal Supplies Management Relief Worker''s watch will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −20 | Openness 25 | Force −50 | Material 0 | Communal 20 | Principle 40 | Publicity 15 | Qualification 25 | Dispersion 20 | Transformation −15\n- Desires: Craving 45 | Monopoly −5 | Risk 40 | Display 15 | Continuity 35 | Orientation Fluid | Bonding None\n:::","relations":{"outgoing":[{"from":"Jo Awon","type":"Contract","to":"Su Hyoeun","basis":"Jo Awon informs Su Hyoeun of the condition of the herbs under her care and the quantity needed during treatment. Su Hyoeun checks the drying room and clinic output logs to find where a gap in storage power led to herb damage."}],"incoming":[]}}', '{"id":"person-0708","name":"조아원","title":"약재 물류상","position":"약재 관리 구호원","characterId":"K708","rank":"구호원","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-조아원","detailRoute":"/people/person-0708","birthDate":"2064-06-25","birthday":"06-25","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"응급 지혈 수행","rating":55}],"traits":[{"id":"stated-priority","name":"불빛을 바꿔 치료를 잇는다","description":"정전 중 휴대전화 불빛으로 응급 지혈을 이어갔다. 실제 손의 수행은 인정하지만 완결된 응급처치원 경력이나 성과는 만들지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"정전 중 휴대전화 불빛으로 응급 지혈을 이어갔다. 실제 손의 수행은 인정하지만 완결된 응급처치원 경력이나 성과는 만들지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-d3c9-c591-8d99","name":"평양 조씨","crest":"clan-crests/c870-d3c9-c591-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":25,"무력":-50,"물질":0,"공동":20,"원칙":40,"공개":15,"자격":25,"분산":20,"변혁":-15},"desire":{"갈망":45,"독점":-5,"위험":40,"과시":15,"지속":35,"지향":"유동","결합":"없음"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약재 물류상","가치관":"권위 −20 | 개방 25 | 무력 −50 | 물질 0 | 공동 20 | 원칙 40 | 공개 15 | 자격 25 | 분산 20 | 변혁 −15","욕망":"갈망 45 | 독점 −5 | 위험 40 | 과시 15 | 지속 35 | 지향 유동 | 결합 없음"},"sections":{"생애":"2064-06-25에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 조아원의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"조아원은 관리하는 약재의 상태와 진료 중 필요한 양을 수효은에게 알린다. 수효은은 건조실·진료소 출력 일지를 확인해 보관 전력 공백이 약재 손상으로 이어진 곳을 찾는다.","야망":"약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약재 물류상\n**생애.** 2064-06-25에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 조아원의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약재 관리 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 응급 처치 중 정전이 되자 손전화 불빛 아래에서 지혈을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 조아원은 관리하는 약재의 상태와 진료 중 필요한 양을 수효은에게 알린다. 수효은은 건조실·진료소 출력 일지를 확인해 보관 전력 공백이 약재 손상으로 이어진 곳을 찾는다.\n\n**야망.** 약재 관리 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 25 | 무력 −50 | 물질 0 | 공동 20 | 원칙 40 | 공개 15 | 자격 25 | 분산 20 | 변혁 −15\n- 욕망: 갈망 45 | 독점 −5 | 위험 40 | 과시 15 | 지속 35 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"조아원","type":"계약","to":"수효은","basis":"조아원은 관리하는 약재의 상태와 진료 중 필요한 양을 수효은에게 알린다. 수효은은 건조실·진료소 출력 일지를 확인해 보관 전력 공백이 약재 손상으로 이어진 곳을 찾는다."}],"incoming":[]}}');
