INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0719', 'c1a1-c740-c9c4-5b8b', '{"id":"person-0719","name":"Song Dohyeon","title":"Auction Clerk","position":"Auction Clerk","characterId":"K719","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Auction Ledger Recording","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-08#inmul-song-dohyeon","detailRoute":"/people/person-0719","birthDate":"2087-08-21","birthday":"08-21","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"hose-receipt-ledger","name":"Hose receipt ledger","rating":45}],"traits":[{"id":"k719-disposition","name":"Ledger recording","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Office. Rank: Ordinary Citizen. Title: auction clerk.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k719-choice","name":"Auction Clerk","description":"Title: Auction Clerk.","behavior":"Relations. Bound by handover to the senior duty line of the same living quarters.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Title: Auction Clerk.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-c740-c9c4-5b8b","name":"Eunjin Song Clan","crest":"clan-crests/c1a1-c740-c9c4-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":30,"Force":-10,"Material":90,"Communal":-25,"Principle":-40,"Public":20,"Eligibility":10,"Dispersed":10,"Transformative":10},"desire":{"Longing":0,"Monopoly":-40,"Risk":-30,"Display":30,"Sustained":30,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Affiliation":"The Government","Rank":"Ordinary Citizen","Livelihood":"Auction Ledger Recording","Appearance":"Height 183 cm, weight 70 kg. Has a slim build with broad shoulders and long limbs. Distinguished by fair skin, black hair, light brown eyes and a straight nose bridge, and gives a calm, somewhat cool impression.","Title":"Auction Clerk","Values":"Authority −10 | Openness 30 | Force −10 | Materialism 90 | Community −25 | Principle −40 | Publicity 20 | Qualification 10 | Dispersion 10 | Transformation 10","Desires":"Craving 0 | Possessiveness −40 | Risk −30 | Display 30 | Persistence 30 | Orientation opposite-sex | Bonding monogamous"},"sections":{"Life":"Born in the generation of 2126. Grew up at the Cheongnyangni Station freight platform. The Auction Clerk post opened through a public re-inspection of the scales.\n-","Offices":"Rank: Ordinary Citizen. Title: Auction Clerk. Hands over only the keys and records of his own post, and does not invent authority he does not have.","Anecdote":"","Relationships":"","Ambition":"To keep the Government''s books unbroken from the Auction Clerk post.","Fear":"","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty shift. He trusts a single line in the ledger over loud talk.\n\n- Affiliation: The Government\n- Rank: Ordinary Citizen\n- Livelihood: Auction Ledger Recording\n- Appearance: Height 183 cm, weight 70 kg. Has a slim build with broad shoulders and long limbs. Distinguished by fair skin, black hair, light brown eyes and a straight nose bridge, and gives a calm, somewhat cool impression.\n- Title: Auction Clerk\n**Life.** Born in the generation of 2126. Grew up at the Cheongnyangni Station freight platform. The Auction Clerk post opened through a public re-inspection of the scales.\n\n**Office.** Rank: Ordinary Citizen. Title: Auction Clerk. Hands over only the keys and records of his own post, and does not invent authority he does not have.\n\n**Ambition.** To keep the Government''s books unbroken from the Auction Clerk post.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 30 | Force −10 | Materialism 90 | Community −25 | Principle −40 | Publicity 20 | Qualification 10 | Dispersion 10 | Transformation 10\n- Desires: Craving 0 | Possessiveness −40 | Risk −30 | Display 30 | Persistence 30 | Orientation opposite-sex | Bonding monogamous\n:::","relations":{"outgoing":[{"from":"Song Dohyeon","type":"Contract","to":"Ji Yun-jae","basis":""}],"incoming":[]}}', '{"id":"person-0719","name":"송도현","title":"경매 서기","position":"경매 서기","characterId":"K719","rank":"일반 시민","commonTier":"T5","occupation":"경매 장부 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-08#인물-송도현","detailRoute":"/people/person-0719","birthDate":"2087-08-21","birthday":"08-21","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"ef