INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0726', 'bc30-d765-d574-88f5', '{"id":"person-0726","name":"Bae Darwon","title":"Warehouse Duty Officer","position":"Myeongdong Station Confirmation Roster Duty Officer","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Confirmation Roster Handover Record","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0726","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0726","name":"배달원","title":"창고 당직","position":"명동역 인준 명부 당직","rank":"일반 시민","commonTier":"T5","occupation":"인준 명부 인수인계 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0726","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0727', 'bc31-c218-c6d0', '{"id":"person-0727","name":"Baek Reumrae","title":"Utility Tunnel Duty Officer","position":"Utility Tunnel Duty Officer","rank":"Guild Member","commonTier":"T5","occupation":"Utility Tunnel Duty Log · Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0727","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0727","name":"백름래","title":"공동구 당직","position":"공동구 당직","rank":"조합원","commonTier":"T5","occupation":"공동구 당직 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0727","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0728', 'd5c8-d558-c591-8a31', '{"id":"person-0728","name":"Heo Bau","title":"Bridge Passage Herald","position":"Bridge Passage Herald","characterId":"K728","rank":"Clerk","commonTier":"T5","occupation":"Bridge Guard Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-heo-bau","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k728-ambush-trace-reading","name":"Reading ambush traces","rating":55}],"traits":[{"id":"k728-action-priority","name":"Read traces first","description":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","behavior":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","stress":"That if the tunnel courier duty stands empty, news between stations will be cut off and no one can report where a kidnapped person was taken.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]},{"id":"k728-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That if the tunnel courier duty stands empty, news between stations will be cut off and no one can report where a kidnapped person was taken.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]}],"narrative":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":0,"Force":20,"Material":20,"Communal":10,"Principle":15,"Public":20,"Eligibility":10,"Dispersed":-55,"Transformative":-25},"desire":{"Longing":40,"Monopoly":10,"Risk":-35,"Display":-25,"Sustained":-20,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Affiliation":"Free City","Livelihood":"Bridge Guard Duty","Rank":"Clerk","Title":"Bridge Passage Herald","Work Location":"Dangsan 2-dong. In 2125, Heo Bau read the traces of an ambush on a patrol of Seoul''s hill paths from the Amsa guard post and prevented casualties. He now passes the trace-reading he learned then, along with the nighttime river-crossing reports, to Kim Taeun''s bridge duty shift in Dangsan 2-dong.","Values":"Authority 60 | Openness 0 | Force 20 | Materialism 20 | Community 10 | Principle 15 | Publicity 20 | Qualification 10 | Dispersion −55 | Transformation −25","Desires":"Craving 40 | Possessiveness 10 | Risk −35 | Display −25 | Persistence −20 | Orientation opposite-sex | Bonding polyamorous"},"sections":{"Life":"Born in the 2126 cohort. Grew up at the Amsa guard post. The Bridge Crossing Herald post opened after an unauthorized night crossing was caught.\n- Duty station: Dangsan 2-dong. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.","Offices":"Rank: Clerk. Title: Bridge Passage Herald. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.","Anecdote":"In 2125, on the Seoul hill-road patrol connected to the Amsa guard post, Heo Ba-u found the ambush traces first and warned the guard unit, then turned back the people crossing and prevented losses.","Relationships":"Under Kim Taeun''s command, handles bridge passage and nighttime river-crossing reports.","Ambition":"From the tunnel courier post, he keeps Dangsan Station''s record of news connected without a break.","Fear":"That if the tunnel courier duty goes unfilled, news between stations will be cut off and no one can report where a kidnapped person was taken.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the watch. He trusts a single line in the ledger over loud talk.\n\n- Affiliation: Free City\n- Livelihood: Bridge Guard Duty\n- Rank: Clerk\n- Title: Bridge Passage Herald\n**Life.** Born in the 2126 cohort. Grew up at the Amsa guard post. The Bridge Crossing Herald post opened after an unauthorized night crossing was caught.\n- Duty station: Dangsan 2-dong. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.\n\n**Office.** Rank: Clerk. Title: Bridge Passage Herald.\n\n**Anecdote.** In 2125, on the Seoul hill-road patrol connected to the Amsa guard post, Heo Ba-u found the ambush traces first and warned the guard unit, then turned back the people crossing and prevented losses.\n\n**Relations.** Under Kim Taeun''s command, handles bridge passage and nighttime river-crossing reports.\n\n**Ambition.** From the tunnel courier post, he keeps Dangsan Station''s record of news connected without a break.\n\n**Fear.** That if the tunnel courier duty goes unfilled, news between stations will be cut off and no one can report where a kidnapped person was taken.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 60 | Openness 0 | Force 20 | Material 20 | Community 10 | Principle 15 | Publicity 20 | Qualification 10 | Decentralization −55 | Transformation −25\n- Desires: Craving 40 | Exclusivity 10 | Risk −35 | Display −25 | Persistence −20 | Orientation: opposite-sex | Bonding: multiple partners\n:::","directLiege":{"personId":"K003","name":"Gim Tae-un","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"Heo Bau","type":"Command","to":"Gim Tae-un","basis":"Handles bridge traffic and night-crossing reports under Gim Taeun''s command"}],"incoming":[]}}', '{"id":"person-0728","name":"허바우","title":"교량 통행 전령","position":"교량 통행 전령","characterId":"K728","rank":"주사","commonTier":"T5","occupation":"교량 경비 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-허바우","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k728-ambush-trace-reading","name":"매복 흔적 확인","rating":55}],"traits":[{"id":"k728-action-priority","name":"흔적을 먼저 읽는다","description":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","behavior":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","stress":"터널 연락 당직이 비면 역 사이 소식이 끊겨 납치된 사람의 행방도 알리지 못하는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]},{"id":"k728-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"터널 연락 당직이 비면 역 사이 소식이 끊겨 납치된 사람의 행방도 알리지 못하는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]}],"narrative":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"하양 허씨","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":0,"무력":20,"물질":20,"공동":10,"원칙":15,"공개":20,"자격":10,"분산":-55,"변혁":-25},"desire":{"갈망":40,"독점":10,"위험":-35,"과시":-25,"지속":-20,"지향":"이성","결합":"다자"},"fields":{"소속":"자유도시","생업":"교량 경비 당직","품계":"주사","직함":"교량 통행 전령","업무 위치":"당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","가치관":"권위 60 | 개방 0 | 무력 20 | 물질 20 | 공동 10 | 원칙 15 | 공개 20 | 자격 10 | 분산 −55 | 변혁 −25","욕망":"갈망 40 | 독점 10 | 위험 −35 | 과시 −25 | 지속 −20 | 지향 이성 | 결합 다자"},"sections":{"생애":"2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","관직":"품계 주사. 직함은 교량 통행 전령이다. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","일화":"2125년 암사 경비 초소와 이어지는 서울 언덕길 초계에서 허바우는 매복 흔적을 먼저 찾아 경비대에 알렸고 통행 인원을 돌려 피해를 막았다.","관계":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","야망":"터널 연락 자리에서 당산역의 소식 기록을 끊기지 않게 잇는다.","공포":"터널 연락 당직이 비면 역 사이 소식이 끊겨 납치된 사람의 행방도 알리지 못하는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 교량 경비 당직\n- 품계: 주사\n- 직함: 교량 통행 전령\n**생애.** 2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.\n\n**관직.** 품계 주사. 직함은 교량 통행 전령이다.\n\n**일화.** 2125년 암사 경비 초소와 이어지는 서울 언덕길 초계에서 허바우는 매복 흔적을 먼저 찾아 경비대에 알렸고 통행 인원을 돌려 피해를 막았다.\n\n**관계.** 김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.\n\n**야망.** 터널 연락 자리에서 당산역의 소식 기록을 끊기지 않게 잇는다.\n\n**공포.** 터널 연락 당직이 비면 역 사이 소식이 끊겨 납치된 사람의 행방도 알리지 못하는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 0 | 무력 20 | 물질 20 | 공동 10 | 원칙 15 | 공개 20 | 자격 10 | 분산 −55 | 변혁 −25\n- 욕망: 갈망 40 | 독점 10 | 위험 −35 | 과시 −25 | 지속 −20 | 지향 이성 | 결합 다자\n:::","directLiege":{"personId":"K003","name":"김태운","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"허바우","type":"지휘","to":"김태운","basis":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡음"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0729', 'c720-ac15-b989', '{"id":"person-0729","name":"Yu Dolhun","title":"Power Device Patrol","position":"Power Device Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Guard & Patrol","gender":"Female","stage":"S4","state":"S02","stateName":"Free City","detailRoute":"/people/person-0729","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0729","name":"유돌훈","title":"전력장치 순찰대","position":"전력장치 순찰대","rank":"조합원","commonTier":"T5","occupation":"경비·순찰","gender":"여성","stage":"S4","state":"S02","stateName":"자유도시","detailRoute":"/people/person-0729","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0730', 'b0a8-c758-b839', '{"id":"person-0730","name":"Nam Saewon","title":"Entrance Heat and Light Gauger","position":"Entrance Heat and Light Gauger","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Duty Log Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0730","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0730","name":"남새원","title":"출입구 열·빛 계측원","position":"출입구 열·빛 계측원","rank":"일반 시민","commonTier":"T5","occupation":"당직 기록 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0730","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0731', 'b178-c7a5-c5f0-76e7', '{"id":"person-0731","name":"No Baa","title":"Workshop Herald","position":"Workshop Herald","characterId":"K731","rank":"Teacher","commonTier":"T5","occupation":"Timetable · Departure Check","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#character-noh-ba-a","detailRoute":"/people/person-0731","birthDate":"2097-07-25","birthday":"07-25","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure","name":"Departure and dispatch checks","rating":50},{"id":"handover","name":"Record and key handover","rating":40}],"traits":[{"id":"stop-unmarked-trains","name":"Stop Unmarked Trains","description":"No Baa shows a verification-centered reluctance to permit a train to depart without a dispatch sheet.","behavior":"She stopped a train without a dispatch sheet and prevented an unsigned departure.","stress":"","relationship":"She may clearly tell the senior duty holder that departure was stopped because the dispatch sheet and signature were missing.","effects":[]},{"id":"respect-explicit-authority","name":"Respect Explicit Authority","description":"No Baa respects the scope of her post''s keys and records and does not invent authority.","behavior":"She enforces dispatch-sheet and signature checks while limiting handover to her post''s keys and records.","stress":"Even if a duty gap threatens passage, she may rely on verification requirements and her explicitly defined post scope.","relationship":"She may keep authority boundaries clear with the senior duty holder by specifying the records and keys being transferred.","effects":[]}],"narrative":"She halted a train departing without a dispatch sheet. Conditional enforcement is supported; messenger combat ability is unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-c7a5-c5f0-76e7","name":"Jangyeon No Clan","crest":"clan-crests/b178-c7a5-c5f0-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":20,"Force":-20,"Material":10,"Communal":40,"Principle":20,"Public":-15,"Eligibility":20,"Dispersed":30,"Transformative":0},"desire":{"Longing":45,"Monopoly":40,"Risk":5,"Display":5,"Sustained":5,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Timetable · Departure Check","Rank":"Teacher","Title":"Workshop Herald","Values":"Authority −5 | Openness 20 | Force −20 | Material 10 | Community 40 | Principle 20 | Publicity −15 | Qualification 20 | Decentralization 30 | Transformation 0","Desires":"Craving 45 | Exclusivity 40 | Risk 5 | Display 5 | Persistence 5 | Orientation: fluid | Bonding: non-exclusive"},"sections":{"Life":"Born in the 2126 cohort. Noh Ba-a grew up at the Sinnae transfer watch. Noh Ba-a took the Workshop Herald post after stopping a ticketless train''s departure.\n- Noh Ba-a''s Workshop Herald duties are connected to Amsa 1-dong.","Offices":"Noh Ba-a hands over only the keys and records attached to her own post. She does not invent authority she lacks.","Anecdote":"In 2125, Noh Ba-a stopped a train with no dispatch slip and prevented an unsigned departure. Because of this, the signature of the Workshop Herald post was entered in the ledger.","Relationships":"Noh Ba-a is bound by handover to the senior watch officer of the same living sphere.","Ambition":"Noh Ba-a wants to keep the Arc''s ledger connected without a break through the Workshop Herald watch.","Fear":"","Intervention":"Noh Ba-a can bring in a witness for a watch handover or expose an empty key."},"biography":"Noh Ba-a chooses first not to break the watch. Noh Ba-a trusts a single line in the ledger over loud talk.\n\n- Affiliation: Arc\n- Occupation: Timetable · Departure Check\n- Rank: Teacher\n- Title: Workshop Herald\n**Life.** Born in the 2126 cohort. Noh Ba-a grew up at the Sinnae transfer watch. Noh Ba-a took the Workshop Herald post after stopping a ticketless train''s departure.\n- Noh Ba-a''s Workshop Herald duties are connected to Amsa 1-dong.\n\n**Office.** Noh Ba-a hands over only the keys and records attached to her own post. She does not invent authority she lacks.\n\n**Anecdote.** In 2125, Noh Ba-a stopped a train with no dispatch slip and prevented an unsigned departure. Because of this, the signature of the Workshop Herald post was entered in the ledger.\n\n**Relations.** Noh Ba-a is bound by handover to the senior watch officer of the same living sphere.\n\n**Ambition.** Noh Ba-a wants to keep the Arc''s ledger connected without a break through the Workshop Herald watch.\n\n**Intervention.** Noh Ba-a can bring in a witness for a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 20 | Force −20 | Material 10 | Community 40 | Principle 20 | Publicity −15 | Qualification 20 | Decentralization 30 | Transformation 0\n- Desires: Craving 45 | Exclusivity 40 | Risk 5 | Display 5 | Persistence 5 | Orientation: fluid | Bonding: non-exclusive\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0731","name":"노바아","title":"공방 전령","position":"공방 전령","characterId":"K731","rank":"교사","commonTier":"T5","occupation":"배차표·출발 확인","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-노바아","detailRoute":"/people/person-0731","birthDate":"2097-07-25","birthday":"07-25","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure","name":"배차표·출발 확인","rating":50},{"id":"handover","name":"기록·열쇠 인수인계","rating":40}],"traits":[{"id":"stop-unmarked-trains","name":"무표 열차 세우기","description":"노바아는 배차표가 없는 열차의 출발을 허용하지 않는 확인 중심 성향을 보인다.","behavior":"배차표 없는 열차를 세워 서명 없는 출발을 막았다.","stress":"","relationship":"선배 당직에게는 배차표와 서명이 없어 출발을 세운 사실을 분명히 넘기려 할 수 있다.","effects":[]},{"id":"respect-explicit-authority","name":"명시 권한 준수","description":"노바아는 자기 직위에 명시된 열쇠와 기록의 범위를 지키고 없는 권한을 만들지 않는다.","behavior":"배차표와 서명의 확인 조건을 집행하면서 인계는 자기 직위의 열쇠와 기록에 한정한다.","stress":"당직 공백으로 통행이 위태로워져도 확인 조건과 명시된 직위 범위에 기대려 할 수 있다.","relationship":"선배 당직과는 넘길 기록과 열쇠를 명확히 하며 권한의 경계를 유지하려 할 수 있다.","effects":[]}],"narrative":"배차표가 없는 열차의 출발을 세웠다. 확인 조건 집행만 근거이며 전령의 전투 기량은 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-c7a5-c5f0-76e7","name":"장연 노씨","crest":"clan-crests/b178-c7a5-c5f0-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":20,"무력":-20,"물질":10,"공동":40,"원칙":20,"공개":-15,"자격":20,"분산":30,"변혁":0},"desire":{"갈망":45,"독점":40,"위험":5,"과시":5,"지속":5,"지향":"유동","결합":"비독점"},"fields":{"소속":"Arc","생업":"배차표·출발 확인","품계":"교사","직함":"공방 전령","가치관":"권위 −5 | 개방 20 | 무력 −20 | 물질 10 | 공동 40 | 원칙 20 | 공개 −15 | 자격 20 | 분산 30 | 변혁 0","욕망":"갈망 45 | 독점 40 | 위험 5 | 과시 5 | 지속 5 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2126년 세대. 노바아는 신내 환승 당직에서 자랐다. 노바아는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 노바아의 공방 전령 업무는 암사1동과 연결된다.","관직":"노바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 노바아는 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.","관계":"노바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"노바아는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"","개입":"노바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"노바아는 당직을 끊지 않는 쪽을 먼저 고른다. 노바아는 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 배차표·출발 확인\n- 품계: 교사\n- 직함: 공방 전령\n**생애.** 2126년 세대. 노바아는 신내 환승 당직에서 자랐다. 노바아는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 노바아의 공방 전령 업무는 암사1동과 연결된다.\n\n**관직.** 노바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 노바아는 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 노바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 노바아는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**개입.** 노바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 20 | 무력 −20 | 물질 10 | 공동 40 | 원칙 20 | 공개 −15 | 자격 20 | 분산 30 | 변혁 0\n- 욕망: 갈망 45 | 독점 40 | 위험 5 | 과시 5 | 지속 5 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[],"incoming":[]}}');
