INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0746', 'c870-d3c9-c591-8d99', '{"id":"person-0746","name":"Jo Dong-jun","title":"Certification Courier","position":"Certification Courier","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Female","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0746","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0746","name":"조동준","title":"인증 전령","position":"인증 전령","rank":"일반 시민","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"여성","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0746","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0747', 'c724-d30c-d3c9', '{"id":"person-0747","name":"Yun Buk-yul","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K747","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Parts Shipment Inspection","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-yun-bugyul","detailRoute":"/people/person-0747","birthDate":"2073-04-29","birthday":"04-29","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"Defective-parts dispatch inspection","rating":50},{"id":"wheel","name":"Wheel-defect inspection","rating":40}],"traits":[{"id":"no-defective-shipments","name":"No Defective Shipments","description":"Yun Bugyul shows a quality-checking disposition by refusing to pass on defective parts even just before shipment.","behavior":"He returned a box of defective parts immediately before shipment.","stress":"Even when concerned about duty gaps and dependent passage, he may be cautious about shipping confirmed defects.","relationship":"He may clearly hand over the returned parts box and the defect judgment to the senior duty holder.","effects":[]},{"id":"maintain-record-continuity","name":"Maintain Record Continuity","description":"Yun Bugyul values carrying his post''s records forward to avoid breaks in the ledger and duty.","behavior":"He returns defective parts and passes on his post''s keys and records to support ledger continuity.","stress":"","relationship":"He may value handover that gives the senior duty holder a recorded reason why the parts were not shipped.","effects":[]}],"narrative":"He returned a defective-parts box. Release checks and wheel reporting are supported, not authority over an entire logistics network.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43770-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K747","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43770-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":5,"Force":-25,"Material":45,"Communal":20,"Principle":0,"Public":-25,"Eligibility":30,"Dispersed":25,"Transformative":-10},"desire":{"Longing":10,"Monopoly":0,"Risk":40,"Display":20,"Sustained":-5,"Orientation":"None","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Parts Shipment Inspection","Rank":"Ordinary Citizen","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 20 | Principle 0 | Publicity −25 | Credentials 30 | Dispersal 25 | Transformation −10","Desires":"Longing 10 | Monopoly 0 | Risk 40 | Display 20 | Continuity −5 | Orientation: None | Bonding: Polyamorous"},"sections":{"Life":"Generation of 2126. Yun Bugyul grew up at the Sinjeong Depot. He took the post of Parts Logistics Merchant through a defect report made just before a derailment.\n- Yun Bugyul''s Parts Logistics Merchant work is connected to Cheonho 3-dong.","Offices":"Yun Bugyul hands over only the keys and records attached to his own post. He does not invent authority that he does not have.","Anecdote":"In 2125, Yun Bugyul sent a defective parts crate back just before shipment. Because of this, the signature for the post of Parts Logistics Merchant was entered in the ledger.","Relationships":"Yun Bugyul is bound by handover to the senior duty officer of the same living sphere.","Ambition":"Yun Bugyul wants to keep the Arc''s ledger continuous and unbroken through the Parts Logistics Merchant''s duty.","Fear":"","Intervention":"Yun Bugyul can bring in a witness for a duty handover or expose an empty key."},"biography":"Yun Bugyul chooses first not to break the duty chain. Yun Bugyul trusts a single ledger line more than loud voices.\n\n- Affiliation: Arc\n- Livelihood: Parts Shipment Inspection\n- Rank: Ordinary Citizen\n- Title: Parts Logistics Merchant\n**Life.** Generation of 2126. Yun Bugyul grew up at the Sinjeong Depot. He took the post of Parts Logistics Merchant through a defect report made just before a derailment.\n- Yun Bugyul''s Parts Logistics Merchant work is connected to Cheonho 3-dong.\n\n**Office.** Yun Bugyul hands over only the keys and records attached to his own post. He does not invent authority that he does not have.\n\n**Anecdote.** In 2125, Yun Bugyul sent a defective parts crate back just before shipment. Because of this, the signature for the post of Parts Logistics Merchant was entered in the ledger.\n\n**Relations.** Yun Bugyul is bound by handover to the senior duty officer of the same living sphere.\n\n**Ambition.** Yun Bugyul wants to keep the Arc''s ledger continuous and unbroken through the Parts Logistics Merchant''s duty.\n\n**Intervention.** Yun Bugyul can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 20 | Principle 0 | Publicity −25 | Credentials 30 | Dispersal 25 | Transformation −10\n- Desires: Longing 10 | Monopoly 0 | Risk 40 | Display 20 | Continuity −5 | Orientation: None | Bonding: Polyamorous\n:::","relations":{"outgoing":[{"from":"Yun Buk-yul","type":"Contract","to":"Bak Serin","basis":"Yun Bugyul sends the defective pump parts screened out in the dispatch inspection back to Bak Serin. Bak Serin checks the warehouse parts and the elder''s seal to find the point where the defective items got mixed into the normal dispatch list."}],"incoming":[]}}', '{"id":"person-0747","name":"윤북율","title":"부품 물류상","position":"부품 물류상","characterId":"K747","rank":"일반 시민","commonTier":"T3","occupation":"부품 출고 검사","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-윤북율","detailRoute":"/people/person-0747","birthDate":"2073-04-29","birthday":"04-29","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"불량 부품 출고 검사","rating":50},{"id":"wheel","name":"차륜 결함 점검","rating":40}],"traits":[{"id":"no-defective-shipments","name":"불량 출고 거부","description":"윤북율은 출고 직전에도 불량 부품을 넘기지 않는 품질 확인 성향을 보인다.","behavior":"불량 부품 상자를 출고 직전에 되돌려 보냈다.","stress":"당직 공백과 통행 종속을 우려하더라도 확인된 불량을 그대로 출고하는 데 신중할 수 있다.","relationship":"선배 당직에게는 반송한 부품 상자와 불량 판단을 분명히 인계하려 할 수 있다.","effects":[]},{"id":"maintain-record-continuity","name":"기록 잇기","description":"윤북율은 자기 직위의 기록을 이어 장부와 당직의 중단을 피하는 데 무게를 둔다.","behavior":"불량 부품을 반송하고 자기 직위의 열쇠와 기록을 넘겨 장부의 연속성을 지향한다.","stress":"","relationship":"선배 당직과는 출고하지 않은 이유를 기록으로 이어 주는 인계를 중시할 수 있다.","effects":[]}],"narrative":"불량 부품 상자를 되돌려 보냈다. 출고 검사와 생애의 차륜 보고만 평가하며 물류망 전체 운영 권한은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43770-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K747","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43770-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":5,"무력":-25,"물질":45,"공동":20,"원칙":0,"공개":-25,"자격":30,"분산":25,"변혁":-10},"desire":{"갈망":10,"독점":0,"위험":40,"과시":20,"지속":-5,"지향":"무성향","결합":"다자"},"fields":{"소속":"Arc","생업":"부품 출고 검사","품계":"일반 시민","직함":"부품 물류상","가치관":"권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 20 | 원칙 0 | 공개 −25 | 자격 30 | 분산 25 | 변혁 −10","욕망":"갈망 10 | 독점 0 | 위험 40 | 과시 20 | 지속 −5 | 지향 무성향 | 결합 다자"},"sections":{"생애":"2126년 세대. 윤북율은 신정 차량기지에서 자랐다. 윤북율은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 윤북율의 부품 물류상 업무는 천호3동과 연결된다.","관직":"윤북율은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 윤북율은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"윤북율은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"윤북율은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"","개입":"윤북율은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"윤북율은 당직을 끊지 않는 쪽을 먼저 고른다. 윤북율은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 부품 출고 검사\n- 품계: 일반 시민\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 윤북율은 신정 차량기지에서 자랐다. 윤북율은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 윤북율의 부품 물류상 업무는 천호3동과 연결된다.\n\n**관직.** 윤북율은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 윤북율은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 윤북율은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 윤북율은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**개입.** 윤북율은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 20 | 원칙 0 | 공개 −25 | 자격 30 | 분산 25 | 변혁 −10\n- 욕망: 갈망 10 | 독점 0 | 위험 40 | 과시 20 | 지속 −5 | 지향 무성향 | 결합 다자\n:::","relations":{"outgoing":[{"from":"윤북율","type":"계약","to":"박세린","basis":"윤북율은 출고 검사에서 가려낸 불량 펌프 부품을 박세린에게 돌려보낸다. 박세린은 창고 부품과 원로 날인을 확인해 불량품이 정상 출고 목록에 섞인 지점을 찾는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0748', 'c7a5-baa9-cc9c-5f35', '{"id":"person-0748","name":"Jang Byeol-lin","title":"Eastern Command Guard Squad","position":"Eastern Patrol","rank":"Guard","commonTier":"T5","occupation":"Access Security · Roster Recheck","gender":"Male","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0748","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0748","name":"장별린","title":"동방사 경비조","position":"동부 순찰대","rank":"경비대원","commonTier":"T5","occupation":"출입 경비·명부 재점검","gender":"남성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0748","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0749', 'c784-c608-cc9c-6797', '{"id":"person-0749","name":"Im Bit-na","title":"Ratification Registrar","position":"Ratification Registrar","characterId":"K749","rank":"Clerk","commonTier":"T5","occupation":"Ratification Ledger Handover · Continuous Record","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#person-im-bitna","detailRoute":"/people/person-0749","birthDate":"2084-02-07","birthday":"02-07","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k749-approval-handover","name":"Approval handover","rating":60}],"traits":[{"id":"k749-choice","name":"Records competing costs","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Title: Ratification Registrar.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k749-boundary","name":"Maintains work boundaries","description":"Office. Rank: Clerk. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Office. Rank: Clerk. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-c608-cc9c-6797","name":"Yecheon Im Clan","crest":"clan-crests/c784-c608-cc9c-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":-15,"Force":-35,"Material":-30,"Communal":20,"Principle":60,"Public":-15,"Eligibility":0,"Dispersed":-20,"Transformative":-30},"desire":{"Longing":5,"Monopoly":20,"Risk":40,"Display":-10,"Sustained":15,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Ratification Ledger Handover · Continuous Record","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Ratification Registrar","Values":"Authority 20 | Openness −15 | Force −35 | Material −30 | Communal 20 | Principle 60 | Publicity −15 | Qualification 0 | Dispersion −20 | Transformation −30","Desires":"Craving 5 | Monopoly 20 | Risk 40 | Display −10 | Persistence 15 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Grew up at the Seoul Station Registry Office. The Confirmation Recorder post opened through the deletion of a single line in a double ledger.\n- Im Bitna''s work on confirmation-ledger handover and continuous records is tied to Hoehyeon-dong.","Civil Servant Position and Grade":"The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.","Anecdote":"","Relationships":"Through the handover of the confirmation-ledger handover and continuous-record work, he is connected to a senior duty officer from the same living area.","Ambition":"From the post of Confirmation Recorder, he carries on the confirmation-ledger handover and continuous records so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between duty shifts.","Fear":"","Intervention":"He can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post."},"biography":"He chooses to leave out neither the receipt time nor the hold status.\n- Livelihood: Ratification Ledger Handover · Continuous Record\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Ratification Registrar\n**Life.** Grew up at the Seoul Station Registry Office. The Confirmation Recorder post opened through the deletion of a single line in a double ledger.\n- Im Bitna''s work on confirmation-ledger handover and continuous records is tied to Hoehyeon-dong.\n\n**Civil Service Position and Grade.** The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.\n\n**Relationships.** Through the handover of the confirmation-ledger handover and continuous-record work, he is connected to a senior duty officer from the same living area.\n\n**Ambition.** From the post of Confirmation Recorder, he carries on the confirmation-ledger handover and continuous records so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between duty shifts.\n\n**Intervention.** He can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 20 | Openness −15 | Force −35 | Material −30 | Communal 20 | Principle 60 | Publicity −15 | Qualification 0 | Dispersion −20 | Transformation −30\n- Desires: Craving 5 | Monopoly 20 | Risk 40 | Display −10 | Persistence 15 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Im Bit-na","type":"Contract","to":"Yang Haeon","basis":"Im Bitna hands over the continuous record of approval receipt times and hold status to Yang Haeon. Yang Haeon checks the reviewer''s seal and the archive custody confirmation, and delivers a message with no omitted hold on the next shift."}],"incoming":[]}}', '{"id":"person-0749","name":"임빛나","title":"인준 기록관","position":"인준 기록관","characterId":"K749","rank":"주사","commonTier":"T5","occupation":"인준 장부 인수인계·연속 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-임빛나","detailRoute":"/people/person-0749","birthDate":"2084-02-07","birthday":"02-07","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","prose