INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0769', 'b178-ad50-d558-76e7', '{"id":"person-0769","name":"No Geum-ho","title":"Refugee Recorder","position":"Records Transcriber","characterId":"K769","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Transcribed Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-nogeumho","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"register-separation","name":"Separate cross-check of allocation tables and duty rosters","rating":50}],"traits":[{"id":"register-separation-disposition","name":"Refugee Recorder","description":"Title: Refugee Recorder.","behavior":"Title: Refugee Recorder.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"recorded-boundary","name":"Refugee Recorder","description":"Title: Refugee Recorder.","behavior":"Title: Refugee Recorder.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Title: Refugee Recorder.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-ad50-d558-76e7","name":"Gyoha No Clan","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-55,"Openness":60,"Force":-30,"Material":-30,"Communal":75,"Principle":50,"Public":45,"Eligibility":30,"Dispersed":60,"Transformative":-10},"desire":{"Longing":30,"Monopoly":-5,"Risk":-30,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Transcribed Records and Duty Keys Handover","Affiliation":"The Government","Rank":"Ordinary Citizen","Title":"Records Transcriber","Values":"Authority −55 | Openness 60 | Force −30 | Material −30 | Communal 75 | Principle 50 | Disclosure 45 | Qualification 30 | Dispersal 60 | Transformation −10","Desires":"Craving 30 | Monopoly −5 | Risk −30 | Display 10 | Endurance 35 | Orientation Opposite-sex | Bonding Non-exclusive"},"sections":{"Life":"Born 2098-01-15, active at the 2126 opening. Grew up at the Seoul Station registry office. The Records Copyist''s duty record contains the deletion of one line of a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for No Geumho''s records transcript and duty key handover work. It does not confirm current posting, residence, holding, or ownership.","Offices":"Rank: Ordinary Citizen. Title: Records Transcriber. She hands over only the keys and transcripts of her own duty and creates no authority that she does not have. She takes orders only from her own duty superior.","Anecdote":"","Relationships":"No Geumho receives the last line of a senior duty officer''s ledger and begins the next shift''s record.","Ambition":"","Fear":"","Intervention":""},"biography":"- Livelihood: Transcribed Records and Duty Keys Handover\n- Affiliation: The Government\n- Rank: Ordinary Citizen\n- Title: Records Transcriber\n**Life.** Born 2098-01-15, active at the 2126 opening. Grew up at the Seoul Station registry office. The Records Copyist''s duty record contains the deletion of one line of a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for No Geumho''s records transcript and duty key handover work. It does not confirm current posting, residence, holding, or ownership.\n\n**Office.** Rank: Ordinary Citizen. Title: Records Transcriber. She hands over only the keys and transcripts of her own duty and creates no authority that she does not have. She takes orders only from her own duty superior.\n\n**Relations.** No Geumho receives the last line of a senior duty officer''s ledger and begins the next shift''s record.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −55 | Openness 60 | Force −30 | Material −30 | Communal 75 | Principle 50 | Disclosure 45 | Qualification 30 | Dispersal 60 | Transformation −10\n- Desires: Craving 30 | Monopoly −5 | Risk −30 | Display 10 | Endurance 35 | Orientation Opposite-sex | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"No Geum-ho","type":"Contract","to":"Yun Choa","basis":""}],"incoming":[]}}', '{"id":"person-0769","name":"노금호","title":"피난 기록관","position":"기록 필사원","characterId":"K769","rank":"일반 시민","commonTier":"T5","occupation":"기록 필사본·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-노금호","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"register-separation","name":"배분표·당직 명부 분리 대조","rating":50}],"traits":[{"id":"register-separation-disposition","name":"피난 