INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0772', 'cangnyeong-seong-yeolcha', '{"id":"person-0772","name":"Seong Sol-hyeon","title":"Medicine Storage Clerk","position":"Medicine Storage Relief Worker","characterId":"K772","rank":"Relief Worker","commonTier":"T3","occupation":"Medicine Release Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-seongsolhyeon","detailRoute":"/people/person-0772","birthDate":"2098-10-03","birthday":"10-03","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"shift-condition-negotiation","name":"Shift condition negotiation","rating":55}],"traits":[{"id":"stated-priority","name":"Talks that reopen the next shift","description":"Overnight negotiation with a slowdown crew opened the next shift. Negotiation and sustained effort are reflected without filling in prescribing work from the title.","behavior":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Overnight negotiation with a slowdown crew opened the next shift. Negotiation and sustained effort are reflected without filling in prescribing work from the title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":35,"Force":-55,"Material":-10,"Communal":25,"Principle":45,"Public":25,"Eligibility":15,"Dispersed":15,"Transformative":-10},"desire":{"Longing":0,"Monopoly":-40,"Risk":35,"Display":10,"Sustained":20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medicine Release Records and Duty Keys Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicine Storage Clerk","Values":"Authority −10 | Openness 35 | Force −55 | Material −10 | Communal 25 | Principle 45 | Disclosure 25 | Qualification 15 | Dispersal 15 | Transformation −10","Desires":"Craving 0 | Monopoly −40 | Risk 35 | Display 10 | Endurance 20 | Orientation Same-sex | Bonding Non-exclusive"},"sections":{"Life":"Born 2098-10-03. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duties and records. In the succession record of that post, it opened as a substitute duty for an unauthorized shift absence.\n- The prescription record and duty key handover desk in Jegi-dong is taken as Seong Solhyeon''s work reference point. This posting does not confirm residence, exact facility boundaries, title, holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Medicine Storage Relief Worker. She hands over only the keys and records of her own post, and writes in the ledger the time of receipt of the keys and records she has handed over.","Anecdote":"In 2125 shared terms overnight with the slowdown work crew and opened the next shift. That day''s record remained as grounds for handover that the next duty could verify.","Relationships":"Seong Solhyeon hands the records of the reopened prescription duty over to Eun Chaeyun. Eun Chaeyun checks the triage level and clinical findings and continues the treatment of patients who were dropped during the shift-change gap.","Ambition":"From the Medicine Storage Relief Worker post, she carries on the White Cross Order''s ledger so that it is not broken.","Fear":"She fears that the Medicine Storage Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Medicine Release Records and Duty Keys Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicine Storage Clerk\n**Life.** Born 2098-10-03. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duties and records. In the succession record of that post, it opened as a substitute duty for an unauthorized shift absence.\n- The prescription record and duty key handover desk in Jegi-dong is taken as Seong Solhyeon''s work reference point. This posting does not confirm residence, exact facility boundaries, title, holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Medicine Storage Relief Worker. She hands over only the keys and records of her own post, and writes in the ledger the time of receipt of the keys and records she has handed over.\n\n**Anecdote.** In 2125 shared terms overnight with the slowdown work crew and opened the next shift. That day''s record remained as grounds for handover that the next duty could verify.\n\n**Relations.** Seong Solhyeon hands the records of the reopened prescription duty over to Eun Chaeyun. Eun Chaeyun checks the triage level and clinical findings and continues the treatment of patients who were dropped during the shift-change gap.\n\n**Ambition.** From the Medicine Storage Relief Worker post, she carries on the White Cross Order''s ledger so that it is not broken.\n\n**Fear.** She fears that the Medicine Storage Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 35 | Force −55 | Material −10 | Communal 25 | Principle 45 | Disclosure 25 | Qualification 15 | Dispersal 15 | Transformation −10\n- Desires: Craving 0 | Monopoly −40 | Risk 35 | Display 10 | Endurance 20 | Orientation Same-sex | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Seong Sol-hyeon","type":"Contract","to":"Eun Chaeyun","basis":"Seong Solhyeon hands the records of the reopened prescription duty over to Eun Chaeyun. Eun Chaeyun checks the triage level and clinical findings and continues the treatment of patients who were dropped during the shift-change gap."}],"incoming":[]}}', '{"id":"person-0772","name":"성솔현","title":"약 보관 서기","position":"약 보관 구호원","characterId":"K772","rank":"구호원","commonTier":"T3","occupation":"약 출고 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-성솔현","detailRoute":"/people/person-0772","bi