INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0787', 'c7a5-d765-b355', '{"id":"person-0787","name":"Jang Da-won","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0787","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0787","name":"장다원","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0787","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0788', 'c784-d3c9-d0dd-6797', '{"id":"person-0788","name":"Im Ba-na","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K788","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-im-bana","detailRoute":"/people/person-0788","birthDate":"2101-09-17","birthday":"09-17","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"stated-priority","name":"Signs the wrong line correction","description":"A duplicate payment line was removed and the correction signed. Numerical reconciliation is clear, while the card does not establish sanitation scope.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A duplicate payment line was removed and the correction signed. Numerical reconciliation is clear, while the card does not establish sanitation scope.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-d3c9-d0dd-6797","name":"Pyeongtaek Im Clan","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":35,"Force":-60,"Material":-20,"Communal":20,"Principle":70,"Public":20,"Eligibility":30,"Dispersed":20,"Transformative":-15},"desire":{"Longing":20,"Monopoly":-40,"Risk":-25,"Display":-20,"Sustained":15,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −30 | Openness 35 | Force −60 | Material −20 | Communal 20 | Principle 70 | Publicity 20 | Qualification 30 | Decentralization 20 | Transformation −15","Desires":"Craving 20 | Exclusivity −40 | Risk −25 | Display −20 | Endurance 15 | Orientation opposite-sex | Bonding non-exclusive"},"sections":{"Life":"Born on 2101-09-17. As of the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- Im Bana''s work reference point is the epidemic control records and duty-key handover window in Jegi-dong. This placement does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.","Relationships":"Im Bana hands the corrected quarantine ledger and the handover signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records to distinguish duplicated lines from actual patient movement.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first the option that keeps the duty watch unbroken. Trusts a single ledger line over loud talk.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born on 2101-09-17. As of the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- Im Bana''s work reference point is the epidemic control records and duty-key handover window in Jegi-dong. This placement does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.\n\n**Relationships.** Im Bana hands the corrected quarantine ledger and the handover signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records to distinguish duplicated lines from actual patient movement.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 35 | Force −60 | Material −20 | Communal 20 | Principle 70 | Publicity 20 | Qualification 30 | Decentralization 20 | Transformation −15\n- Desires: Craving 20 | Exclusivity −40 | Risk −25 | Display −20 | Endurance 15 | Orientation opposite-sex | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Im Ba-na","type":"Contract","to":"Ra Seyeong","basis":"Im Bana hands the corrected quarantine ledger and the handover signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records to distinguish duplicated lines from actual patient movement."}],"incoming":[]}}', '{"id":"person-0788","name":"임바나","title":"방역 기록관","position":"방역 구호원","characterId":"K788","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-임바나","detailRoute":"/people/person-0788","birthDate":"2101-09-17","birthday":"09-17","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"지급 장부 대조","rating":50}],"traits":[{"id":"stated-priority","name":"틀린 한 줄을 서명한다","description":"이중 지급 줄을 지우고 정정에 서명했다. 숫자 대조는 분명하지만 방역 실무의 범위는 짧은 카드로 확정할 수 없다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"이중 지급 줄을 지우고 정정에 서명했다. 숫자 대조는 분명하지만 방역 실무의 범위는 짧은 카드로 확정할 수 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-d3c9-d0dd-6797","name":"평택 임씨","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":35,"무력":-60,"물질":-20,"공동":20,"원칙":70,"공개":20,"자격":30,"분산":20,"변혁":-15},"desire":{"갈망":20,"독점":-40,"위험":-25,"과시":-20,"지속":15,"지향":"이성","결합":"비독점"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −30 | 개방 35 | 무력 −60 | 물질 −20 | 공동 20 | 원칙 70 | 공개 20 | 자격 30 | 분산 20 | 변혁 −15","욕망":"갈망 20 | 독점 −40 | 위험 −25 | 과시 −20 | 지속 15 | 지향 이성 | 결합 비독점"},"sections":{"생애":"2101-09-17에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 임바나의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2101-09-17에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 임바나의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 35 | 무력 −60 | 물질 −20 | 공동 20 | 원칙 70 | 공개 20 | 자격 30 | 분산 20 | 변혁 −15\n- 욕망: 갈망 20 | 독점 −40 | 위험 −25 | 과시 −20 | 지속 15 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"임바나","type":"계약","to":"라세영","basis":"임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0789', 'd55c-ccad-c8fc', '{"id":"person-0789","name":"Han Ga-seo","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S14","stateName":"The Government","detailRoute":"/people/person-0789","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0789","name":"한가서","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S14","stateName":"정부","detailRoute":"/people/person-0789","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0790', 'c624-d574-c8fc', '{"id":"person-0790","name":"O Ra-seo","title":"Auction Clerk","position":"Myeongdong Station Records Clerk","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Handover Log","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0790","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0790","name":"오라서","title":"경매 서기","position":"명동역 기록 서기","rank":"일반 시민","commonTier":"T5","occupation":"기록·인수인계 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0790","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0791', 'c11c-b2ec-c131', '{"id":"person-0791","name":"Seo Sa-seo","title":"Audit Recorder","position":"Audit Recorder","characterId":"K791","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#inmul-seosaseo","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audit-access-custody","name":"Audit access custody","rating":60}],"traits":[{"id":"evidenced-choice","name":"Audit Recorder","description":"Title: Audit Recorder.","behavior":"Title: Audit Recorder.","stress":"May recheck originals and handovers when shifts are blocked or records disappear.","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"In the audit recorder''s seat, keeps the Suseo Station Union ledger unbroken and, even if workshop factions split, protects the result of the all-member direct election of the chair.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]}],"narrative":"Title: Audit Recorder.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":35,"Force":-20,"Material":-5,"Communal":15,"Principle":40,"Public":25,"Eligibility":25,"Dispersed":45,"Transformative":0},"desire":{"Longing":30,"Monopoly":40,"Risk":20,"Display":-40,"Sustained":20,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Audit Log and Duty Key Handover","Affiliation":"Arc","Community Role":"Guild Member","Duty":"Audit Recorder","Values":"Authority −25 | Openness 35 | Force −20 | Material −5 | Communal 15 | Principle 40 | Publicity 25 | Qualification 25 | Decentralization 45 | Transformation 0","Desires":"Craving 30 | Exclusivity 40 | Risk 20 | Display −40 | Endurance 20 | Orientation same-sex | Bonding contract cohabitation"},"sections":{"Life":"Born on 2092-08-31, Seo Saseo works as an Audit Records Officer at the Suseo Station union workshop in the winter. Checks the records of direct elections by union members and public votes, and distinguishes offices conferred by the Government from community duties.\n- Seo Saseo works as an Audit Records Officer at the Suseo Station union workshop in Suseo-dong. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.","Duty":"The community role is Guild Member, and the duty is keeping machine-body maintenance records. This is a role within the Arc, not a government office or rank.","Anecdote":"","Relationships":"Seo Saseo''s existing relationship records are as follows. Bound by duty shifts and handovers with a senior in the same work and living sphere.","Goals":"Seo Saseo seeks to keep the signing, handover, and public procedures of the Audit Records Officer''s work verifiable in the Suseo Station union ledger.","Fear":"That the signatures or handover records of the Audit Records Officer''s work will be altered, so that Seo Saseo''s scope of responsibility and the union members'' public procedures collapse together.","Intervention":"Seo Saseo can cross-check the relevant signatures and handover times and make the records public, but cannot confer new offices, ranks, rights, or holdings."},"biography":"In winter, Seo Saseo first cross-checks the machine-body repair records keeping work records against the parts stock sheet at the Arc workshop. On days when parts run short, receipt times and handover order are entered in the same ledger.\n\n- Livelihood: Audit Log and Duty Key Handover\n- Affiliation: Arc\n- Community Role: Guild Member\n- Duty: Audit Recorder\n**Life.** Born on 2092-08-31, Seo Saseo works as an Audit Records Officer at the Suseo Station union workshop in the winter. Checks the records of direct elections by union members and public votes, and distinguishes offices conferred by the Government from community duties.\n- Seo Saseo works as an Audit Records Officer at the Suseo Station union workshop in Suseo-dong. This work reference point does not fix a residence, exact facility boundaries, a rank, a holding, or tenure rights.\n\n**Duty.** The community role is Guild Member, and the duty is keeping machine-body maintenance records. This is a role within the Arc, not a government office or rank.\n\n**Relationships.** Seo Saseo''s existing relationship records are as follows. Bound by duty shifts and handovers with a senior in the same work and living sphere.\n\n**Goal.** Seo Saseo seeks to keep the signing, handover, and public procedures of the Audit Records Officer''s work verifiable in the Suseo Station union ledger.\n\n**Fear.** That the signatures or handover records of the Audit Records Officer''s work will be altered, so that Seo Saseo''s scope of responsibility and the union members'' public procedures collapse together.\n\n**Intervention.** Seo Saseo can cross-check the relevant signatures and handover times and make the records public, but cannot confer new offices, ranks, rights, or holdings.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 35 | Force −20 | Material −5 | Communal 15 | Principle 40 | Publicity 25 | Qualification 25 | Decentralization 45 | Transformation 0\n- Desires: Craving 30 | Exclusivity 40 | Risk 20 | Display −40 | Endurance 20 | Orientation same-sex | Bonding contract cohabitation\n:::","relations":{"outgoing":[{"from":"Seo Sa-seo","type":"Contract","to":"Gwak Eunjae","basis":"Seo Sa-seo informs Gwak Eunjae of the storage status of maintenance records awaiting public review and of the patrol delay slots marked in them. Gwak Eunjae checks the review copy so that no closing seal is stamped before public confirmation."}],"incoming":[]}}', '{"id":"person-0791","name":"서사서","title":"감사 기록관","position":"감사 기록관","characterId":"K791","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#인물-서사서","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audit-access-custody","name":"감사 열람 보관","rating":60}],"traits":[{"id":"evidenced-choice","name":"감사 기록관","description":"직함은 감사 기록관.","behavior":"직함은 감사 기록관.","stress":"교대가 막히거나 기록이 사라지면 원본과 인계를 재확인할 수 있다.","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]},{"id":"handover-continuity","name":"기록 단절 경계","description":"감사 기록관 자리에서 수서역 조합 장부를 끊기지 않게 잇고, 작업장 파벌이 갈려도 조합원 전원의 위원장 직접선거 결과를 지킨다.","behavior":"맡은 기록과 서명의 연결을 확인하려 한다.","stress":"","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]}],"narrative":"직함은 감사 기록관.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":35,"무력":-20,"물질":-5,"공동":15,"원칙":40,"공개":25,"자격":25,"분산":45,"변혁":0},"desire":{"갈망":30,"독점":40,"위험":20,"과시":-40,"지속":20,"지향":"동성","결합":"계약동거"},"fields":{"생업":"감사 기록·당직 열쇠 인계","소속":"Arc","공동체 역할":"조합원","직무":"감사 기록관","가치관":"권위 −25 | 개방 35 | 무력 −20 | 물질 −5 | 공동 15 | 원칙 40 | 공개 25 | 자격 25 | 분산 45 | 변혁 0","욕망":"갈망 30 | 독점 40 | 위험 20 | 과시 −40 | 지속 20 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"2092-08-31에 태어난 서사서는 겨울의 수서역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 서사서는 수서동의 수서역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.","직무":"공동체 역할은 조합원이며 맡은 일은 기계몸 정비 기록 보관이다. 이 일은 Arc 안의 역할이고 정부 관직이나 품계가 아니다.","일화":"","관계":"서사서의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.","목표":"서사서는 감사 기록관 업무의 서명·인계·공개 절차를 수서역 조합 장부에서 검증 가능하게 유지하려 한다.","공포":"감사 기록관 업무의 서명이나 인계 기록이 바뀌어 서사서의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.","개입":"서사서는 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다."},"biography":"서사서는 겨울의 Arc 작업장에서 기계몸 정비 기록 보관 업무 기록과 부품 재고표를 먼저 대조한다. 부품이 모자란 날에는 접수 시각과 인계 순서를 같은 장부에 남긴다.\n\n- 생업: 감사 기록·당직 열쇠 인계\n- 소속: Arc\n- 공동체 역할: 조합원\n- 직무: 감사 기록관\n**생애.** 2092-08-31에 태어난 서사서는 겨울의 수서역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 서사서는 수서동의 수서역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·직위·영지·점유권을 정하지 않는다.\n\n**직무.** 공동체 역할은 조합원이며 맡은 일은 기계몸 정비 기록 보관이다. 이 일은 Arc 안의 역할이고 정부 관직이나 품계가 아니다.\n\n**관계.** 서사서의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.\n\n**목표.** 서사서는 감사 기록관 업무의 서명·인계·공개 절차를 수서역 조합 장부에서 검증 가능하게 유지하려 한다.\n\n**공포.** 감사 기록관 업무의 서명이나 인계 기록이 바뀌어 서사서의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.\n\n**개입.** 서사서는 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 35 | 무력 −20 | 물질 −5 | 공동 15 | 원칙 40 | 공개 25 | 자격 25 | 분산 45 | 변혁 0\n- 욕망: 갈망 30 | 독점 40 | 위험 20 | 과시 −40 | 지속 20 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"서사서","type":"계약","to":"곽은재","basis":"서사서는 공개 열람을 기다리는 정비 기록의 보관 상태와 표시한 순찰 지연 칸을 곽은재에게 알린다. 곽은재는 열람 사본을 확인해 공개 확인 전 종결 도장이 찍히지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0792', 'c2e0-d3c9-c0b0', '{"id":"person-0792","name":"Sin Cha-min","title":"Concourse Heating Checker","position":"Concourse Heating Checker","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Male","stage":"S4","state":"S01","stateName":"Free City","detailRoute":"/people/person-0792","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0792","name":"신차민","title":"대합실 난방 점검원","position":"대합실 난방 점검원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"남성","stage":"S4","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0792","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0793', 'ad8c-c548-b3d9', '{"id":"person-0793","name":"Gwon Payun","title":"Restoration Service Recorder","position":"Restoration Service Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Registration & Records","gender":"Female","stage":"S4","state":"S02","stateName":"Free City","detailRoute":"/people/person-0793","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0793","name":"권파윤","title":"복구복무 기록관","position":"복구복무 기록관","rank":"조합원","commonTier":"T5","occupation":"등기·기록","gender":"여성","stage":"S4","state":"S02","stateName":"자유도시","detailRoute":"/people/person-0793","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0794', 'd669-d3c9-d574-9ec3', '{"id":"person-0794","name":"Hwang Euna","title":"Certification Courier","position":"Certification Courier","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0794","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0794","name":"황은아","title":"인증 전령","position":"인증 전령","rank":"일반 시민","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0794","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0795', 'c548-c21c-d765', '{"id":"person-0795","name":"An Namneul","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K795","rank":"Ordinary Citizen","commonTier":"T3","occupation":"Wheel & Pump Maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-annamneul","detailRoute":"/people/person-0795","birthDate":"2096-09-23","birthday":"09-23","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"wheel","name":"Wheel-defect inspection","rating":50},{"id":"handover","name":"Record and key handover","rating":40}],"traits":[{"id":"stop-for-wheel-defects","name":"Stop for Wheel Defects","description":"An Namneul shows a disposition to prioritize stopping over continued movement when a wheel defect is detected.","behavior":"She detected a wheel defect by touch and stopped the train just before derailment.","stress":"If continued operation conflicts with addressing a defect, she may choose to stop first to protect passage.","relationship":"During handover to senior duty staff, she may emphasize the wheel defect she detected and the resulting stop.","effects":[]},{"id":"no-invented-authority","name":"No Invented Authority","description":"An Namneul maintains a boundary against claiming powers her position does not grant, even when addressing defects.","behavior":"She transfers only her position’s keys and records without treating defect detection as a source of additional authority.","stress":"Even if she fears a duty gap, she may seek continuity within her remit rather than expand her authority.","relationship":"With senior duty staff, she may favor clear boundaries around which keys and records she can transfer.","effects":[]}],"narrative":"She detected a wheel defect by touch and stopped a train. Narrow inspection is supported; a parts trader’s transaction history is absent.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41131-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41131-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41133-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41133-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41135-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41135-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41461-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41461-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41463-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41463-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41465-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41465-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-43111-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43111-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43112-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43112-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43113-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43113-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43114-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43114-S04","directLiegePersonId":"K108"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":20,"Force":-25,"Material":35,"Communal":40,"Principle":0,"Public":-10,"Eligibility":40,"Dispersed":25,"Transformative":-10},"desire":{"Longing":0,"Monopoly":-40,"Risk":-30,"Display":25,"Sustained":5,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Affiliation":"Arc","Livelihood":"Wheel & Pump Maintenance","Rank":"Ordinary Citizen","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 20 | Force −25 | Material 35 | Communal 40 | Principle 0 | Publicity −10 | Qualification 40 | Decentralization 25 | Transformation −10","Desires":"Craving 0 | Monopoly −40 | Risk −30 | Display 25 | Persistence 5 | Orientation Fluid | Bonding Monogamous"},"sections":{"Life":"Generation of 2126. An Namneul grew up at the Sinjeong Depot. An Namneul took the Parts Logistics Steward post after reporting a defect just before a derailment.\n- An Namneul''s Parts Logistics Steward duties are tied to Cheonho 3-dong.","Offices":"An Namneul hands over only the keys and records that come with the post. They do not invent authority they do not hold.","Anecdote":"In 2125, An Namneul caught a wheel defect just before a derailment on the stabling siding and stopped the train. Because of this, the signature for the Parts Logistics Steward post was entered in the ledger.","Relationships":"An Namneul is bound by handover to a senior duty officer from the same living sphere.","Ambition":"As Parts Logistics Steward on duty, An Namneul wants to keep the Arc''s ledger unbroken.","Fear":"","Intervention":"An Namneul can bring in a witness for a duty handover or expose an empty key."},"biography":"An Namneul chooses first not to break the duty chain. An Namneul trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Arc\n- Livelihood: Wheel & Pump Maintenance\n- Rank: Ordinary Citizen\n- Title: Parts Logistics Merchant\n**Life.** Generation of 2126. An Namneul grew up at the Sinjeong Depot. An Namneul took the Parts Logistics Steward post after reporting a defect just before a derailment.\n- An Namneul''s Parts Logistics Steward duties are tied to Cheonho 3-dong.\n\n**Office.** An Namneul hands over only the keys and records that come with the post. They do not invent authority they do not hold.\n\n**Anecdote.** In 2125, An Namneul caught a wheel defect just before a derailment on the stabling siding and stopped the train. Because of this, the signature for the Parts Logistics Steward post was entered in the ledger.\n\n**Relationships.** An Namneul is bound by handover to a senior duty officer from the same living sphere.\n\n**Ambition.** As Parts Logistics Steward on duty, An Namneul wants to keep the Arc''s ledger unbroken.\n\n**Intervention.** An Namneul can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 20 | Force −25 | Material 35 | Communal 40 | Principle 0 | Publicity −10 | Qualification 40 | Decentralization 25 | Transformation −10\n- Desires: Craving 0 | Monopoly −40 | Risk −30 | Display 25 | Persistence 5 | Orientation Fluid | Bonding Monogamous\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0795","name":"안남늘","title":"부품 물류상","position":"부품 물류상","characterId":"K795","rank":"일반 시민","commonTier":"T3","occupation":"차륜·펌프 정비","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-안남늘","detailRoute":"/people/person-0795","birthDate":"2096-09-23","birthday":"09-23","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"wheel","name":"차륜 결함 점검","rating":50},{"id":"handover","name":"기록·열쇠 인수인계","rating":40}],"traits":[{"id":"stop-for-wheel-defects","name":"바퀴 결함에 정지","description":"안남늘은 바퀴의 실제 결함을 확인하면 운행보다 정지를 우선하는 성향을 보인다.","behavior":"탈선 직전 바퀴 결함을 손으로 감지해 열차를 세웠다.","stress":"운행 지속과 결함 대응이 충돌하면 통행을 지키기 위해 먼저 멈추는 선택을 할 수 있다.","relationship":"선배 당직에게 인계할 때 자신이 확인한 바퀴 결함과 정지 사실을 중요하게 전달할 수 있다.","effects":[]},{"id":"no-invented-authority","name":"없는 권한 만들지 않기","description":"안남늘은 결함에 대응하더라도 자기 직위에 없는 권한을 내세우지 않는 태도를 지닌다.","behavior":"자기 직위의 열쇠와 기록만 넘기며 결함 발견을 근거로 별도의 권한을 만들어 내지 않는다.","stress":"당직 공백이 두려워도 대응 범위를 넓히기보다 맡은 권한 안에서 연속성을 지키려 할 수 있다.","relationship":"선배 당직과는 넘길 수 있는 열쇠와 기록의 범위를 분명히 하는 관계를 선호할 수 있다.","effects":[]}],"narrative":"탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 점검의 좁은 강점이며 부품 상인의 거래 이력은 원문에 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41131-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41131-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41133-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41133-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41135-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41135-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41461-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41461-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41463-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41463-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41465-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41465-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-43111-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43111-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43112-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43112-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43113-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43113-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43114-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43114-S04","directLiegePersonId":"K108"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":20,"무력":-25,"물질":35,"공동":40,"원칙":0,"공개":-10,"자격":40,"분산":25,"변혁":-10},"desire":{"갈망":0,"독점":-40,"위험":-30,"과시":25,"지속":5,"지향":"유동","결합":"단혼"},"fields":{"소속":"Arc","생업":"차륜·펌프 정비","품계":"일반 시민","직함":"부품 물류상","가치관":"권위 −5 | 개방 20 | 무력 −25 | 물질 35 | 공동 40 | 원칙 0 | 공개 −10 | 자격 40 | 분산 25 | 변혁 −10","욕망":"갈망 0 | 독점 −40 | 위험 −30 | 과시 25 | 지속 5 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2126년 세대. 안남늘은 신정 차량기지에서 자랐다. 안남늘은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 안남늘의 부품 물류상 업무는 천호3동과 연결된다.","관직":"안남늘은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 안남늘은 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"안남늘은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"안남늘은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"","개입":"안남늘은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"안남늘은 당직을 끊지 않는 쪽을 먼저 고른다. 안남늘은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 차륜·펌프 정비\n- 품계: 일반 시민\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 안남늘은 신정 차량기지에서 자랐다. 안남늘은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 안남늘의 부품 물류상 업무는 천호3동과 연결된다.\n\n**관직.** 안남늘은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 안남늘은 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 안남늘은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 안남늘은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**개입.** 안남늘은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 20 | 무력 −25 | 물질 35 | 공동 40 | 원칙 0 | 공개 −10 | 자격 40 | 분산 25 | 변혁 −10\n- 욕망: 갈망 0 | 독점 −40 | 위험 −30 | 과시 25 | 지속 5 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0796', 'c1a1-d64d-c8fc-5b8b', '{"id":"person-0796","name":"Song Neulji","title":"Eastern Command Guard Squad","position":"Eastern Patrol","rank":"Guard","commonTier":"T5","occupation":"Investigating Ridge Patrol and Ambush Traces","gender":"Male","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0796","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0796","name":"송늘지","title":"동방사 경비조","position":"동부 순찰대","rank":"경비대원","commonTier":"T5","occupation":"능선 초계·매복 흔적 조사","gender":"남성","stage":"S4","state":"S05","stateName":"Arc","detailRoute":"/people/person-0796","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0797', 'b958-bb38-d654-67f3', '{"id":"person-0797","name":"Ryu Dalhyeon","title":"Ratification Registrar","position":"Ratification Registrar","characterId":"K797","rank":"Clerk","commonTier":"T5","occupation":"Ratification Ledger Handover · Continuous Record","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#Person-Ryu-Dalhyeon","detailRoute":"/people/person-0797","birthDate":"2095-11-29","birthday":"11-29","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k797-seal-time-log","name":"Seal time logging","rating":60}],"traits":[{"id":"k797-choice","name":"Records during suspension","description":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","behavior":"Title: Ratification Registrar.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k797-boundary","name":"Maintains work boundaries","description":"Office. Rank: Clerk. Title: ratification registrar. She handed over only the keys and records of her own post, and never made authority she did not hold.","behavior":"Office. Rank: Clerk. Title: ratification registrar. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Title: Ratification Registrar.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":25,"Openness":-5,"Force":-25,"Material":-25,"Communal":10,"Principle":75,"Public":-5,"Eligibility":0,"Dispersed":-40,"Transformative":-35},"desire":{"Longing":0,"Monopoly":30,"Risk":25,"Display":-15,"Sustained":35,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Ratification Ledger Handover · Continuous Record","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Ratification Registrar","Values":"Authority 25 | Openness −5 | Force −25 | Material −25 | Communal 10 | Principle 75 | Publicity −5 | Qualification 0 | Decentralization −40 | Transformation −35","Desires":"Craving 0 | Monopoly 30 | Risk 25 | Display −15 | Persistence 35 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Grew up at the Seoul Station Registry. The Approval Records Officer post opened through the deletion of a single line in a double ledger.\n- Ryu Dalhyeon''s approval ledger handover and continuity records work is linked to Hoehyeon-dong.","Civil Servant Position and Grade":"The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.","Anecdote":"","Relationships":"Through the handover of the confirmation-ledger handover and continuous-record work, she is connected to a senior duty officer from the same living area.","Ambition":"","Fear":"","Intervention":"She can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post."},"biography":"Will not let the handover be broken by pressure from loud voices.\n\n- Livelihood: Ratification Ledger Handover · Continuous Record\n- Affiliation: Seoul Metropolitan Government Local Civil Service Organization\n- Position and Grade: The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Assigned Duties: Ratification Registrar\n**Life.** Grew up at the Seoul Station Registry. The Approval Records Officer post opened through the deletion of a single line in a double ledger.\n- Ryu Dalhyeon''s approval ledger handover and continuity records work is linked to Hoehyeon-dong.\n\n**Civil Servant Position and Grade.** The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.\n\n**Relationships.** Through the handover of the confirmation-ledger handover and continuous-record work, she is connected to a senior duty officer from the same living area.\n\n**Intervention.** She can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 25 | Openness −5 | Force −25 | Material −25 | Communal 10 | Principle 75 | Publicity −5 | Qualification 0 | Decentralization −40 | Transformation −35\n- Desires: Craving 0 | Monopoly 30 | Risk 25 | Display −15 | Persistence 35 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Ryu Dalhyeon","type":"Contract","to":"Yang Haeon","basis":"Ryu Dalhyeon hands over to Yang Haeon the seal times and approval-hold order that she confirmed at each shift. Yang Haeon checks the review seal and the custody confirmation so that the hold status does not vanish from the next message."}],"incoming":[]}}', '{"id":"person-0797","name":"류달현","title":"인준 기록관","position":"인준 기록관","characterId":"K797","rank":"주사","commonTier":"T5","occupation":"인준 장부 인수인계·연속 기록","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-류달현","detailRoute":"/people/person-0797","birthDate":"2095-11-29","birthday":"11-29","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k797-seal-time-log","name":"봉인 시각 기록","rating":60}],"traits":[{"id":"k797-choice","name":"보류 중에도 기록","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"직함은 인준 기록관.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k797-boundary","name":"업무 경계를 지킴","description":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"직함은 인준 기록관.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":25,"개방":-5,"무력":-25,"물질":-25,"공동":10,"원칙":75,"공개":-5,"자격":0,"분산":-40,"변혁":-35},"desire":{"갈망":0,"독점":30,"위험":25,"과시":-15,"지속":35,"지향":"유동","결합":"비독점"},"fields":{"생업":"인준 장부 인수인계·연속 기록","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"인준 기록관","가치관":"권위 25 | 개방 −5 | 무력 −25 | 물질 −25 | 공동 10 | 원칙 75 | 공개 −5 | 자격 0 | 분산 −40 | 변혁 −35","욕망":"갈망 0 | 독점 30 | 위험 25 | 과시 −15 | 지속 35 | 지향 유동 | 결합 비독점"},"sections":{"생애":"서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 류달현의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.","일화":"","관계":"인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"","공포":"","개입":"인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"큰소리에 밀려 인수인계가 끊기게 두지 않는 쪽이다.\n\n- 생업: 인준 장부 인수인계·연속 기록\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 인준 기록관\n**생애.** 서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 류달현의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.\n\n**관계.** 인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**개입.** 인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 25 | 개방 −5 | 무력 −25 | 물질 −25 | 공동 10 | 원칙 75 | 공개 −5 | 자격 0 | 분산 −40 | 변혁 −35\n- 욕망: 갈망 0 | 독점 30 | 위험 25 | 과시 −15 | 지속 35 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"류달현","type":"계약","to":"양해온","basis":"류달현은 교대마다 확인한 봉인 시각과 인준 보류 순서를 양해온에게 넘긴다. 양해온은 심사 날인과 보관 확인을 살펴 보류 상태가 다음 전갈에서 사라지지 않게 한다."}],"incoming":[]}}');
