INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0809', 'd558-c9c4-c8fc', '{"id":"person-0809","name":"Ha Gujae","title":"Work Crew Courier","position":"Work Crew Courier","rank":"Guild Member","commonTier":"T5","occupation":"Transfer Message Delivery","gender":"Male","stage":"S4","state":"S02","stateName":"Free City","detailRoute":"/people/person-0809","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0809","name":"하구재","title":"작업반 전령","position":"작업반 전령","rank":"조합원","commonTier":"T5","occupation":"환승 전갈 전달","gender":"남성","stage":"S4","state":"S02","stateName":"자유도시","detailRoute":"/people/person-0809","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0810', 'acfd-d604-d48d', '{"id":"person-0810","name":"Gwak Gangho","title":"Seed Stock Recorder","position":"Seed Stock Recorder","characterId":"K810","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#Person-Gwak-Gangho","detailRoute":"/people/person-0810","birthDate":"2071-10-16","birthday":"10-16","age":55,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"inventory","name":"Seed-list reconciliation","rating":55},{"id":"copy","name":"Document copying and preservation","rating":45}],"traits":[{"id":"read-items-one-by-one","name":"Read Items One by One","description":"Gwak Gangho makes list agreement explicit by reading items aloud individually.","behavior":"They read the items in the seed records and the proposed joint technical register list aloud before Park Jinsol.","stress":"If differences between lists threaten record continuity, they may place greater weight on item-by-item checking.","relationship":"When checking lists with Park Jinsol, they may favor reading aloud so both can follow the same items.","effects":[]},{"id":"joint-list-checking","name":"Joint List Checking","description":"Gwak Gangho values correspondence between a proposed joint technical register list and existing seed records.","behavior":"They prepare a copy aligning the two lists and verify its contents before Park Jinsol.","stress":"When a new price column makes correspondence between records more consequential, they may become more alert to list discrepancies.","relationship":"When aligning shared records with Park Jinsol, they may use the matched copy as a common reference.","effects":[]}],"narrative":"She reconciled two seed lists, copied them, and read each item aloud. Specific checking is supported, not negotiating seed prices.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":25,"Force":-25,"Material":20,"Communal":-10,"Principle":60,"Public":50,"Eligibility":50,"Dispersed":15,"Transformative":0},"desire":{"Longing":-15,"Monopoly":-35,"Risk":-35,"Display":-30,"Sustained":20,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Records and Keys Handover","Rank":"Ordinary Citizen","Title":"Seed Stock Recorder","Duty":"Daechi 1-dong. At Daechi 1-dong, Gwak Gangho matches the seed records and handover signatures against the originals and passes them to the next shift. Any unreadable copy or misaligned seal is sent to Bak Jinsol together with the original.","Values":"Authority −10 | Openness 25 | Force −25 | Materialism 20 | Community −10 | Principle 60 | Publicity 50 | Qualification 50 | Decentralization 15 | Transformation 0","Desires":"Craving −15 | Monopoly −35 | Risk −35 | Display −30 | Persistence 20 | Orientation Heterosexual | Bonding Polyamorous"},"sections":{"Life":"Generation of 2126. Raised at the Seoul Station Registry Office. Gwak Gangho is in charge of matching the seed records with the vault''s handover records.\n- Duties: Daechi 1-dong. At Daechi 1-dong, Gwak Gangho matches the seed records and handover signatures against the originals and passes them to the next shift. Any unreadable copy or misaligned seal is sent to Bak Jinsol together with the original.","Offices":"Rank: Ordinary Citizen. Title: Seed Stock Recorder. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.","Anecdote":"News reaches the vault that a seed price column has opened in Nam Yungyeong''s Price Ledger. Gwak Gangho makes a copy in which the items of the seed list that Bak Jinsol wants to post to the Joint Technology Ledger are matched with the seed records, and in front of Bak Jinsol she reads the items of the two lists aloud, one by one.","Relationships":"Gwak Gangho reads aloud, in front of Bak Jinsol, a copy in which the seed records have been cross-checked against the list to be entered in the Joint Technical Ledger. Bak Jinsol verifies the items and preservation records so that the seed prices in the price ledger and the actual storage list are not mixed up.","Ambition":"Gwak Gangho wants to match the seed items to be posted to the Joint Technology Ledger against the preservation records one entry at a time, keeping them distinct from the price column of the Price Ledger.","Fear":"That items from the price list will be copied as if they were the actual stored seed list and get mixed into Bak Jinsol''s release decisions.","Intervention":"The player can compare the two lists that Gwak Gangho read aloud with the original items."},"biography":"At Daechi 1-dong, Gwak Gangho first checks the seed originals for missing lines. Even when pressed to hurry the vault release, she matches the handover records with the temperature-and-humidity log before passing them to Bak Jinsol.\n\n- Affiliation: Arc\n- Livelihood: Records and Keys Handover\n- Rank: Ordinary Citizen\n- Title: Seed Stock Recorder\n**Life.** Generation of 2126. Raised at the Seoul Station Registry Office. Gwak Gangho is in charge of matching the seed records with the vault''s handover records.\n- Duties: Daechi 1-dong. At Daechi 1-dong, Gwak Gangho matches the seed records and handover signatures against the originals and passes them to the next shift. Any unreadable copy or misaligned seal is sent to Bak Jinsol together with the original.\n\n**Office.** Rank: Ordinary Citizen. Title: Seed Stock Recorder. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.\n\n**Anecdote.** News reaches the vault that a seed price column has opened in Nam Yungyeong''s Price Ledger. Gwak Gangho makes a copy in which the items of the seed list that Bak Jinsol wants to post to the Joint Technology Ledger are matched with the seed records, and in front of Bak Jinsol she reads the items of the two lists aloud, one by one.\n\n**Relationships.** Gwak Gangho reads aloud, in front of Bak Jinsol, a copy in which the seed records have been cross-checked against the list to be entered in the Joint Technical Ledger. Bak Jinsol verifies the items and preservation records so that the seed prices in the price ledger and the actual storage list are not mixed up.\n\n**Ambition.** Gwak Gangho wants to match the seed items to be posted to the Joint Technology Ledger against the preservation records one entry at a time, keeping them distinct from the price column of the Price Ledger.\n\n**Fear.** That items from the price list will be copied as if they were the actual stored seed list and get mixed into Bak Jinsol''s release decisions.\n\n**Intervention.** The player can compare the two lists that Gwak Gangho read aloud with the original items.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 25 | Force −25 | Materialism 20 | Community −10 | Principle 60 | Publicity 50 | Qualification 50 | Decentralization 15 | Transformation 0\n- Desires: Craving −15 | Monopoly −35 | Risk −35 | Display −30 | Persistence 20 | Orientation Heterosexual | Bonding Polyamorous\n:::","relations":{"outgoing":[{"from":"Gwak Gangho","type":"Contract","to":"Bak Jinsol","basis":"Gwak Gangho reads aloud, in front of Bak Jinsol, a copy in which the seed records have been cross-checked against the list to be entered in the Joint Technical Ledger. Bak Jinsol verifies the items and preservation records so that the seed prices in the price ledger and the actual storage list are not mixed up."}],"incoming":[]}}', '{"id":"person-0810","name":"곽강호","title":"종자 기록관","position":"종자 기록관","characterId":"K810","rank":"일반 시민","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-곽강호","detailRoute":"/people/person-0810","birthDate":"2071-10-16","birthday":"10-16","age":55,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"inventory","name":"종자 품목 목록 대조","rating":55},{"id":"copy","name":"문서 필사·보존","rating":45}],"traits":[{"id":"read-items-one-by-one","name":"품목 하나씩 낭독","description":"곽강호는 목록의 일치를 품목별 낭독으로 드러내 확인하는 쪽이다.","behavior":"박진솔 앞에서 종자 기록과 공동기술원장용 목록의 품목을 하나씩 소리 내어 읽는다.","stress":"목록 차이가 기록 연속성을 해칠 우려가 있으면 품목별 확인을 더 중시할 수 있다.","relationship":"박진솔과 목록을 확인할 때 상대가 함께 들을 수 있는 낭독을 확인 방식으로 삼을 수 있다.","effects":[]},{"id":"joint-list-checking","name":"공동 목록 대조","description":"곽강호는 공동기술원장에 올릴 목록과 기존 종자 기록의 대응을 중시한다.","behavior":"두 목록의 품목을 맞춘 사본을 만들고 박진솔 앞에서 대조 내용을 확인한다.","stress":"새 시세 칸이 열려 기록 간 대응이 중요해지면 목록 불일치를 더 경계할 수 있다.","relationship":"박진솔과 공동 기록을 맞출 때 대조 사본을 공유 근거로 삼을 수 있다.","effects":[]}],"narrative":"종자 목록 두 벌을 맞춰 사본을 만들고 품목을 소리 내어 확인했다. 구체적 대조는 확인되나 종자 가격 협상은 수행하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"acfd-d604-d48d","name":"현풍 곽씨","crest":"clan-crests/acfd-d604-d48d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":25,"무력":-25,"물질":20,"공동":-10,"원칙":60,"공개":50,"자격":50,"분산":15,"변혁":0},"desire":{"갈망":-15,"독점":-35,"위험":-35,"과시":-30,"지속":20,"지향":"이성","결합":"다자"},"fields":{"소속":"Arc","생업":"기록·열쇠 인수인계","품계":"일반 시민","직함":"종자 기록관","업무":"대치1동. 곽강호는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 읽히지 않는 사본이나 어긋난 날인은 박진솔에게 원본과 함께 전한다.","가치관":"권위 −10 | 개방 25 | 무력 −25 | 물질 20 | 공동 −10 | 원칙 60 | 공개 50 | 자격 50 | 분산 15 | 변혁 0","욕망":"갈망 −15 | 독점 −35 | 위험 −35 | 과시 −30 | 지속 20 | 지향 이성 | 결합 다자"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 곽강호는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 대치1동. 곽강호는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 읽히지 않는 사본이나 어긋난 날인은 박진솔에게 원본과 함께 전한다.","관직":"품계 일반 시민. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.","일화":"남윤경의 가격 원장에 종자 시세 칸이 열렸다는 소식이 보존고에 닿는다. 곽강호는 박진솔이 공동기술원장에 올리려는 종자 목록과 종자 기록의 품목을 맞춘 사본을 만들고, 박진솔 앞에서 두 목록의 품목을 하나씩 소리 내어 읽는다.","관계":"곽강호는 종자 기록과 공동기술원장에 올릴 목록을 대조한 사본을 박진솔 앞에서 읽는다. 박진솔은 품목과 보존 기록을 확인해 가격 원장의 종자 시세와 실제 보관 목록이 뒤섞이지 않게 한다.","야망":"곽강호는 공동기술원장에 올릴 종자 품목을 보존 기록과 한 항목씩 맞춰 가격 원장의 시세 칸과 구별하려 한다.","공포":"가격표의 품목이 실제 보관 종자 목록인 듯 복사되어 박진솔의 출고 판단에 섞이는 것.","개입":"플레이어는 곽강호가 소리 내어 읽은 두 목록과 원본 품목을 비교할 수 있다."},"biography":"대치1동에서 곽강호는 종자 원본의 빠진 줄을 먼저 살핀다. 보존고 출고를 재촉받아도 인수 기록과 온습도 장부를 맞춘 뒤 박진솔에게 넘긴다.\n\n- 소속: Arc\n- 생업: 기록·열쇠 인수인계\n- 품계: 일반 시민\n- 직함: 종자 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 곽강호는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 대치1동. 곽강호는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 읽히지 않는 사본이나 어긋난 날인은 박진솔에게 원본과 함께 전한다.\n\n**관직.** 품계 일반 시민. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.\n\n**일화.** 남윤경의 가격 원장에 종자 시세 칸이 열렸다는 소식이 보존고에 닿는다. 곽강호는 박진솔이 공동기술원장에 올리려는 종자 목록과 종자 기록의 품목을 맞춘 사본을 만들고, 박진솔 앞에서 두 목록의 품목을 하나씩 소리 내어 읽는다.\n\n**관계.** 곽강호는 종자 기록과 공동기술원장에 올릴 목록을 대조한 사본을 박진솔 앞에서 읽는다. 박진솔은 품목과 보존 기록을 확인해 가격 원장의 종자 시세와 실제 보관 목록이 뒤섞이지 않게 한다.\n\n**야망.** 곽강호는 공동기술원장에 올릴 종자 품목을 보존 기록과 한 항목씩 맞춰 가격 원장의 시세 칸과 구별하려 한다.\n\n**공포.** 가격표의 품목이 실제 보관 종자 목록인 듯 복사되어 박진솔의 출고 판단에 섞이는 것.\n\n**개입.** 플레이어는 곽강호가 소리 내어 읽은 두 목록과 원본 품목을 비교할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 25 | 무력 −25 | 물질 20 | 공동 −10 | 원칙 60 | 공개 50 | 자격 50 | 분산 15 | 변혁 0\n- 욕망: 갈망 −15 | 독점 −35 | 위험 −35 | 과시 −30 | 지속 20 | 지향 이성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"곽강호","type":"계약","to":"박진솔","basis":"곽강호는 종자 기록과 공동기술원장에 올릴 목록을 대조한 사본을 박진솔 앞에서 읽는다. 박진솔은 품목과 보존 기록을 확인해 가격 원장의 종자 시세와 실제 보관 목록이 뒤섞이지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0811', 'cangnyeong-seong-yeolcha', '{"id":"person-0811","name":"Seong Supyeon","title":"Holding Track Patrol","position":"Holding Track Patrol","rank":"Teacher","commonTier":"T5","occupation":"Guard & Patrol","gender":"Male","stage":"S4","state":"S04","stateName":"Arc","detailRoute":"/people/person-0811","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0811","name":"성숲현","title":"유치선 순찰대","position":"유치선 순찰대","rank":"교사","commonTier":"T5","occupation":"경비·순찰","gender":"남성","stage":"S4","state":"S04","stateName":"Arc","detailRoute":"/people/person-0811","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
