INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0845', 'b0a8-c758-b839', '{"id":"person-0845","name":"Nam Guwon","title":"Ratification Registrar","position":"Ratification Registrar","rank":"Clerk","commonTier":"T5","occupation":"Double Payment Ledger Reconciliation & Correction","gender":"Male","stage":"S4","state":"S06","stateName":"Government of the Republic of Korea","detailRoute":"/people/person-0845","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0845","name":"남구원","title":"인준 기록관","position":"인준 기록관","rank":"주사","commonTier":"T5","occupation":"이중 지급 장부 대조·정정","gender":"남성","stage":"S4","state":"S06","stateName":"대한민국정부","detailRoute":"/people/person-0845","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0846', NULL, '{"id":"person-0846","name":"Jacob Thomas","title":"Escort Courier","position":"Escort Courier","characterId":"K846","rank":"Clerk","commonTier":"T5","occupation":"Protecting the Convoy Casualty Ledger","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-07#Person-Jacob Thomas","detailRoute":"/people/person-0846","birthDate":"2083-03-07","birthday":"03-07","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"people-ledger-preservation","name":"People ledger preservation","rating":45}],"traits":[{"id":"k846-disposition","name":"People records before cargo","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Office. Rank: Clerk. Title: Escort Courier. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the transport courier duty would stand empty, cutting off arrival confirmation at Ichon Station and passing unverified arrival records to the tunnel patrol and the hospital transport side.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Jacob Thomas gives Park Taegyeom’s counter the personnel ledger protected during a convoy. Park checks arrivals and dispatch order so people are not omitted from cargo-only arrival records.","effects":[]},{"id":"k846-choice","name":"Actual receipt matters","description":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the convoy courier post rose into the ledger.","behavior":"Relations. Bound by handover to the senior duty line of the same living quarters. Jacob Thomas gives Park Taegyeom’s counter the personnel ledger protected during a convoy. Park checks arrivals and dispatch order so people are not omitted from cargo-only arrival records.","stress":"Fear. That the transport courier duty would stand empty, cutting off arrival confirmation at Ichon Station and passing unverified arrival records to the tunnel patrol and the hospital transport side.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Jacob Thomas gives Park Taegyeom’s counter the personnel ledger protected during a convoy. Park checks arrivals and dispatch order so people are not omitted from cargo-only arrival records.","effects":[]}],"narrative":"Saves the people ledger during an attack and hands it to Park Taegyeom. Arrival accountability is supported, not fighting or warrior experience.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":5,"Openness":25,"Force":-10,"Material":25,"Communal":-15,"Principle":10,"Public":0,"Eligibility":25,"Dispersed":5,"Transformative":-5},"desire":{"Longing":10,"Monopoly":-10,"Risk":5,"Display":-10,"Sustained":15,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Affiliation":"The Government","Rank":"Clerk","Livelihood":"Protecting the Convoy Casualty Ledger","Title":"Escort Courier","Values":"Authority 5 | Openness 25 | Force −10 | Materiality 25 | Community −15 | Principle 10 | Publicity 0 | Qualification 25 | Dispersal 5 | Transformation −5","Desires":"Craving 10 | Monopoly −10 | Risk 5 | Display −10 | Persistence 15 | Orientation: Same-sex | Union: Non-exclusive"},"sections":{"Life":"Born in 2083, Jacob Thomas takes on convoy courier duties at the 2126 opening. He grew up at the Sinnae Interchange Duty Post. His convoy courier work began with stopping a ticketless departing train. His African American family line is rooted in the Yongsan·Itaewon living area. Samuel Thomas was handling U.S. Army supply work in Yongsan·Itaewon in 2026 when the communication network was cut off. The family passed their dwelling and goods handover records on to the next generation, and Jacob Thomas''s parents'' generation cross-checked those records against the living ledgers of their own time. At home they use English, and in daily life and at work they use Korean.\n- Jacob Thomas''s work protecting the convoy casualty ledger is connected to Hangang-ro-dong.","Offices":"Rank: Clerk. Title: Escort Courier. He hands over only the keys and records of his own post and does not invent authority he lacks.","Anecdote":"In 2125, ambushed during an escort, he secured the ledger of lives before the cargo. This act led to the signature of the Escort Courier post being entered in the ledger.","Relationships":"Jacob Thomas hands the ledger of lives protected on convoys to Bak Taegyeom''s window. Bak Taegyeom checks arrival headcounts and dispatch order so that people do not go missing from records of cargo-only arrivals.","Ambition":"He links the escorted-people ledger protection records of the transport courier duty to the Ichon Station office ledger, so that the next duty officer can verify the same records.","Fear":"That if the transport courier duty falls vacant, arrival confirmation at Ichon Station will be cut off, and unverified arrival records will pass to the tunnel patrol and the hospital transport side.","Intervention":"He can bring in a witness to the duty handover or expose an empty key."},"biography":"Jacob Thomas is in charge of protecting the convoy people ledger. Jacob Thomas hands the people ledger he safeguarded on the convoy over to Bak Taegyeom''s desk.\n\n- Affiliation: The Government\n- Rank: Clerk\n- Livelihood: Protecting the Convoy Casualty Ledger\n- Title: Escort Courier\n**Life.** Born in 2083, Jacob Thomas takes on convoy courier duties at the 2126 opening. He grew up at the Sinnae Interchange Duty Post. His convoy courier work began with stopping a ticketless departing train. His African American family line is rooted in the Yongsan·Itaewon living area. Samuel Thomas was handling U.S. Army supply work in Yongsan·Itaewon in 2026 when the communication network was cut off. The family passed their dwelling and goods handover records on to the next generation, and Jacob Thomas''s parents'' generation cross-checked those records against the living ledgers of their own time. At home they use English, and in daily life and at work they use Korean.\n- Jacob Thomas''s work protecting the convoy casualty ledger is connected to Hangang-ro-dong.\n\n**Office.** Rank: Clerk. Title: Escort Courier. He hands over only the keys and records of his own post and does not invent authority he lacks.\n\n**Anecdote.** In 2125, ambushed during an escort, he secured the ledger of lives before the cargo. This act led to the signature of the Escort Courier post being entered in the ledger.\n\n**Relations.** Jacob Thomas hands the ledger of lives protected on convoys to Bak Taegyeom''s window. Bak Taegyeom checks arrival headcounts and dispatch order so that people do not go missing from records of cargo-only arrivals.\n\n**Ambition.** He links the escorted-people ledger protection records of the transport courier duty to the Ichon Station office ledger, so that the next duty officer can verify the same records.\n\n**Fear.** That if the transport courier duty falls vacant, arrival confirmation at Ichon Station will be cut off, and unverified arrival records will pass to the tunnel patrol and the hospital transport side.\n\n**Intervention.** He can bring in a witness to the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 5 | Openness 25 | Force −10 | Materiality 25 | Community −15 | Principle 10 | Publicity 0 | Qualification 25 | Decentralization 5 | Transformation −5\n- Desires: Craving 10 | Monopoly −10 | Risk 5 | Display −10 | Persistence 15 | Orientation Same-sex | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Jacob Thomas","type":"Contract","to":"Bak Tae-gyeom","basis":"Jacob Thomas hands the ledger of lives protected on convoys to Bak Taegyeom''s window. Bak Taegyeom checks arrival headcounts and dispatch order so that people do not go missing from records of cargo-only arrivals."}],"incoming":[]}}', '{"id":"person-0846","name":"제이컵 토머스","title":"호송 전령","position":"호송 전령","characterId":"K846","rank":"주사","commonTier":"T5","occupation":"호송 인명 장부 보호","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-07#인물-제이컵 토머스","detailRoute":"/people/person-0846","birthDate":"2083-03-07","birthday":"03-07","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"people-ledger-preservation","name":"인명 장부 보존","rating":45}],"traits":[{"id":"k846-disposition","name":"화물보다 사람 기록","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"관직. 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 호송 전령 당직이 비면 이촌역의 도착 확인이 끊기고, 터널 순찰과 병원 호송 쪽에 확인되지 않은 도착 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다. 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다.","effects":[]},{"id":"k846-choice","name":"도착 인수를 중시함","description":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 호송 전령 자리의 서명이 장부에 올랐다.","behavior":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다. 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다.","stress":"공포. 호송 전령 당직이 비면 이촌역의 도착 확인이 끊기고, 터널 순찰과 병원 호송 쪽에 확인되지 않은 도착 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다. 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다.","effects":[]}],"narrative":"습격 중 인명 장부를 지켜 박태겸에게 넘겼다. 사람의 도착을 잇는 선택만 확인되며 격투와 전사 경력은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":5,"개방":25,"무력":-10,"물질":25,"공동":-15,"원칙":10,"공개":0,"자격":25,"분산":5,"변혁":-5},"desire":{"갈망":10,"독점":-10,"위험":5,"과시":-10,"지속":15,"지향":"동성","결합":"비독점"},"fields":{"소속":"정부","품계":"주사","생업":"호송 인명 장부 보호","직함":"호송 전령","가치관":"권위 5 | 개방 25 | 무력 −10 | 물질 25 | 공동 −15 | 원칙 10 | 공개 0 | 자격 25 | 분산 5 | 변혁 −5","욕망":"갈망 10 | 독점 −10 | 위험 5 | 과시 −10 | 지속 15 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2083년생인 제이컵 토머스는 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 아프리카계 미국인 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 새뮤얼 토머스는 2026년 용산·이태원에서 미 육군 보급 업무를 맡다가 연락망 단절을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 제이컵 토머스의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 영어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 제이컵 토머스의 호송 인명 장부 보호 업무는 한강로동과 연결된다.","관직":"품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.","일화":"2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.","관계":"제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다. 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다.","야망":"호송 전령 업무의 호송 인명 장부 보호 기록을 이촌역 사무소 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.","공포":"호송 전령 당직이 비면 이촌역의 도착 확인이 끊기고, 터널 순찰과 병원 호송 쪽에 확인되지 않은 도착 기록이 넘어가는 것.","개입":"당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"제이컵 토머스는 호송 인명 장부 보호 업무를 맡는다. 제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다.\n\n- 소속: 정부\n- 품계: 주사\n- 생업: 호송 인명 장부 보호\n- 직함: 호송 전령\n**생애.** 2083년생인 제이컵 토머스는 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 아프리카계 미국인 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 새뮤얼 토머스는 2026년 용산·이태원에서 미 육군 보급 업무를 맡다가 연락망 단절을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 제이컵 토머스의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 영어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 제이컵 토머스의 호송 인명 장부 보호 업무는 한강로동과 연결된다.\n\n**관직.** 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.\n\n**일화.** 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다.\n\n**야망.** 호송 전령 업무의 호송 인명 장부 보호 기록을 이촌역 사무소 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.\n\n**공포.** 호송 전령 당직이 비면 이촌역의 도착 확인이 끊기고, 터널 순찰과 병원 호송 쪽에 확인되지 않은 도착 기록이 넘어가는 것.\n\n**개입.** 당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 5 | 개방 25 | 무력 −10 | 물질 25 | 공동 −15 | 원칙 10 | 공개 0 | 자격 25 | 분산 5 | 변혁 −5\n- 욕망: 갈망 10 | 독점 −10 | 위험 5 | 과시 −10 | 지속 15 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"제이컵 토머스","type":"계약","to":"박태겸","basis":"제이컵 토머스는 호송에서 지킨 인명 장부를 박태겸의 창구에 넘긴다. 박태겸은 도착 인원·배차 순서를 확인해 화물만 도착한 기록에 사람이 빠지지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0847', 'b178-d48d-cc9c-76e7', '{"id":"person-0847","name":"No Supa","title":"Ice Logistics Merchant","position":"Ice Logistics Merchant","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Auction Scale Replacement and Joint Weighing","gender":"Male","stage":"S4","state":"S08","stateName":"The Government","detailRoute":"/people/person-0847","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0847","name":"노숲아","title":"얼음 물류상","position":"얼음 물류상","rank":"일반 시민","commonTier":"T5","occupation":"경매 저울 교체·공동 계량","gender":"남성","stage":"S4","state":"S08","stateName":"정부","detailRoute":"/people/person-0847","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0848', 'd558-c9c4-c8fc', '{"id":"person-0848","name":"Ha Rameun","title":"Antenna Technician","position":"Vault Technician","characterId":"K848","rank":"Clerk","commonTier":"T5","occupation":"Vault Equipment Inspection & Maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-09#inmul-Ha-Rameun","detailRoute":"/people/person-0848","birthDate":"2066-02-19","birthday":"02-19","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"pump-shaft","name":"Pump-shaft replacement","rating":45}],"traits":[{"id":"pump-shaft-disposition","name":"Repairs the identified cause","description":"Replaces one worn shaft to restart the device.","behavior":"Replaces one worn shaft to restart the device.","stress":"","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"bounded-handover","name":"Bounded handover","description":"Keeps duty continuous without inventing authority.","behavior":"Hands over only duty keys and records.","stress":"Fears vacant duty becoming dependence.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Disassembled a pump and restarted it after replacing the worn shaft. The short anecdote and handover do not establish expert command, combat or institutional success.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d558-c9c4-c8fc","name":"Jinju Ha Clan","crest":"clan-crests/d558-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":0,"Force":-30,"Material":-10,"Communal":5,"Principle":10,"Public":50,"Eligibility":20,"Dispersed":25,"Transformative":0},"desire":{"Longing":0,"Monopoly":-15,"Risk":-40,"Display":20,"Sustained":0,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Livelihood":"Vault Equipment Inspection & Maintenance","Affiliation":"Free City","Rank":"Clerk","Title":"Vault Technician","Values":"Authority 0 | Openness 0 | Force −30 | Materiality −10 | Community 5 | Principle 10 | Publicity 50 | Qualification 20 | Decentralization 25 | Transformation 0","Desires":"Craving 0 | Monopoly −15 | Risk −40 | Display 20 | Persistence 0 | Orientation Bisexual | Bonding Non-exclusive"},"sections":{"Life":"The birth cohort approved for the 2066-02-19 birth is Cohort 3. Active at the 2126 opening. Grew up at the Sinjeong rail depot. The Vault Mechanic post opened through a defect report made just before a derailment.\n- Ha Rameun hands over the vault equipment inspection and maintenance work related to Yeoui-dong to a senior watch officer.","Offices":"Rank: Clerk. Title: Vault Technician. Hands over only the keys and records of their own post and does not create authority they do not have.","Anecdote":"In 2125, took apart a pump that had stopped, ground down just one worn shaft, and got it running again. This act put the Vault Mechanic post''s signature into the ledger.","Relationships":"Bound by handover to a senior watch from the same living sphere.","Ambition":"From the storeroom maintenance post, keeps Dangsan Station''s equipment inspection record unbroken.","Fear":"That if the storeroom maintenance watch falls empty, a shutter will warp on a winter night, light will leak out, and outside machines drawn to the light will come near.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to let the watch break. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Vault Equipment Inspection & Maintenance\n- Affiliation: Free City\n- Rank: Clerk\n- Title: Vault Technician\n**Life.** The birth cohort approved for the 2066-02-19 birth is Cohort 3. Active at the 2126 opening. Grew up at the Sinjeong rail depot. The Vault Mechanic post opened through a defect report made just before a derailment.\n- Ha Rameun hands over the vault equipment inspection and maintenance work related to Yeoui-dong to a senior watch officer.\n\n**Office.** Rank: Clerk. Title: Vault Technician. Hands over only the keys and records of their own post and does not create authority they do not have.\n\n**Anecdote.** In 2125, took apart a pump that had stopped, ground down just one worn shaft, and got it running again. This act put the Vault Mechanic post''s signature into the ledger.\n\n**Relations.** Bound by handover to a senior watch from the same living sphere.\n\n**Ambition.** From the storeroom maintenance post, keeps Dangsan Station''s equipment inspection record unbroken.\n\n**Fear.** That if the storeroom maintenance watch falls empty, a shutter will warp on a winter night, light will leak out, and outside machines drawn to the light will come near.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness 0 | Force −30 | Materiality −10 | Community 5 | Principle 10 | Publicity 50 | Qualification 20 | Decentralization 25 | Transformation 0\n- Desires: Craving 0 | Monopoly −15 | Risk −40 | Display 20 | Persistence 0 | Orientation Bisexual | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Ha Rameun","type":"Contract","to":"Du Bong","basis":"Ha Rameun informs Dubong of a supply anomaly found in the vault equipment inspection. Dubong rotation-tests the backup power and Ha Rameun rechecks the equipment, to tell a power problem from a mechanical failure."}],"incoming":[]}}', '{"id":"person-0848","name":"하람은","title":"안테나 정비사","position":"금고 정비사","characterId":"K848","rank":"서기","commonTier":"T5","occupation":"금고 설비 점검·정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-09#인물-하람은","detailRoute":"/people/person-0848","birthDate":"2066-02-19","birthday":"02-19","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"pump-shaft","name":"펌프 축 교체","rating":45}],"traits":[{"id":"pump-shaft-disposition","name":"원인 한 곳을 고침","description":"마모 축 하나를 갈아 장치를 다시 돌린다.","behavior":"마모 축 하나를 갈아 장치를 다시 돌린다.","stress":"","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-handover","name":"경계를 지키는 인계","description":"당직을 잇되 없는 권한을 만들지 않는다.","behavior":"자기 열쇠와 기록만 넘긴다.","stress":"당직 공백이 외부 의존으로 번질 것을 경계한다.","relationship":"선배 당직과 인수인계로 연결된다.","effects":[]}],"narrative":"펌프를 분해해 마모 축만 교체하고 재가동했다. 짧은 일화와 인계만으로 전문 지휘·전투·제도 성립을 추정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d558-c9c4-c8fc","name":"진주 하씨","crest":"clan-crests/d558-c9c4-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":0,"무력":-30,"물질":-10,"공동":5,"원칙":10,"공개":50,"자격":20,"분산":25,"변혁":0},"desire":{"갈망":0,"독점":-15,"위험":-40,"과시":20,"지속":0,"지향":"양성","결합":"비독점"},"fields":{"생업":"금고 설비 점검·정비","소속":"자유도시","품계":"서기","직함":"금고 정비사","가치관":"권위 0 | 개방 0 | 무력 −30 | 물질 −10 | 공동 5 | 원칙 10 | 공개 50 | 자격 20 | 분산 25 | 변혁 0","욕망":"갈망 0 | 독점 −15 | 위험 −40 | 과시 20 | 지속 0 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2066-02-19 출생으로 승인된 출생군은 3군이다. 2126년 개막에 활동했다. 신정 차량기지에서 자랐다. 금고 정비사 자리는 탈선 직전 결함 보고로 열렸다.\n- 하람은은 여의동과 관련한 금고 설비 점검·정비 업무를 선배 당직과 인수인계한다.","관직":"품계 서기. 직함은 금고 정비사. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","일화":"2125년 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 금고 정비사 자리의 서명이 장부에 올랐다.","관계":"같은 생활권 선배 당직과 인수인계로 묶인다.","야망":"창고 정비 자리에서 당산역의 설비 점검 기록을 끊기지 않게 잇는다.","공포":"창고 정비 당직이 비면 겨울밤에 셔터가 어긋나 빛이 새고, 빛에 이끌린 바깥 기계가 다가오는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 금고 설비 점검·정비\n- 소속: 자유도시\n- 품계: 서기\n- 직함: 금고 정비사\n**생애.** 2066-02-19 출생으로 승인된 출생군은 3군이다. 2126년 개막에 활동했다. 신정 차량기지에서 자랐다. 금고 정비사 자리는 탈선 직전 결함 보고로 열렸다.\n- 하람은은 여의동과 관련한 금고 설비 점검·정비 업무를 선배 당직과 인수인계한다.\n\n**관직.** 품계 서기. 직함은 금고 정비사. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 금고 정비사 자리의 서명이 장부에 올랐다.\n\n**관계.** 같은 생활권 선배 당직과 인수인계로 묶인다.\n\n**야망.** 창고 정비 자리에서 당산역의 설비 점검 기록을 끊기지 않게 잇는다.\n\n**공포.** 창고 정비 당직이 비면 겨울밤에 셔터가 어긋나 빛이 새고, 빛에 이끌린 바깥 기계가 다가오는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 0 | 무력 −30 | 물질 −10 | 공동 5 | 원칙 10 | 공개 50 | 자격 20 | 분산 25 | 변혁 0\n- 욕망: 갈망 0 | 독점 −15 | 위험 −40 | 과시 20 | 지속 0 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"하람은","type":"계약","to":"두봉","basis":"하람은은 금고 설비 점검의 공급 이상을 두봉에게 알린다. 두봉은 예비 전원을 순환 시험하고 하람은은 설비를 다시 확인해 전력 문제와 기계 고장을 구분한다."}],"incoming":[]}}');
