INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0887', 'acfd-d604-d48d', '{"id":"person-0887","name":"Gwak Kahyeon","title":"Audit Recorder","position":"Audit Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0887","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0887","name":"곽카현","title":"감사 기록관","position":"감사 기록관","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0887","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0888', 'cangnyeong-seong-yeolcha', '{"id":"person-0888","name":"Seong Hahyeon","title":"Concourse Heating Checker","position":"Concourse Heating Checker","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Male","stage":"S4","state":"S01","stateName":"Free City","detailRoute":"/people/person-0888","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0888","name":"성하현","title":"대합실 난방 점검원","position":"대합실 난방 점검원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"남성","stage":"S4","state":"S01","stateName":"자유도시","detailRoute":"/people/person-0888","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0889', 'cc28-c5f0-c548', '{"id":"person-0889","name":"Cha Donghwan","title":"Restoration Service Recorder","position":"Restoration Service Recorder","characterId":"K889","rank":"Guild Member","commonTier":"T5","occupation":"Registration & Records","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-02#inmul-cha-donghwan","detailRoute":"/people/person-0889","birthDate":"2098-06-05","birthday":"06-05","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k889-guard-visit-recording","name":"Guard-visit recording","rating":60}],"traits":[{"id":"k889-action-priority","name":"Restoration Service Recorder","description":"Title: Restoration Service Recorder.","behavior":"Title: Restoration Service Recorder.","stress":"That if the infirmary duty stands empty, patients who collapse in the cold will be left unattended and the medicine stock will run out.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k889-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That if the infirmary duty stands empty, patients who collapse in the cold will be left unattended and the medicine stock will run out.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":0,"Force":-5,"Material":45,"Communal":50,"Principle":30,"Public":35,"Eligibility":50,"Dispersed":30,"Transformative":20},"desire":{"Longing":-10,"Monopoly":-15,"Risk":-35,"Display":0,"Sustained":5,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Affiliation":"Free City","Livelihood":"Registration & Records","Rank":"Guild Member","Title":"Restoration Service Recorder","Work Location":"Guro 2-dong. At the Guro 2-dong workshop records duty, Cha Donghwan locks the roster of restoration service workers demanded by the guard corps with the duty key. Only the time of the visit and the number of guards are left in the registry record and sent to Kang Minseo, and Kim Nayul''s original citizenship record is handed over to the next clerk.","Values":"Authority −30 | Openness 0 | Force −5 | Materialism 45 | Community 50 | Principle 30 | Publicity 35 | Qualification 50 | Decentralization 30 | Transformation 20","Desires":"Longing −10 | Monopoly −15 | Risk −35 | Display 0 | Endurance 5 | Orientation Same-sex | Union Non-exclusive"},"sections":{"Life":"Of the 2126 generation. Grew up at the Seoul Station Registry. The post of Restoration Service Records Officer opened with the deletion of one line from the double ledger.\n- Duty location: Guro 2-dong. At the Guro 2-dong workshop records duty, Cha Donghwan locks the roster of restoration service workers demanded by the guard corps with the duty key. Only the time of the visit and the number of guards are left in the registry record and sent to Kang Minseo, and Kim Nayul''s original citizenship record is handed over to the next clerk.","Offices":"Rank: Guild Member. Title: Restoration Service Recorder. Leaves only the time of the visit and the number of guards in the registry record and sends it to Kang Minseo, and hands Kim Nayul''s original citizenship record over to the next clerk.","Anecdote":"","Relationships":"Cha Donghwan relays to Gim Nayul the time and personnel records of the Guard Corps who demanded the list. Gim Nayul checks the shifts and citizenship registrations and examines the traces of the restoration-service list having been used as a copy of the military household register.","Ambition":"","Fear":"That the time of the guard corps'' roster demand will go unrecorded, and Kim Nayul will not notice that the original citizenship record has been diverted to the military household registry.","Intervention":"The player can lock the roster away with Cha Donghwan using the duty key, or pass the guard corps'' visit record to Kim Nayul."},"biography":"Cha Donghwan records the Guard Corps'' demand for the roster, but he does not hand over the original citizenship records as copies of a military household register.\n\n- Affiliation: Free City\n- Livelihood: Registration & Records\n- Rank: Guild Member\n- Title: Restoration Service Recorder\n**Life.** Of the 2126 generation. Grew up at the Seoul Station Registry. The post of Restoration Service Records Officer opened with the deletion of one line from the double ledger.\n- Duty location: Guro 2-dong. At the Guro 2-dong workshop records duty, Cha Donghwan locks the roster of restoration service workers demanded by the guard corps with the duty key. Only the time of the visit and the number of guards are left in the registry record and sent to Kang Minseo, and Kim Nayul''s original citizenship record is handed over to the next clerk.\n\n**Office.** Rank: Guild Member. Leaves only the time of the visit and the number of guards in the registry record and sends it to Kang Minseo, and hands Kim Nayul''s original citizenship record over to the next clerk.\n\n**Relations.** Cha Donghwan relays to Gim Nayul the time and personnel records of the Guard Corps who demanded the list. Gim Nayul checks the shifts and citizenship registrations and examines the traces of the restoration-service list having been used as a copy of the military household register.\n\n**Fear.** That the time of the guard corps'' roster demand will go unrecorded, and Kim Nayul will not notice that the original citizenship record has been diverted to the military household registry.\n\n**Intervention.** The player can lock the roster away with Cha Donghwan using the duty key, or pass the guard corps'' visit record to Kim Nayul.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 0 | Force −5 | Material 45 | Communal 50 | Principle 30 | Publicity 35 | Qualification 50 | Decentralization 30 | Transformation 20\n- Desires: Craving −10 | Exclusivity −15 | Risk −35 | Display 0 | Persistence 5 | Orientation Same-sex | Union Non-exclusive\n:::","relations":{"outgoing":[{"from":"Cha Donghwan","type":"Contract","to":"Kim Nayul","basis":"Cha Donghwan relays to Gim Nayul the time and personnel records of the Guard Corps who demanded the list. Gim Nayul checks the shifts and citizenship registrations and examines the traces of the restoration-service list having been used as a copy of the military household register."}],"incoming":[]}}', '{"id":"person-0889","name":"차동환","title":"복구복무 기록관","position":"복구복무 기록관","characterId":"K889","rank":"조합원","commonTier":"T5","occupation":"등기·기록","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-02#인물-차동환","detailRoute":"/people/person-0889","birthDate":"2098-06-05","birthday":"06-05","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k889-guard-visit-recording","name":"경비 방문 기록","rating":60}],"traits":[{"id":"k889-action-priority","name":"복구복무 기록관","description":"직함은 복구복무 기록관.","behavior":"직함은 복구복무 기록관.","stress":"의무실 당직이 비면 한파에 쓰러진 환자가 방치되고 약 재고가 끊기는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k889-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"의무실 당직이 비면 한파에 쓰러진 환자가 방치되고 약 재고가 끊기는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":0,"무력":-5,"물질":45,"공동":50,"원칙":30,"공개":35,"자격":50,"분산":30,"변혁":20},"desire":{"갈망":-10,"독점":-15,"위험":-35,"과시":0,"지속":5,"지향":"동성","결합":"비독점"},"fields":{"소속":"자유도시","생업":"등기·기록","품계":"조합원","직함":"복구복무 기록관","업무 위치":"구로2동. 차동환은 구로2동 공방 기록 당직에서 경비대가 요구한 복구복무자 명부를 당직 열쇠로 잠근다. 찾아온 시각과 인원만 등기 기록에 남겨 강민서에게 보내고, 김나율의 시민권 원본은 다음 서기에게 인계한다.","가치관":"권위 −30 | 개방 0 | 무력 −5 | 물질 45 | 공동 50 | 원칙 30 | 공개 35 | 자격 50 | 분산 30 | 변혁 20","욕망":"갈망 −10 | 독점 −15 | 위험 −35 | 과시 0 | 지속 5 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 차동환은 구로2동 공방 기록 당직에서 경비대가 요구한 복구복무자 명부를 당직 열쇠로 잠근다. 찾아온 시각과 인원만 등기 기록에 남겨 강민서에게 보내고, 김나율의 시민권 원본은 다음 서기에게 인계한다.","관직":"품계 조합원. 직함은 복구복무 기록관. 찾아온 시각과 인원만 등기 기록에 남겨 강민서에게 보내고, 김나율의 시민권 원본은 다음 서기에게 인계한다.","일화":"","관계":"차동환은 명단을 요구한 경비대의 시각·인원 기록을 김나율에게 전한다. 김나율은 교대와 시민권 등록을 확인해 복구복무 명단이 군사호적 사본으로 쓰인 흔적을 살핀다.","야망":"","공포":"경비대의 명부 요구 시각을 남기지 못해 김나율이 시민권 원본의 군사호적 전용을 알아채지 못하는 것.","개입":"플레이어는 차동환과 명부를 당직 열쇠로 잠그거나 경비대의 방문 기록을 김나율에게 전할 수 있다."},"biography":"차동환은 경비대의 명부 요구를 기록하되 시민권 원본 자체를 군사호적 사본으로 내주지 않는다.\n\n- 소속: 자유도시\n- 생업: 등기·기록\n- 품계: 조합원\n- 직함: 복구복무 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 차동환은 구로2동 공방 기록 당직에서 경비대가 요구한 복구복무자 명부를 당직 열쇠로 잠근다. 찾아온 시각과 인원만 등기 기록에 남겨 강민서에게 보내고, 김나율의 시민권 원본은 다음 서기에게 인계한다.\n\n**관직.** 품계 조합원. 직함은 복구복무 기록관.\n\n**관계.** 차동환은 명단을 요구한 경비대의 시각·인원 기록을 김나율에게 전한다. 김나율은 교대와 시민권 등록을 확인해 복구복무 명단이 군사호적 사본으로 쓰인 흔적을 살핀다.\n\n**공포.** 경비대의 명부 요구 시각을 남기지 못해 김나율이 시민권 원본의 군사호적 전용을 알아채지 못하는 것.\n\n**개입.** 플레이어는 차동환과 명부를 당직 열쇠로 잠그거나 경비대의 방문 기록을 김나율에게 전할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 0 | 무력 −5 | 물질 45 | 공동 50 | 원칙 30 | 공개 35 | 자격 50 | 분산 30 | 변혁 20\n- 욕망: 갈망 −10 | 독점 −15 | 위험 −35 | 과시 0 | 지속 5 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"차동환","type":"계약","to":"김나율","basis":"차동환은 명단을 요구한 경비대의 시각·인원 기록을 김나율에게 전한다. 김나율은 교대와 시민권 등록을 확인해 복구복무 명단이 군사호적 사본으로 쓰인 흔적을 살핀다."}],"incoming":[]}}');
