INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0905', 'd55c-ccad-c8fc', '{"id":"person-0905","name":"Han Reumseo","title":"Work Crew Courier","position":"Work Crew Courier","rank":"Guild Member","commonTier":"T5","occupation":"Transfer Message Delivery","gender":"Female","stage":"S4","state":"S02","stateName":"Free City","detailRoute":"/people/person-0905","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0905","name":"한름서","title":"작업반 전령","position":"작업반 전령","rank":"조합원","commonTier":"T5","occupation":"환승 전갈 전달","gender":"여성","stage":"S4","state":"S02","stateName":"자유도시","detailRoute":"/people/person-0905","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0906', 'c11c-b2ec-c131', '{"id":"person-0906","name":"Seo Dolseo","title":"Seed Stock Recorder","position":"Seed Stock Recorder","characterId":"K906","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-seodolseo","detailRoute":"/people/person-0906","birthDate":"2064-10-09","birthday":"10-09","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"log-gap","name":"Temperature-log gap reconciliation","rating":55},{"id":"seed","name":"Temperature and seed-release checks","rating":50}],"traits":[{"id":"temperature-logs-over-requisition","name":"Temperature Logs Over Requisition","description":"Seo Dolseo checks a box''s temperature records first even when its release request carries a requisition document.","behavior":"They locate the requested box''s temperature log and mark its interrupted intervals.","stress":"Even under mounting wartime requisition pressure, they may seek to expose record gaps first.","relationship":"When reporting the release request to Park Jinsol, they may present temperature gaps alongside the requisition document.","effects":[]},{"id":"mark-locked-boxes","name":"Mark Locked Boxes","description":"Seo Dolseo identifies boxes subject to release locks by number in reports.","behavior":"They report the box numbers under Jeong Harin''s release lock to Park Jinsol together with the temperature gaps.","stress":"When a requisition request intersects with a release lock, they may take extra care not to omit the locked box numbers.","relationship":"When connecting Jeong Harin''s lock with Park Jinsol''s review, they may relay explicit numbers rather than remove the lock themselves.","effects":[]}],"narrative":"He recorded temperature gaps and locked-box numbers together despite a requisition request. Conditional checking is supported, not military command.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":10,"Force":-30,"Material":0,"Communal":-10,"Principle":70,"Public":50,"Eligibility":45,"Dispersed":10,"Transformative":5},"desire":{"Longing":35,"Monopoly":-10,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Bisexual","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Records and Keys Handover","Rank":"Ordinary Citizen","Title":"Seed Stock Recorder","Duty":"Daechi 1-dong. In Daechi 1-dong, Seo Dolseo matches the seed records and handover signatures against the originals and passes them to the next duty shift. For crates whose temperature and humidity records are interrupted, he writes the numbers separately and notifies Park Jinsol.","Values":"Authority −5 | Openness 10 | Force −30 | Material 0 | Communal −10 | Principle 70 | Publicity 50 | Qualification 45 | Decentralization 10 | Transformation 5","Desires":"Craving 35 | Exclusivity −10 | Risk −10 | Display 0 | Persistence 15 | Orientation Bisexual | Union Polyamorous"},"sections":{"Life":"Born into the 2126 generation. Grew up at the Seoul Station Registry Office. Seo Dolseo is responsible for matching seed records with storehouse handover records.\n- Work: Daechi 1-dong. In Daechi 1-dong, Seo Dolseo matches the seed records and handover signatures against the originals and passes them to the next duty shift. For crates whose temperature and humidity records are interrupted, he writes the numbers separately and notifies Park Jinsol.","Offices":"Rank: Ordinary Citizen. Title: Seed Stock Recorder. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.","Anecdote":"A release request arrives for a seed crate with a wartime requisition document attached. Seo Dolseo first finds the temperature log of that crate and marks the interrupted interval, then writes down the number of the crate under Jeong Harin''s removal lock and submits it to Park Jinsol.","Relationships":"Seo Dolseo reports to Bak Jinsol the boxes whose temperature logs were cut off and their removal-lock numbers. Bak Jinsol checks the preservation records of those boxes so that unverified boxes are not released, even with a wartime requisition document.","Ambition":"Seo Dolseo intends to check the interrupted temperature log and Jeong Harin''s removal lock, even for a crate with a wartime requisition document attached, before submitting it to Park Jinsol.","Fear":"That the requisition document covers over gaps in the preservation records and the lock number, so that an unverified crate is released.","Intervention":"The player can compare the log gaps and lock numbers that Seo Dolseo recorded and put the release decision on that crate on hold."},"biography":"In Daechi 1-dong, Seo Dolseo first looks for missing lines in the original seed records. Even when pressed to hurry a storehouse release, he matches the handover records against the temperature and humidity ledger before passing it to Park Jinsol.\n\n- Affiliation: Arc\n- Livelihood: Records and Keys Handover\n- Rank: Ordinary Citizen\n- Title: Seed Stock Recorder\n**Life.** Born into the 2126 generation. Grew up at the Seoul Station Registry Office. Seo Dolseo is responsible for matching seed records with storehouse handover records.\n- Work: Daechi 1-dong. In Daechi 1-dong, Seo Dolseo matches the seed records and handover signatures against the originals and passes them to the next duty shift. For crates whose temperature and humidity records are interrupted, he writes the numbers separately and notifies Park Jinsol.\n\n**Office.** Rank: Ordinary Citizen. Title: Seed Stock Recorder. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.\n\n**Anecdote.** A release request arrives for a seed crate with a wartime requisition document attached. Seo Dolseo first finds the temperature log of that crate and marks the interrupted interval, then writes down the number of the crate under Jeong Harin''s removal lock and submits it to Park Jinsol.\n\n**Relations.** Seo Dolseo reports to Bak Jinsol the boxes whose temperature logs were cut off and their removal-lock numbers. Bak Jinsol checks the preservation records of those boxes so that unverified boxes are not released, even with a wartime requisition document.\n\n**Ambition.** Seo Dolseo intends to check the interrupted temperature log and Jeong Harin''s removal lock, even for a crate with a wartime requisition document attached, before submitting it to Park Jinsol.\n\n**Fear.** That the requisition document covers over gaps in the preservation records and the lock number, so that an unverified crate is released.\n\n**Intervention.** The player can compare the log gaps and lock numbers that Seo Dolseo recorded and put the release decision on that crate on hold.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 10 | Force −30 | Material 0 | Communal −10 | Principle 70 | Publicity 50 | Qualification 45 | Decentralization 10 | Transformation 5\n- Desires: Craving 35 | Exclusivity −10 | Risk −10 | Display 0 | Persistence 15 | Orientation Bisexual | Union Polyamorous\n:::","relations":{"outgoing":[{"from":"Seo Dolseo","type":"Contract","to":"Bak Jinsol","basis":"Seo Dolseo reports to Bak Jinsol the boxes whose temperature logs were cut off and their removal-lock numbers. Bak Jinsol checks the preservation records of those boxes so that unverified boxes are not released, even with a wartime requisition document."}],"incoming":[]}}', '{"id":"person-0906","name":"서돌서","title":"종자 기록관","position":"종자 기록관","characterId":"K906","rank":"일반 시민","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-서돌서","detailRoute":"/people/person-0906","birthDate":"2064-10-09","birthday":"10-09","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"log-gap","name":"온습도 기록 공백 대조","rating":55},{"id":"seed","name":"온습도·종자 출고 확인","rating":50}],"traits":[{"id":"temperature-logs-over-requisition","name":"징발보다 온도 로그","description":"서돌서는 징발 문서가 붙은 출고 요청에서도 해당 상자의 온도 기록부터 확인한다.","behavior":"징발 요청 상자의 온도 로그를 찾아 끊긴 구간을 표시한다.","stress":"전시 징발의 압박이 커져도 기록 공백을 먼저 드러내려 할 수 있다.","relationship":"박진솔에게 출고 요청을 올릴 때 징발 문서만이 아니라 온도 공백을 함께 판단 근거로 제시할 수 있다.","effects":[]},{"id":"mark-locked-boxes","name":"잠금 상자 표시","description":"서돌서는 반출 잠금이 걸린 상자를 번호로 특정해 보고하는 쪽이다.","behavior":"정하린의 반출 잠금이 걸린 상자 번호를 온도 공백과 함께 적어 박진솔에게 올린다.","stress":"징발 요청과 반출 잠금이 맞물리면 잠금 대상 번호가 보고에서 빠지지 않도록 더 주의할 수 있다.","relationship":"정하린의 잠금과 박진솔의 확인을 연결할 때 잠금을 임의로 풀기보다 번호를 명시해 전달할 수 있다.","effects":[]}],"narrative":"징발 요청 상자의 온도 공백과 반출 잠금 번호를 함께 기록했다. 이 사건의 조건 대조를 평가하며 군사 명령권은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":10,"무력":-30,"물질":0,"공동":-10,"원칙":70,"공개":50,"자격":45,"분산":10,"변혁":5},"desire":{"갈망":35,"독점":-10,"위험":-10,"과시":0,"지속":15,"지향":"양성","결합":"다자"},"fields":{"소속":"Arc","생업":"기록·열쇠 인수인계","품계":"일반 시민","직함":"종자 기록관","업무":"대치1동. 서돌서는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.","가치관":"권위 −5 | 개방 10 | 무력 −30 | 물질 0 | 공동 −10 | 원칙 70 | 공개 50 | 자격 45 | 분산 10 | 변혁 5","욕망":"갈망 35 | 독점 −10 | 위험 −10 | 과시 0 | 지속 15 | 지향 양성 | 결합 다자"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 서돌서는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 대치1동. 서돌서는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.","관직":"품계 일반 시민. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.","일화":"전시 징발 문서를 붙인 종자 상자 출고 요청이 올라온다. 서돌서는 해당 상자의 온도 로그부터 찾아 끊긴 구간에 표시하고, 정하린의 반출 잠금이 걸린 상자 번호를 함께 적어 박진솔에게 올린다.","관계":"서돌서는 온도 로그가 끊긴 상자와 반출 잠금 번호를 박진솔에게 올린다. 박진솔은 그 상자의 보존 기록을 확인해 전시 징발 문서가 있어도 미확인 상자를 출고하지 않는다.","야망":"서돌서는 전시 징발 문서가 붙은 상자도 끊긴 온도 로그와 정하린의 반출 잠금을 확인한 뒤 박진솔에게 올리려 한다.","공포":"징발 문서가 보존 기록의 공백과 잠금 번호를 덮어 미확인 상자가 출고되는 것.","개입":"플레이어는 서돌서가 적은 로그 공백과 잠금 번호를 대조해 해당 상자의 출고 판단을 보류할 수 있다."},"biography":"대치1동에서 서돌서는 종자 원본의 빠진 줄을 먼저 살핀다. 보존고 출고를 재촉받아도 인수 기록과 온습도 장부를 맞춘 뒤 박진솔에게 넘긴다.\n\n- 소속: Arc\n- 생업: 기록·열쇠 인수인계\n- 품계: 일반 시민\n- 직함: 종자 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 서돌서는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 대치1동. 서돌서는 대치1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.\n\n**관직.** 품계 일반 시민. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.\n\n**일화.** 전시 징발 문서를 붙인 종자 상자 출고 요청이 올라온다. 서돌서는 해당 상자의 온도 로그부터 찾아 끊긴 구간에 표시하고, 정하린의 반출 잠금이 걸린 상자 번호를 함께 적어 박진솔에게 올린다.\n\n**관계.** 서돌서는 온도 로그가 끊긴 상자와 반출 잠금 번호를 박진솔에게 올린다. 박진솔은 그 상자의 보존 기록을 확인해 전시 징발 문서가 있어도 미확인 상자를 출고하지 않는다.\n\n**야망.** 서돌서는 전시 징발 문서가 붙은 상자도 끊긴 온도 로그와 정하린의 반출 잠금을 확인한 뒤 박진솔에게 올리려 한다.\n\n**공포.** 징발 문서가 보존 기록의 공백과 잠금 번호를 덮어 미확인 상자가 출고되는 것.\n\n**개입.** 플레이어는 서돌서가 적은 로그 공백과 잠금 번호를 대조해 해당 상자의 출고 판단을 보류할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 10 | 무력 −30 | 물질 0 | 공동 −10 | 원칙 70 | 공개 50 | 자격 45 | 분산 10 | 변혁 5\n- 욕망: 갈망 35 | 독점 −10 | 위험 −10 | 과시 0 | 지속 15 | 지향 양성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"서돌서","type":"계약","to":"박진솔","basis":"서돌서는 온도 로그가 끊긴 상자와 반출 잠금 번호를 박진솔에게 올린다. 박진솔은 그 상자의 보존 기록을 확인해 전시 징발 문서가 있어도 미확인 상자를 출고하지 않는다."}],"incoming":[]}}');
