INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0926', NULL, '{"id":"person-0926","name":"Étienne Moreau","title":"Relay Duty","position":"Relay Duty","characterId":"K926","rank":"Clerk","commonTier":"T5","occupation":"Spare Battery Rotation & Transmission Upkeep","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-07#person-Etienne Moreau","detailRoute":"/people/person-0926","birthDate":"2080-09-22","birthday":"09-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"backup-power-radio","name":"Backup-battery transmission","rating":55}],"traits":[{"id":"k926-disposition","name":"Transmission through outages","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Office. Rank: Clerk. Title: relay duty. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That if the radio relay duty post stands empty, contact between Yongsan Station and other stations will be cut, and unverified news will be passed to the hospital and the escort teams.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Étienne Moreau reports reserve batteries used for transmission and shift times to Adeola Adeyemi. Adeola checks fuel and output records to distinguish remaining power from supply already consumed.","effects":[]},{"id":"k926-choice","name":"Handing over used power","description":"Anecdote. For the three blackout days of 2125 he kept the transmission alive by cycling the backup batteries. By this deed the signature of the relay duty post rose into the ledger.","behavior":"Relations. Bound by handover to the senior duty line of the same living quarters. Étienne Moreau reports reserve batteries used for transmission and shift times to Adeola Adeyemi. Adeola checks fuel and output records to distinguish remaining power from supply already consumed.","stress":"Fear. That if the radio relay duty post stands empty, contact between Yongsan Station and other stations will be cut, and unverified news will be passed to the hospital and the escort teams.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Étienne Moreau reports reserve batteries used for transmission and shift times to Adeola Adeyemi. Adeola checks fuel and output records to distinguish remaining power from supply already consumed.","effects":[]}],"narrative":"Transmits on batteries for three outage days and reports shift times to Adeola. Sustained effort does not prove backup-power design ability.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":25,"Force":-10,"Material":25,"Communal":0,"Principle":10,"Public":-30,"Eligibility":35,"Dispersed":5,"Transformative":-10},"desire":{"Longing":45,"Monopoly":-10,"Risk":0,"Display":25,"Sustained":20,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Affiliation":"The Government","Rank":"Clerk","Livelihood":"Spare Battery Rotation & Transmission Upkeep","Title":"Relay Duty","Values":"Authority 15 | Openness 25 | Force −10 | Material 25 | Communal 0 | Principle 10 | Publicity −30 | Qualification 35 | Decentralization 5 | Reform −10","Desires":"Craving 45 | Possessiveness −10 | Risk 0 | Display 25 | Persistence 20 | Orientation Same-sex | Union Contract Cohabitation"},"sections":{"Life":"Born in 2080, Etienne Moreau takes charge of relay watch duties in the 2126 opening period. Grew up in the Sangam transmission room. The relay watch duties began with keeping transmission going through a three-day blackout. The French-descended family line is rooted in the Yongsan-Itaewon living sphere. Louis Moreau lived through the Great Blackout around 2026 working in a private warehouse and in electrical repair in Yongsan, within Yongsan-Itaewon. The family passed on its shelter and goods handover records to the next generation, and Etienne Moreau''s parents'' generation cross-checked those records against the living ledgers of their own time. They speak French at home and Korean in daily life and at work.\n- Etienne Moreau''s reserve battery rotation and transmission upkeep duties are connected to Hangangno-dong.\n- Etienne Moreau''s reserve battery rotation and transmission upkeep duties are connected to Sangam-dong.","Offices":"Rank: Clerk. Title: Relay Duty. He hands over only the keys and records of his own post, and does not invent authority he does not have.","Anecdote":"During the three-day blackout of 2125, he kept the transmission running without a break by rotating the reserve batteries. After this act, the Relay Duty post''s signature was entered in the ledger.","Relationships":"Étienne Moreau reports to Adeola Adeyemi the reserve batteries used for transmission and the shift times. Adeola Adeyemi checks the fuel and output records to distinguish the remaining power from the supply already used.","Ambition":"He keeps complete records of the radio relay duty''s reserve battery rotation and transmission checks, so that the next duty officer checks the same records.","Fear":"That if the radio relay duty falls vacant, contact between Yongsan Station and other stations will be cut, and unverified news will be passed to the hospital and the escort teams.","Intervention":"He can bring in a witness to the duty handover or expose an empty key."},"biography":"Étienne Moreau handles reserve battery rotation and transmission upkeep. Étienne Moreau passes the reserve batteries used for transmission and the rotation times to Adeola Adeyemi.\n\n- Affiliation: The Government\n- Rank: Clerk\n- Livelihood: Spare Battery Rotation & Transmission Upkeep\n- Title: Relay Duty\n**Life.** Born in 2080, Etienne Moreau takes charge of relay watch duties in the 2126 opening period. Grew up in the Sangam transmission room. The relay watch duties began with keeping transmission going through a three-day blackout. The French-descended family line is rooted in the Yongsan-Itaewon living sphere. Louis Moreau lived through the Great Blackout around 2026 working in a private warehouse and in electrical repair in Yongsan, within Yongsan-Itaewon. The family passed on its shelter and goods handover records to the next generation, and Etienne Moreau''s parents'' generation cross-checked those records against the living ledgers of their own time. They speak French at home and Korean in daily life and at work.\n- Etienne Moreau''s reserve battery rotation and transmission upkeep duties are connected to Hangangno-dong.\n- Etienne Moreau''s reserve battery rotation and transmission upkeep duties are connected to Sangam-dong.\n\n**Office.** Rank: Clerk. Title: Relay Duty. He hands over only the keys and records of his own post, and does not invent authority he does not have.\n\n**Anecdote.** During the three-day blackout of 2125, he kept the transmission running without a break by rotating the reserve batteries. After this act, the Relay Duty post''s signature was entered in the ledger.\n\n**Relations.** Étienne Moreau reports to Adeola Adeyemi the reserve batteries used for transmission and the shift times. Adeola Adeyemi checks the fuel and output records to distinguish the remaining power from the supply already used.\n\n**Ambition.** He keeps complete records of the radio relay duty''s reserve battery rotation and transmission checks, so that the next duty officer checks the same records.\n\n**Fear.** That if the radio relay duty falls vacant, contact between Yongsan Station and other stations will be cut, and unverified news will be passed to the hospital and the escort teams.\n\n**Intervention.** He can bring in a witness to the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness 25 | Force −10 | Materialism 25 | Communality 0 | Principle 10 | Publicity −30 | Credentials 35 | Decentralization 5 | Transformation −10\n- Desires: Craving 45 | Possessiveness −10 | Risk 0 | Display 25 | Endurance 20 | Orientation: same-sex | Bonding: contract cohabitation\n:::","relations":{"outgoing":[{"from":"Étienne Moreau","type":"Contract","to":"Adeola Adeyemi","basis":"Étienne Moreau reports to Adeola Adeyemi the reserve batteries used for transmission and the shift times. Adeola Adeyemi checks the fuel and output records to distinguish the remaining power from the supply already used."}],"incoming":[]}}', '{"id":"person-0926","name":"에티엔 모로","title":"중계 당직","position":"중계 당직","characterId":"K926","rank":"주사","commonTier":"T5","occupation":"예비 전지 교대·송신 유지","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-07#인물-에티엔 모로","detailRoute":"/people/person-0926","birthDate":"2080-09-22","birthday":"09-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"backup-power-radio","name":"예비 전지 송신 운용","rating":55}],"traits":[{"id":"k926-disposition","name":"정전에도 송신 유지","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"관직. 품계 주사. 직함은 중계 당직. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 무선 중계 당직이 비면 용산역과 다른 역 사이의 연락이 끊기고, 병원과 호송대에 확인되지 않은 소식이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다. 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다.","effects":[]},{"id":"k926-choice","name":"사용 전력 인계","description":"일화. 2125년 정전 사흘간 송신을 끊지 않고 예비 전지를 돌렸다. 이 일로 중계 당직 자리의 서명이 장부에 올랐다.","behavior":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다. 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다.","stress":"공포. 무선 중계 당직이 비면 용산역과 다른 역 사이의 연락이 끊기고, 병원과 호송대에 확인되지 않은 소식이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다. 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다.","effects":[]}],"narrative":"사흘 정전에도 전지로 송신하고 교대 시각을 아데올라에게 전했다. 지속성은 있으나 예비 전력의 설계 능력은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":25,"무력":-10,"물질":25,"공동":0,"원칙":10,"공개":-30,"자격":35,"분산":5,"변혁":-10},"desire":{"갈망":45,"독점":-10,"위험":0,"과시":25,"지속":20,"지향":"동성","결합":"계약동거"},"fields":{"소속":"정부","품계":"주사","생업":"예비 전지 교대·송신 유지","직함":"중계 당직","가치관":"권위 15 | 개방 25 | 무력 −10 | 물질 25 | 공동 0 | 원칙 10 | 공개 −30 | 자격 35 | 분산 5 | 변혁 −10","욕망":"갈망 45 | 독점 −10 | 위험 0 | 과시 25 | 지속 20 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"2080년생인 에티엔 모로는 2126년 개막기에 중계 당직 업무를 맡는다. 상암 송신실에서 자랐다. 중계 당직 업무는 정전 사흘 송신 유지를 계기로 시작됐다. 프랑스계 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 루이 모로는 약 2026년 용산·이태원에서 용산의 민간 창고·전기 수선 일을 하며 대정전을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 에티엔 모로의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 프랑스어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 에티엔 모로의 예비 전지 교대·송신 유지 업무는 한강로동과 연결된다.\n- 에티엔 모로의 예비 전지 교대·송신 유지 업무는 상암동과 연결된다.","관직":"품계 주사. 직함은 중계 당직. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.","일화":"2125년 정전 사흘간 송신을 끊지 않고 예비 전지를 돌렸다. 이 행동을 계기로 중계 당직 자리의 서명이 장부에 올랐다.","관계":"에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다. 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다.","야망":"무선 중계 당직의 예비 전지 교대와 송신 점검 기록을 빠짐없이 남겨, 다음 당직이 같은 기록을 확인하게 한다.","공포":"무선 중계 당직이 비면 용산역과 다른 역 사이의 연락이 끊기고, 병원과 호송대에 확인되지 않은 소식이 넘어가는 것.","개입":"당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"에티엔 모로는 예비 전지 교대·송신 유지 업무를 맡는다. 에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다.\n\n- 소속: 정부\n- 품계: 주사\n- 생업: 예비 전지 교대·송신 유지\n- 직함: 중계 당직\n**생애.** 2080년생인 에티엔 모로는 2126년 개막기에 중계 당직 업무를 맡는다. 상암 송신실에서 자랐다. 중계 당직 업무는 정전 사흘 송신 유지를 계기로 시작됐다. 프랑스계 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 루이 모로는 약 2026년 용산·이태원에서 용산의 민간 창고·전기 수선 일을 하며 대정전을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 에티엔 모로의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 프랑스어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 에티엔 모로의 예비 전지 교대·송신 유지 업무는 한강로동과 연결된다.\n- 에티엔 모로의 예비 전지 교대·송신 유지 업무는 상암동과 연결된다.\n\n**관직.** 품계 주사. 직함은 중계 당직. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.\n\n**일화.** 2125년 정전 사흘간 송신을 끊지 않고 예비 전지를 돌렸다. 이 행동을 계기로 중계 당직 자리의 서명이 장부에 올랐다.\n\n**관계.** 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다.\n\n**야망.** 무선 중계 당직의 예비 전지 교대와 송신 점검 기록을 빠짐없이 남겨, 다음 당직이 같은 기록을 확인하게 한다.\n\n**공포.** 무선 중계 당직이 비면 용산역과 다른 역 사이의 연락이 끊기고, 병원과 호송대에 확인되지 않은 소식이 넘어가는 것.\n\n**개입.** 당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 25 | 무력 −10 | 물질 25 | 공동 0 | 원칙 10 | 공개 −30 | 자격 35 | 분산 5 | 변혁 −10\n- 욕망: 갈망 45 | 독점 −10 | 위험 0 | 과시 25 | 지속 20 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"에티엔 모로","type":"계약","to":"아데올라 아데예미","basis":"에티엔 모로는 송신에 쓴 예비 전지와 교대 시각을 아데올라 아데예미에게 전한다. 아데올라 아데예미는 연료·출력 기록을 확인해 남은 전력과 이미 사용한 공급을 구분한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0927', 'c8fc-c2e0-c548', '{"id":"person-0927","name":"Ju Sanin","title":"Market Patrol","position":"Market Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Ridge Patrol · Checking for Ambush Traces","gender":"Female","stage":"S4","state":"S08","stateName":"The Government","detailRoute":"/people/person-0927","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":9,"effective":9}}}}', '{"id":"person-0927","name":"주산인","title":"시장 순찰대","position":"시장 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"능선 초계·매복 흔적 확인","gender":"여성","stage":"S4","state":"S08","stateName":"정부","detailRoute":"/people/person-0927","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":9,"effective":9}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0928', 'c6b0-b2e8-c591', '{"id":"person-0928","name":"U Damin","title":"Transmission Duty","position":"Vault Duty","rank":"Clerk","commonTier":"T5","occupation":"Vault Duty Shift Change and Record Handover","gender":"Female","stage":"S4","state":"S09","stateName":"Free City","detailRoute":"/people/person-0928","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0928","name":"우다민","title":"송신 당직","position":"금고 당직","rank":"서기","commonTier":"T5","occupation":"금고 당직 교대·기록 인수","gender":"여성","stage":"S4","state":"S09","stateName":"자유도시","detailRoute":"/people/person-0928","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
