INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0930', 'bbfc-c5ec-d765-9594', '{"id":"person-0930","name":"Min Gahyeon","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0930","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0930","name":"민가현","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"일반 시민","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"Arc","detailRoute":"/people/person-0930","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0931', 'c9c4-d48d-ae30', '{"id":"person-0931","name":"Jin Rarin","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0931","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0931","name":"진라린","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0931","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0932', 'ae40-c0c1-b77d-91d1', '{"id":"person-0932","name":"Kim Sayeon","title":"Epidemic Control Recorder","position":"Epidemic Control Relief Worker","characterId":"K932","rank":"Relief Worker","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-Kim-Sayeon","detailRoute":"/people/person-0932","birthDate":"2087-08-06","birthday":"08-06","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"triage-documentation","name":"Triage documentation","rating":55}],"traits":[{"id":"stated-priority","name":"Leaves wealth fields blank","description":"A counterfeit medicine surge prompted paired severity and clinical notes, with affiliation and wealth blank. Supervised allocation documentation is the evidence.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Epidemic Control Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Epidemic Control Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A counterfeit medicine surge prompted paired severity and clinical notes, with affiliation and wealth blank. Supervised allocation documentation is the evidence.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ae40-c0c1-b77d-91d1","name":"Sangnak Kim Clan","crest":"clan-crests/ae40-c0c1-b77d-91d1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":40,"Force":-80,"Material":-20,"Communal":10,"Principle":65,"Public":15,"Eligibility":25,"Dispersed":20,"Transformative":-5},"desire":{"Longing":10,"Monopoly":-40,"Risk":-25,"Display":0,"Sustained":0,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Epidemic Control Recorder","Values":"Authority −10 | Openness 40 | Force −80 | Materialism −20 | Communality 10 | Principle 65 | Publicity 15 | Credentials 25 | Decentralization 20 | Transformation −5","Desires":"Craving 10 | Possessiveness −40 | Risk −25 | Display 0 | Endurance 0 | Orientation: same-sex | Bonding: non-exclusive"},"sections":{"Life":"Born on 2087-08-06. As of the opening of 2126, he holds the post of Quarantine Records Officer and continues the existing duty and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- The quarantine records and duty key handover desk in Jegi-dong is taken as Kim Sayeon''s work reference point. This placement does not fix a residence, exact facility boundaries, a rank, a holding, or occupancy rights.","Offices":"Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"On the day fake medicine circulates in Jegi-dong and Ryu Eunbi cuts off the medicine trade, a new line of patients floods the quarantine records. Beside the attending first-aid officer, Kim Sayeon writes each patient''s severity and clinical findings together on one line, leaves the affiliation and property columns blank, and submits them to Ryu Eunbi in bed-assignment order.","Relationships":"Kim Sayeon stands beside the attending first-aid officer and reports the lower-acuity cases and clinical findings to Ryu Eunbi. Ryu Eunbi checks the bed-assignment order and continues treatment on clinical grounds rather than a patient''s affiliation or wealth.","Ambition":"From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that the Epidemic Control Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to let the duty lapse. He trusts one line in the ledger more than loud talk.\n\n- Livelihood: Epidemic Control Log and Duty Key Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Epidemic Control Recorder\n**Life.** Born on 2087-08-06. As of the opening of 2126, he holds the post of Quarantine Records Officer and continues the existing duty and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- The quarantine records and duty key handover desk in Jegi-dong is taken as Kim Sayeon''s work reference point. This placement does not fix a residence, exact facility boundaries, a rank, a holding, or occupancy rights.\n\n**Office.** Rank: Relief Worker. Title: Epidemic Control Relief Worker. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** On the day fake medicine circulates in Jegi-dong and Ryu Eunbi cuts off the medicine trade, a new line of patients floods the quarantine records. Beside the attending first-aid officer, Kim Sayeon writes each patient''s severity and clinical findings together on one line, leaves the affiliation and property columns blank, and submits them to Ryu Eunbi in bed-assignment order.\n\n**Relations.** Kim Sayeon stands beside the attending first-aid officer and reports the lower-acuity cases and clinical findings to Ryu Eunbi. Ryu Eunbi checks the bed-assignment order and continues treatment on clinical grounds rather than a patient''s affiliation or wealth.\n\n**Ambition.** From the Epidemic Control Relief Worker post, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that the Epidemic Control Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 40 | Force −80 | Materialism −20 | Communality 10 | Principle 65 | Publicity 15 | Credentials 25 | Decentralization 20 | Transformation −5\n- Desires: Craving 10 | Possessiveness −40 | Risk −25 | Display 0 | Endurance 0 | Orientation: same-sex | Bonding: non-exclusive\n:::","relations":{"outgoing":[{"from":"Kim Sayeon","type":"Contract","to":"Ryu Eunbi","basis":"Kim Sayeon stands beside the attending first-aid officer and reports the lower-acuity cases and clinical findings to Ryu Eunbi. Ryu Eunbi checks the bed-assignment order and continues treatment on clinical grounds rather than a patient''s affiliation or wealth."}],"incoming":[]}}', '{"id":"person-0932","name":"김사연","title":"방역 기록관","position":"방역 구호원","characterId":"K932","rank":"구호원","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-김사연","detailRoute":"/people/person-0932","birthDate":"2087-08-06","birthday":"08-06","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"triage-documentation","name":"중증도 기록","rating":55}],"traits":[{"id":"stated-priority","name":"재산 칸을 비운다","description":"가짜 약으로 환자가 몰리자 중증도와 소견을 한 줄에 적고 소속·재산 칸은 비웠다. 담당 응급처치원 곁의 배정 기록 수행이 근거다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"가짜 약으로 환자가 몰리자 중증도와 소견을 한 줄에 적고 소속·재산 칸은 비웠다. 담당 응급처치원 곁의 배정 기록 수행이 근거다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ae40-c0c1-b77d-91d1","name":"상락 김씨","crest":"clan-crests/ae40-c0c1-b77d-91d1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":40,"무력":-80,"물질":-20,"공동":10,"원칙":65,"공개":15,"자격":25,"분산":20,"변혁":-5},"desire":{"갈망":10,"독점":-40,"위험":-25,"과시":0,"지속":0,"지향":"동성","결합":"비독점"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"방역 기록관","가치관":"권위 −10 | 개방 40 | 무력 −80 | 물질 −20 | 공동 10 | 원칙 65 | 공개 15 | 자격 25 | 분산 20 | 변혁 −5","욕망":"갈망 10 | 독점 −40 | 위험 −25 | 과시 0 | 지속 0 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2087-08-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 김사연의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"제기동에 가짜 약이 돌아 류은비가 약 거래를 끊은 날, 방역 기록에 새 환자 줄이 몰린다. 김사연은 담당 응급처치원 곁에서 환자마다 중증도와 진료 소견을 한 줄에 함께 적고, 소속과 재산 칸은 비운 채 병상 배정 순서대로 류은비에게 올린다.","관계":"김사연은 담당 응급처치원 곁에서 적은 중증도·진료 소견을 류은비에게 올린다. 류은비는 병상 배정 순서를 확인해 환자의 소속이나 재산 대신 임상 근거로 치료를 잇는다.","야망":"방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 방역 기록관\n**생애.** 2087-08-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 김사연의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 방역 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 제기동에 가짜 약이 돌아 류은비가 약 거래를 끊은 날, 방역 기록에 새 환자 줄이 몰린다. 김사연은 담당 응급처치원 곁에서 환자마다 중증도와 진료 소견을 한 줄에 함께 적고, 소속과 재산 칸은 비운 채 병상 배정 순서대로 류은비에게 올린다.\n\n**관계.** 김사연은 담당 응급처치원 곁에서 적은 중증도·진료 소견을 류은비에게 올린다. 류은비는 병상 배정 순서를 확인해 환자의 소속이나 재산 대신 임상 근거로 치료를 잇는다.\n\n**야망.** 방역 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 40 | 무력 −80 | 물질 −20 | 공동 10 | 원칙 65 | 공개 15 | 자격 25 | 분산 20 | 변혁 −5\n- 욕망: 갈망 10 | 독점 −40 | 위험 −25 | 과시 0 | 지속 0 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"김사연","type":"계약","to":"류은비","basis":"김사연은 담당 응급처치원 곁에서 적은 중증도·진료 소견을 류은비에게 올린다. 류은비는 병상 배정 순서를 확인해 환자의 소속이나 재산 대신 임상 근거로 치료를 잇는다."}],"incoming":[]}}');
