INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0963', 'cangnyeong-seong-yeolcha', '{"id":"person-0963","name":"Seong Dahyeon","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S12","stateName":"The Government","detailRoute":"/people/person-0963","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0963","name":"성다현","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"정부","detailRoute":"/people/person-0963","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0964', 'cc28-c5f0-c548', '{"id":"person-0964","name":"Cha Bahwan","title":"Medicine Storage Clerk","position":"Medicine Storage Relief Worker","characterId":"K964","rank":"Relief Worker","commonTier":"T3","occupation":"Medicine Release Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#Person-Cha Bahwan","detailRoute":"/people/person-0964","birthDate":"2098-01-04","birthday":"01-04","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"Public desk referral","rating":40}],"traits":[{"id":"stated-priority","name":"Redirects private requests","description":"A private request was directed to the public desk. The allocation centers on the recorded procedural choice rather than the prescribing title.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: Relief Worker. Title: Medicine Storage Relief Worker. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the Medicine Storage Relief Worker duty post would stand empty.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A private request was directed to the public desk. The allocation centers on the recorded procedural choice rather than the prescribing title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":35,"Force":-55,"Material":-10,"Communal":20,"Principle":35,"Public":20,"Eligibility":10,"Dispersed":25,"Transformative":-20},"desire":{"Longing":40,"Monopoly":-5,"Risk":-15,"Display":-10,"Sustained":35,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Medicine Release Records and Duty Keys Handover","Affiliation":"The Government","Rank":"Relief Worker","Title":"Medicine Storage Clerk","Values":"Authority −25 | Openness 35 | Force −55 | Material −10 | Communal 20 | Principle 35 | Publicity 20 | Credentials 10 | Dispersion 25 | Transformation −20","Desires":"Craving 40 | Exclusivity −5 | Risk −15 | Display −10 | Persistence 35 | Orientation None | Bonding None"},"sections":{"Life":"Born on 2098-01-04. As of the 2126 opening, Cha Ba-hwan holds the post of Prescription Clerk and continues the existing watches and records. The succession record for that post opened with a substitute watch covering an unexcused shift absence.\n- Jegi-dong''s prescription-record and watch-key handover desk is Cha Ba-hwan''s work reference point. This placement does not fix residence, exact facility boundaries, rank, holding, or possession rights.","Offices":"Rank: Relief Worker. Title: Medicine Storage Relief Worker. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.","Relationships":"Cha Bahwan redirects treatment-order requests to the public desk and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by triage level and clinical findings so that critical patients are not pushed aside by requests.","Ambition":"From the Medicine Storage Relief Worker post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that the Medicine Storage Relief Worker duty will fall vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Cha Ba-hwan chooses not to break the watch first. Trusts a single line in the ledger more than a loud voice.\n\n- Livelihood: Medicine Release Records and Duty Keys Handover\n- Affiliation: The Government\n- Rank: Relief Worker\n- Title: Medicine Storage Clerk\n**Life.** Born on 2098-01-04. As of the 2126 opening, Cha Ba-hwan holds the post of Prescription Clerk and continues the existing watches and records. The succession record for that post opened with a substitute watch covering an unexcused shift absence.\n- Jegi-dong''s prescription-record and watch-key handover desk is Cha Ba-hwan''s work reference point. This placement does not fix residence, exact facility boundaries, rank, holding, or possession rights.\n\n**Office.** Rank: Relief Worker. Title: Medicine Storage Relief Worker. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.\n\n**Anecdote.** In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.\n\n**Relationships.** Cha Bahwan redirects treatment-order requests to the public desk and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by triage level and clinical findings so that critical patients are not pushed aside by requests.\n\n**Ambition.** From the Medicine Storage Relief Worker post, he carries on the White Cross Order''s ledger so that it is not broken.\n\n**Fear.** He fears that the Medicine Storage Relief Worker duty will fall vacant.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −25 | Openness 35 | Force −55 | Material −10 | Communal 20 | Principle 35 | Publicity 20 | Qualification 10 | Dispersal 25 | Transformation −20\n- Desires: Yearning 40 | Monopoly −5 | Risk −15 | Display −10 | Persistence 35 | Orientation None | Bond None\n:::","relations":{"outgoing":[{"from":"Cha Bahwan","type":"Contract","to":"Eun Chaeyun","basis":"Cha Bahwan redirects treatment-order requests to the public desk and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by triage level and clinical findings so that critical patients are not pushed aside by requests."}],"incoming":[]}}', '{"id":"person-0964","name":"차바환","title":"약 보관 서기","position":"약 보관 구호원","characterId":"K964","rank":"구호원","commonTier":"T3","occupation":"약 출고 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-차바환","detailRoute":"/people/person-0964","birthDate":"2098-01-04","birthday":"01-04","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"창구 안내","rating":40}],"traits":[{"id":"stated-priority","name":"사적 요청을 돌려보낸다","description":"사적 청탁을 공개 창구로 보냈다. 처방 직함보다 확인된 절차 선택을 중심으로 좁게 평가한다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 약 보관 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약 보관 구호원 당직이 비는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"사적 청탁을 공개 창구로 보냈다. 처방 직함보다 확인된 절차 선택을 중심으로 좁게 평가한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":35,"무력":-55,"물질":-10,"공동":20,"원칙":35,"공개":20,"자격":10,"분산":25,"변혁":-20},"desire":{"갈망":40,"독점":-5,"위험":-15,"과시":-10,"지속":35,"지향":"무성향","결합":"없음"},"fields":{"생업":"약 출고 기록·당직 열쇠 인계","소속":"정부","품계":"구호원","직함":"약 보관 서기","가치관":"권위 −25 | 개방 35 | 무력 −55 | 물질 −10 | 공동 20 | 원칙 35 | 공개 20 | 자격 10 | 분산 25 | 변혁 −20","욕망":"갈망 40 | 독점 −5 | 위험 −15 | 과시 −10 | 지속 35 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2098-01-04에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 차바환의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.","관직":"품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"차바환은 치료 순서 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도·진료 소견으로 배정해 위중한 환자가 청탁에 밀리지 않게 한다.","야망":"약 보관 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약 보관 구호원 당직이 비는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약 출고 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 구호원\n- 직함: 약 보관 서기\n**생애.** 2098-01-04에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 차바환의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·직위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 구호원. 직함은 약 보관 구호원. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 차바환은 치료 순서 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도·진료 소견으로 배정해 위중한 환자가 청탁에 밀리지 않게 한다.\n\n**야망.** 약 보관 구호원 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약 보관 구호원 당직이 비는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 35 | 무력 −55 | 물질 −10 | 공동 20 | 원칙 35 | 공개 20 | 자격 10 | 분산 25 | 변혁 −20\n- 욕망: 갈망 40 | 독점 −5 | 위험 −15 | 과시 −10 | 지속 35 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"차바환","type":"계약","to":"은채윤","basis":"차바환은 치료 순서 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도·진료 소견으로 배정해 위중한 환자가 청탁에 밀리지 않게 한다."}],"incoming":[]}}');
