INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0970', 'ae40-ac15-b989-91d1', '{"id":"person-0970","name":"Kim Eunho","title":"Entrance Heat and Light Gauger","position":"Entrance Heat and Light Gauger","rank":"Ordinary Citizen","commonTier":"T5","occupation":"Duty Log Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0970","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0970","name":"김은호","title":"출입구 열·빛 계측원","position":"출입구 열·빛 계측원","rank":"일반 시민","commonTier":"T5","occupation":"당직 기록 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"Arc","detailRoute":"/people/person-0970","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0971', 'c774-c131-c8fc-674e', '{"id":"person-0971","name":"I Nammin","title":"Workshop Herald","position":"Workshop Herald","characterId":"K971","rank":"Teacher","commonTier":"T5","occupation":"Escort and Personnel Ledger Management","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-i-nam-min","detailRoute":"/people/person-0971","birthDate":"2102-01-16","birthday":"01-16","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"save-register","name":"Emergency preservation of personnel registers","rating":45},{"id":"departure","name":"Departure and dispatch checks","rating":40}],"traits":[{"id":"ledgers-first-amid-attacks","name":"Ledgers First Amid Attacks","description":"I Nammin shows a disposition to prioritize personal records over cargo even under attack pressure.","behavior":"When attacked during a convoy, he secured the register of people before the cargo.","stress":"If attack pressure coincides with the risk of broken record continuity, he may give greater weight to preserving the register.","relationship":"With senior duty staff, he may feel responsible for passing onward the register preserved during the attack.","effects":[]},{"id":"limited-record-responsibility","name":"Limited Record Responsibility","description":"I Nammin limits his responsibility for safeguarding records to his position’s keys and records.","behavior":"He hands over only his position’s keys and records without using ledger preservation to claim additional powers.","stress":"Even if he fears a duty gap, he may respond within the scope of preserving the records entrusted to him.","relationship":"With senior duty staff, he may seek to make the actual scope of his record responsibility clear during handover.","effects":[]}],"narrative":"He preserved personnel registers over freight during an attack. The choice is reflected, not assumed overall convoy success or enemy restraint.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c774-c131-c8fc-674e","name":"Seongju I Clan","crest":"clan-crests/c774-c131-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":20,"Force":-15,"Material":20,"Communal":30,"Principle":15,"Public":-5,"Eligibility":20,"Dispersed":30,"Transformative":0},"desire":{"Longing":40,"Monopoly":-40,"Risk":-10,"Display":5,"Sustained":30,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Escort and Personnel Ledger Management","Rank":"Teacher","Title":"Workshop Herald","Values":"Authority 0 | Openness 20 | Force −15 | Material 20 | Communal 30 | Principle 15 | Publicity −5 | Qualification 20 | Dispersal 30 | Transformation 0","Desires":"Yearning 40 | Monopoly −40 | Risk −10 | Display 5 | Persistence 30 | Orientation None | Bond Contract Cohabitation"},"sections":{"Life":"Generation of 2126. I Nam-min grew up at the Sinnae Interchange Watch. I Nam-min took the post of Workshop Courier by stopping a ticketless departing train.\n- I Nam-min''s Workshop Courier duties are tied to Amsa 1-dong.","Offices":"I Nam-min hands over only the keys and records attached to one''s own post. I Nam-min does not invent authority that one does not have.","Anecdote":"In 2125, caught in an attack during an escort, I Nam-min secured the life ledger before the cargo. Because of this, the signature of the Workshop Courier post entered the ledger.","Relationships":"I Nam-min is bound by handover to a senior watch member of the same living sphere.","Ambition":"I Nam-min wants to keep the Arc''s ledger unbroken from the Workshop Courier watch.","Fear":"","Intervention":"I Nam-min can bring in a witness to the watch handover or expose an empty key."},"biography":"I Nam-min chooses not to break the watch first. I Nam-min trusts a single line in the ledger more than a loud voice.\n\n- Affiliation: Arc\n- Livelihood: Escort and Personnel Ledger Management\n- Rank: Teacher\n- Title: Workshop Herald\n**Life.** Generation of 2126. I Nam-min grew up at the Sinnae Interchange Watch. I Nam-min took the post of Workshop Courier by stopping a ticketless departing train.\n- I Nam-min''s Workshop Courier duties are tied to Amsa 1-dong.\n\n**Office.** I Nam-min hands over only the keys and records attached to one''s own post. I Nam-min does not invent authority that one does not have.\n\n**Anecdote.** In 2125, caught in an attack during an escort, I Nam-min secured the life ledger before the cargo. Because of this, the signature of the Workshop Courier post entered the ledger.\n\n**Relationships.** I Nam-min is bound by handover to a senior watch member of the same living sphere.\n\n**Ambition.** I Nam-min wants to keep the Arc''s ledger unbroken from the Workshop Courier watch.\n\n**Intervention.** I Nam-min can bring in a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 0 | Openness 20 | Force −15 | Material 20 | Communal 30 | Principle 15 | Publicity −5 | Qualification 20 | Dispersal 30 | Transformation 0\n- Desires: Yearning 40 | Monopoly −40 | Risk −10 | Display 5 | Persistence 30 | Orientation None | Bond Contract Cohabitation\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0971","name":"이남민","title":"공방 전령","position":"공방 전령","characterId":"K971","rank":"교사","commonTier":"T5","occupation":"호송·인명 장부 관리","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-이남민","detailRoute":"/people/person-0971","birthDate":"2102-01-16","birthday":"01-16","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"save-register","name":"위기 인명 장부 보존","rating":45},{"id":"departure","name":"배차표·출발 확인","rating":40}],"traits":[{"id":"ledgers-first-amid-attacks","name":"습격 속 장부 우선","description":"이남민은 습격의 압박 속에서도 화물보다 인명 기록을 우선하는 성향을 보인다.","behavior":"호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다.","stress":"습격과 기록 단절의 우려가 겹치면 인명 장부 보존에 더 무게를 둘 수 있다.","relationship":"선배 당직과는 습격 중 지켜낸 장부를 이어 넘기는 데 책임을 느낄 수 있다.","effects":[]},{"id":"limited-record-responsibility","name":"기록 책임 한정","description":"이남민은 기록을 지키는 책임을 자기 직위의 열쇠와 기록 범위 안에 한정한다.","behavior":"자기 직위의 열쇠와 기록만 넘기고 장부 보존을 이유로 없는 권한을 만들지 않는다.","stress":"당직 공백이 두려워도 맡은 기록의 연속성을 지키는 범위에서 대응하려 할 수 있다.","relationship":"선배 당직과는 실제로 맡은 기록의 책임 범위를 분명히 하며 인계하려 할 수 있다.","effects":[]}],"narrative":"습격 때 화물보다 인명 장부를 보존했다. 실제 선택만 평가하며 호송 성공 전체나 적 제압을 단정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c774-c131-c8fc-674e","name":"성주 이씨","crest":"clan-crests/c774-c131-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":20,"무력":-15,"물질":20,"공동":30,"원칙":15,"공개":-5,"자격":20,"분산":30,"변혁":0},"desire":{"갈망":40,"독점":-40,"위험":-10,"과시":5,"지속":30,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"Arc","생업":"호송·인명 장부 관리","품계":"교사","직함":"공방 전령","가치관":"권위 0 | 개방 20 | 무력 −15 | 물질 20 | 공동 30 | 원칙 15 | 공개 −5 | 자격 20 | 분산 30 | 변혁 0","욕망":"갈망 40 | 독점 −40 | 위험 −10 | 과시 5 | 지속 30 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 이남민은 신내 환승 당직에서 자랐다. 이남민은 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 이남민의 공방 전령 업무는 암사1동과 연결된다.","관직":"이남민은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 이남민은 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.","관계":"이남민은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"이남민은 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"","개입":"이남민은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"이남민은 당직을 끊지 않는 쪽을 먼저 고른다. 이남민은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 호송·인명 장부 관리\n- 품계: 교사\n- 직함: 공방 전령\n**생애.** 2126년 세대. 이남민은 신내 환승 당직에서 자랐다. 이남민은 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 이남민의 공방 전령 업무는 암사1동과 연결된다.\n\n**관직.** 이남민은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 이남민은 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 이남민은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 이남민은 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**개입.** 이남민은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 20 | 무력 −15 | 물질 20 | 공동 30 | 원칙 15 | 공개 −5 | 자격 20 | 분산 30 | 변혁 0\n- 욕망: 갈망 40 | 독점 −40 | 위험 −10 | 과시 5 | 지속 30 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[],"incoming":[]}}');
