INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0983', 'd669-d68c-b355-9ec3', '{"id":"person-0983","name":"Hwang Sora","title":"Audit Recorder","position":"Audit Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0983","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0983","name":"황솔아","title":"감사 기록관","position":"감사 기록관","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0983","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
