INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1001', 'acfd-d604-d48d', '{"id":"person-1001","name":"Gwak Gahyeon","title":"Resident Roster Keeper","position":"Resident Roster Keeper","characterId":"K1001","rank":"Clerk","commonTier":"T5","occupation":"Resident Roster Keeping","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-gwak-gahyeon","detailRoute":"/people/person-1001","birthDate":"2068-06-12","birthday":"06-12","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k1001-district-allocation-separation","name":"Separate district allocations","rating":60}],"traits":[{"id":"k1001-action-priority","name":"Resident Roster Keeper","description":"Title: Resident Roster Keeper.","behavior":"Title: Resident Roster Keeper.","stress":"That the resident roster duty would stand empty, a missing person would go unnoticed, and that person would end up a hostage of another faction.","relationship":"Works at Yeongdeungpo-gu Office Station as the resident roster keeper and reads the roster out to shift colleagues and patrolling residents.","effects":[]},{"id":"k1001-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the resident roster duty would stand empty, a missing person would go unnoticed, and that person would end up a hostage of another faction.","relationship":"Works at Yeongdeungpo-gu Office Station as the resident roster keeper and reads the roster out to shift colleagues and patrolling residents.","effects":[]}],"narrative":"The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-20,"Force":10,"Material":45,"Communal":20,"Principle":20,"Public":20,"Eligibility":5,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":0,"Monopoly":5,"Risk":5,"Display":-10,"Sustained":-15,"Orientation":"Same-Sex","Union":"None"},"fields":{"Affiliation":"Free City","Livelihood":"Resident Roster Keeping","Rank":"Clerk","Title":"Resident Roster Keeper","Work Location":"Yeongdeungpo-gu Office Station.","Values":"Authority 55 | Openness −20 | Force 10 | Materiality 45 | Community 20 | Principle 20 | Publicity 20 | Credentials 5 | Dispersion −40 | Transformation −25","Desires":"Craving 0 | Monopoly 5 | Risk 5 | Display −10 | Endurance −15 | Orientation: same-sex | Bond: none"},"sections":{"Life":"Generation of 2126. Raised in the residents'' quarter of Yeongdeungpo-gu Office Station.\n- Duty location: Yeongdeungpo-gu Office Station.","Offices":"Rank: Clerk. Title: Resident Roster Keeper.","Anecdote":"","Relationships":"Works at Yeongdeungpo-gu Office Station as the resident roster keeper and reads the roster out to shift colleagues and patrolling residents.","Ambition":"From the post of Resident Roster Keeper, keeps Yeongdeungpo-gu Office Station''s record of its people linked without a break.","Fear":"That the resident roster duty would stand empty, a missing person would go unnoticed, and that person would end up a hostage of another faction.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first whatever keeps the watch from being broken. Trusts a single line in the ledger over loud talk.\n\n- Affiliation: Free City\n- Livelihood: Resident Roster Keeping\n- Rank: Clerk\n- Title: Resident Roster Keeper\n**Life.** Generation of 2126. Raised in the residents'' quarter of Yeongdeungpo-gu Office Station.\n- Duty location: Yeongdeungpo-gu Office Station.\n\n**Office.** Rank: Clerk. Title: Resident Roster Keeper.\n\n**Relationships.** Works at Yeongdeungpo-gu Office Station as the resident roster keeper and reads the roster out to shift colleagues and patrolling residents.\n\n**Ambition.** From the post of Resident Roster Keeper, keeps Yeongdeungpo-gu Office Station''s record of its people linked without a break.\n\n**Fear.** That the resident roster duty would stand empty, a missing person would go unnoticed, and that person would end up a hostage of another faction.\n\n**Intervention.** Can bring in a witness to the watch handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −20 | Force 10 | Materiality 45 | Community 20 | Principle 20 | Publicity 20 | Credentials 5 | Dispersion −40 | Transformation −25\n- Desires: Craving 0 | Monopoly 5 | Risk 5 | Display −10 | Endurance −15 | Orientation: same-sex | Bond: none\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Gwak Gahyeon","type":"Command","to":"I Seo-dam","basis":"Takes the warehouse stock-record watch under Yi Seodam"}],"incoming":[]}}', '{"id":"person-1001","name":"곽가현","title":"주민 명부 담당","position":"주민 명부 담당","characterId":"K1001","rank":"주사","commonTier"